const MIN_LENGTH = 12;
const MIN_DIGITS = 2;
const SPECIAL_SYMBOLS = ['!', '@', '#', '*'];

const hasMinimumLength = (password) => password.length >= MIN_LENGTH;

const hasUpperCase = (password) => /[A-Z]/.test(password);

const hasLowerCase = (password) => /[a-z]/.test(password);

const countDigitCharacters = (password) => {
  let total = 0;
  for (const character of password) {
    if (character >= '0' && character <= '9') {
      total += 1;
    }
  }
  return total;
};

const hasEnoughDigits = (password) => countDigitCharacters(password) >= MIN_DIGITS;

const hasSpecialSymbol = (password) =>
  SPECIAL_SYMBOLS.some((symbol) => password.includes(symbol));

const hasMixedCase = (password) => hasUpperCase(password) && hasLowerCase(password);

const isStrongPassword = (password) => {
  if (!hasMinimumLength(password)) {
    return false;
  }
  if (!hasMixedCase(password)) {
    return false;
  }
  if (!hasEnoughDigits(password)) {
    return false;
  }
  return hasSpecialSymbol(password);
};

function validate(passwords) {
  if (!Array.isArray(passwords)) {
    throw new TypeError('validate expects an array of password strings');
  }
  return passwords.map((password) => {
    if (typeof password !== 'string') {
      throw new TypeError('every password must be a string');
    }
    return isStrongPassword(password);
  });
}

const collectFailureReasons = (password) => {
  const reasons = [];
  if (!hasMinimumLength(password)) {
    reasons.push(`shorter than ${MIN_LENGTH} characters`);
  }
  if (!hasUpperCase(password)) {
    reasons.push('no uppercase letter');
  }
  if (!hasLowerCase(password)) {
    reasons.push('no lowercase letter');
  }
  if (!hasEnoughDigits(password)) {
    reasons.push(`fewer than ${MIN_DIGITS} digits`);
  }
  if (!hasSpecialSymbol(password)) {
    reasons.push(`no symbol from ${SPECIAL_SYMBOLS.join('')}`);
  }
  return reasons;
};

const formatAuditLine = (password, accepted) => {
  if (accepted) {
    return `${password}: accepted`;
  }
  return `${password}: rejected (${collectFailureReasons(password).join(', ')})`;
};

const auditPasswords = (passwords) => {
  const results = validate(passwords);
  return passwords.map((password, index) => formatAuditLine(password, results[index]));
};

const samples = ['short', 'Valid12#Pass!', 'alllowercase12!', 'NoDigitsHere!!!!'];
console.log(validate(samples));
auditPasswords(samples).forEach((line) => console.log(line));

module.exports = { validate, auditPasswords };

