const stripPunctuation = (word) => word.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, '');

const splitIntoSentences = (text) =>
  text
    .split('.')
    .map((sentence) => sentence.trim())
    .filter((sentence) => sentence.length > 0);

const extractWords = (sentence) => {
  const rawTokens = sentence.split(/\s+/);
  return rawTokens.map(stripPunctuation).filter((word) => word.length > 0);
};

const isSignificantWord = (word) => word.length > 5;

const scoreSentence = (sentence) => {
  const words = extractWords(sentence);
  return words.filter(isSignificantWord).length;
};

const compareByScore = (left, right) =>
  right.score - left.score || left.index - right.index;

const rankSentences = (sentences) => {
  const scored = sentences.map((text, index) => ({
    text,
    index,
    score: scoreSentence(text),
  }));
  return scored.sort(compareByScore);
};

const takeTopSentences = (ranked, limit) =>
  ranked.slice(0, limit).map((entry) => entry.text);

const joinSummary = (parts) => (parts.length === 0 ? '' : `${parts.join('. ')}.`);

const assertIsString = (value, label) => {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string, received ${typeof value}`);
  }
};

function summarize(text) {
  assertIsString(text, 'text');
  const sentences = splitIntoSentences(text);
  const ranked = rankSentences(sentences);
  const selected = takeTopSentences(ranked, 3);
  return joinSummary(selected);
}

const formatReport = (text) => {
  assertIsString(text, 'text');
  const sentences = splitIntoSentences(text);
  const ranked = rankSentences(sentences);
  const lines = ranked.map(
    (entry) => `  #${entry.index + 1} (score ${entry.score}): ${entry.text}`
  );
  return ['Sentence ranking:'].concat(lines).join('\n');
};

const readStandardInput = () =>
  new Promise((resolve, reject) => {
    let buffer = '';
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => {
      buffer += chunk;
    });
    process.stdin.on('end', () => resolve(buffer));
    process.stdin.on('error', reject);
  });

const runCommandLine = async (argv) => {
  const inline = argv.slice(2).join(' ').trim();
  const source = inline.length > 0 ? inline : await readStandardInput();
  const report = formatReport(source);
  const summary = summarize(source);
  process.stdout.write(`${report}\n${summary}\n`);
};

if (require.main === module) {
  runCommandLine(process.argv).catch((error) => {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 1;
  });
}

module.exports.summarize = summarize;
module.exports.formatReport = formatReport;
module.exports.scoreSentence = scoreSentence;
module.exports.splitIntoSentences = splitIntoSentences;

