const CRITICAL_LEVELS = ['ERROR', 'CRITICAL'];

const splitLogLine = (line) => String(line).split('|');

const trimParts = (parts) => parts.map((part) => part.trim());

const normalizeSeverity = (rawSeverity) => rawSeverity.trim().toUpperCase();

const hasRequiredFields = (parts) => parts.length >= 3 && parts.every((part) => part.length > 0);

function joinMessageParts(parts) {
  const cleaned = trimParts(parts);
  return cleaned.join(' | ');
}

function buildLogEntry(line) {
  const columns = splitLogLine(line);
  if (columns.length < 3) {
    return null;
  }
  const date = columns[0].trim();
  const severity = normalizeSeverity(columns[1]);
  const message = joinMessageParts(columns.slice(2));
  if (!hasRequiredFields([date, severity, message])) {
    return null;
  }
  return { date, severity, message };
}

const isCriticalEntry = (entry) => CRITICAL_LEVELS.includes(entry.severity);

const formatSummaryLine = (entry) => `[${entry.date}] ${entry.message}`;

function parse(logs) {
  if (!Array.isArray(logs)) {
    throw new TypeError('parse expects an array of log strings');
  }
  const entries = [];
  for (const line of logs) {
    const entry = buildLogEntry(line);
    if (entry) {
      entries.push(entry);
    }
  }
  const critical = entries.filter(isCriticalEntry);
  return critical.map(formatSummaryLine);
}

const countBySeverity = (logs) => {
  const tally = {};
  for (const line of logs) {
    const entry = buildLogEntry(line);
    if (entry) {
      tally[entry.severity] = (tally[entry.severity] || 0) + 1;
    }
  }
  return tally;
};

const renderTallyReport = (tally) =>
  Object.keys(tally)
    .sort()
    .map((severity) => `${severity}: ${tally[severity]}`)
    .join(', ');

function main() {
  const sampleLogs = [
    '2023-01-01 | error | system crash',
    '2023-01-02 | info | user login',
    '2023-01-03 | Critical | disk failure | sector 42',
    'malformed line without separators',
    '2023-01-04 |  | missing severity',
  ];
  const summary = parse(sampleLogs);
  summary.forEach((line) => console.log(line));
  const tally = countBySeverity(sampleLogs);
  console.log(renderTallyReport(tally));
}

main();

module.exports.parse = parse;
module.exports.buildLogEntry = buildLogEntry;
module.exports.countBySeverity = countBySeverity;
module.exports.renderTallyReport = renderTallyReport;

