const isBooleanCell = (value) => typeof value === 'boolean';

const formatBoolean = (value) => (value ? 'TRUE' : 'FALSE');

const isNumericCell = (value) => typeof value === 'number' && Number.isFinite(value);

const formatNumber = (value) => value.toFixed(2);

const escapeQuotes = (text) => text.replace(/"/g, '""');

const needsQuoting = (text) => text.includes(',') || text.includes('\n') || text.includes('\r');

const quoteField = (text) => {
  const escaped = escapeQuotes(text);
  return `"${escaped}"`;
};

const toCellText = (value) => {
  if (value === null || value === undefined) {
    return '';
  }
  return String(value);
};

const encodeCell = (value) => {
  if (isBooleanCell(value)) {
    return formatBoolean(value);
  }
  if (isNumericCell(value)) {
    return formatNumber(value);
  }
  const text = toCellText(value);
  if (needsQuoting(text)) {
    return quoteField(text);
  }
  return text;
};

const encodeRow = (row) => {
  const cells = row.map(encodeCell);
  return cells.join(',');
};

const validateRows = (rows) => {
  if (!Array.isArray(rows)) {
    throw new TypeError('encode expects an array of rows');
  }
  rows.forEach((row, index) => {
    if (!Array.isArray(row)) {
      throw new TypeError(`row ${index} is not an array`);
    }
  });
};

function encode(rows) {
  validateRows(rows);
  return rows.map(encodeRow).join('\n');
}

const describeShape = (rows) => {
  const widths = rows.map((row) => row.length);
  const maxWidth = widths.length ? Math.max(...widths) : 0;
  return `${rows.length} row(s), widest row has ${maxWidth} cell(s)`;
};

const runMain = () => {
  const inventory = [
    ['apple, inc', true, 5.123],
    ['he said "hi"', false, 42],
    ['multi\nline', true, 0.005],
  ];
  const summary = [['label', 'value'], ['total', 47.128]];

  console.log(describeShape(inventory));
  console.log(encode(inventory));
  console.log('---');
  console.log(describeShape(summary));
  console.log(encode(summary));
};

if (require.main === module) {
  runMain();
}

module.exports = { encode };
module.exports.encodeRow = encodeRow;
module.exports.encodeCell = encodeCell;

