const isWholeNumber = (value) => typeof value === 'number' && value === Math.trunc(value);

const isCoordinatePair = (vertex) => {
  if (!Array.isArray(vertex) || vertex.length !== 2) {
    return false;
  }
  return vertex.every(isWholeNumber);
};

const validatePolygon = (polygon) => {
  if (!Array.isArray(polygon) || polygon.length < 3) {
    throw new TypeError('a polygon needs at least three vertices');
  }
  polygon.forEach((vertex, index) => {
    if (!isCoordinatePair(vertex)) {
      throw new TypeError(`vertex ${index} is not a pair of integers`);
    }
  });
};

const collectAxis = (polygon, axis) => polygon.map((vertex) => vertex[axis]);

const smallestOf = (values) => values.reduce((best, value) => (value < best ? value : best));

const largestOf = (values) => values.reduce((best, value) => (value > best ? value : best));

const computeBoundingBox = (polygon) => {
  const xs = collectAxis(polygon, 0);
  const ys = collectAxis(polygon, 1);
  const left = smallestOf(xs);
  const bottom = smallestOf(ys);
  const right = largestOf(xs);
  const top = largestOf(ys);
  return [left, bottom, right, top];
};

const crossProduct = (a, b) => a[0] * b[1] - a[1] * b[0];

const nextVertex = (polygon, index) => polygon[(index + 1) % polygon.length];

const shoelaceSum = (polygon) =>
  polygon.reduce((total, vertex, index) => {
    const follower = nextVertex(polygon, index);
    return total + crossProduct(vertex, follower);
  }, 0);

const computeArea = (polygon) => {
  const doubled = shoelaceSum(polygon);
  return Math.abs(doubled) / 2;
};

function measure(polygon) {
  validatePolygon(polygon);
  const area = computeArea(polygon);
  const box = computeBoundingBox(polygon);
  return [area, box];
}

const formatBoundingBox = ([minX, minY, maxX, maxY]) =>
  `x: ${minX}..${maxX}, y: ${minY}..${maxY}`;

const formatMeasurement = (polygon) => {
  const [area, box] = measure(polygon);
  const range = formatBoundingBox(box);
  return `area = ${area.toFixed(1)} | ${range}`;
};

const describePolygon = (name, polygon) => {
  const summary = formatMeasurement(polygon);
  return `${name}: ${summary}`;
};

const shapes = [
  ['rectangle', [[0, 0], [4, 0], [4, 3], [0, 3]]],
  ['triangle', [[1, 1], [5, 1], [3, 6]]],
  ['L-shape', [[0, 0], [3, 0], [3, 1], [1, 1], [1, 4], [0, 4]]],
  ['clockwise square', [[2, 2], [2, -2], [-2, -2], [-2, 2]]]
];

shapes.forEach(([name, polygon]) => {
  console.log(describePolygon(name, polygon));
});

module.exports = {
  measure,
  computeArea,
  computeBoundingBox,
  describePolygon
};

