const normalizeUnit = (unit) => {
  const cleaned = String(unit).trim().toLowerCase();
  return cleaned.endsWith('s') ? cleaned.slice(0, -1) : cleaned;
};

const lookupUnitVolume = (unit) => {
  const key = normalizeUnit(unit);
  if (!Object.prototype.hasOwnProperty.call(UNIT_MILLILITERS, key)) {
    throw new Error(`unknown unit: ${unit}`);
  }
  return UNIT_MILLILITERS[key];
};

