  if (!Array.isArray(ingredient) || ingredient.length !== 3) {
    throw new Error('each ingredient needs a name, a quantity and a unit');
  }
  const [name, quantity, unit] = ingredient;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new Error('ingredient name must be a non-empty string');
  }
  if (typeof quantity !== 'number' || !Number.isFinite(quantity) || quantity < 0) {
    throw new Error(`invalid quantity for ${name}`);
  }
  return { name: name.trim(), quantity, unit };
};

const toBaseVolume = (ingredient) => {
  const { name, quantity, unit } = validateIngredient(ingredient);
  return { name, milliliters: quantity * lookupUnitVolume(unit) };
};

