  if (milliliters >= 1000) {
    return `${formatAmount(milliliters / 1000)} liters`;
  }
  return `${formatAmount(milliliters)} milliliters`;
};

const scaleIngredient = (ingredient, factor) => {
  const { name, milliliters } = toBaseVolume(ingredient);
  return `${formatVolume(milliliters * factor)} ${name}`;
};

