const isValidTimeString = (value) =>
  typeof value === 'string' && /^([01]\d|2[0-3]):[0-5]\d$/.test(value);

const parseTimeToMinutes = (value) => {
  if (!isValidTimeString(value)) {
    throw new TypeError(`invalid 24 hour time: ${String(value)}`);
  }
  const [hours, minutes] = value.split(':').map(Number);
  return hours * 60 + minutes;
};

const toMinuteEvent = (event) => {
  const [start, end, name] = event;
  const startMinutes = parseTimeToMinutes(start);
  const endMinutes = parseTimeToMinutes(end);
  if (endMinutes <= startMinutes) {
    throw new RangeError(`meeting "${name}" ends before it starts`);
  }
  return { start: startMinutes, end: endMinutes, name };
};

const compareByStartTime = (left, right) =>
  left.start - right.start || left.end - right.end;

const hasStrictOverlap = (earlier, later) => later.start < earlier.end;

const sortChronologically = (timedEvents) =>
  [...timedEvents].sort(compareByStartTime);

function conflicts(events) {
  const parsed = events.map(toMinuteEvent);
  const timed = sortChronologically(parsed);
  const found = [];
  for (let i = 0; i < timed.length - 1; i += 1) {
    for (let j = i + 1; j < timed.length; j += 1) {
      if (!hasStrictOverlap(timed[i], timed[j])) {
        break;
      }
      found.push([timed[i].name, timed[j].name]);
    }
  }
  return found;
}

const formatMinutes = (total) => {
  const hours = Math.floor(total / 60);
  const minutes = total % 60;
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
};

const describeEvent = (event) => {
  const from = formatMinutes(event.start);
  const until = formatMinutes(event.end);
  return `${event.name} (${from}-${until})`;
};

const buildConflictReport = (events) => {
  const pairs = conflicts(events);
  if (pairs.length === 0) {
    return 'no conflicts';
  }
  const byName = new Map();
  for (const event of events.map(toMinuteEvent)) {
    byName.set(event.name, event);
  }
  return pairs
    .map(([first, second]) => {
      const left = describeEvent(byName.get(first));
      const right = describeEvent(byName.get(second));
      return `${left} overlaps ${right}`;
    })
    .join('\n');
};

const schedule = [
  ['09:00', '10:30', 'alpha'],
  ['10:00', '11:00', 'beta'],
  ['11:00', '11:45', 'gamma'],
  ['11:30', '13:00', 'delta'],
];

console.log(JSON.stringify(conflicts(schedule)));
console.log(buildConflictReport(schedule));

module.exports = { conflicts, parseTimeToMinutes, buildConflictReport };

