const normalizeInput = (lines) => {
  if (!Array.isArray(lines)) {
    throw new TypeError('convert expects an array of lines');
  }
  return lines.map((line) => (typeof line === 'string' ? line : String(line)));
};

const isListItem = (line) => line.startsWith('- ');

const extractItemText = (line) => line.slice(2).replace(/\s+$/, '');

const wrapListItem = (text) => `<li>${text}</li>`;

const wrapUnorderedList = (inner) => `<ul>${inner}</ul>`;

const collectListItems = (lines) => {
  const normalized = normalizeInput(lines);
  const itemLines = normalized.filter(isListItem);
  return itemLines.map(extractItemText);
};

function convert(lines) {
  const texts = collectListItems(lines);
  const markupItems = texts.map(wrapListItem);
  return wrapUnorderedList(markupItems.join(''));
}

const describeConversion = (lines) => {
  const normalized = normalizeInput(lines);
  const items = collectListItems(normalized);
  const ignored = normalized.length - items.length;
  return `${items.length} of ${normalized.length} line(s) converted, ${ignored} ignored`;
};

const splitIntoLines = (block) => block.split(/\r?\n/);

const convertBlock = (block) => {
  const lines = splitIntoLines(block);
  return convert(lines);
};

const buildReport = (label, lines) => {
  const markup = convert(lines);
  const summary = describeConversion(lines);
  return [`== ${label} ==`, markup, summary].join('\n');
};

