const sortCharacters = (word) => word.split('').sort().join('');

const isValidWord = (value) =>
  typeof value === 'string' && value.length > 0 && /^[a-z]+$/.test(value);

function buildSignature(word) {
  if (!isValidWord(word)) {
    throw new TypeError(`not a lowercase word: ${String(word)}`);
  }
  return sortCharacters(word);
}

function collectSignatures(words) {
  const buckets = new Map();
  for (const word of words) {
    const key = buildSignature(word);
    if (!buckets.has(key)) {
      buckets.set(key, []);
    }
    buckets.get(key).push(word);
  }
  return buckets;
}

const compareClusters = (left, right) => {
  if (left.length !== right.length) {
    return right.length - left.length;
  }
  return left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0;
};

function group(words) {
  if (!Array.isArray(words)) {
    throw new TypeError('group expects an array of words');
  }
  const buckets = collectSignatures(words);
  return Array.from(buckets.values()).sort(compareClusters);
}

const formatCluster = (cluster) => `[${cluster.join(', ')}]`;

function describeGrouping(words) {
  const clusters = group(words);
  const lines = clusters.map(
    (cluster, index) => `${index + 1}. size ${cluster.length}: ${formatCluster(cluster)}`
  );
  return lines.join('\n');
}

function reportSample(label, words) {
  const header = `${label} -> ${formatCluster(words)}`;
  return `${header}\n${describeGrouping(words)}`;
}

const samples = [
  ['simple', ['bat', 'tab', 'cat']],
  ['mixed', ['listen', 'silent', 'enlist', 'google', 'gogole', 'cat', 'act', 'tac', 'dog']],
  ['singles', ['alpha', 'beta', 'gamma']],
];

for (const [label, words] of samples) {
  console.log(reportSample(label, words));
  console.log('');
}

try {
  group(['ok', 'Bad']);
} catch (err) {
  console.log(`rejected: ${err.message}`);
}

module.exports = { group, buildSignature, describeGrouping };

