const splitOctets = (address) => String(address).trim().split('.');

const isValidAddress = (address) => {
  const octets = splitOctets(address);
  if (octets.length !== 4) {
    return false;
  }
  return octets.every((part) => /^\d{1,3}$/.test(part) && Number(part) <= 255);
};

const ipToInteger = (address) =>
  splitOctets(address).reduce((acc, part) => ((acc << 8) | Number(part)) >>> 0, 0);

const integerToIp = (value) => [24, 16, 8, 0].map((shift) => (value >>> shift) & 255).join('.');

const buildNetworkMask = (prefix) => (prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0);

const applyNetworkMask = (value, mask) => (value & mask) >>> 0;

const normalizePrefix = (prefix) => {
  const length = Number(prefix);
  if (!Number.isInteger(length) || length < 0 || length > 32) {
    throw new RangeError(`prefix must be an integer between 0 and 32, got: ${prefix}`);
  }
  return length;
};

function subnet(addresses, target, prefix) {
  const length = normalizePrefix(prefix);
  if (!isValidAddress(target)) {
    throw new TypeError(`invalid target network: ${target}`);
  }
  const mask = buildNetworkMask(length);
  const targetValue = ipToInteger(target);
  const network = applyNetworkMask(targetValue, mask);
  return addresses.filter((address) => {
    if (!isValidAddress(address)) {
      return false;
    }
    const value = ipToInteger(address);
    return applyNetworkMask(value, mask) === network;
  });
}

const describeNetwork = (target, prefix) => {
  const length = normalizePrefix(prefix);
  const mask = buildNetworkMask(length);
  const targetValue = ipToInteger(target);
  const base = applyNetworkMask(targetValue, mask);
  const broadcast = (base | (~mask >>> 0)) >>> 0;
  const baseText = integerToIp(base);
  const maskText = integerToIp(mask);
  const broadcastText = integerToIp(broadcast);
  return `${baseText}/${length} mask ${maskText} range ${baseText}-${broadcastText}`;
};

const formatSubnetReport = (addresses, target, prefix) => {
  const matches = subnet(addresses, target, prefix);
  const listing = matches.length > 0 ? matches.join(', ') : '(none)';
  const header = describeNetwork(target, prefix);
  return `${header}\n  matched ${matches.length}/${addresses.length}: ${listing}`;
};

function main() {
  const pool = ['192.168.1.5', '10.0.0.1', '192.168.1.250', '192.168.2.7', '10.0.0.99', '300.1.1.1'];
  console.log(subnet(['192.168.1.5', '10.0.0.1'], '192.168.1.0', 24));
  console.log(formatSubnetReport(pool, '192.168.1.0', 24));
  console.log(formatSubnetReport(pool, '10.0.0.0', 8));
  console.log(formatSubnetReport(pool, '192.168.1.240', 28));
