const splitTimeStamp = (stamp) => String(stamp).trim().split(':');

const isValidTimeStamp = (stamp) => {
  const parts = splitTimeStamp(stamp);
  if (parts.length !== 2) return false;
  return parts.every((part) => /^\d{1,2}$/.test(part));
};

const parseTrackSeconds = (stamp) => {
  if (!isValidTimeStamp(stamp)) {
    throw new Error(`Malformed track length: "${stamp}"`);
  }
  const [minutes, seconds] = splitTimeStamp(stamp).map(Number);
  if (seconds > 59) {
    throw new Error(`Seconds out of range in "${stamp}"`);
  }
  return minutes * 60 + seconds;
};

const sumTrackSeconds = (tracks) =>
  tracks.reduce((total, stamp) => total + parseTrackSeconds(stamp), 0);

const formatTotalSeconds = (total) => {
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
