const validatePrices = (prices) => {
  if (!Array.isArray(prices)) {
    throw new TypeError('analyze expects an array of daily prices');
  }
  prices.forEach((price, index) => {
    if (typeof price !== 'number' || !Number.isFinite(price)) {
      throw new TypeError(`price at index ${index} is not a finite number`);
    }
  });
};

const computeMean = (values) => {
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

const rollingAverages = (prices, windowSize) => {
  const averages = [];
  for (let end = windowSize; end <= prices.length; end += 1) {
    const window = prices.slice(end - windowSize, end);
    averages.push(computeMean(window));
  }
  return averages;
};

const collectSignals = (shortAverages, longAverages) => {
  const signals = [];
  for (let day = 4; day < longAverages.length + 4; day += 1) {
    const shortValue = shortAverages[day - 2];
    const longValue = longAverages[day - 4];
    if (shortValue > longValue) {
      signals.push(day);
    }
  }
  return signals;
};

function analyze(prices) {
  validatePrices(prices);
  if (prices.length < 5) {
    return [];
  }
  const shortAverages = rollingAverages(prices, 3);
  const longAverages = rollingAverages(prices, 5);
  return collectSignals(shortAverages, longAverages);
}

const parsePriceList = (text) => {
  const tokens = text.split(/[\s,]+/).filter((token) => token.length > 0);
  return tokens.map((token) => Number(token));
};

const formatPriceSeries = (prices) => `[${prices.join(', ')}]`;

const formatSignalReport = (prices) => {
  const signals = analyze(prices);
  const series = formatPriceSeries(prices);
  if (signals.length === 0) {
    return `${series} -> no buy signals`;
  }
  return `${series} -> buy on days ${signals.join(', ')}`;
};

if (require.main === module) {
  const prices = parsePriceList(process.argv.slice(2).join(' '));
  console.log(formatSignalReport(prices));
}

module.exports = { analyze, computeMean, rollingAverages, parsePriceList, formatSignalReport };

