const RANK_WORDS = {
  two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8,
  nine: 9, ten: 10, jack: 11, queen: 12, king: 13, ace: 14,
};

const SUIT_WORDS = ['hearts', 'diamonds', 'clubs', 'spades'];

const wordToNumber = (word) => {
  const value = RANK_WORDS[word];
  if (value === undefined) {
    throw new Error(`unknown card rank: ${word}`);
  }
  return value;
};

const normalizeSuit = (word) => {
  if (!SUIT_WORDS.includes(word)) {
    throw new Error(`unknown card suit: ${word}`);
  }
  return word;
};

function parseCard(card) {
  const parts = String(card).trim().toLowerCase().split(/\s+/);
  if (parts.length !== 3 || parts[1] !== 'of') {
    throw new Error(`malformed card: ${card}`);
  }
  const value = wordToNumber(parts[0]);
  const suit = normalizeSuit(parts[2]);
  return { value, suit };
}

const parseHand = (hand) => {
  if (!Array.isArray(hand) || hand.length !== 5) {
    throw new Error('a hand must contain exactly five cards');
  }
  return hand.map(parseCard);
};

const isFlush = (cards) => cards.every((card) => card.suit === cards[0].suit);

const sortedValues = (cards) => cards.map((card) => card.value).sort((a, b) => a - b);

const isStraight = (cards) => {
  const values = sortedValues(cards);
  return values.every((value, index) => index === 0 || value === values[index - 1] + 1);
};

function rank(hand) {
  const cards = parseHand(hand);
  const flush = isFlush(cards);
  const straight = isStraight(cards);
  if (straight && flush) return 4;
  if (flush) return 3;
  if (straight) return 2;
  return 1;
}

const describeScore = (score) => (
  ['high card', 'straight', 'flush', 'straight flush'][score - 1]
);

const formatReport = (hand) => {
  const cards = parseHand(hand);
  const values = sortedValues(cards);
  const score = rank(hand);
  const label = describeScore(score);
  return `${hand.join(', ')} => ${score} (${label}, high ${values[4]})`;
};

const hands = [
  ['two of hearts', 'three of hearts', 'four of hearts', 'five of hearts', 'six of hearts'],
  ['two of hearts', 'three of hearts', 'four of hearts', 'five of hearts', 'nine of hearts'],
  ['ten of clubs', 'jack of spades', 'queen of hearts', 'king of clubs', 'ace of diamonds'],
  ['two of clubs', 'seven of spades', 'nine of hearts', 'jack of clubs', 'ace of diamonds'],
];

hands.forEach((hand) => console.log(formatReport(hand)));

module.exports = { rank, parseCard, isFlush, isStraight, formatReport };

