const greatestCommonDivisor = (a, b) => {
  let x = Math.abs(a);
  let y = Math.abs(b);
  while (y !== 0) {
    const remainder = x % y;
    x = y;
    y = remainder;
  }
  return x;
};

const leastCommonMultiple = (a, b) => {
  const divisor = greatestCommonDivisor(a, b);
  if (divisor === 0) {
    throw new Error('least common multiple of zero is undefined');
  }
  return Math.abs(a / divisor * b);
};

const simplifyFraction = ([numerator, denominator]) => {
  if (denominator === 0) {
    throw new Error('denominator must not be zero');
  }
  const sign = denominator < 0 ? -1 : 1;
  const divisor = greatestCommonDivisor(numerator, denominator) || 1;
  return [sign * numerator / divisor, sign * denominator / divisor];
};

const addFractions = (left, right) => {
  const [leftNum, leftDen] = left;
  const [rightNum, rightDen] = right;
  const commonDenominator = leastCommonMultiple(leftDen, rightDen);
  const scaledLeft = leftNum * (commonDenominator / leftDen);
  const scaledRight = rightNum * (commonDenominator / rightDen);
  return simplifyFraction([scaledLeft + scaledRight, commonDenominator]);
};

const validateFraction = (fraction) => {
  if (!Array.isArray(fraction) || fraction.length !== 2) {
    throw new Error('each fraction must be a list of two integers');
  }
  const allIntegers = fraction.every((value) => Number.isInteger(value));
  if (!allIntegers) {
    throw new Error(`fraction contains non-integer values: ${fraction}`);
  }
  return fraction;
};

function calculate(fractions) {
  if (!Array.isArray(fractions) || fractions.length === 0) {
    throw new Error('at least one fraction is required');
  }
  const checked = fractions.map(validateFraction);
  const initial = simplifyFraction(checked[0]);
  return checked.slice(1).reduce(addFractions, initial);
}

const formatFraction = ([numerator, denominator]) =>
  denominator === 1 ? `${numerator}` : `${numerator}/${denominator}`;

const reportSum = (fractions) => {
  const terms = fractions.map(formatFraction).join(' + ');
  const total = calculate(fractions);
  return `${terms} = ${formatFraction(total)}`;
};

const samples = [
  [[1, 2], [1, 3], [1, 6]],
  [[3, 4], [-1, 8], [5, 12]],
  [[7, 3]],
];

samples.forEach((sample) => {
  console.log(reportSum(sample));
});

module.exports = {
  calculate,
  addFractions,
  simplifyFraction,
  greatestCommonDivisor,
  leastCommonMultiple,
  formatFraction,
  reportSum,
};

