const isEmptyNode = (node) => node === null || node === undefined;

function nodeValue(node) {
  return node[0];
}

function leftChild(node) {
  return node[1];
}

function rightChild(node) {
  return node[2];
}

const isNodeShaped = (node) => Array.isArray(node) && node.length === 3;

function hasNumericValue(node) {
  const value = nodeValue(node);
  return typeof value === "number" && Number.isFinite(value);
}

function inOrderTraversal(node) {
  if (isEmptyNode(node)) {
    return [];
  }
  const left = leftChild(node);
  const right = rightChild(node);
  const values = inOrderTraversal(left);
  values.push(nodeValue(node));
  return values.concat(inOrderTraversal(right));
}

function isStrictlyAscending(values) {
  for (let i = 1; i < values.length; i += 1) {
    if (values[i - 1] >= values[i]) {
      return false;
    }
  }
  return true;
}

function isWellFormed(node) {
  if (isEmptyNode(node)) {
    return true;
  }
  if (!isNodeShaped(node)) {
    return false;
  }
  if (!hasNumericValue(node)) {
    return false;
  }
  const left = leftChild(node);
  const right = rightChild(node);
  if (!isWellFormed(left)) {
    return false;
  }
  return isWellFormed(right);
}

function verify(tree) {
  if (!isWellFormed(tree)) {
    return false;
  }
  const values = inOrderTraversal(tree);
  return isStrictlyAscending(values);
}

module.exports = {
  verify,
  nodeValue,
  leftChild,
  rightChild,
  inOrderTraversal,
  isStrictlyAscending,
};

