const isLeapYear = (year) => {
  if (year % 400 === 0) return true;
  if (year % 100 === 0) return false;
  return year % 4 === 0;
};

const daysInMonth = (year, month) => {
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month === 2 && isLeapYear(year)) return 29;
  return lengths[month - 1];
};

const parseDateString = (text) => {
  const parts = String(text).trim().split('-');
  if (parts.length !== 3) {
    throw new Error(`invalid date format: ${text}`);
  }
  const [year, month, day] = parts.map((part) => {
    if (!/^\d+$/.test(part)) {
      throw new Error(`invalid date component: ${part}`);
    }
    return Number(part);
  });
  return { year, month, day };
};

const validateDate = ({ year, month, day }) => {
  if (month < 1 || month > 12) {
    throw new Error(`month out of range: ${month}`);
  }
  const limit = daysInMonth(year, month);
  if (day < 1 || day > limit) {
    throw new Error(`day out of range: ${day}`);
  }
};

const daysFromYearStart = ({ year, month, day }) => {
  let total = day;
  for (let m = 1; m < month; m += 1) {
    total += daysInMonth(year, m);
  }
  return total;
};

const daysSinceYearZero = (date) => {
  const previous = date.year - 1;
  const leapDays = Math.floor(previous / 4) - Math.floor(previous / 100) + Math.floor(previous / 400);
  return date.year * 365 + leapDays + daysFromYearStart(date);
};

function measure(dates) {
  if (!Array.isArray(dates) || dates.length !== 2) {
    throw new Error('measure expects exactly two date strings');
  }
  const parsed = dates.map(parseDateString);
  parsed.forEach(validateDate);
  const [first, second] = parsed.map(daysSinceYearZero);
  return Math.abs(second - first);
}

const describeSpan = (dates) => {
  const days = measure(dates);
  return `${dates[0]} .. ${dates[1]}: ${days} day${days === 1 ? '' : 's'}`;
};

