const parseCidrString = (cidr) => {
  const parts = String(cidr).split('/');
  if (parts.length !== 2) {
    throw new Error(`malformed CIDR notation: ${cidr}`);
  }
  const prefix = Number(parts[1]);
  if (!Number.isInteger(prefix) || prefix < 0 || prefix > 32) {
    throw new Error(`prefix length out of range: ${parts[1]}`);
  }
  return { address: parts[0], prefix };
};

const ipToInteger = (dotted) => {
  const octets = dotted.split('.');
  if (octets.length !== 4) {
    throw new Error(`address needs four octets: ${dotted}`);
  }
  return octets.reduce((accumulated, text) => {
    const value = Number(text);
    if (!/^\d{1,3}$/.test(text) || value > 255) {
      throw new Error(`invalid octet "${text}" in ${dotted}`);
    }
    return accumulated * 256 + value;
  }, 0);
};

const integerToIp = (value) => {
  const octets = [];
  for (let shift = 24; shift >= 0; shift -= 8) {
    octets.push(Math.floor(value / 2 ** shift) % 256);
  }
  return octets.join('.');
};

const maskFromPrefix = (prefix) => (prefix === 0 ? 0 : 2 ** 32 - 2 ** (32 - prefix));

const networkAddressInt = (addressInt, maskInt) => (addressInt & maskInt) >>> 0;

const broadcastAddressInt = (networkInt, maskInt) => (networkInt | ~maskInt) >>> 0;

const usableHostCount = (prefix) => (prefix >= 31 ? 0 : 2 ** (32 - prefix) - 2);

function subnet(cidr) {
  const { address, prefix } = parseCidrString(cidr);
  const addressInt = ipToInteger(address);
  const maskInt = maskFromPrefix(prefix);
  const networkInt = networkAddressInt(addressInt, maskInt);
  const broadcastInt = broadcastAddressInt(networkInt, maskInt);
  const network = integerToIp(networkInt);
  const broadcast = integerToIp(broadcastInt);
  return [network, broadcast, usableHostCount(prefix)];
}

const formatSubnetReport = (cidr) => {
  const [network, broadcast, hosts] = subnet(cidr);
  const { prefix } = parseCidrString(cidr);
  const maskInt = maskFromPrefix(prefix);
  const mask = integerToIp(maskInt);
  return `${cidr}: network ${network}, broadcast ${broadcast}, mask ${mask}, hosts ${hosts}`;
};

const inputs = ['192.168.1.10/24', '10.0.0.77/8', '172.16.5.200/20', '203.0.113.9/31'];
for (const cidr of inputs) {
  console.log(formatSubnetReport(cidr));
}

module.exports = {
  subnet,
  ipToInteger,
  integerToIp,
  maskFromPrefix,
  networkAddressInt,
  broadcastAddressInt,
  usableHostCount,
  formatSubnetReport,
};

