const BASE64_ALPHABET =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

const assertPlainText = (text) => {
  if (typeof text !== 'string') {
    throw new TypeError('encode expects a string');
  }
  for (let i = 0; i < text.length; i += 1) {
    if (text.charCodeAt(i) > 255) {
      throw new RangeError(`character "${text[i]}" is not a single byte`);
    }
  }
  return text;
};

const charToBinary = (char) => {
  const code = char.charCodeAt(0);
  let bits = '';
  for (let power = 7; power >= 0; power -= 1) {
    bits += Math.floor(code / 2 ** power) % 2;
  }
  return bits;
};

const textToBinaryStream = (text) => {
  const safe = assertPlainText(text);
  let stream = '';
  for (const char of safe) {
    stream += charToBinary(char);
  }
  return stream;
};

const padChunkToSixBits = (chunk) => {
  let padded = chunk;
  while (padded.length < 6) {
    padded += '0';
  }
  return padded;
};

const splitIntoSixBitChunks = (stream) => {
  const chunks = [];
  for (let i = 0; i < stream.length; i += 6) {
    chunks.push(padChunkToSixBits(stream.slice(i, i + 6)));
  }
  return chunks;
};

const sixBitToDecimal = (bits) => {
  let value = 0;
  for (const bit of bits) {
    value = value * 2 + (bit === '1' ? 1 : 0);
  }
  return value;
};

const decimalToBase64Char = (value) => {
  if (value < 0 || value > 63) {
    throw new RangeError(`value ${value} is outside the base64 range`);
  }
  return BASE64_ALPHABET[value];
};

const buildPadding = (byteLength) => {
  const remainder = byteLength % 3;
  return remainder === 0 ? '' : '='.repeat(3 - remainder);
};

function encode(text) {
  const stream = textToBinaryStream(text);
  const chunks = splitIntoSixBitChunks(stream);
  let encoded = '';
  for (const chunk of chunks) {
    const value = sixBitToDecimal(chunk);
    encoded += decimalToBase64Char(value);
  }
  return encoded + buildPadding(text.length);
}

const formatEncodedReport = (text) => `"${text}" -> ${encode(text)}`;

for (const sample of ['Hi', 'Man', 'any carnal pleasure', '', 'f']) {
  console.log(formatEncodedReport(sample));
}

module.exports = { encode, charToBinary, splitIntoSixBitChunks };

