const validateParameters = (parameters) => {
  if (!Array.isArray(parameters) || parameters.length !== 3) {
    throw new TypeError('paginate expects a list of three numbers');
  }
  const [totalItems, perPage, currentPage] = parameters.map(Number);
  if (![totalItems, perPage, currentPage].every(Number.isFinite)) {
    throw new TypeError('paginate expects numeric values');
  }
  if (perPage < 1 || currentPage < 1 || totalItems < 0) {
    throw new RangeError('paginate expects positive page settings');
  }
  return [Math.floor(totalItems), Math.floor(perPage), Math.floor(currentPage)];
};

const calculateTotalPages = (totalItems, perPage) => Math.ceil(totalItems / perPage);

const clampCurrentPage = (currentPage, totalPages) => Math.min(currentPage, Math.max(totalPages, 1));

const calculateStartIndex = (page, perPage) => (page - 1) * perPage + 1;

const calculateEndIndex = (page, perPage, totalItems) => Math.min(page * perPage, totalItems);

const hasPreviousPage = (page) => (page > 1 ? 1 : 0);

const hasNextPage = (page, totalPages) => (page < totalPages ? 1 : 0);

function paginate(parameters) {
  const [totalItems, perPage, requestedPage] = validateParameters(parameters);
  const totalPages = calculateTotalPages(totalItems, perPage);
  const page = clampCurrentPage(requestedPage, totalPages);
  return [
    totalPages,
    calculateStartIndex(page, perPage),
    calculateEndIndex(page, perPage, totalItems),
    hasPreviousPage(page),
    hasNextPage(page, totalPages),
  ];
}

const formatPaginationReport = (parameters) => {
  const [totalPages, start, end, previous, next] = paginate(parameters);
  const range = start > end ? 'no items' : `items ${start}-${end}`;
  const neighbours = [previous ? 'prev' : null, next ? 'next' : null].filter(Boolean);
  const links = neighbours.length ? neighbours.join('/') : 'none';
  return `page ${clampCurrentPage(parameters[2], totalPages)} of ${totalPages}: ${range} (links: ${links})`;
};

const runDriver = () => {
  const requests = [
    [55, 10, 3],
    [55, 10, 1],
    [55, 10, 6],
    [0, 10, 1],
    [7, 3, 2],
  ];
  requests.forEach((request) => {
    console.log(JSON.stringify(request), '->', JSON.stringify(paginate(request)));
    console.log('   ', formatPaginationReport(request));
  });
};

runDriver();

module.exports = {
  paginate,
  calculateTotalPages,
  calculateStartIndex,
  calculateEndIndex,
  hasPreviousPage,
  hasNextPage,
  formatPaginationReport,
};

