const K_FACTOR = 30;
const VALID_SCORES = [0, 0.5, 1];

function transformedRating(rating) {
  return Math.pow(10, rating / 400);
}

function expectedScore(rating, opponentRating) {
  const own = transformedRating(rating);
  const other = transformedRating(opponentRating);
  return own / (own + other);
}

function ratingChange(actualScore, expected) {
  return K_FACTOR * (actualScore - expected);
}

function updateRating(currentRating, actualScore, expected) {
  return currentRating + ratingChange(actualScore, expected);
}

const normalizeOutcome = (value) => {
  const score = Number(value);
  if (!VALID_SCORES.includes(score)) {
    throw new RangeError(`match outcome must be 0, 0.5 or 1, got ${value}`);
  }
  return score;
};

function parseMatchOutcomes(matches) {
  if (!Array.isArray(matches) || matches.length < 2) {
    throw new TypeError('input must list two ratings followed by match outcomes');
  }
  const [first, second] = matches;
  if (!Number.isFinite(Number(first)) || !Number.isFinite(Number(second))) {
    throw new TypeError('the first two entries must be numeric ratings');
  }
  return matches.slice(2).map(normalizeOutcome);
}

function rank(matches) {
  const outcomes = parseMatchOutcomes(matches);
  let playerOne = Number(matches[0]);
  let playerTwo = Number(matches[1]);
  for (const scoreOne of outcomes) {
    const expectedOne = expectedScore(playerOne, playerTwo);
    const expectedTwo = expectedScore(playerTwo, playerOne);
    const nextOne = updateRating(playerOne, scoreOne, expectedOne);
    playerTwo = updateRating(playerTwo, 1 - scoreOne, expectedTwo);
    playerOne = nextOne;
  }
  return [Math.round(playerOne), Math.round(playerTwo)];
}

const formatRatingLine = (label, before, after) => {
  const delta = after - before;
  const sign = delta >= 0 ? '+' : '-';
  return `${label}: ${before} -> ${after} (${sign}${Math.abs(delta)})`;
};

function reportRanking(matches) {
  const [finalOne, finalTwo] = rank(matches);
  const played = parseMatchOutcomes(matches).length;
  return [
    `${played} match(es) played`,
    formatRatingLine('player one', Number(matches[0]), finalOne),
    formatRatingLine('player two', Number(matches[1]), finalTwo),
  ].join('\n');
}

console.log(reportRanking([1500, 1500, 1, 0, 1]));
console.log(reportRanking([1200, 1400, 0.5, 0.5, 1, 0]));

module.exports = { rank, transformedRating, expectedScore, ratingChange, updateRating, reportRanking };

