const getRowChars = (board, rowIndex) => board[rowIndex].split('');

const getColumnChars = (board, colIndex) => board.map((row) => row[colIndex]);

const getDiagonalChars = (board) => [
  [board[0][0], board[1][1], board[2][2]],
  [board[0][2], board[1][1], board[2][0]],
];

const isSamePlayerMark = (line) => line[0] !== '.' && line.every((cell) => cell === line[0]);

const countEmptySpaces = (board) => board.join('').split('').filter((cell) => cell === '.').length;

const collectAllLines = (board) => {
  const lines = [];
  for (let index = 0; index < 3; index += 1) {
    lines.push(getRowChars(board, index));
    lines.push(getColumnChars(board, index));
  }
  return lines.concat(getDiagonalChars(board));
};

const findWinningMark = (board) => {
  const lines = collectAllLines(board);
  const winner = lines.find(isSamePlayerMark);
  return winner ? winner[0] : null;
};

function validateBoard(board) {
  if (!Array.isArray(board) || board.length !== 3) {
    throw new TypeError('board must be a list of three rows');
  }
  board.forEach((row) => {
    if (typeof row !== 'string' || !/^[XO.]{3}$/.test(row)) {
      throw new TypeError(`invalid row: ${String(row)}`);
    }
  });
  return board;
}

function judge(board) {
  validateBoard(board);
  const mark = findWinningMark(board);
  if (mark) {
    return `${mark} wins`;
  }
  if (countEmptySpaces(board) === 0) {
    return 'Draw';
  }
  return 'Ongoing';
}

const parseBoardArgument = (args) => {
  if (args.length === 1) {
    return args[0].split(/[,/|]/).map((part) => part.trim());
  }
  return args;
};

const describeBoard = (board) => {
  const picture = board.map((row, index) => `${index}: ${row}`).join('\n');
  return `${picture}\n=> ${judge(board)}`;
};

function main(argv) {
  const board = parseBoardArgument(argv);
  if (board.length === 0) {
    process.stderr.write('usage: node judge.js "XXO,O.X,X.O"\n');
    process.exitCode = 1;
    return;
  }
  try {
    process.stdout.write(`${describeBoard(board)}\n`);
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}

if (require.main === module) {
  main(process.argv.slice(2));
}

module.exports.judge = judge;
module.exports.getRowChars = getRowChars;
module.exports.getColumnChars = getColumnChars;
module.exports.getDiagonalChars = getDiagonalChars;
module.exports.isSamePlayerMark = isSamePlayerMark;
module.exports.countEmptySpaces = countEmptySpaces;

