const SHARP_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const FLAT_NAMES = ['C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab', 'A', 'Bb', 'B'];

const normalizeNoteName = (note) => {
  const letter = note.trim().charAt(0).toUpperCase();
  const accidental = note.trim().slice(1).toLowerCase().replace('♯', '#').replace('♭', 'b');
  return letter + accidental;
};

const noteToIndex = (note) => {
  const name = normalizeNoteName(note);
  const sharpIndex = SHARP_NAMES.indexOf(name);
  if (sharpIndex >= 0) return sharpIndex;
  const flatIndex = FLAT_NAMES.indexOf(name);
  if (flatIndex >= 0) return flatIndex;
  throw new Error(`Unknown note: ${note}`);
};

const prefersFlatNames = (root) => {
  const name = normalizeNoteName(root);
  return name.endsWith('b');
};

const indexToNote = (index, useFlats) => {
  const table = useFlats ? FLAT_NAMES : SHARP_NAMES;
  return table[((index % 12) + 12) % 12];
};

const majorIntervals = () => [2, 2, 1, 2, 2, 2];

const minorIntervals = () => [2, 1, 2, 2, 1, 2];

const intervalsForMode = (mode) => {
  const normalized = mode.trim().toLowerCase();
  if (normalized === 'major') return majorIntervals();
  if (normalized === 'minor') return minorIntervals();
  throw new Error(`Unknown mode: ${mode}`);
};

const nextNoteIndex = (index, interval) => (index + interval) % 12;

const buildScale = (rootIndex, intervals, useFlats) => {
  const notes = [indexToNote(rootIndex, useFlats)];
  let current = rootIndex;
  for (const step of intervals) {
    current = nextNoteIndex(current, step);
    notes.push(indexToNote(current, useFlats));
  }
  return notes;
};

function scale(parameters) {
  const [root, mode] = parameters;
  const rootIndex = noteToIndex(root);
  const intervals = intervalsForMode(mode);
  const useFlats = prefersFlatNames(root);
