const G = 1;
const DT = 1;

const SubtractVectors = (a, b) => a.map((value, i) => value - b[i]);
const AddVectors = (a, b) => a.map((value, i) => value + b[i]);
const ScaleVector = (v, factor) => v.map((value) => value * factor);
const VectorLength = (v) => Math.sqrt(v.reduce((sum, value) => sum + value * value, 0));
const ZeroVector = (size) => new Array(size).fill(0);

function ValidateBodies(bodies) {
  if (!Array.isArray(bodies)) throw new TypeError('bodies must be an array');
  bodies.forEach((body, index) => {
    if (!Array.isArray(body.position)) throw new TypeError(`body ${index} has no position vector`);
    if (!(body.mass > 0)) throw new RangeError(`body ${index} needs a positive mass`);
    if (body.velocity && body.velocity.length !== body.position.length) {
      throw new RangeError(`body ${index} mixes vectors of different dimensions`);
    }
  });
}

const NormalizeBody = (body) => ({
  mass: body.mass,
  position: body.position.slice(),
  velocity: body.velocity ? body.velocity.slice() : ZeroVector(body.position.length),
});

const PairAcceleration = (target, source) => {
  const offset = SubtractVectors(source.position, target.position);
  const distance = VectorLength(offset);
  if (distance === 0) return ZeroVector(offset.length);
  const strength = (G * source.mass) / (distance * distance * distance);
  return ScaleVector(offset, strength);
};

const AccelerationOn = (target, bodies) => {
  let total = ZeroVector(target.position.length);
  for (const other of bodies) {
    if (other === target) continue;
    const pull = PairAcceleration(target, other);
    total = AddVectors(total, pull);
  }
  return total;
};

const AccumulateAccelerations = (bodies) => bodies.map((body) => AccelerationOn(body, bodies));

const AdvanceVelocity = (body, acceleration, dt) => {
  const deltaV = ScaleVector(acceleration, dt);
  return { mass: body.mass, position: body.position, velocity: AddVectors(body.velocity, deltaV) };
};

const AdvancePosition = (body, dt) => {
  const deltaX = ScaleVector(body.velocity, dt);
  return { mass: body.mass, position: AddVectors(body.position, deltaX), velocity: body.velocity };
};

function StepSimulation(bodies, dt) {
  const accelerations = AccumulateAccelerations(bodies);
  const pushed = bodies.map((body, i) => AdvanceVelocity(body, accelerations[i], dt));
  return pushed.map((body) => AdvancePosition(body, dt));
}

