const OPERATORS = ['+', '-', '*', '/'];

const isOperatorToken = (token) => OPERATORS.includes(token);

const tokenizeExpression = (expression) => {
  if (typeof expression !== 'string') {
    throw new TypeError('expression must be a string');
  }
  return expression.trim().split(/\s+/).filter((token) => token.length > 0);
};

const parseNumberToken = (token) => {
  const value = Number(token);
  if (!Number.isFinite(value)) {
    throw new SyntaxError(`unexpected token: ${token}`);
  }
  return { type: 'number', value };
};

const buildSyntaxTree = (tokens) => {
  if (tokens.length === 0) {
    throw new SyntaxError('unexpected end of expression');
  }
  const token = tokens.shift();
  if (isOperatorToken(token)) {
    const left = buildSyntaxTree(tokens);
    const right = buildSyntaxTree(tokens);
    return { type: 'operation', operator: token, left, right };
  }
  return parseNumberToken(token);
};

const parseExpression = (expression) => {
  const tokens = tokenizeExpression(expression);
  const tree = buildSyntaxTree(tokens);
  if (tokens.length > 0) {
    throw new SyntaxError(`trailing tokens: ${tokens.join(' ')}`);
  }
  return tree;
};

const applyOperation = (operator, left, right) => {
  switch (operator) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/':
      if (right === 0) {
        throw new RangeError('division by zero');
      }
      return left / right;
    default:
      throw new SyntaxError(`unknown operator: ${operator}`);
  }
};

const evaluateNode = (node) => {
  if (node.type === 'number') {
    return node.value;
  }
  const left = evaluateNode(node.left);
  const right = evaluateNode(node.right);
  return applyOperation(node.operator, left, right);
};

const formatSyntaxTree = (node) => {
  if (node.type === 'number') {
    return String(node.value);
  }
  const left = formatSyntaxTree(node.left);
  const right = formatSyntaxTree(node.right);
  return `(${left} ${node.operator} ${right})`;
};

function evaluate(expression) {
  const tree = parseExpression(expression);
  return evaluateNode(tree);
}

const describeExpression = (expression) => {
  const tree = parseExpression(expression);
  const infix = formatSyntaxTree(tree);
  return `${expression.trim()}  =>  ${infix}  =  ${evaluateNode(tree)}`;
};

function main(argv) {
  if (argv.length === 0) {
    process.stderr.write('usage: node prefix.js "+ 2 3"\n');
    process.exitCode = 1;
    return;
  }
  process.stdout.write(`${describeExpression(argv.join(' '))}\n`);
}

if (require.main === module) {
  main(process.argv.slice(2));
}

module.exports = { evaluate, describeExpression };

