const getNeighbors = (graph, node) => graph[node] || {};

function validateGraph(graph, start, end) {
  const nodes = Object.keys(graph);
  if (!nodes.includes(start) || !nodes.includes(end)) {
    throw new Error(`endpoints ${start}/${end} are not present in the graph`);
  }
  for (const node of nodes) {
    const edges = getNeighbors(graph, node);
    for (const [target, weight] of Object.entries(edges)) {
      if (typeof weight !== 'number' || weight < 0) {
        throw new Error(`edge ${node}->${target} has an invalid weight`);
      }
      if (!nodes.includes(target)) {
        throw new Error(`edge ${node}->${target} points to an unknown node`);
      }
    }
  }
  return nodes;
}

function initializeDistances(nodes, start) {
  const distances = {};
  for (const node of nodes) {
    distances[node] = node === start ? 0 : Infinity;
  }
  return distances;
}

function findClosestUnvisited(distances, visited) {
  let best = null;
  for (const [node, distance] of Object.entries(distances)) {
    if (visited.has(node) || distance === Infinity) continue;
    if (best === null || distance < distances[best]) best = node;
  }
  return best;
}

function relaxNeighbors(graph, current, distances, previous, visited) {
  const edges = getNeighbors(graph, current);
  for (const [neighbor, weight] of Object.entries(edges)) {
    if (visited.has(neighbor)) continue;
    const candidate = distances[current] + weight;
    if (candidate < distances[neighbor]) {
      distances[neighbor] = candidate;
      previous[neighbor] = current;
    }
  }
}

function buildPathFromPrevious(previous, start, end) {
  const path = [];
  let cursor = end;
  while (cursor !== undefined) {
    path.unshift(cursor);
    if (cursor === start) return path;
    cursor = previous[cursor];
  }
  return [];
}

function navigate(graph, start, end) {
  const nodes = validateGraph(graph, start, end);
  const distances = initializeDistances(nodes, start);
  const previous = {};
  const visited = new Set();
  let current = findClosestUnvisited(distances, visited);
  while (current !== null && current !== end) {
    relaxNeighbors(graph, current, distances, previous, visited);
    visited.add(current);
    current = findClosestUnvisited(distances, visited);
  }
  return buildPathFromPrevious(previous, start, end);
}

const totalPathWeight = (graph, path) =>
  path.slice(1).reduce((sum, node, index) => sum + getNeighbors(graph, path[index])[node], 0);

function formatPathReport(graph, path) {
  if (path.length === 0) return 'no route found';
  const weight = totalPathWeight(graph, path);
  return `${path.join(' -> ')} (cost ${weight})`;
}

const triangle = {
  A: { B: 5, C: 9 },
  B: { A: 5, C: 3 },
  C: { A: 9, B: 3 },
};

const shortLeg = navigate(triangle, 'A', 'C');
console.log(formatPathReport(triangle, shortLeg));
const backLeg = navigate(triangle, 'B', 'A');
console.log(formatPathReport(triangle, backLeg));

