const isDotWildcard = (ch) => ch === '.';

const charMatches = (patternChar, textChar) => {
  if (textChar === undefined) return false;
  return isDotWildcard(patternChar) || patternChar === textChar;
};

const nextToken = (pattern) => {
  const char = pattern[0];
  const starred = pattern[1] === '*';
  return { char, starred, rest: pattern.slice(starred ? 2 : 1) };
};

const validatePattern = (pattern) => {
  if (typeof pattern !== 'string') {
    throw new TypeError('pattern must be a string');
  }
  for (let i = 0; i < pattern.length; i += 1) {
    if (pattern[i] !== '*') continue;
    if (i === 0 || pattern[i - 1] === '*') {
      throw new SyntaxError(`star at index ${i} has no preceding character`);
    }
  }
  return pattern;
};

const matchStarToken = (token, text) => {
  if (matchTokens(token.rest, text)) return true;
  let consumed = 0;
  while (charMatches(token.char, text[consumed])) {
    consumed += 1;
    if (matchTokens(token.rest, text.slice(consumed))) return true;
  }
  return false;
};

const matchTokens = (pattern, text) => {
  if (pattern.length === 0) return text.length === 0;
  const token = nextToken(pattern);
  if (token.starred) {
    return matchStarToken(token, text);
  }
  if (!charMatches(token.char, text[0])) return false;
  return matchTokens(token.rest, text.slice(1));
};

function match(pattern, text) {
  validatePattern(pattern);
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  return matchTokens(pattern, text);
}

const formatOutcome = (pattern, text, result) =>
  `${JSON.stringify(pattern)} vs ${JSON.stringify(text)} -> ${result}`;

const runCases = (cases) =>
  cases.map(([pattern, text]) => {
    try {
      return formatOutcome(pattern, text, match(pattern, text));
    } catch (err) {
      return formatOutcome(pattern, text, `error: ${err.message}`);
    }
  });

const main = () => {
  const cases = [
    ['a*', 'aaaaa'],
    ['a*b', 'aaab'],
    ['.*', 'anything'],
    ['a.c', 'abc'],
    ['a.c', 'abd'],
    ['ab*c.', 'abbbbcd'],
    ['*a', 'a'],
  ];
  runCases(cases).forEach((line) => console.log(line));
};

main();

module.exports = { match, matchTokens, nextToken, charMatches, validatePattern };

