const ESCAPE_MAP = {
  '"': '\\"',
  '\\': '\\\\',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
  '\b': '\\b',
  '\f': '\\f'
};

const escapeSpecialCharacters = (text) =>
  text.replace(/[\\"\u0000-\u001f]/g, (char) => {
    if (Object.prototype.hasOwnProperty.call(ESCAPE_MAP, char)) {
      return ESCAPE_MAP[char];
    }
    return '\\u' + char.charCodeAt(0).toString(16).padStart(4, '0');
  });

const formatTextString = (text) => {
  const escaped = escapeSpecialCharacters(text);
  return '"' + escaped + '"';
};

const formatSimpleValue = (value) => {
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (Number.isFinite(value)) {
    return String(value);
  }
  return 'null';
};

const detectValueKind = (value) => {
  if (value === null || value === undefined) return 'null';
  if (Array.isArray(value)) return 'array';
  if (typeof value === 'string') return 'string';
  if (typeof value === 'number' || typeof value === 'boolean') return 'simple';
  if (typeof value === 'object') return 'object';
  return 'unsupported';
};

const formatArrayElements = (items) => {
  const parts = items.map((item) => stringify(item));
  return '[' + parts.join(',') + ']';
};

const formatObjectProperties = (source) => {
  const parts = [];
  for (const key of Object.keys(source)) {
    const value = source[key];
    if (detectValueKind(value) === 'unsupported') continue;
    const encodedKey = formatTextString(key);
    parts.push(encodedKey + ':' + stringify(value));
  }
  return '{' + parts.join(',') + '}';
};

