  switch (detectValueKind(data)) {
    case 'string':
      return formatTextString(data);
    case 'simple':
      return formatSimpleValue(data);
    case 'array':
      return formatArrayElements(data);
    case 'object':
      return formatObjectProperties(data);
    default:
      return 'null';
  }
}

