const isValidModuleName = (name) => typeof name === 'string' && name.trim().length > 0;

const normalizeDependencies = (raw) => {
  if (Array.isArray(raw)) return raw.map((dep) => String(dep).trim());
  if (raw === undefined || raw === null || raw === '') return [];
  return [String(raw).trim()];
};

const toEntryList = (packages) => {
  const rawEntries = Array.isArray(packages)
    ? packages.map((item) => (Array.isArray(item) ? [item[0], item[1]] : [item.name, item.dependencies]))
    : Object.entries(packages || {});
  return rawEntries.map(([name, deps]) => {
    if (!isValidModuleName(name)) throw new TypeError(`invalid module name: ${JSON.stringify(name)}`);
    return [name.trim(), normalizeDependencies(deps)];
  });
};

const buildDependencyMap = (packages) => {
  const depMap = new Map();
  for (const [name, deps] of toEntryList(packages)) {
    const own = deps.filter((dep) => dep !== name);
    depMap.set(name, own);
  }
  for (const deps of [...depMap.values()]) {
    for (const dep of deps) {
      if (!isValidModuleName(dep)) throw new TypeError(`invalid dependency name: ${JSON.stringify(dep)}`);
      if (!depMap.has(dep)) depMap.set(dep, []);
    }
  }
  return depMap;
};

const sortModuleNames = (names) => [...names].sort((a, b) => a.localeCompare(b));

const collectModuleNames = (depMap) => sortModuleNames(depMap.keys());

const isDependencySatisfied = (dep, resolved) => resolved.has(dep);

const hasAllDependenciesResolved = (deps, resolved) => deps.every((dep) => isDependencySatisfied(dep, resolved));

const findReadyModules = (depMap, resolved, pending) => {
  const ready = [...pending].filter((name) => hasAllDependenciesResolved(depMap.get(name), resolved));
  return sortModuleNames(ready);
};

const build = (packages) => {
  const depMap = buildDependencyMap(packages);
  const pending = new Set(collectModuleNames(depMap));
  const resolved = new Set();
  const order = [];
  while (pending.size > 0) {
    const ready = findReadyModules(depMap, resolved, pending);
    if (ready.length === 0) return [];
    for (const name of ready) {
      order.push(name);
      resolved.add(name);
      pending.delete(name);
    }
  }
  return order;
};

const formatBuildOrder = (order) =>
  order.length > 0 ? order.join(' -> ') : '(circular dependency: nothing can be compiled)';

const reportBuild = (label, packages) => {
  const order = build(packages);
  console.log(`${label}: ${formatBuildOrder(order)}`);
  return order;
};

reportBuild('two dependent packages', { app: ['core'], core: [] });
reportBuild('toolchain', {
