});
reportBuild('entry list form', [['gui', 'widgets'], ['widgets', ['canvas']]]);
reportBuild('cyclic', { alpha: ['beta'], beta: ['gamma'], gamma: ['alpha'] });

module.exports = { build, buildDependencyMap, findReadyModules, formatBuildOrder };

