  category: normalizeCategory(record.category),
  amount: parseAmount(record.amount)
});

const keepSettled = (transactions) => transactions.filter((record) => !isPendingTransaction(record));

const groupByCategory = (entries) => {
  const totals = new Map();
  for (const entry of entries) {
    const previous = totals.has(entry.category) ? totals.get(entry.category) : 0;
