const splitIntoWords = (text) => text.split(/\s+/).filter((word) => word.length > 0);

const buildTransitionMap = (words) => {
  const map = new Map();
  for (let i = 0; i < words.length - 1; i += 1) {
    const current = words[i];
    if (!map.has(current)) {
      map.set(current, []);
    }
    map.get(current).push(words[i + 1]);
  }
  return map;
};

const pickRandomItem = (items) => items[Math.floor(Math.random() * items.length)];

const chooseNextWord = (transitions, word, allWords) => {
  const followers = transitions.get(word);
  if (followers === undefined) {
    return pickRandomItem(allWords);
  }
  return pickRandomItem(followers);
};

const formatSentence = (words) => words.join(' ');

function babble(text, length) {
  const words = splitIntoWords(text);
  if (words.length === 0 || length <= 0) {
    return '';
  }
  const transitions = buildTransitionMap(words);
  const result = [pickRandomItem(words)];
  while (result.length < length) {
    const previous = result[result.length - 1];
    result.push(chooseNextWord(transitions, previous, words));
  }
  return formatSentence(result);
}

const countWordUses = (sentence) => {
  const counts = new Map();
  for (const word of splitIntoWords(sentence)) {
    counts.set(word, (counts.get(word) || 0) + 1);
  }
  return counts;
};

const describeFrequencies = (sentence) => {
  const counts = countWordUses(sentence);
