const validateFadeParams = (duration, rate) => {
  if (typeof duration !== 'number' || !Number.isFinite(duration) || duration <= 0) {
    throw new RangeError(`duration must be a positive finite number, got ${duration}`);
  }
  if (!Number.isInteger(rate) || rate <= 0) {
    throw new RangeError(`rate must be a positive integer, got ${rate}`);
  }
};

const countTotalSamples = (duration, rate) => Math.max(1, Math.round(duration * rate));

const normalizedPosition = (index, total) => (total <= 1 ? 1 : index / (total - 1));

function fadeOutMultiplier(index, total) {
  return 0.5 * (1 + Math.cos(Math.PI * normalizedPosition(index, total)));
}

function fadeInMultiplier(index, total) {
  return 1 - fadeOutMultiplier(index, total);
}

function crossfade(duration, rate) {
  validateFadeParams(duration, rate);
  const total = countTotalSamples(duration, rate);
  const pairs = [];
  for (let i = 0; i < total; i += 1) {
    const out = fadeOutMultiplier(i, total);
    const into = fadeInMultiplier(i, total);
    pairs.push([out, into]);
  }
  return pairs;
}

const applyCrossfade = (trackA, trackB, curve) =>
  curve.map(([out, into], i) => (trackA[i] ?? 0) * out + (trackB[i] ?? 0) * into);

const formatMultiplier = (value) => value.toFixed(4).padStart(7, ' ');

const describePair = ([out, into], index) => {
  const left = formatMultiplier(out);
  const right = formatMultiplier(into);
  return `#${String(index).padStart(5, ' ')}  out=${left}  in=${right}`;
};

const sampleEvenly = (pairs, count) => {
  const picked = [];
  const step = (pairs.length - 1) / Math.max(1, count - 1);
  for (let k = 0; k < count && pairs.length > 0; k += 1) {
    const index = Math.min(pairs.length - 1, Math.round(k * step));
    picked.push([index, pairs[index]]);
  }
  return picked;
};

const reportCurve = (pairs, label) => {
  const lines = [`${label}: ${pairs.length} samples`];
  for (const [index, pair] of sampleEvenly(pairs, 5)) {
    lines.push(describePair(pair, index));
  }
  const energyDrift = pairs.reduce((worst, [out, into]) => {
    return Math.max(worst, Math.abs(out + into - 1));
  }, 0);
  lines.push(`max |out+in-1| = ${formatMultiplier(energyDrift)}`);
  return lines.join('\n');
};

const curve = crossfade(1, 44100);
console.log(reportCurve(curve, 'one second crossfade @ 44.1 kHz'));

const shortCurve = crossfade(0.25, 8000);
console.log(reportCurve(shortCurve, 'quarter second crossfade @ 8 kHz'));

const toneA = Array.from({ length: shortCurve.length }, () => 1);
const toneB = Array.from({ length: shortCurve.length }, () => -1);
const blended = applyCrossfade(toneA, toneB, shortCurve);
const firstBlended = formatMultiplier(blended[0]);
const lastBlended = formatMultiplier(blended[blended.length - 1]);
console.log(`blend endpoints: ${firstBlended} -> ${lastBlended}`);

module.exports = { crossfade, fadeInMultiplier, fadeOutMultiplier, applyCrossfade };

