const RED_DURATION = 30;
const GREEN_DURATION = 45;
const CYCLE_LENGTH = RED_DURATION + GREEN_DURATION;

const normalizeArrival = (vehicle) => {
  if (typeof vehicle === 'number') return vehicle;
  if (vehicle && typeof vehicle.arrival === 'number') return vehicle.arrival;
  throw new TypeError(`cannot read an arrival time from ${JSON.stringify(vehicle)}`);
};

const validateVehicles = (vehicles) => {
  if (!Array.isArray(vehicles)) {
    throw new TypeError('traffic() expects an array of vehicles');
  }
  return vehicles.map((vehicle, index) => {
    const arrival = normalizeArrival(vehicle);
    if (!Number.isFinite(arrival) || arrival < 0) {
      throw new RangeError(`vehicle ${index} has an invalid arrival time: ${arrival}`);
    }
    return arrival;
  });
};

const cyclePosition = (time) => time % CYCLE_LENGTH;

const isRedPhase = (time) => cyclePosition(time) < RED_DURATION;

const waitForGreen = (time) => {
  const position = cyclePosition(time);
  return isRedPhase(time) ? RED_DURATION - position : 0;
};

const averageOf = (values) => {
  if (values.length === 0) return 0;
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

function traffic(vehicles) {
  const arrivals = validateVehicles(vehicles);
  const waits = arrivals.map(waitForGreen);
  return averageOf(waits);
}

const describeVehicle = (arrival) => {
  const wait = waitForGreen(arrival);
  const phase = isRedPhase(arrival) ? 'RED' : 'GREEN';
  const departure = arrival + wait;
  return `t=${arrival}s  phase=${phase}  wait=${wait}s  crosses at ${departure}s`;
};

const formatReport = (vehicles) => {
  const arrivals = validateVehicles(vehicles);
  const lines = arrivals.map(describeVehicle);
  const average = traffic(arrivals);
  lines.push(`average wait for ${arrivals.length} vehicles: ${average.toFixed(2)}s`);
  return lines.join('\n');
};

const runMain = () => {
  const fleet = [0, 12, 30, 44, 75, 76, 121, { arrival: 150 }];
  console.log(formatReport(fleet));
  const clustered = [0, 1, 2, 3];
  console.log(`clustered red arrivals average: ${traffic(clustered).toFixed(2)}s`);
  console.log(`single green arrival average: ${traffic([60]).toFixed(2)}s`);
};

runMain();

module.exports = { traffic, waitForGreen, isRedPhase, formatReport };

