const LEVELS = 256;

const clampLevel = (value) => Math.min(LEVELS - 1, Math.max(0, Math.round(value)));

const validateImage = (pixels, width, height) => {
  if (!Number.isInteger(width) || !Number.isInteger(height) || width <= 0 || height <= 0) {
    throw new RangeError('width and height must be positive integers');
  }
  if (pixels.length !== width * height) {
    throw new RangeError(`expected ${width * height} pixels, received ${pixels.length}`);
  }
};

const buildHistogram = (pixels) => {
  const histogram = new Array(LEVELS).fill(0);
  for (const pixel of pixels) {
    histogram[clampLevel(pixel)] += 1;
  }
  return histogram;
};

const cumulativeDistribution = (histogram) => {
  const cdf = new Array(histogram.length);
  let running = 0;
  for (let level = 0; level < histogram.length; level += 1) {
    running += histogram[level];
    cdf[level] = running;
  }
  return cdf;
};

const findFirstNonZero = (cdf) => cdf.find((count) => count > 0) ?? 0;

const buildLookupTable = (cdf, totalPixels) => {
  const cdfMin = findFirstNonZero(cdf);
  const span = totalPixels - cdfMin;
  return cdf.map((count) => (span <= 0 ? 0 : clampLevel(((count - cdfMin) / span) * (LEVELS - 1))));
};

const applyLookupTable = (pixels, lookup) => pixels.map((pixel) => lookup[clampLevel(pixel)]);

function equalize(pixels, width, height) {
  validateImage(pixels, width, height);
  const histogram = buildHistogram(pixels);
  const cdf = cumulativeDistribution(histogram);
  const lookup = buildLookupTable(cdf, width * height);
  return applyLookupTable(pixels, lookup);
}

const buildMidtoneImage = (width, height) => {
  const pixels = [];
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      pixels.push(clampLevel(110 + ((x + y) % 5) * 5));
    }
  }
  return pixels;
};

const describeRange = (pixels) => ({ min: Math.min(...pixels), max: Math.max(...pixels) });

const formatRange = (label, pixels) => {
  const { min, max } = describeRange(pixels);
  return `${label}: min=${min} max=${max} spread=${max - min}`;
};

const formatRow = (pixels, width, row) =>
  pixels
    .slice(row * width, row * width + width)
    .map((pixel) => String(pixel).padStart(4))
    .join('');

const renderImage = (pixels, width, height) => {
  const lines = [];
  for (let row = 0; row < height; row += 1) {
    lines.push(formatRow(pixels, width, row));
  }
  return lines.join('\n');
};

const width = 8;
const height = 4;
const source = buildMidtoneImage(width, height);
const equalized = equalize(source, width, height);
console.log(formatRange('before', source));
console.log(renderImage(source, width, height));
console.log(formatRange('after', equalized));
console.log(renderImage(equalized, width, height));

module.exports = { equalize, buildHistogram, cumulativeDistribution, buildLookupTable };

