function validateFloor(floor, floors) {
  if (!Number.isInteger(floor) || floor < 1 || floor > floors) {
    throw new RangeError(`floor ${floor} is outside the range 1..${floors}`);
  }
  return floor;
}

const createCarBank = (floors) => [
  { id: 'A', position: 1, destination: null },
  { id: 'B', position: 4, destination: null },
  { id: 'C', position: 8, destination: 2 },
].map((car) => ({ ...car, position: validateFloor(car.position, floors), stops: [] }));

function normalizeRequest(request, floors) {
  const floor = validateFloor(request.floor, floors);
  const direction = request.direction || (floor === floors ? 'down' : 'up');
  return { floor, direction };
}

const movementDirection = (car) => {
  if (car.destination === null || car.destination === car.position) return 'idle';
  return car.destination > car.position ? 'up' : 'down';
};

const isMovingAway = (car, floor) => {
  const direction = movementDirection(car);
  return (direction === 'up' && floor < car.position) || (direction === 'down' && floor > car.position);
};

function travelDistance(car, floor) {
  const direction = movementDirection(car);
  if (direction === 'idle') return Math.abs(car.position - floor);
  if (isMovingAway(car, floor)) {
    return Math.abs(car.position - car.destination) + Math.abs(car.destination - floor);
  }
  return Math.abs(car.position - floor);
}

function computePenalty(car, request, floors) {
  let penalty = travelDistance(car, request.floor);
  if (isMovingAway(car, request.floor)) penalty += floors;
  const direction = movementDirection(car);
  if (direction !== 'idle' && direction !== request.direction) penalty += 2;
  return penalty + car.stops.length * 2;
}

function chooseBestCar(cars, request, floors) {
  let best = null;
  for (const car of cars) {
    const penalty = computePenalty(car, request, floors);
    if (best === null || penalty < best.penalty) best = { car, penalty };
  }
  return best;
}

const assignStop = (car, floor) => {
  car.stops.push(floor);
  if (car.destination === null || car.destination === car.position) car.destination = floor;
};

const formatAssignment = (a) => `floor ${a.floor} (${a.direction}) -> car ${a.car}, penalty ${a.penalty}`;

const summarizeBank = (cars) =>
  cars.map((car) => `${car.id}@${car.position} ${movementDirection(car)} stops=[${car.stops.join(',')}]`).join(' | ');

function dispatch(requests, floors, cars) {
  const bank = cars || createCarBank(floors);
  return requests.map((raw) => {
    const request = normalizeRequest(raw, floors);
    const { car, penalty } = chooseBestCar(bank, request, floors);
    assignStop(car, request.floor);
    return { floor: request.floor, direction: request.direction, car: car.id, penalty };
  });
}

const totalFloors = 10;
const activeBank = createCarBank(totalFloors);
const pending = [{ floor: 5 }, { floor: 9, direction: 'down' }, { floor: 2, direction: 'up' }];
for (const assignment of dispatch(pending, totalFloors, activeBank)) {
  console.log(formatAssignment(assignment));
}
console.log(summarizeBank(activeBank));

module.exports.dispatch = dispatch;
module.exports.createCarBank = createCarBank;
module.exports.computePenalty = computePenalty;
module.exports.travelDistance = travelDistance;

