const isLeapYear = (year) => (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;

const daysInMonth = (year, month) => {
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month === 2 && isLeapYear(year)) {
    return 29;
  }
  return lengths[month - 1];
};

const parseDateString = (text) => {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(text).trim());
  if (!match) {
    throw new Error(`invalid date: ${text}`);
  }
  const [year, month, day] = match.slice(1).map(Number);
  if (month < 1 || month > 12) {
    throw new Error(`impossible date: ${text}`);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new Error(`impossible date: ${text}`);
  }
  return { year, month, day };
};

const padNumber = (value) => String(value).padStart(2, '0');

const formatDate = ({ year, month, day }) => {
  const monthText = padNumber(month);
  const dayText = padNumber(day);
  return `${year}-${monthText}-${dayText}`;
};

const addDays = (date, amount) => {
  let { year, month, day } = date;
  day += amount;
  while (day > daysInMonth(year, month)) {
    day -= daysInMonth(year, month);
    month += 1;
    if (month > 12) {
      month = 1;
      year += 1;
    }
  }
  return { year, month, day };
};

const compareDates = (left, right) => {
  for (const key of ['year', 'month', 'day']) {
    if (left[key] !== right[key]) {
      return left[key] < right[key] ? -1 : 1;
    }
  }
  return 0;
};

const validateEvent = (event) => {
  if (!Number.isInteger(event.intervalDays) || event.intervalDays < 1) {
    throw new Error('intervalDays must be a positive integer');
  }
  if (!Number.isInteger(event.count) || event.count < 1) {
    throw new Error('count must be a positive integer');
  }
  return parseDateString(event.start);
};

function unroll(event, limit) {
  const maximum = parseDateString(limit);
  let current = validateEvent(event);
  const dates = [];
  while (dates.length < event.count && compareDates(current, maximum) <= 0) {
    dates.push(formatDate(current));
    current = addDays(current, event.intervalDays);
  }
  return dates;
}

const describeSchedule = (event, limit) => {
  const dates = unroll(event, limit);
  return `${event.start} every ${event.intervalDays}d -> ${dates.join(', ')}`;
};

console.log(describeSchedule({ start: '2024-02-26', intervalDays: 7, count: 6 }, '2024-12-31'));

