const OVERTIME_MULTIPLIER = 1.5;

const roundCurrency = (amount) => Math.round(amount * 100) / 100;

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function validateRecord(record, index) {
  if (!Array.isArray(record) || record.length !== 4) {
    throw new TypeError(`worker ${index}: expected an array of four numbers`);
  }
  record.forEach((value, position) => {
    if (!isFiniteNumber(value)) {
      throw new TypeError(`worker ${index}: field ${position} is not a finite number`);
    }
    if (value < 0) {
      throw new RangeError(`worker ${index}: field ${position} must not be negative`);
    }
  });
  if (record[3] > 100) {
    throw new RangeError(`worker ${index}: tax rate must not exceed 100`);
  }
}

const computeRegularPay = (hourlyRate, regularHours) => hourlyRate * regularHours;

const computeOvertimePay = (hourlyRate, overtimeHours) =>
  hourlyRate * OVERTIME_MULTIPLIER * overtimeHours;

function computeGrossPay(record) {
  const [hourlyRate, regularHours, overtimeHours] = record;
  const regular = computeRegularPay(hourlyRate, regularHours);
  const overtime = computeOvertimePay(hourlyRate, overtimeHours);
  return regular + overtime;
}

const applyTaxRate = (gross, taxRate) => gross * (1 - taxRate / 100);

function computeNetPay(record, index) {
  validateRecord(record, index);
  const gross = computeGrossPay(record);
  const taxed = applyTaxRate(gross, record[3]);
  return roundCurrency(taxed);
}

function process(workers) {
  if (!Array.isArray(workers)) {
    throw new TypeError('workers must be an array of records');
  }
  return workers.map(computeNetPay);
}

function formatCurrency(amount) {
  const rounded = roundCurrency(amount);
  return `$${rounded.toFixed(2)}`;
}

function formatPayLine(record, index, net) {
  const [hourlyRate, regularHours, overtimeHours, taxRate] = record;
  const gross = computeGrossPay(record);
  const rate = formatCurrency(hourlyRate);
  const hours = `${regularHours}h + ${overtimeHours}h OT @ ${rate}`;
  const amounts = `gross ${formatCurrency(gross)}, tax ${taxRate}%`;
  return `#${index + 1}: ${hours} -> ${amounts}, net ${formatCurrency(net)}`;
}

function buildPayrollReport(workers) {
  const nets = process(workers);
  const lines = workers.map((record, index) => formatPayLine(record, index, nets[index]));
  const total = nets.reduce((sum, net) => sum + net, 0);
  lines.push(`TOTAL NET: ${formatCurrency(total)}`);
  return lines.join('\n');
}

const payroll = [
  [20, 40, 5, 10],
  [15.5, 38, 0, 12],
  [32, 40, 10, 25],
];

console.log(JSON.stringify(process(payroll)));
console.log(buildPayrollReport(payroll));

exports.process = process;
exports.buildPayrollReport = buildPayrollReport;

