      throw new RangeError(`Order ${index}: ${labels[position]} must be a non-negative number`);
    }
  });
  return order;
}

const computeBasePrice = (size) => roundToCents(size * 1.5);

function computeToppingsCost(standardCount, premiumCount) {
  return standardCount * 1 + premiumCount * 2;
}

function computeDeliveryFee(distance) {
  if (distance < 5) {
    return 0;
  }
  return roundToCents(2 + 0.5 * distance);
}

function computeOrderTotal(order) {
  const [size, standardCount, premiumCount, distance] = order;
  const base = computeBasePrice(size);
  const toppings = computeToppingsCost(standardCount, premiumCount);
  const delivery = computeDeliveryFee(distance);
  return roundToCents(base + toppings + delivery);
}

function calculate(orders) {
  if (!Array.isArray(orders)) {
    throw new TypeError('orders must be an array');
  }
  return orders.map((order, index) => {
    const validated = validateOrder(order, index);
    return computeOrderTotal(validated);
  });
}

