const CLASS_PRIORITIES = { first: 1, business: 2, economy: 3 };

const normalizeTicketClass = (ticketClass) =>
  String(ticketClass).trim().toLowerCase();

const getClassPriority = (ticketClass) => {
  const key = normalizeTicketClass(ticketClass);
  if (!Object.prototype.hasOwnProperty.call(CLASS_PRIORITIES, key)) {
    throw new RangeError(`unknown ticket class: ${ticketClass}`);
  }
  return CLASS_PRIORITIES[key];
};

const getStatusPriority = (statusLevel) => {
  if (statusLevel >= 3) return 1;
  if (statusLevel >= 1) return 2;
  return 3;
};

const validatePassenger = (passenger, index) => {
  if (!Array.isArray(passenger) || passenger.length !== 3) {
    throw new TypeError(`passenger ${index} must be [status, class, assistance]`);
  }
  const [statusLevel, ticketClass, assistance] = passenger;
  if (!Number.isInteger(statusLevel) || statusLevel < 0) {
    throw new TypeError(`passenger ${index} has an invalid status level`);
  }
  if (typeof assistance !== "boolean") {
    throw new TypeError(`passenger ${index} has a non-boolean assistance flag`);
  }
  return { statusLevel, ticketClass, assistance };
};

const computeBoardingZone = (passenger, index) => {
  const { statusLevel, ticketClass, assistance } = validatePassenger(passenger, index);
  if (assistance) return 1;
  const byClass = getClassPriority(ticketClass);
  const byStatus = getStatusPriority(statusLevel);
  return Math.min(byClass, byStatus);
};

function group(passengers) {
  if (!Array.isArray(passengers)) {
    throw new TypeError("passengers must be an array");
  }
  return passengers.map((passenger, index) => computeBoardingZone(passenger, index));
}

const countZoneOccupancy = (zones) => {
  const tally = new Map([[1, 0], [2, 0], [3, 0]]);
  for (const zone of zones) {
    tally.set(zone, (tally.get(zone) || 0) + 1);
  }
  return tally;
};

const describePassenger = (passenger) => {
  const [statusLevel, ticketClass, assistance] = passenger;
  const label = normalizeTicketClass(ticketClass);
  return `status ${statusLevel}, ${label}${assistance ? ", assistance" : ""}`;
};

const formatBoardingReport = (passengers, zones) => {
  const lines = passengers.map(
    (passenger, i) => `zone ${zones[i]} <- ${describePassenger(passenger)}`
  );
  const tally = countZoneOccupancy(zones);
  const summary = [...tally.entries()]
    .map(([zone, count]) => `zone ${zone}: ${count}`)
    .join(", ");
  return `${lines.join("\n")}\n${summary}`;
};

const manifest = [
  [2, "economy", false],
  [4, "economy", false],
  [0, "first", false],
  [0, "economy", true],
  [1, "business", false],
];

const manifestZones = group(manifest);
const report = formatBoardingReport(manifest, manifestZones);
console.log(report);

