  }
  return parsed;
};

const normalizeVehicle = (vehicle) => {
  if (!Array.isArray(vehicle) || vehicle.length !== 3) {
    throw new TypeError('each vehicle must be [age, thousandsOfMiles, carbonOutput]');
  }
  const age = toFiniteNumber(vehicle[0], 'age');
  const mileage = toFiniteNumber(vehicle[1], 'mileage');
  const carbon = toFiniteNumber(vehicle[2], 'carbon output');
  return { age, mileage, carbon };
};

const computeAgePenalty = (age) => {
  const yearsOverLimit = Math.max(0, age - 5);
  return yearsOverLimit * 2;
};

const computeMileagePenalty = (thousandsOfMiles) => {
  const thousandsOverLimit = Math.max(0, thousandsOfMiles - 50);
  return Math.floor(thousandsOverLimit / 10);
};

