const MULTIPLE_CHOICE_POINTS = 3;
const TRUE_FALSE_POINTS = 1;
const ESSAY_POINT_CAP = 20;
const LATE_DEDUCTION = 10;

const isWholeNumber = (value) => Number.isInteger(value) && value >= 0;

const validateExamEntry = (exam, index) => {
  if (!Array.isArray(exam) || exam.length !== 4) {
    throw new TypeError(`exam ${index} must be an array of four elements`);
  }
  const [mc, tf, essay, late] = exam;
  if (![mc, tf, essay].every(isWholeNumber)) {
    throw new TypeError(`exam ${index} must hold non-negative integer counts`);
  }
  if (typeof late !== 'boolean') {
    throw new TypeError(`exam ${index} must end with a boolean late flag`);
  }
  return exam;
};

const computeMultipleChoiceScore = (correct) => correct * MULTIPLE_CHOICE_POINTS;

const computeTrueFalseScore = (correct) => correct * TRUE_FALSE_POINTS;

const computeEssayScore = (rawPoints) => Math.min(rawPoints, ESSAY_POINT_CAP);

const applyLateDeduction = (points, isLate) => (isLate ? points - LATE_DEDUCTION : points);

function scoreSingleExam(exam) {
  const [mcCorrect, tfCorrect, essayPoints, isLate] = exam;
  const total =
    computeMultipleChoiceScore(mcCorrect) +
    computeTrueFalseScore(tfCorrect) +
    computeEssayScore(essayPoints);
  return applyLateDeduction(total, isLate);
}

function score(exams) {
  if (!Array.isArray(exams)) {
    throw new TypeError('exams must be an array of exam arrays');
  }
  return exams.map((exam, index) => {
    const checked = validateExamEntry(exam, index);
    return scoreSingleExam(checked);
  });
}

const describeBreakdown = (exam) => {
  const [mcCorrect, tfCorrect, essayPoints, isLate] = exam;
  const parts = [
    `mc=${computeMultipleChoiceScore(mcCorrect)}`,
    `tf=${computeTrueFalseScore(tfCorrect)}`,
    `essay=${computeEssayScore(essayPoints)}`,
  ];
  if (isLate) {
    parts.push(`late=-${LATE_DEDUCTION}`);
  }
  return parts.join(' ');
};

const buildReportLines = (exams, totals) =>
  exams.map((exam, index) => `#${index + 1}: ${describeBreakdown(exam)} -> ${totals[index]}`);

function main() {
  const submissions = [
    [15, 10, 25, false],
    [20, 15, 18, true],
    [0, 0, 0, false],
  ];
  const totals = score(submissions);
  for (const line of buildReportLines(submissions, totals)) {
    console.log(line);
  }
  console.log(`totals: [${totals.join(', ')}]`);
}

main();

module.exports.score = score;
module.exports.scoreSingleExam = scoreSingleExam;
module.exports.buildReportLines = buildReportLines;

