const TIER_THREE_THRESHOLD = 1000;

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function validateCustomerRecord(record, index) {
  if (!Array.isArray(record) || record.length !== 3) {
    throw new TypeError(`Customer ${index} must be [balance, tier, purchase]`);
  }
  const [balance, tier, purchase] = record;
  if (!isFiniteNumber(balance) || !isFiniteNumber(tier)) {
    throw new TypeError(`Customer ${index} has a non-numeric balance or tier`);
  }
  if (!isFiniteNumber(purchase) || purchase < 0) {
    throw new TypeError(`Customer ${index} has an invalid purchase amount`);
  }
  return { balance, tier, purchase };
}

function getTierMultiplier(tier) {
  if (tier >= 3) {
    return 2;
  }
  if (tier === 2) {
    return 1.5;
  }
  return 1;
}

function calculateEarnedPoints(purchase, tier) {
  const basePoints = Math.floor(purchase);
  return Math.round(basePoints * getTierMultiplier(tier));
}

function determineNewTier(newBalance, oldTier) {
  return newBalance > TIER_THREE_THRESHOLD ? 3 : oldTier;
}

function updateCustomer(record, index) {
  const { balance, tier, purchase } = validateCustomerRecord(record, index);
  const newBalance = balance + calculateEarnedPoints(purchase, tier);
  return [newBalance, determineNewTier(newBalance, tier)];
}

function process(customers) {
  if (!Array.isArray(customers)) {
    throw new TypeError('customers must be an array of records');
  }
  return customers.map(updateCustomer);
}

function formatLoyaltyLine(original, updated, index) {
  const earned = updated[0] - original[0];
  const upgraded = updated[1] > original[1] ? ' (upgraded)' : '';
  return `#${index}: +${earned} pts -> ${updated[0]} @ tier ${updated[1]}${upgraded}`;
}

function buildLoyaltyReport(customers) {
  return process(customers)
    .map((row, i) => formatLoyaltyLine(customers[i], row, i))
    .join('\n');
}

function parseCustomerInput(text) {
  const data = JSON.parse(text);
  if (!Array.isArray(data)) {
    throw new TypeError('input JSON must be an array of customer records');
  }
  return data;
}

function runCli() {
  const text = require('fs').readFileSync(0, 'utf8');
  const customers = parseCustomerInput(text);
  console.log(JSON.stringify(process(customers)));
  console.log(buildLoyaltyReport(customers));
}

if (require.main === module) {
  runCli();
}

exports.process = process;
exports.buildLoyaltyReport = buildLoyaltyReport;
exports.determineNewTier = determineNewTier;
exports.getTierMultiplier = getTierMultiplier;

