const WEEKDAY_RATE = 100;
const WEEKEND_RATE = 150;
const CITY_TAX_RATE = 0.1;

const SEASON_MODIFIERS = {
  peak: 0.2,
  offpeak: -0.1,
};

const normalizeSeason = (season) => String(season).trim().toLowerCase();

const isKnownSeason = (season) => Object.prototype.hasOwnProperty.call(SEASON_MODIFIERS, season);

const validateStay = (stay, index) => {
  if (!Array.isArray(stay) || stay.length !== 3) {
    throw new TypeError(`stay ${index} must be [weekdayNights, weekendNights, season]`);
  }
  const [weekdayNights, weekendNights, season] = stay;
  if (!Number.isInteger(weekdayNights) || !Number.isInteger(weekendNights)) {
    throw new TypeError(`stay ${index} must use whole numbers of nights`);
  }
  if (weekdayNights < 0 || weekendNights < 0) {
    throw new RangeError(`stay ${index} cannot have negative nights`);
  }
  const normalized = normalizeSeason(season);
  if (!isKnownSeason(normalized)) {
    throw new RangeError(`stay ${index} has unknown season "${season}"`);
  }
  return { weekdayNights, weekendNights, season: normalized };
};

const computeWeekdayCost = (nights) => nights * WEEKDAY_RATE;

const computeWeekendCost = (nights) => nights * WEEKEND_RATE;

const applySeasonModifier = (nightCost, season) => {
  const modifier = SEASON_MODIFIERS[season];
  return nightCost * (1 + modifier);
};

const applyCityTax = (amount) => amount * (1 + CITY_TAX_RATE);

const roundCurrency = (amount) => Math.round(amount * 100) / 100;

const billStay = (stay, index) => {
  const { weekdayNights, weekendNights, season } = validateStay(stay, index);
  let nightCost = computeWeekdayCost(weekdayNights);
  nightCost += computeWeekendCost(weekendNights);
  const modified = applySeasonModifier(nightCost, season);
  const taxed = applyCityTax(modified);
  return roundCurrency(taxed);
};

function invoice(stays) {
  if (!Array.isArray(stays)) {
    throw new TypeError('stays must be an array of stays');
  }
  return stays.map(billStay);
}

const describeStay = (stay) => {
  const [weekdayNights, weekendNights, season] = stay;
  const label = normalizeSeason(season);
  return `${weekdayNights} weekday + ${weekendNights} weekend nights (${label})`;
};

const formatInvoiceLine = (stay, amount) => {
  const description = describeStay(stay);
  return `${description} => ${amount.toFixed(2)}`;
};

const printInvoiceReport = (stays) => {
  const amounts = invoice(stays);
  stays.forEach((stay, index) => {
    console.log(formatInvoiceLine(stay, amounts[index]));
  });
  const total = amounts.reduce((sum, amount) => sum + amount, 0);
  console.log(`total: ${roundCurrency(total).toFixed(2)}`);
};

printInvoiceReport([
  [3, 2, 'peak'],
  [5, 0, 'offpeak'],
  [1, 1, 'PEAK'],
]);

module.exports = { invoice, printInvoiceReport };

