const WEIGHT_RATE = 2;
const DISTANCE_RATE = 0.5;
const HAZARD_FEE = 100;
const BULK_THRESHOLD = 100;
const BULK_DISCOUNT = 50;

const IsFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

const ValidateShipment = (shipment, index) => {
  if (!Array.isArray(shipment) || shipment.length !== 3) {
    throw new TypeError(`shipment ${index} must be [weight, distance, hazardous]`);
  }
  const [weight, distance, hazardous] = shipment;
  if (!IsFiniteNumber(weight) || weight < 0) {
    throw new RangeError(`shipment ${index} has an invalid weight: ${weight}`);
  }
  if (!IsFiniteNumber(distance) || distance < 0) {
    throw new RangeError(`shipment ${index} has an invalid distance: ${distance}`);
  }
  if (typeof hazardous !== 'boolean') {
    throw new TypeError(`shipment ${index} must flag hazardous materials with a boolean`);
  }
  return { weight, distance, hazardous };
};

const ComputeWeightFee = (weight) => weight * WEIGHT_RATE;

const ComputeDistanceFee = (distance) => distance * DISTANCE_RATE;

const ComputeHazardSurcharge = (hazardous) => (hazardous ? HAZARD_FEE : 0);

const ComputeBulkDiscount = (weight) => (weight > BULK_THRESHOLD ? BULK_DISCOUNT : 0);

const RoundToCents = (amount) => Math.round(amount * 100) / 100;

const PriceShipment = (shipment, index) => {
  const { weight, distance, hazardous } = ValidateShipment(shipment, index);
  const weightFee = ComputeWeightFee(weight);
  const distanceFee = ComputeDistanceFee(distance);
  const hazardFee = ComputeHazardSurcharge(hazardous);
  const discount = ComputeBulkDiscount(weight);
  return RoundToCents(weightFee + distanceFee + hazardFee - discount);
};

function Estimate(shipments) {
  if (!Array.isArray(shipments)) {
    throw new TypeError('estimate expects an array of shipments');
  }
  return shipments.map(PriceShipment);
}

const FormatCurrency = (amount) => {
  const cents = RoundToCents(amount);
  return `$${cents.toFixed(2)}`;
};

const DescribeShipment = (shipment, index) => {
  const { weight, distance, hazardous } = ValidateShipment(shipment, index);
  const weightFee = ComputeWeightFee(weight);
  const distanceFee = ComputeDistanceFee(distance);
  const parts = [
    `${weight} lb @ ${FormatCurrency(weightFee)}`,
    `${distance} mi @ ${FormatCurrency(distanceFee)}`,
  ];
  const hazardFee = ComputeHazardSurcharge(hazardous);
  if (hazardFee > 0) {
    parts.push(`hazmat ${FormatCurrency(hazardFee)}`);
  }
  const discount = ComputeBulkDiscount(weight);
  if (discount > 0) {
    parts.push(`bulk -${FormatCurrency(discount)}`);
  }
  return parts.join(' + ');
};

const BuildReport = (shipments) => {
  const totals = Estimate(shipments);
  return shipments.map((shipment, index) => {
    const breakdown = DescribeShipment(shipment, index);
    return `#${index + 1}: ${breakdown} => ${FormatCurrency(totals[index])}`;
  });
};

