const costs = Estimate(manifest);
console.log(costs);
BuildReport(manifest).forEach((line) => console.log(line));
const manifestTotal = costs.reduce((sum, cost) => sum + cost, 0);
console.log(`Manifest total: ${FormatCurrency(manifestTotal)}`);

module.exports = { Estimate, BuildReport, FormatCurrency };

