const BASE_YIELD_PER_ACRE = 100;
const SOIL_DIVISOR = 5;
const RAINFALL_DIVISOR = 20;
const MAX_RAINFALL_MULTIPLIER = 1.5;
const PEST_LOSS = 0.1;

const isPositiveNumber = (value) => typeof value === 'number' && Number.isFinite(value) && value > 0;

function validateField(field, index) {
  if (!Array.isArray(field) || field.length !== 4) {
    throw new TypeError(`field ${index} must be an array of four values`);
  }
  const [area, soil, rainfall, pests] = field;
  if (!isPositiveNumber(area)) {
    throw new RangeError(`field ${index}: area must be a positive number`);
  }
  if (!isPositiveNumber(soil) || soil > 10) {
    throw new RangeError(`field ${index}: soil quality must be between 1 and 10`);
  }
  if (typeof rainfall !== 'number' || !Number.isFinite(rainfall) || rainfall < 0) {
    throw new RangeError(`field ${index}: rainfall must be a non-negative number`);
  }
  if (typeof pests !== 'boolean') {
    throw new TypeError(`field ${index}: pest problem must be a boolean`);
  }
}

const computeBaseYield = (area) => area * BASE_YIELD_PER_ACRE;

const computeSoilMultiplier = (soilQuality) => soilQuality / SOIL_DIVISOR;

function computeRainfallMultiplier(rainfall) {
  return Math.min(rainfall / RAINFALL_DIVISOR, MAX_RAINFALL_MULTIPLIER);
}

const applyPestPenalty = (yieldSoFar, hasPests) => (hasPests ? yieldSoFar * (1 - PEST_LOSS) : yieldSoFar);

function computeFieldYield(field) {
  const [area, soilQuality, rainfall, hasPests] = field;
  const grossYield = computeBaseYield(area)
    * computeSoilMultiplier(soilQuality)
    * computeRainfallMultiplier(rainfall);
  return applyPestPenalty(grossYield, hasPests);
}

function predict(fields) {
  if (!Array.isArray(fields)) {
    throw new TypeError('fields must be an array of field descriptions');
  }
  fields.forEach(validateField);
  return fields.map(computeFieldYield);
}

const formatBushels = (amount) => `${amount.toFixed(1)} bushels`;

function describeField(field, predicted) {
  const [area, soilQuality, rainfall, hasPests] = field;
  const pestNote = hasPests ? 'pest problem' : 'pest free';
  const rainNote = computeRainfallMultiplier(rainfall).toFixed(2);
  return `${area} acres, soil ${soilQuality}, rain x${rainNote}, ${pestNote} -> ${formatBushels(predicted)}`;
}

function buildReport(fields) {
  const predictions = predict(fields);
  const lines = fields.map((field, index) => describeField(field, predictions[index]));
  const total = predictions.reduce((sum, value) => sum + value, 0);
  lines.push(`total: ${formatBushels(total)}`);
  return lines.join('\n');
}

const farm = [
  [10, 8, 24, false],
  [25, 5, 12, true],
  [40, 10, 60, false],
];

console.log(predict(farm));
console.log(buildReport(farm));

module.exports = { predict, buildReport, computeFieldYield };

