const RATING_PERCENTS = { good: 20, average: 15, poor: 10 };
const LARGE_PARTY_MINIMUM = 6;
const LARGE_PARTY_BONUS = 5;
const HOLIDAY_SURCHARGE = 5;

const normalizeRating = (rating) => String(rating).trim().toLowerCase();

function getBaseTipPercent(rating) {
  const key = normalizeRating(rating);
  if (!Object.prototype.hasOwnProperty.call(RATING_PERCENTS, key)) {
    throw new Error(`unknown service rating: ${rating}`);
  }
  return RATING_PERCENTS[key];
}

const isLargeParty = (partySize) => partySize >= LARGE_PARTY_MINIMUM;

function getAdjustedPercent(rating, partySize) {
  const base = getBaseTipPercent(rating);
  const bonus = isLargeParty(partySize) ? LARGE_PARTY_BONUS : 0;
  return base + bonus;
}

const computeSubtotalTip = (foodTotal, percent) => (foodTotal * percent) / 100;

const getHolidaySurcharge = (isHoliday) => (isHoliday ? HOLIDAY_SURCHARGE : 0);

const roundToDollar = (amount) => Math.round(amount);

function validateBill(bill, index) {
  if (!Array.isArray(bill) || bill.length !== 4) {
    throw new Error(`bill ${index} must be an array of four values`);
  }
  const [foodTotal, partySize, , isHoliday] = bill;
  if (!Number.isFinite(foodTotal) || foodTotal < 0) {
    throw new Error(`bill ${index} has an invalid food total: ${foodTotal}`);
  }
  if (!Number.isInteger(partySize) || partySize < 1) {
    throw new Error(`bill ${index} has an invalid party size: ${partySize}`);
  }
  if (typeof isHoliday !== 'boolean') {
    throw new Error(`bill ${index} needs a boolean holiday flag`);
  }
  return bill;
}

function computeTipForBill(bill, index) {
  const [foodTotal, partySize, rating, isHoliday] = validateBill(bill, index);
  const percent = getAdjustedPercent(rating, partySize);
  const subtotal = computeSubtotalTip(foodTotal, percent);
  const surcharge = getHolidaySurcharge(isHoliday);
  return roundToDollar(subtotal + surcharge);
}

function suggest(bills) {
  if (!Array.isArray(bills)) {
    throw new Error('suggest expects an array of bills');
  }
  return bills.map(computeTipForBill);
}

function formatTipLine(bill, tip) {
  const [foodTotal, partySize, rating, isHoliday] = bill;
  const percent = getAdjustedPercent(rating, partySize);
  const party = isLargeParty(partySize) ? 'large party' : 'small party';
  const holiday = isHoliday ? ', holiday' : '';
  return `$${foodTotal} / ${partySize} (${normalizeRating(rating)}, ${party}${holiday}) -> ${percent}% = $${tip}`;
}

function printReport(bills) {
  const tips = suggest(bills);
  bills.forEach((bill, i) => console.log(formatTipLine(bill, tips[i])));
  const total = tips.reduce((sum, tip) => sum + tip, 0);
  console.log(`total suggested tips: $${roundToDollar(total)}`);
}

printReport([
  [100, 8, 'good', false],
  [80, 2, 'average', true],
  [45.5, 6, 'poor', true],
  [200, 4, 'Good', false],
]);

module.exports = { suggest, getBaseTipPercent, getAdjustedPercent, formatTipLine };

