const OUT_OF_STOCK = "Out of stock";
const NOT_ENOUGH_MONEY = "Insufficient payment";

const isValidAmount = (value) => Number.isInteger(value) && value >= 0;

const parsePurchase = (entry, index) => {
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError(`purchase ${index} must be [price, inserted, stock]`);
  }
  const [price, inserted, stock] = entry;
  if (!isValidAmount(price)) {
    throw new RangeError(`purchase ${index}: price must be a non-negative integer of cents`);
  }
  if (!isValidAmount(inserted)) {
    throw new RangeError(`purchase ${index}: inserted amount must be a non-negative integer of cents`);
  }
  if (!isValidAmount(stock)) {
    throw new RangeError(`purchase ${index}: stock must be a non-negative integer`);
  }
  return { price, inserted, stock };
};

const isOutOfStock = (purchase) => purchase.stock === 0;

const hasSufficientPayment = (purchase) => purchase.inserted >= purchase.price;

const computeChange = (purchase) => purchase.inserted - purchase.price;

const countQuarters = (change) => Math.floor(change / 25);

const processPurchase = (purchase) => {
  if (isOutOfStock(purchase)) {
    return OUT_OF_STOCK;
  }
  if (!hasSufficientPayment(purchase)) {
    return NOT_ENOUGH_MONEY;
  }
  const change = computeChange(purchase);
  return countQuarters(change);
};

function transact(purchases) {
  if (!Array.isArray(purchases)) {
    throw new TypeError("purchases must be an array of [price, inserted, stock] triples");
  }
  return purchases.map((entry, index) => {
    const purchase = parsePurchase(entry, index);
    return processPurchase(purchase);
  });
}

const centsToDollars = (cents) => `$${(cents / 100).toFixed(2)}`;

const describePurchase = (entry) => {
  const price = centsToDollars(entry[0]);
  const inserted = centsToDollars(entry[1]);
  return `item ${price}, inserted ${inserted}, stock ${entry[2]}`;
};

const formatOutcome = (result) =>
  typeof result === "number" ? `${result} quarter(s) returned` : result;

const buildReport = (purchases) => {
  const results = transact(purchases);
  return purchases.map((entry, index) => {
    const description = describePurchase(entry);
    return `${description} -> ${formatOutcome(results[index])}`;
  });
};

