  [150, 200, 5],
  [125, 100, 3],
  [75, 500, 0],
  [100, 100, 1],
];

console.log(transact([[150, 200, 5]]));
console.log(transact(batch));
buildReport(batch).forEach((line) => console.log(line));

module.exports = { transact, buildReport };

