const BASE_PREMIUM = 100;

const isValidDriver = (driver) =>
  Array.isArray(driver) && driver.length === 3 && driver.every((n) => Number.isFinite(n) && n >= 0);

const validateDrivers = (drivers) => {
  if (!Array.isArray(drivers)) {
    throw new TypeError('quote expects an array of drivers');
  }
  drivers.forEach((driver, index) => {
    if (!isValidDriver(driver)) {
      throw new TypeError(`driver at index ${index} must be [age, accidents, dailyMiles]`);
    }
  });
  return drivers;
};

const calculateAgeRisk = (age) => {
  if (age < 25) {
    return BASE_PREMIUM + 50;
  }
  if (age > 50) {
    return BASE_PREMIUM - 20;
  }
  return BASE_PREMIUM;
};

const calculateAccidentPenalty = (accidents) => accidents * 40;

const calculateMileageSurcharge = (dailyMiles) => {
  const excessMiles = dailyMiles - 30;
  if (excessMiles <= 0) {
    return 0;
  }
  return Math.floor(excessMiles / 10) * 10;
};

const applySafeDriverDiscount = (subtotal, accidents) => (accidents === 0 ? subtotal - 15 : subtotal);

const premiumForDriver = ([age, accidents, dailyMiles]) => {
  const ageRisk = calculateAgeRisk(age);
  const penalty = calculateAccidentPenalty(accidents);
  const surcharge = calculateMileageSurcharge(dailyMiles);
  return applySafeDriverDiscount(ageRisk + penalty + surcharge, accidents);
};

function quote(drivers) {
  const checked = validateDrivers(drivers);
  return checked.map(premiumForDriver);
}

const describeDriver = ([age, accidents, dailyMiles]) =>
  `age ${age}, ${accidents} accident(s), ${dailyMiles} mi/day`;

const formatQuoteReport = (drivers) => {
  const premiums = quote(drivers);
  const lines = drivers.map((driver, index) => `${describeDriver(driver)} -> $${premiums[index]}/month`);
  const total = premiums.reduce((sum, premium) => sum + premium, 0);
  lines.push(`household total: $${total}/month`);
  return lines.join('\n');
};

const main = () => {
  const household = [
    [22, 1, 40],
    [35, 0, 20],
    [58, 2, 75],
  ];
  console.log(formatQuoteReport(household));
};

main();

module.exports.quote = quote;
module.exports.formatQuoteReport = formatQuoteReport;

