const isInsideBoard = (row, col) =>
  row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE;

const pieceColorOf = (piece) => {
  if (piece === '.') return null;
  return piece === piece.toUpperCase() ? 'white' : 'black';
};

const isEmptySquare = (board, row, col) => board[row][col] === '.';

const isEnemyPiece = (board, row, col, color) => {
  if (!isInsideBoard(row, col)) return false;
  const owner = pieceColorOf(board[row][col]);
  return owner !== null && owner !== color;
};

const pawnAttackOffsets = (color) => {
  const dir = color === 'white' ? -1 : 1;
  return [[dir, -1], [dir, 1]];
};

const knightAttackOffsets = () => [
  [-2, -1], [-2, 1], [-1, -2], [-1, 2],
  [1, -2], [1, 2], [2, -1], [2, 1],
];

const slidingDirections = (kind) => {
  const straight = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  const diagonal = [[-1, -1], [-1, 1], [1, -1], [1, 1]];
  if (kind === 'r') return straight;
  if (kind === 'b') return diagonal;
  return straight.concat(diagonal);
};

const collectStepTargets = (board, row, col, color, offsets) => {
  const found = [];
  for (const [dr, dc] of offsets) {
    const r = row + dr;
    const c = col + dc;
    if (isEnemyPiece(board, r, c, color)) found.push([r, c]);
  }
  return found;
};

const collectSlideTargets = (board, row, col, color, directions) => {
  const found = [];
  for (const [dr, dc] of directions) {
    let r = row + dr;
    let c = col + dc;
    while (isInsideBoard(r, c)) {
      if (!isEmptySquare(board, r, c)) break;
      r += dr;
      c += dc;
    }
    if (isEnemyPiece(board, r, c, color)) found.push([r, c]);
  }
  return found;
};

const targetsForPiece = (board, row, col, color, kind) => {
  let vectors;
  if (kind === 'p') vectors = pawnAttackOffsets(color);
  else if (kind === 'n') vectors = knightAttackOffsets();
  else if (kind === 'k') vectors = slidingDirections('q');
  else if ('rbq'.includes(kind)) {
    const rays = slidingDirections(kind);
    return collectSlideTargets(board, row, col, color, rays);
  } else return [];
