const SCORE_NAMES = ['love', 'fifteen', 'thirty', 'forty'];

const normalizePlayerName = (token) => {
  const cleaned = String(token).trim().toLowerCase();
  if (cleaned === 'player one' || cleaned === 'one' || cleaned === '1') return 1;
  if (cleaned === 'player two' || cleaned === 'two' || cleaned === '2') return 2;
  throw new Error(`unknown rally winner: ${token}`);
};

const describePointCount = (count) => SCORE_NAMES[count];

const formatRegularScore = (first, second) => {
  const leaderWord = describePointCount(first);
  const trailerWord = describePointCount(second);
  if (first === second) return `${leaderWord} all`;
  return `${leaderWord} ${trailerWord}`;
};

const isDeuceState = (first, second) => first >= 3 && second >= 3 && first === second;

const hasAdvantage = (first, second) =>
  first >= 3 && second >= 3 && Math.abs(first - second) === 1;

const leadingPlayerName = (first, second) => (first > second ? 'player one' : 'player two');

const isGameFinished = (first, second) =>
  (first >= 4 || second >= 4) && Math.abs(first - second) >= 2;

const announceGameWinner = (first, second) => {
  const winner = leadingPlayerName(first, second);
  return `${winner} wins`;
};

const describeScore = (first, second) => {
  if (isGameFinished(first, second)) {
    return announceGameWinner(first, second);
  }
  if (isDeuceState(first, second)) {
    return 'deuce';
  }
  if (hasAdvantage(first, second)) {
    const leader = leadingPlayerName(first, second);
    return `advantage ${leader}`;
  }
  return formatRegularScore(first, second);
};

function referee(points) {
  const progression = [];
  let first = 0;
  let second = 0;
  for (const point of points) {
    if (isGameFinished(first, second)) break;
    if (normalizePlayerName(point) === 1) first += 1;
    else second += 1;
    progression.push(describeScore(first, second));
  }
  return progression;
}

const runGameReport = (label, points) => {
  const progression = referee(points);
  console.log(`${label}: ${progression.join(', ')}`);
};

const repeatWinner = (name, times) => new Array(times).fill(name);

const sweepRallies = repeatWinner('player one', 4);
runGameReport('sweep', sweepRallies);
runGameReport('deuce battle', [
  'player one', 'player two', 'player one', 'player two',
  'player one', 'player two', 'player two', 'player two',
]);
runGameReport('mixed', ['player two', 'player one', 'player two', 'player two', 'player two']);

module.exports = {
  referee,
  describeScore,
  isDeuceState,
  hasAdvantage,
};

