const roundTo = (value, digits) => Number(value.toFixed(digits));

const isPositiveNumber = (value) =>
  typeof value === 'number' && Number.isFinite(value) && value > 0;

function parseRecord(record) {
  const [coin, quantity, price] = Array.isArray(record)
    ? record
    : [record.coin, record.quantity, record.price];
  if (typeof coin !== 'string' || coin.length === 0) {
    throw new TypeError('each ledger record needs a coin name');
  }
  if (!isPositiveNumber(quantity)) {
    throw new RangeError(`bad quantity for ${coin}`);
  }
  if (!isPositiveNumber(price)) {
    throw new RangeError(`bad purchase price for ${coin}`);
  }
  return { coin, quantity, price };
}

function aggregateHoldings(ledger) {
  const holdings = new Map();
  for (const record of ledger) {
    const { coin, quantity, price } = parseRecord(record);
    const entry = holdings.get(coin) || { quantity: 0, cost: 0 };
    entry.quantity += quantity;
    entry.cost += quantity * price;
    holdings.set(coin, entry);
  }
  return holdings;
}

const averagePrice = (entry) => entry.cost / entry.quantity;

function marketPriceFor(prices, coin) {
  const price = prices[coin];
  if (!isPositiveNumber(price)) {
    throw new RangeError(`no market price available for ${coin}`);
  }
  return price;
}

const currentValue = (entry, marketPrice) => entry.quantity * marketPrice;

const profitPercent = (avgPrice, marketPrice) =>
  ((marketPrice - avgPrice) / avgPrice) * 100;

function portfolio(ledger, prices) {
  const holdings = aggregateHoldings(ledger);
  const rows = [];
  for (const [coin, entry] of holdings) {
    const marketPrice = marketPriceFor(prices, coin);
    const avgPrice = averagePrice(entry);
    const gain = profitPercent(avgPrice, marketPrice);
    const quantity = roundTo(entry.quantity, 8);
    rows.push([coin, quantity, roundTo(gain, 2)]);
  }
  return rows;
}

function totalMarketValue(ledger, prices) {
  let total = 0;
  for (const [coin, entry] of aggregateHoldings(ledger)) {
    const marketPrice = marketPriceFor(prices, coin);
    total += currentValue(entry, marketPrice);
  }
  return roundTo(total, 2);
}

const formatHoldingLine = ([coin, quantity, gain]) =>
  `${coin.padEnd(6)} qty=${quantity} ${gain >= 0 ? '+' : ''}${gain}%`;

const ledger = [
  ['BTC', 2, 10],
  ['BTC', 1, 20],
  ['ETH', 5, 100],
  { coin: 'ETH', quantity: 5, price: 140 },
];
const prices = { BTC: 15, ETH: 110 };

for (const row of portfolio(ledger, prices)) {
  console.log(formatHoldingLine(row));
}
console.log(`total value: ${totalMarketValue(ledger, prices)}`);

