const normalizeWord = (word) => String(word).trim().toLowerCase();

const hasDistinctLetters = (word) => new Set(word).size === word.length;

function validateSecret(secret) {
  if (secret.length === 0) {
    throw new Error('the secret word must not be empty');
  }
  if (!hasDistinctLetters(secret)) {
    throw new Error(`the secret word "${secret}" must have distinct letters`);
  }
  return secret;
}

function validateGuess(secret, guess) {
  if (guess.length !== secret.length) {
    throw new Error(`guess "${guess}" must be ${secret.length} letters long`);
  }
  return guess;
}

function countExactMatches(secret, guess) {
  let exact = 0;
  for (let i = 0; i < secret.length; i += 1) {
    if (secret[i] === guess[i]) {
      exact += 1;
    }
  }
  return exact;
}

function collectUnmatchedLetters(secret, guess) {
  const pool = [];
  for (let i = 0; i < secret.length; i += 1) {
    if (secret[i] !== guess[i]) {
      pool.push(secret[i]);
    }
  }
  return pool;
}

function countPartialMatches(secret, guess) {
  const pool = collectUnmatchedLetters(secret, guess);
  let partial = 0;
  for (let i = 0; i < guess.length; i += 1) {
    if (secret[i] === guess[i]) {
      continue;
    }
    const found = pool.indexOf(guess[i]);
    if (found !== -1) {
      pool.splice(found, 1);
      partial += 1;
    }
  }
  return partial;
}

function scoreGuess(secret, guess) {
  const exact = countExactMatches(secret, guess);
  const partial = countPartialMatches(secret, guess);
  return [exact, partial];
}

function evaluate(secret, guesses) {
  const target = validateSecret(normalizeWord(secret));
  return guesses.map((raw) => {
    const guess = validateGuess(target, normalizeWord(raw));
    return scoreGuess(target, guess);
  });
}

const formatScoreLine = (guess, [exact, partial]) =>
  `${normalizeWord(guess)} -> ${exact} exact, ${partial} partial`;

function buildReport(secret, guesses) {
  const scores = evaluate(secret, guesses);
  return guesses.map((guess, i) => formatScoreLine(guess, scores[i])).join('\n');
}

const secretWord = 'fast';
const attempts = ['cast', 'Fast', 'tsaf', 'toll', 'safe'];
console.log(buildReport(secretWord, attempts));

module.exports = { evaluate, scoreGuess, buildReport };

