const NUMBER_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
  'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
  'seventeen', 'eighteen', 'nineteen', 'twenty'];

const MULTIPLIER_WORDS = { single: 1, double: 2, triple: 3, treble: 3 };

const STARTING_SCORE = 501;
const THROWS_PER_TURN = 3;

const wordToNumber = (word) => {
  if (word === 'bull') return 25;
  const index = NUMBER_WORDS.indexOf(word);
  if (index < 1) throw new Error(`unknown point value: "${word}"`);
  return index;
};

const parseThrowNotation = (text) => {
  const words = String(text).trim().toLowerCase().split(/[\s-]+/);
  if (words.length !== 2) throw new Error(`cannot parse throw: "${text}"`);
  const factor = MULTIPLIER_WORDS[words[0]];
  if (factor === undefined) throw new Error(`unknown multiplier: "${words[0]}"`);
  return { factor, base: wordToNumber(words[1]) };
};

const computeThrowValue = (parsed) => parsed.factor * parsed.base;

const isDoubleThrow = (parsed) => parsed.factor === 2;

const isBustState = (score) => score < 0 || score === 1;

const ensureThrowList = (throws) => {
  if (typeof throws === 'string') return throws.split(',').map((piece) => piece.trim());
  if (Array.isArray(throws)) return throws;
  throw new Error('throws must be an array or a comma separated string');
};

const chunkIntoTurns = (list, size) => {
  const turns = [];
  for (let i = 0; i < list.length; i += size) turns.push(list.slice(i, i + size));
  return turns;
};

function darts(throws) {
  const list = ensureThrowList(throws);
  let score = STARTING_SCORE;
  for (const turn of chunkIntoTurns(list, THROWS_PER_TURN)) {
    const turnStart = score;
    for (const notation of turn) {
      const parsed = parseThrowNotation(notation);
      const next = score - computeThrowValue(parsed);
      if (next === 0 && isDoubleThrow(parsed)) return 0;
      if (next === 0 || isBustState(next)) {
        score = turnStart;
        break;
      }
      score = next;
    }
  }
  return score;
}

const formatGameReport = (label, throws) => {
  const remaining = darts(throws);
  const status = remaining === 0 ? 'game shot' : `${remaining} to go`;
  return `${label.padEnd(18)} -> ${status}`;
};

