const TIME_RANGE_PATTERN = /^(\d{2}:\d{2}:\d{2},\d{3})\s*-->\s*(\d{2}:\d{2}:\d{2},\d{3})(.*)$/;

const isTimeRangeLine = (line) => TIME_RANGE_PATTERN.test(line.trim());

const parseTimestamp = (stamp) => {
  const [clock, millis] = stamp.split(',');
  const [hours, minutes, seconds] = clock.split(':').map(Number);
  return ((hours * 60 + minutes) * 60 + seconds) * 1000 + Number(millis);
};

const padNumber = (value, width) => String(value).padStart(width, '0');

const formatTimestamp = (total) => {
  const millis = total % 1000;
  const allSeconds = Math.floor(total / 1000);
  const seconds = allSeconds % 60;
  const allMinutes = Math.floor(allSeconds / 60);
  const minutes = allMinutes % 60;
  const hours = Math.floor(allMinutes / 60);
  const clock = [hours, minutes, seconds].map((unit) => padNumber(unit, 2)).join(':');
  return `${clock},${padNumber(millis, 3)}`;
};

const shiftTimestamp = (stamp, delay) => {
  const shifted = parseTimestamp(stamp) + delay;
  return formatTimestamp(Math.max(0, shifted));
};

const shiftTimeRange = (line, delay) => {
  const match = line.trim().match(TIME_RANGE_PATTERN);
  const start = shiftTimestamp(match[1], delay);
  const end = shiftTimestamp(match[2], delay);
  return `${start} --> ${end}${match[3]}`;
};

const splitIntoLines = (text) => text.split(/\r?\n/);

const detectLineEnding = (text) => (text.includes('\r\n') ? '\r\n' : '\n');

function shift(subtitles, delay) {
  const ending = detectLineEnding(subtitles);
  const lines = splitIntoLines(subtitles);
  const adjusted = lines.map((line) => {
    if (isTimeRangeLine(line)) {
      return shiftTimeRange(line, delay);
    }
    return line;
  });
  return adjusted.join(ending);
}

const countCues = (text) => {
  const lines = splitIntoLines(text);
  return lines.filter(isTimeRangeLine).length;
};

const describeShift = (delay) => {
  const direction = delay < 0 ? 'earlier' : 'later';
  return `${Math.abs(delay)} ms ${direction}`;
};

function main() {
  const sample = [
    '1',
    '00:00:00,000 --> 00:00:02,110',
    'Hello there.',
    '',
    '2',
    '00:59:59,900 --> 01:00:03,000',
    'Rolling over the hour.',
    ''
  ].join('\n');
  const delay = 500;
  const result = shift(sample, delay);
  const cues = countCues(sample);
  console.log(`Shifting ${cues} cues ${describeShift(delay)}:`);
  console.log(result);
  const restored = shift(result, -delay);
  console.log(`Back again ${describeShift(-delay)}:`);
  console.log(restored);
}

main();

