const validateCandidates = (candidates) => {
  if (!Array.isArray(candidates) || candidates.length === 0) {
    throw new Error("elect: expected a non-empty list of candidate names");
  }
  const cleaned = candidates.map((name) => String(name).trim());
  return [...new Set(cleaned)];
};

const firstAvailableChoice = (ballot, active) => ballot.find((name) => active.has(name));

const normalizeBallot = (ballot, active) => {
  if (!Array.isArray(ballot)) {
    throw new Error("elect: every ballot must be an ordered list of names");
  }
  const preferences = ballot.map((name) => String(name).trim());
  return preferences.filter((name, index) => active.has(name) && preferences.indexOf(name) === index);
};

const countTopPreferences = (papers, active) => {
  const tally = new Map();
  for (const name of active) {
    tally.set(name, 0);
  }
  for (const paper of papers) {
    const top = firstAvailableChoice(paper, active);
    if (top !== undefined) {
      tally.set(top, tally.get(top) + 1);
    }
  }
  return tally;
};

const totalActiveVotes = (tally) => [...tally.values()].reduce((sum, votes) => sum + votes, 0);

const findMajorityWinner = (tally, total) => {
  for (const [name, votes] of tally) {
    if (votes * 2 > total) return name;
  }
  return null;
};

const findWeakestCandidate = (tally) => {
  const ordered = [...tally.entries()].sort((a, b) => a[1] - b[1] || a[0].localeCompare(b[0]));
  return ordered[0][0];
};

const formatRoundReport = (round, tally) => {
  const parts = [...tally.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([name, votes]) => `${name}=${votes}`);
  return `Round ${round}: ${parts.join(", ")}`;
};

function elect(candidates, ballots) {
  const active = new Set(validateCandidates(candidates));
  const papers = ballots
    .map((ballot) => normalizeBallot(ballot, active))
    .filter((paper) => paper.length > 0);
  for (let round = 1; ; round += 1) {
    const tally = countTopPreferences(papers, active);
    const total = totalActiveVotes(tally);
    console.log(formatRoundReport(round, tally));
    const majorityWinner = findMajorityWinner(tally, total);
    if (majorityWinner !== null) return majorityWinner;
    if (active.size <= 1 || total === 0) return [...active].sort()[0];
    active.delete(findWeakestCandidate(tally));
  }
}

const names = ["Alice", "Bob", "Carol"];
const landslide = [["Alice", "Bob"], ["Alice"], ["Bob", "Carol"]];
console.log(`Winner: ${elect(names, landslide)}`);

const contested = [
  ["Alice", "Carol"],
  ["Alice", "Bob"],
  ["Bob", "Carol"],
  ["Bob", "Alice"],
  ["Carol", "Bob"],
];
console.log(`Winner: ${elect(names, contested)}`);

