const EARTH_RADIUS_METERS = 6371000;

const degreesToRadians = (degrees) => (degrees * Math.PI) / 180;

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function validatePoint(point, index) {
  if (!Array.isArray(point) || point.length !== 3) {
    throw new TypeError(`point ${index} must be a [lat, lon, elevation] triplet`);
  }
  const [lat, lon, elevation] = point;
  if (!isFiniteNumber(lat) || Math.abs(lat) > 90) {
    throw new RangeError(`point ${index} has an invalid latitude: ${lat}`);
  }
  if (!isFiniteNumber(lon) || Math.abs(lon) > 180) {
    throw new RangeError(`point ${index} has an invalid longitude: ${lon}`);
  }
  if (!isFiniteNumber(elevation)) {
    throw new RangeError(`point ${index} has an invalid elevation: ${elevation}`);
  }
  return point;
}

function greatCircleDistance(from, to) {
  const lat1 = degreesToRadians(from[0]);
  const lat2 = degreesToRadians(to[0]);
  const deltaLat = lat2 - lat1;
  const deltaLon = degreesToRadians(to[1] - from[1]);
  const h =
    Math.sin(deltaLat / 2) ** 2 +
    Math.cos(lat1) * Math.cos(lat2) * Math.sin(deltaLon / 2) ** 2;
  return 2 * EARTH_RADIUS_METERS * Math.asin(Math.min(1, Math.sqrt(h)));
}

function segmentDistance(from, to) {
  const flat = greatCircleDistance(from, to);
  const rise = to[2] - from[2];
  return Math.sqrt(flat * flat + rise * rise);
}

function distance(points) {
  if (!Array.isArray(points)) {
    throw new TypeError('points must be an array of coordinate triplets');
  }
  const checked = points.map(validatePoint);
  let total = 0;
  for (let i = 1; i < checked.length; i += 1) {
    total += segmentDistance(checked[i - 1], checked[i]);
  }
  return total;
}

const formatDistance = (meters) =>
  meters >= 1000 ? `${(meters / 1000).toFixed(3)} km` : `${meters.toFixed(1)} m`;

function describePath(name, points) {
  const legs = [];
  for (let i = 1; i < points.length; i += 1) {
    const leg = segmentDistance(points[i - 1], points[i]);
    legs.push(formatDistance(leg));
  }
  const total = distance(points);
  const totalText = formatDistance(total);
  return `${name}: ${totalText} (legs: ${legs.join(', ') || 'none'})`;
}

function main() {
  const equatorHop = [
    [0, 0, 0],
    [0, 1, 0],
  ];
  const mountainWalk = [
    [45.0, 7.0, 500],
    [45.01, 7.01, 900],
    [45.02, 7.005, 1400],
  ];
  console.log(describePath('equator hop', equatorHop));
  console.log(describePath('mountain walk', mountainWalk));
}

main();

module.exports = {
  distance,
  segmentDistance,
  describePath,
  degreesToRadians,
};

