const ENGLISH_FREQUENCIES = {
  a: 8.167, b: 1.492, c: 2.782, d: 4.253, e: 12.702, f: 2.228,
  g: 2.015, h: 6.094, i: 6.966, j: 0.153, k: 0.772, l: 4.025,
  m: 2.406, n: 6.749, o: 7.507, p: 1.929, q: 0.095, r: 5.987,
  s: 6.327, t: 9.056, u: 2.758, v: 0.978, w: 2.360, x: 0.150,
  y: 1.974, z: 0.074
};

const isAsciiLetter = (ch) => /^[a-z]$/i.test(ch);

const shiftCharacter = (ch, shift) => {
  if (!isAsciiLetter(ch)) return ch;
  const base = ch === ch.toLowerCase() ? 97 : 65;
  const offset = (ch.charCodeAt(0) - base + shift + 26) % 26;
  return String.fromCharCode(base + offset);
};

const shiftText = (text, shift) =>
  Array.from(text, (ch) => shiftCharacter(ch, shift)).join('');

const countLetterFrequencies = (text) => {
  const counts = {};
  let total = 0;
  for (const ch of text.toLowerCase()) {
    if (!isAsciiLetter(ch)) continue;
    counts[ch] = (counts[ch] || 0) + 1;
    total += 1;
  }
  return { counts, total };
};

const scoreCandidate = (text) => {
  const { counts, total } = countLetterFrequencies(text);
  if (total === 0) return 0;
  let score = 0;
  for (const [letter, expected] of Object.entries(ENGLISH_FREQUENCIES)) {
    const observed = ((counts[letter] || 0) / total) * 100;
    score += Math.sqrt(observed * expected);
  }
  return score;
};

function crack(text) {
  let bestText = text;
  let bestScore = -Infinity;
  for (let shift = 0; shift < 26; shift += 1) {
    const candidate = shiftText(text, -shift);
    const candidateScore = scoreCandidate(candidate);
    if (candidateScore > bestScore) {
      bestScore = candidateScore;
      bestText = candidate;
    }
  }
  return bestText;
}

const formatReport = (cipher) => {
  const plain = crack(cipher);
  const confidence = scoreCandidate(plain).toFixed(2);
  return `${cipher} -> ${plain} (score ${confidence})`;
};

const runDriver = () => {
  const samples = [
    shiftText('apple', 1),
    shiftText('The quick brown fox jumps over the lazy dog.', 13),
    shiftText('Attack at dawn, bring every soldier you have.', 7)
  ];
  for (const sample of samples) {
    console.log(formatReport(sample));
  }
};

runDriver();

module.exports = { crack, shiftText, scoreCandidate, countLetterFrequencies };

