const isNonNegativeInteger = (value) =>
  Number.isInteger(value) && value >= 0;

const validateBase = (base) => {
  if (!Number.isInteger(base) || base <= 0) {
    throw new TypeError('base must be a positive integer');
  }
  return base;
};

const validatePlayers = (players) => {
  if (!Array.isArray(players)) {
    throw new TypeError('players must be an array of experience totals');
  }
  players.forEach((xp, index) => {
    if (!isNonNegativeInteger(xp)) {
      throw new TypeError(`player ${index} has invalid experience: ${xp}`);
    }
  });
  return players;
};

const thresholdForLevel = (level, base) =>
  level <= 1 ? 0 : base * Math.pow(2, level - 2);

const determineCurrentLevel = (xp, base) => {
  if (xp < base) {
    return 1;
  }
  return Math.floor(Math.log2(xp / base)) + 2;
};

const roundToTwo = (value) => Math.round(value * 100) / 100;

const progressPercent = (xp, lvl, base) => {
  const floor = thresholdForLevel(lvl, base);
  const ceiling = thresholdForLevel(lvl + 1, base);
  return roundToTwo(((xp - floor) / (ceiling - floor)) * 100);
};

const buildTriplet = (xp, base) => {
  const current = determineCurrentLevel(xp, base);
  const next = thresholdForLevel(current + 1, base);
  return [current, next, progressPercent(xp, current, base)];
};

function level(players, base) {
  validateBase(base);
  const totals = validatePlayers(players);
  return totals.map((xp) => buildTriplet(xp, base));
}

const formatTriplet = ([lvl, next, pct]) =>
  `level ${lvl}, next at ${next} xp, ${pct.toFixed(2)}% there`;

const renderReport = (players, base) => {
  const stats = level(players, base);
  return stats
    .map((triplet, index) => `Player ${index + 1}: ${formatTriplet(triplet)}`)
    .join('\n');
};

