const LETTERS = 'abcdefghijklmnopqrstuvwxyz'.split('');

function countLetterFrequencies(text) {
  const counts = new Map();
  for (const ch of String(text).toLowerCase()) {
    if (ch >= 'a' && ch <= 'z') {
      counts.set(ch, (counts.get(ch) || 0) + 1);
    }
  }
  return counts;
}

const presentLetters = (counts) => LETTERS.filter((letter) => counts.has(letter));

function findPeakFrequency(counts) {
  let peak = 0;
  for (const value of counts.values()) {
    if (value > peak) peak = value;
  }
  return peak;
}

const computeChartHeight = (width) => Math.max(1, Math.round(width / 2));

const computeColumnWidth = (width, columnCount) => Math.max(1, Math.floor(width / columnCount));

function scaleFrequency(count, peak, height) {
  if (peak === 0) return 0;
  return Math.max(1, Math.round((count * height) / peak));
}

const padCell = (ch, colWidth) => ch + ' '.repeat(colWidth - 1);

function buildChartRow(letters, scaled, level, colWidth) {
  const cells = letters.map((letter) => padCell(scaled.get(letter) >= level ? '#' : ' ', colWidth));
  return cells.join('').replace(/\s+$/, '');
}

function buildLabelRow(letters, colWidth) {
  const cells = letters.map((letter) => padCell(letter, colWidth));
  return cells.join('').replace(/\s+$/, '');
}

function histogram(text, width) {
  const counts = countLetterFrequencies(text);
  const letters = presentLetters(counts);
  if (letters.length === 0) return '(no alphabetical characters)';
  const height = computeChartHeight(width);
  const colWidth = computeColumnWidth(width, letters.length);
  const peak = findPeakFrequency(counts);
  const scaled = new Map();
  for (const letter of letters) {
    scaled.set(letter, scaleFrequency(counts.get(letter), peak, height));
  }
  const rows = [];
  for (let level = height; level >= 1; level -= 1) {
    rows.push(buildChartRow(letters, scaled, level, colWidth));
  }
  rows.push(buildLabelRow(letters, colWidth));
  return rows.join('\n');
}

function describePeakLetter(counts) {
  const peak = findPeakFrequency(counts);
  if (peak === 0) return 'no letters counted';
  const tallest = presentLetters(counts).filter((letter) => counts.get(letter) === peak);
  return `tallest column(s): ${tallest.join(', ')} with ${peak} occurrence(s)`;
}

function main() {
  const samples = [
    'Eee eerie geese see cheese; the eel feels free.',
    'The quick brown fox jumps over the lazy dog.',
  ];
  for (const sample of samples) {
    const counts = countLetterFrequencies(sample);
    console.log(sample);
    console.log(histogram(sample, 40));
    console.log(describePeakLetter(counts));
    console.log('');
  }
}

main();

