const COMPASS = [
  { name: 'North', dr: -1, dc: 0 },
  { name: 'North East', dr: -1, dc: 1 },
  { name: 'East', dr: 0, dc: 1 },
  { name: 'South East', dr: 1, dc: 1 },
  { name: 'South', dr: 1, dc: 0 },
  { name: 'South West', dr: 1, dc: -1 },
  { name: 'West', dr: 0, dc: -1 },
  { name: 'North West', dr: -1, dc: -1 }
];

const normalizeGrid = (grid) =>
  grid.map((row) => (typeof row === 'string' ? row.split('') : Array.from(row)).map((ch) => ch.toUpperCase()));

const normalizeWord = (word) => String(word).replace(/[^A-Za-z]/g, '').toUpperCase();

const isInsideGrid = (grid, row, col) =>
  row >= 0 && row < grid.length && col >= 0 && col < grid[row].length;

const letterAt = (grid, row, col) => {
  const inside = isInsideGrid(grid, row, col);
  return inside ? grid[row][col] : null;
};

const matchesFromCell = (grid, word, row, col, dr, dc) => {
  for (let i = 0; i < word.length; i += 1) {
    if (letterAt(grid, row + dr * i, col + dc * i) !== word[i]) return false;
  }
  return true;
};

const findWordPlacement = (grid, word) => {
  for (let row = 0; row < grid.length; row += 1) {
    for (let col = 0; col < grid[row].length; col += 1) {
      if (grid[row][col] !== word[0]) continue;
      for (const { name, dr, dc } of COMPASS) {
        if (matchesFromCell(grid, word, row, col, dr, dc)) return [word, row, col, name];
      }
    }
  }
  return null;
};

function search(grid, words) {
  const board = normalizeGrid(grid);
  const found = [];
  for (const raw of words) {
    const word = normalizeWord(raw);
    if (word.length === 0) continue;
    const placement = findWordPlacement(board, word);
    if (placement) found.push(placement);
  }
  return found;
}

const formatFinding = ([word, row, col, direction]) =>
  `${word.padEnd(10)} row ${row}, col ${col}, heading ${direction}`;

const missingWords = (words, findings) => {
  const hits = new Set(findings.map((finding) => finding[0]));
  return words
    .map(normalizeWord)
    .filter((word) => word.length > 0 && !hits.has(word));
};

const renderReport = (grid, words) => {
  const findings = search(grid, words);
  const lines = findings.map(formatFinding);
  const absent = missingWords(words, findings);
  if (absent.length > 0) lines.push(`not found: ${absent.join(', ')}`);
  return lines.join('\n');
};

const puzzle = [
  'TACOS',
  'ODINA',
  'GRAPE',
  'HEXIL',
  'TSOPZ'
];

console.log(renderReport(puzzle, ['cat', 'dog', 'grape', 'post', 'pixel', 'zebra']));

module.exports = {
  search,
  findWordPlacement,
  isInsideGrid,
  renderReport
};

