const vectorBetween = (a, b) => [b[0] - a[0], b[1] - a[1]];

const dotProduct = (u, v) => u[0] * v[0] + u[1] * v[1];

const crossProduct = (u, v) => u[0] * v[1] - u[1] * v[0];

function perpendicularDistance(point, lineStart, lineEnd) {
  const along = vectorBetween(lineStart, lineEnd);
  const offset = vectorBetween(lineStart, point);
  const alongLengthSq = dotProduct(along, along);
  if (alongLengthSq === 0) {
    return Math.sqrt(dotProduct(offset, offset));
  }
  return Math.abs(crossProduct(along, offset)) / Math.sqrt(alongLengthSq);
}

function findFurthestPoint(points, firstIndex, lastIndex) {
  let index = -1;
  let distance = 0;
  for (let i = firstIndex + 1; i < lastIndex; i += 1) {
    const candidate = perpendicularDistance(points[i], points[firstIndex], points[lastIndex]);
    if (candidate > distance) {
      distance = candidate;
      index = i;
    }
  }
  return { index, distance };
}

function markKeptPoints(points, firstIndex, lastIndex, tolerance, keep) {
  const furthest = findFurthestPoint(points, firstIndex, lastIndex);
  if (furthest.index === -1 || furthest.distance <= tolerance) {
    return;
  }
  keep[furthest.index] = true;
  markKeptPoints(points, firstIndex, furthest.index, tolerance, keep);
  markKeptPoints(points, furthest.index, lastIndex, tolerance, keep);
}

function validatePath(points) {
  if (!Array.isArray(points)) {
    throw new TypeError('points must be an array of coordinate pairs');
  }
  points.forEach((point, i) => {
    const isPair = Array.isArray(point) && point.length === 2;
    if (!isPair || !Number.isFinite(point[0]) || !Number.isFinite(point[1])) {
      throw new TypeError(`point at index ${i} is not a finite [x, y] pair`);
    }
  });
}

function simplify(points, tolerance) {
  validatePath(points);
  if (points.length < 3) {
    return points.slice();
  }
  const keep = new Array(points.length).fill(false);
  keep[0] = true;
  keep[points.length - 1] = true;
  markKeptPoints(points, 0, points.length - 1, tolerance, keep);
  return points.filter((_, i) => keep[i]);
}

const formatPoint = (point) => `(${point[0]}, ${point[1]})`;

function formatPath(points) {
  const parts = points.map(formatPoint);
  return parts.join(' -> ');
}

function reportSimplification(label, points, tolerance) {
  const reduced = simplify(points, tolerance);
  console.log(`${label} (tolerance ${tolerance})`);
  console.log(`  in  [${points.length}]: ${formatPath(points)}`);
  console.log(`  out [${reduced.length}]: ${formatPath(reduced)}`);
}

const straightLine = Array.from({ length: 10 }, (_, i) => [i, 2 * i]);
const zigZag = [[0, 0], [1, 0.1], [2, -0.1], [3, 5], [4, 6], [5, 7], [6, 8.1], [7, 9], [8, 9], [9, 9]];

reportSimplification('collinear path', straightLine, 0.01);
reportSimplification('zig-zag path', zigZag, 1);
reportSimplification('zig-zag path', zigZag, 0.05);

module.exports.simplify = simplify;
module.exports.perpendicularDistance = perpendicularDistance;
module.exports.findFurthestPoint = findFurthestPoint;
module.exports.formatPath = formatPath;

