const isNonNegativeInteger = (value) =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0;

const validateRhythmArgs = (pulses, steps) => {
  if (!isNonNegativeInteger(steps)) {
    throw new TypeError('steps must be a non-negative integer');
  }
  if (!isNonNegativeInteger(pulses)) {
    throw new TypeError('pulses must be a non-negative integer');
  }
  if (pulses > steps) {
    throw new RangeError('pulses cannot exceed steps');
  }
};

const makeGroupList = (count, beat) => {
  const groups = [];
  for (let i = 0; i < count; i += 1) {
    groups.push([beat]);
  }
  return groups;
};

const shouldKeepPairing = (front, back) => front.length > 0 && back.length > 1;

const interleaveGroups = (front, back) => {
  const pairs = Math.min(front.length, back.length);
  const merged = [];
  for (let i = 0; i < pairs; i += 1) {
    merged.push(front[i].concat(back[i]));
  }
  const leftover = front.length > pairs ? front.slice(pairs) : back.slice(pairs);
  return { front: merged, back: leftover };
};

const flattenGroups = (groups) =>
  groups.reduce((sequence, group) => sequence.concat(group), []);

const rhythm = (pulses, steps) => {
  validateRhythmArgs(pulses, steps);
  let front = makeGroupList(pulses, 1);
  let back = makeGroupList(steps - pulses, 0);
  while (shouldKeepPairing(front, back)) {
    const paired = interleaveGroups(front, back);
    front = paired.front;
    back = paired.back;
  }
  return flattenGroups(front.concat(back));
};

const countActiveBeats = (pattern) =>
  pattern.reduce((total, beat) => total + beat, 0);

const formatRhythm = (pattern) => pattern.join('') || '(empty)';

const describeRhythm = (pulses, steps) => {
  const pattern = rhythm(pulses, steps);
  const active = countActiveBeats(pattern);
  return `E(${pulses},${steps}) = ${formatRhythm(pattern)}  [${active} active]`;
};

const main = () => {
  const cases = [[3, 8], [5, 13], [4, 4], [0, 5], [7, 16], [2, 5]];
  cases.forEach(([pulses, steps]) => {
    console.log(describeRhythm(pulses, steps));
  });
  console.log(rhythm(3, 8).join(', '));
};

main();

