const normalizeCity = (name) => String(name).trim();

const readLeg = (ticket) => {
  const origin = normalizeCity(ticket.origin ?? ticket.from ?? ticket[0]);
  const destination = normalizeCity(ticket.destination ?? ticket.to ?? ticket[1]);
  return { origin, destination };
};

const validateTickets = (legs) => {
  if (legs.length === 0) {
    throw new Error('no boarding passes supplied');
  }
  const seenOrigins = new Set();
  for (const leg of legs) {
    if (!leg.origin || !leg.destination) {
      throw new Error('a boarding pass is missing a city name');
    }
    if (leg.origin === leg.destination) {
      throw new Error(`boarding pass departs and arrives at ${leg.origin}`);
    }
    if (seenOrigins.has(leg.origin)) {
      throw new Error(`two boarding passes depart from ${leg.origin}`);
    }
    seenOrigins.add(leg.origin);
  }
  return legs;
};

const collectDestinations = (legs) => new Set(legs.map((leg) => leg.destination));

const findStartCity = (legs, destinations) => {
  const heads = legs.map((leg) => leg.origin).filter((city) => !destinations.has(city));
  if (heads.length !== 1) {
    throw new Error('the boarding passes do not form a single journey');
  }
  return heads[0];
};

const findNextLeg = (legs, city) => legs.find((leg) => leg.origin === city);

function route(tickets) {
  const parsed = tickets.map(readLeg);
  const legs = validateTickets(parsed);
  const destinations = collectDestinations(legs);
  let city = findStartCity(legs, destinations);
  const itinerary = [city];
  let leg = findNextLeg(legs, city);
  while (leg) {
    city = leg.destination;
    itinerary.push(city);
    leg = findNextLeg(legs, city);
  }
  if (itinerary.length !== legs.length + 1) {
    throw new Error('some boarding passes are disconnected from the journey');
  }
  return itinerary;
}

const formatItinerary = (cities) => cities.join(' -> ');

const describeJourney = (cities) => `${cities.length} stops over ${cities.length - 1} legs`;

const reportRoute = (tickets) => {
  const cities = route(tickets);
  console.log(formatItinerary(cities));
  console.log(describeJourney(cities));
};

reportRoute([
  { origin: 'Paris', destination: 'Berlin' },
  { origin: 'London', destination: 'Paris' },
]);

reportRoute([
  ['Madrid', 'Rome'],
  ['Cairo', 'Athens'],
  ['Athens', 'Madrid'],
  ['Rome', 'Oslo'],
]);

module.exports.route = route;
module.exports.formatItinerary = formatItinerary;
module.exports.describeJourney = describeJourney;

