const EMPTY = '.';

const isOnBoard = ([row, col]) =>
  row >= 0 && row < 8 && col >= 0 && col < 8;

const getPieceAt = (grid, [row, col]) => grid[row][col];

const isEmptySquare = (grid, square) =>
  getPieceAt(grid, square) === EMPTY;

const belongsToPlayer = (piece, player) =>
  piece !== EMPTY && piece.toLowerCase() === player;

const isOpponentPiece = (piece, player) =>
  piece !== EMPTY && piece.toLowerCase() !== player;

const isKingPiece = (piece) =>
  piece !== EMPTY && piece === piece.toUpperCase();

const getForwardDirection = (player) => (player === 'w' ? -1 : 1);

const isSimpleStep = (from, to) =>
  Math.abs(to[0] - from[0]) === 1 && Math.abs(to[1] - from[1]) === 1;

const isJumpStep = (from, to) =>
  Math.abs(to[0] - from[0]) === 2 && Math.abs(to[1] - from[1]) === 2;

const midpointOf = (from, to) => [(from[0] + to[0]) / 2, (from[1] + to[1]) / 2];

function isForwardStep(from, to, king, player) {
  if (king) return true;
  return Math.sign(to[0] - from[0]) === getForwardDirection(player);
}

function validate(board, move) {
  if (!Array.isArray(move) || move.length < 2) return false;
  if (!move.every(isOnBoard)) return false;
  const grid = board.grid.map((row) => row.slice());
  const player = board.turn;
  const piece = getPieceAt(grid, move[0]);
  if (!belongsToPlayer(piece, player)) return false;
  const king = isKingPiece(piece);
  const jumping = isJumpStep(move[0], move[1]);
  if (!jumping && move.length !== 2) return false;
  grid[move[0][0]][move[0][1]] = EMPTY;
  let current = move[0];
  for (let i = 1; i < move.length; i += 1) {
    const next = move[i];
    if (!isEmptySquare(grid, next)) return false;
    if (!isForwardStep(current, next, king, player)) return false;
    if (jumping) {
      if (!isJumpStep(current, next)) return false;
      const middle = midpointOf(current, next);
      const captured = getPieceAt(grid, middle);
      if (!isOpponentPiece(captured, player)) return false;
      grid[middle[0]][middle[1]] = EMPTY;
    } else if (!isSimpleStep(current, next)) {
      return false;
    }
    current = next;
  }
  return true;
}

const parseBoardRows = (rows, turn) => ({ grid: rows.map((row) => row.split('')), turn });

const describeMove = (move) => move.map(([r, c]) => `(${r},${c})`).join(' -> ');

function runCase(board, move) {
  const label = describeMove(move);
  console.log(`${label}: ${validate(board, move)}`);
}

const whiteBoard = parseBoardRows([
  '........',
  '........',
  '........',
  '..b.b...',
  '........',
  '..b.b...',
  '...w....',
  '........',
], 'w');

runCase(whiteBoard, [[6, 3], [5, 3]]);
runCase(whiteBoard, [[6, 3], [5, 2]]);
runCase(whiteBoard, [[6, 3], [4, 1]]);
runCase(whiteBoard, [[6, 3], [4, 3], [2, 5]]);
runCase(whiteBoard, [[6, 3], [7, 2]]);

const blackBoard = parseBoardRows(whiteBoard.grid.map((row) => row.join('')), 'b');
runCase(blackBoard, [[6, 3], [5, 2]]);
runCase(blackBoard, [[5, 2], [6, 3]]);

module.exports.validate = validate;
module.exports.parseBoardRows = parseBoardRows;

