const splitFields = (line) => line.split(',').map((part) => part.trim());

const parseClockTime = (text) => {
  const parts = text.split(':');
  if (parts.length !== 3) {
    throw new Error(`Malformed time "${text}": expected hh:mm:ss`);
  }
  const [hours, minutes, seconds] = parts.map((part) => Number(part));
  if ([hours, minutes, seconds].some((value) => !Number.isFinite(value))) {
    throw new Error(`Malformed time "${text}": non-numeric component`);
  }
  return hours * 3600 + minutes * 60 + seconds;
};

const parseRating = (text) => {
  const rating = Number(text);
  if (!Number.isFinite(rating) || rating <= 0) {
    throw new Error(`Invalid handicap rating "${text}"`);
  }
  return rating;
};

const parseRaceEntry = (line) => {
  const fields = splitFields(line);
  if (fields.length !== 4) {
    throw new Error(`Expected 4 fields in "${line}", found ${fields.length}`);
  }
  const [name, ratingText, startText, finishText] = fields;
  if (name === '') {
    throw new Error(`Missing boat name in "${line}"`);
  }
  return {
    name,
    rating: parseRating(ratingText),
    start: parseClockTime(startText),
    finish: parseClockTime(finishText),
  };
};

const elapsedSeconds = (entry) => {
  const raw = entry.finish - entry.start;
  const elapsed = raw < 0 ? raw + 24 * 3600 : raw;
  if (elapsed === 0) {
    throw new Error(`Boat ${entry.name} has a zero elapsed time`);
  }
  return elapsed;
};

const correctedTime = (entry) => {
  const elapsed = elapsedSeconds(entry);
  return Math.trunc(elapsed * entry.rating);
};

const rankEntries = (entries) =>
  entries
    .map((entry) => ({ name: entry.name, corrected: correctedTime(entry) }))
    .sort((a, b) => a.corrected - b.corrected || a.name.localeCompare(b.name));

const formatResult = (result) => `${result.name}: ${result.corrected} seconds`;

function score(races) {
  if (!Array.isArray(races)) {
    throw new TypeError('score expects an array of race record strings');
  }
  const entries = races.map((line) => parseRaceEntry(String(line)));
  return rankEntries(entries).map(formatResult);
}

const regatta = [
  'Alpha, 0.95, 12:00:00, 13:15:30',
  'Bravo, 1.02, 12:00:00, 13:10:00',
  'Charlie, 0.88, 12:05:00, 13:30:45',
  'Delta, 1.10, 23:50:00, 01:05:20',
];

score(regatta).forEach((line, index) => console.log(`${index + 1}. ${line}`));

module.exports = { score, parseRaceEntry, correctedTime };

