const PH_MIN = 6.8;
const PH_MAX = 7.6;
const AMMONIA_MAX = 0.2;
const NITRATE_MAX = 40;

const parseDayNumber = (field) => {
  const match = /^(?:day\s*)?(\d+)$/i.exec(field.trim());
  if (!match) {
    throw new Error(`Cannot read a day number from "${field.trim()}"`);
  }
  return Number(match[1]);
};

const parseMeasurement = (field, label) => {
  const value = Number(field.trim());
  if (!Number.isFinite(value)) {
    throw new Error(`Cannot read ${label} from "${field.trim()}"`);
  }
  return value;
};

const parseReading = (line) => {
  const parts = String(line).split(',');
  if (parts.length !== 4) {
    throw new Error(`Expected 4 comma separated fields in "${line}"`);
  }
  return {
    day: parseDayNumber(parts[0]),
    ph: parseMeasurement(parts[1], 'pH'),
    ammonia: parseMeasurement(parts[2], 'ammonia'),
    nitrate: parseMeasurement(parts[3], 'nitrate'),
  };
};

const isPhOutOfRange = (ph) => ph < PH_MIN || ph > PH_MAX;
const isAmmoniaHigh = (ammonia) => ammonia > AMMONIA_MAX;
const isNitrateHigh = (nitrate) => nitrate > NITRATE_MAX;
const describePhFault = (ph) => (ph < PH_MIN ? 'low pH' : 'high pH');

const collectIssues = (reading) => {
  const issues = [];
  if (isPhOutOfRange(reading.ph)) {
    issues.push(describePhFault(reading.ph));
  }
  if (isAmmoniaHigh(reading.ammonia)) {
    issues.push('high ammonia');
  }
  if (isNitrateHigh(reading.nitrate)) {
    issues.push('high nitrate');
  }
  return issues;
};

const analyzeReadings = (readings) =>
  readings.map((line) => {
    const reading = parseReading(line);
    return { day: reading.day, issues: collectIssues(reading) };
  });

const formatAction = (day, issues) => `Day ${day}: ${issues.join(', ')}.`;
const computeHealthScore = (faultCount) => Math.max(0, 100 - 5 * faultCount);

const evaluate = (readings) =>
  analyzeReadings(readings)
    .filter((entry) => entry.issues.length > 0)
    .map((entry) => formatAction(entry.day, entry.issues));

const buildReport = (readings) => {
  const analyzed = analyzeReadings(readings);
  const faults = analyzed.reduce((sum, entry) => sum + entry.issues.length, 0);
  return {
    score: computeHealthScore(faults),
    daysChecked: analyzed.length,
    actions: evaluate(readings),
  };
};

const samples = [
  'Day 1, 7.2, 0.5, 20',
  'Day 2, 6.5, 0.1, 15',
  'Day 3, 7.4, 0.05, 55',
  'Day 4, 7.0, 0.1, 30',
];

const report = buildReport(samples);
report.actions.forEach((action) => console.log(action));
console.log(`Water health score: ${report.score} over ${report.daysChecked} days`);

module.exports = { evaluate, buildReport, parseReading, computeHealthScore };

