function splitPeriodFields(line) {
  const parts = String(line).split(',');
  if (parts.length !== 3) {
    throw new Error(`expected "name, start, end" but got: ${line}`);
  }
  return parts.map((part) => part.trim());
}

const parseYearValue = (text) => {
  const year = Number(text);
  if (!Number.isInteger(year)) {
    throw new Error(`invalid year: ${text}`);
  }
  return year;
};

function parsePeriodLine(line) {
  const fields = splitPeriodFields(line);
  const start = parseYearValue(fields[1]);
  const end = parseYearValue(fields[2]);
  if (end < start) {
    throw new Error(`period ends before it starts: ${line}`);
  }
  return { name: fields[0], start, end };
}

const comparePeriodsByStart = (a, b) => a.start - b.start || a.end - b.end;

const overlapsOrTouches = (first, second) => second.start <= first.end;

function mergeSortedPeriods(sorted) {
  const merged = [];
  for (const period of sorted) {
    const last = merged[merged.length - 1];
    if (last && overlapsOrTouches(last, period)) {
      last.end = Math.max(last.end, period.end);
    } else {
      merged.push({ start: period.start, end: period.end });
    }
  }
  return merged;
}

const spanOfPeriod = (period) => period.end - period.start;

function merge(periods) {
  const parsed = periods.map(parsePeriodLine);
  const sorted = parsed.sort(comparePeriodsByStart);
  const merged = mergeSortedPeriods(sorted);
  return merged.reduce((total, period) => total + spanOfPeriod(period), 0);
}

const formatYearLabel = (year) => (year < 0 ? `${-year} BC` : `${year} AD`);

function describePeriodRange(period) {
  const from = formatYearLabel(period.start);
  const to = formatYearLabel(period.end);
  return `${period.name}: ${from} - ${to} (${spanOfPeriod(period)} years)`;
}

const empires = ['Roman, -27, 476', 'Han, -202, 220'];
for (const line of empires) {
  const period = parsePeriodLine(line);
  console.log(describePeriodRange(period));
}
console.log(merge(empires));

module.exports = { merge, parsePeriodLine, mergeSortedPeriods, describePeriodRange };

