const stitchCosts = { knit: 3, purl: 4 };

const isStitchCommand = (command) => Object.prototype.hasOwnProperty.call(stitchCosts, command);

const splitInstructions = (row) =>
  String(row)
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);

function parseSegment(text) {
  const match = /^([A-Za-z]+)\s+(\d+)(?:\s+times?)?$/.exec(text);
  if (!match) {
    throw new Error(`Unreadable instruction: "${text}"`);
  }
  const command = match[1].toLowerCase();
  if (command !== 'repeat' && !isStitchCommand(command)) {
    throw new Error(`Unknown stitch: "${match[1]}"`);
  }
  return { command, count: Number(match[2]) };
}

const findRepeatCount = (segments) => {
  const repeat = segments.find((segment) => segment.command === 'repeat');
  return repeat ? repeat.count : 1;
};

const selectStitchSegments = (segments) => segments.filter((segment) => isStitchCommand(segment.command));

function countBaseStitches(segments) {
  const stitches = selectStitchSegments(segments);
  return stitches.reduce((sum, segment) => sum + segment.count, 0);
}

function measureBaseYarn(segments) {
  const stitches = selectStitchSegments(segments);
  return stitches.reduce((sum, segment) => sum + segment.count * stitchCosts[segment.command], 0);
}

function summarizeRow(row) {
  const parts = splitInstructions(row);
  const segments = parts.map(parseSegment);
  const repeats = findRepeatCount(segments);
  return {
    stitches: countBaseStitches(segments) * repeats,
    centimeters: measureBaseYarn(segments) * repeats,
  };
}

const roundMeters = (centimeters) => Math.round(centimeters) / 100;

const pluralizeUnit = (count, word) => {
  if (count === 1) {
    return word;
  }
  return word === 'stitch' ? 'stitches' : `${word}s`;
};

function formatSummary(stitches, centimeters) {
  const meters = roundMeters(centimeters);
  const stitchWord = pluralizeUnit(stitches, 'stitch');
  const meterWord = pluralizeUnit(meters, 'meter');
  return `${stitches} ${stitchWord}, ${meters} ${meterWord} of yarn.`;
}

function tally(rows) {
  const rowList = Array.isArray(rows) ? rows : [rows];
  const summaries = rowList.map(summarizeRow);
  const totals = summaries.reduce(
    (acc, row) => ({
      stitches: acc.stitches + row.stitches,
      centimeters: acc.centimeters + row.centimeters,
    }),
    { stitches: 0, centimeters: 0 }
  );
  return formatSummary(totals.stitches, totals.centimeters);
}

const patternRows = process.argv.slice(2);
if (patternRows.length > 0) {
  console.log(tally(patternRows));
}

module.exports = { tally };

