const toPositiveNumber = (text, label) => {
  const value = Number(text);
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`Invalid ${label}: "${text}"`);
  }
  return value;
};

function parseApplianceEntry(entry) {
  const parts = String(entry).split(',').map((part) => part.trim());
  if (parts.length < 3) {
    throw new Error(`Malformed appliance entry: "${entry}"`);
  }
  const [name, wattsText, hoursText] = parts;
  const watts = toPositiveNumber(wattsText, 'wattage');
  const hours = toPositiveNumber(hoursText, 'daily hours');
  return { name, watts, hours };
}

const computeDailyKwh = (watts, hours) => (watts * hours) / 1000;

const computeMonthlyKwh = (dailyKwh) => dailyKwh * 30;

function applyTieredRate(kwh) {
  const baseTier = Math.min(kwh, 100);
  const excessTier = Math.max(kwh - 100, 0);
  return baseTier * 0.1 + excessTier * 0.2;
}

const roundToCents = (amount) => Math.round(amount * 100) / 100;

const formatCurrency = (amount) => {
  const rounded = roundToCents(amount);
  return `$${rounded.toFixed(2)}`;
};

function buildApplianceRecord(entry) {
  const { name, watts, hours } = parseApplianceEntry(entry);
  const dailyKwh = computeDailyKwh(watts, hours);
  const monthlyKwh = computeMonthlyKwh(dailyKwh);
  const rawCost = applyTieredRate(monthlyKwh);
  const cost = roundToCents(rawCost);
  return { name, monthlyKwh, cost };
}

const sumCosts = (records) => records.reduce((running, record) => running + record.cost, 0);

const describeRecord = (record) =>
  `${record.name}: ${record.monthlyKwh.toFixed(1)} kWh -> ${formatCurrency(record.cost)}`;

function aggregate(appliances) {
  if (!Array.isArray(appliances)) {
    throw new TypeError('aggregate expects an array of appliance log strings');
  }
  const records = appliances.map(buildApplianceRecord);
  const rawTotal = sumCosts(records);
  const total = roundToCents(rawTotal);
  const lines = records.map(describeRecord);
  lines.push(`Total: ${formatCurrency(total)}`);
  return { records, total, lines };
}

const logMonthlyBill = (appliances) => {
  const report = aggregate(appliances);
  report.lines.forEach((line) => console.log(line));
  return report.total;
};

logMonthlyBill([
  'Heater, 1500, 4',
  'Refrigerator, 200, 24',
  'Laptop, 65, 8',
  'LED Lamp, 9, 5',
]);

module.exports = { aggregate, parseApplianceEntry, applyTieredRate, formatCurrency, logMonthlyBill };

