const SECTION_ORDER = ['front section', 'middle section', 'rear section'];
const ROW_ORDER = ['first row', 'second row'];

const FAMILIES = {
  strings: ['violin', 'viola', 'cello', 'double bass', 'harp'],
  woodwinds: ['flute', 'piccolo', 'oboe', 'clarinet', 'bassoon', 'english horn'],
  brass: ['trumpet', 'horn', 'french horn', 'trombone', 'tuba', 'cornet'],
};

const SECTION_BY_FAMILY = {
  strings: 'front section',
  woodwinds: 'middle section',
  brass: 'rear section',
};

const normalizeToken = (token) => token.trim().replace(/\s+/g, ' ');

const toTitleCase = (text) => {
  const words = normalizeToken(text).split(' ');
  return words
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const parseMusician = (entry) => {
  const parts = String(entry).split(',').map(normalizeToken);
  if (parts.length !== 3 || parts.some((part) => part === '')) {
    throw new Error(`Cannot parse musician entry: "${entry}"`);
  }
  return {
    name: toTitleCase(parts[0]),
    instrument: parts[1].toLowerCase(),
    rank: parts[2].toLowerCase(),
  };
};

const instrumentFamily = (instrument) => {
  const family = Object.keys(FAMILIES).find((key) => FAMILIES[key].includes(instrument));
  if (!family) {
    throw new Error(`Unknown instrument: "${instrument}"`);
  }
  return family;
};

const sectionForInstrument = (instrument) => {
  const family = instrumentFamily(instrument);
  return SECTION_BY_FAMILY[family];
};

const rowForRank = (rank) => {
  if (rank === 'principal') return 'first row';
  if (rank === 'tutti') return 'second row';
  throw new Error(`Unknown rank: "${rank}"`);
};

const compareSeats = (a, b) =>
  SECTION_ORDER.indexOf(a.section) - SECTION_ORDER.indexOf(b.section) ||
  ROW_ORDER.indexOf(a.row) - ROW_ORDER.indexOf(b.row) ||
  a.name.localeCompare(b.name);

const formatSeat = (seat) => `${seat.name}: ${seat.section}, ${seat.row}`;

const seatMusician = (musician) => ({
  name: musician.name,
  section: sectionForInstrument(musician.instrument),
  row: rowForRank(musician.rank),
});

function arrange(musicians) {
  const parsed = musicians.map(parseMusician);
  const seats = parsed.map(seatMusician);
  seats.sort(compareSeats);
  return seats.map(formatSeat);
}

const printChart = (title, musicians) => {
  console.log(`== ${title} ==`);
  arrange(musicians).forEach((line) => console.log(line));
};

printChart('Chamber ensemble', [
  'John, Violin, Principal',
  'maria lopez, Clarinet, Tutti',
  'Ade, Trombone, Principal',
  'Sven, Cello, Tutti',
]);

module.exports = { arrange, parseMusician, sectionForInstrument, rowForRank };

