const ZONE_LETTERS = ['A', 'B', 'C', 'D', 'E'];

const normalizeField = (field) => field.trim().replace(/\s+/g, ' ');

const parseZoneLabel = (label) => {
  const cleaned = normalizeField(label);
  const match = cleaned.match(/^Zone\s+([A-Ea-e])$/);
  if (!match) {
    throw new Error(`Unrecognized zone: "${label}"`);
  }
  return match[1].toUpperCase();
};

const zoneIndexOf = (letter) => ZONE_LETTERS.indexOf(letter);

const parseTripRecord = (trip) => {
  const fields = String(trip).split(',');
  if (fields.length !== 3) {
    throw new Error(`Expected "origin, destination, passenger" but got "${trip}"`);
  }
  const passengerField = normalizeField(fields[2]);
  return {
    origin: parseZoneLabel(fields[0]),
    destination: parseZoneLabel(fields[1]),
    passenger: passengerField.toLowerCase(),
  };
};

const countBoundariesCrossed = (origin, destination) => {
  const from = zoneIndexOf(origin);
  const to = zoneIndexOf(destination);
  return Math.abs(to - from);
};

const computeBaseFare = (boundaries) => 2 + 3 * boundaries;

const discountRateFor = (passenger) => {
  if (passenger === 'senior') {
    return 0.5;
  }
  if (passenger === 'student') {
    return 0.25;
  }
  if (passenger === 'adult' || passenger === 'regular') {
    return 0;
  }
  throw new Error(`Unknown passenger type: "${passenger}"`);
};

const applyDiscount = (amount, rate) => amount * (1 - rate);

const applyStationTax = (amount) => amount * 1.05;

const formatFareLine = (amount) => `Final fare: ${amount.toFixed(2)}`;

const fare = (trips) =>
  trips.map((trip) => {
    const record = parseTripRecord(trip);
    const boundaries = countBoundariesCrossed(record.origin, record.destination);
    const base = computeBaseFare(boundaries);
    const rate = discountRateFor(record.passenger);
    const discounted = applyDiscount(base, rate);
    const taxed = applyStationTax(discounted);
    return formatFareLine(taxed);
  });

const main = () => {
  const requests = [
    'Zone A, Zone C, Senior',
    'Zone B, Zone B, Adult',
    'Zone E, Zone A, Student',
    'Zone D, Zone C, Regular',
  ];
  const lines = fare(requests);
  requests.forEach((request, index) => {
    console.log(`${request} -> ${lines[index]}`);
  });
};

main();

module.exports = { fare, parseTripRecord, countBoundariesCrossed, discountRateFor };

