const STOP_WORDS = new Set([
  'the', 'and', 'or', 'a', 'an', 'of', 'to', 'in', 'is', 'it',
  'on', 'at', 'as', 'by', 'for', 'with', 'that', 'this', 'was', 'were'
]);

const stripPunctuation = (word) => word.replace(/[^\p{L}\p{N}'-]/gu, '');

const normalizeWord = (word) => {
  const bare = stripPunctuation(word.toLowerCase());
  return bare.replace(/^['-]+/, '').replace(/['-]+$/, '');
};

const isIndexable = (word) => word.length > 0 && !STOP_WORDS.has(word);

const splitPageLine = (line) => {
  const tokens = String(line).trim().split(/\s+/).filter((t) => t.length > 0);
  return { pageToken: tokens[0], words: tokens.slice(1) };
};

const parsePageNumber = (token) => {
  const digits = stripPunctuation(token);
  const value = Number.parseInt(digits, 10);
  return Number.isNaN(value) ? digits : value;
};

const collectPageWords = (words) => {
  const unique = new Set();
  for (const raw of words) {
    const clean = normalizeWord(raw);
    if (isIndexable(clean)) {
      unique.add(clean);
    }
  }
  return unique;
};

const addOccurrence = (map, word, page) => {
  if (!map.has(word)) {
    map.set(word, []);
  }
  const pages = map.get(word);
  if (!pages.includes(page)) {
    pages.push(page);
  }
};

const comparePages = (left, right) => {
  if (typeof left === 'number' && typeof right === 'number') {
    return left - right;
  }
  return String(left).localeCompare(String(right));
};

const formatEntry = (word, pages) => {
  const sorted = [...pages].sort(comparePages);
  return `${word}: ${sorted.join(', ')}`;
};

function index(pages) {
  const occurrences = new Map();
  for (const line of pages) {
    const { pageToken, words } = splitPageLine(line);
    if (pageToken === undefined) {
      continue;
    }
    const page = parsePageNumber(pageToken);
    for (const word of collectPageWords(words)) {
      addOccurrence(occurrences, word, page);
    }
  }
  return [...occurrences.keys()]
    .sort((a, b) => a.localeCompare(b))
    .map((word) => formatEntry(word, occurrences.get(word)));
}

module.exports = { index, normalizeWord, parsePageNumber };

