const MIN_ALE_TEMPERATURE = 18;
const MAX_ALE_TEMPERATURE = 22;
const READING_PATTERN = /Day\s*(\d+)\s*[,;]\s*(-?\d+(?:\.\d+)?)\s*[,;]\s*(\d+(?:\.\d+)?)/i;

const parseReading = (text) => {
  const match = READING_PATTERN.exec(String(text).trim());
  if (!match) {
    return null;
  }
  return {
    day: Number(match[1]),
    temperature: Number(match[2]),
    gravity: Number(match[3]),
  };
};

const parseAll = (readings) =>
  readings.map(parseReading).filter((reading) => reading !== null);

const roundGravity = (value) => Math.round(value * 1000) / 1000;

const gravityDrop = (previous, current) =>
  roundGravity(previous - current);

const isGravityStable = (previous, current) =>
  Math.abs(gravityDrop(previous, current)) < 0.001;

const gravityAt = (list, index) =>
  (index >= 0 ? list[index].gravity : undefined);

const determinePhase = (current, previous, older) => {
  if (previous === undefined) {
    return 'active';
  }
  const stableNow = isGravityStable(previous, current);
  const stableBefore = older !== undefined && isGravityStable(older, previous);
  if (stableNow && stableBefore) {
    return 'finished';
  }
  if (gravityDrop(previous, current) > 0.01) {
    return 'active';
  }
  return 'conditioning';
};

const isTemperatureOutOfRange = (temperature) =>
  temperature < MIN_ALE_TEMPERATURE || temperature > MAX_ALE_TEMPERATURE;

const describeTemperature = (temperature) => {
  if (!isTemperatureOutOfRange(temperature)) {
    return 'temperature normal';
  }
  return temperature < MIN_ALE_TEMPERATURE ? 'temperature low' : 'temperature high';
};

const formatStatus = (reading, phase) =>
  `Day ${reading.day}: ${phase}, ${describeTemperature(reading.temperature)}`;

function monitor(readings) {
  const parsed = parseAll(readings);
  return parsed.map((reading, index) => {
    const previous = gravityAt(parsed, index - 1);
    const older = gravityAt(parsed, index - 2);
    const phase = determinePhase(reading.gravity, previous, older);
    return formatStatus(reading, phase);
  });
}

const summarizeRun = (readings) => {
  const parsed = parseAll(readings);
  const alerts = parsed.filter((r) => isTemperatureOutOfRange(r.temperature)).length;
  const first = gravityAt(parsed, 0);
  const last = gravityAt(parsed, parsed.length - 1);
  const drop = parsed.length > 1 ? gravityDrop(first, last) : 0;
  return `${parsed.length} days logged, total drop ${drop.toFixed(3)}, ${alerts} temperature alert(s)`;
};

const log = [
  'Day 1, 20, 1.060',
  'Day 2, 21, 1.040',
  'Day 3, 20, 1.050',
  'Day 4, 24, 1.014',
  'Day 5, 19, 1.012',
  'Day 6, 17, 1.012',
  'Day 7, 20, 1.012',
];

monitor(log).forEach((line) => console.log(line));
console.log(summarizeRun(log));

module.exports = { monitor, summarizeRun, parseReading, determinePhase };

