const WINDOW_MINUTES = 240;

const PRIORITY_RANKS = { high: 0, medium: 1, low: 2 };

const normalizePriority = (raw) => String(raw).trim().toLowerCase();

const rankPriority = (priority) => {
  const rank = PRIORITY_RANKS[priority];
  if (rank === undefined) {
    throw new Error(`Unknown priority level: "${priority}"`);
  }
  return rank;
};

const parseDurationMinutes = (raw) => {
  const minutes = Number(String(raw).trim());
  if (!Number.isInteger(minutes) || minutes <= 0) {
    throw new Error(`Invalid duration: "${raw}"`);
  }
  return minutes;
};

const parseTargetSpec = (spec) => {
  const parts = String(spec).split(',').map((part) => part.trim());
  if (parts.length !== 3) {
    throw new Error(`Malformed target entry: "${spec}"`);
  }
  const [name, rawDuration, rawPriority] = parts;
  if (name.length === 0) {
    throw new Error(`Missing target name in: "${spec}"`);
  }
  const priority = normalizePriority(rawPriority);
  return {
    name,
    duration: parseDurationMinutes(rawDuration),
    rank: rankPriority(priority)
  };
};

