const normalizeName = (raw) => raw.replace(/\s+/g, ' ').trim();

const isNumericValue = (text) => /^-?\d+(\.\d+)?$/.test(text);

const parseNumericField = (text, label, liftName) => {
  if (!isNumericValue(text)) {
    throw new Error(`Invalid ${label} for ${liftName}: "${text}"`);
  }
  return Number(text);
};

const parseReport = (report) => {
  const fields = splitFields(report);
  if (fields.length !== 3) {
    throw new Error(`Malformed report: "${report}"`);
  }
  const name = normalizeName(fields[0]);
  if (name === '') {
    throw new Error(`Missing lift name in report: "${report}"`);
  }
  return {
    name,
    wind: parseNumericField(fields[1], 'wind speed', name),
    snow: parseNumericField(fields[2], 'snowfall', name),
  };
};

const exceedsWindLimit = (wind) => wind > 60;

const needsAvalancheHold = (snow) => snow > 50;

const isReducedWindRange = (wind) => wind >= 40 && wind <= 60;

const classifyLift = ({ wind, snow }) => {
  if (exceedsWindLimit(wind)) {
    return 'closed';
  }
  if (needsAvalancheHold(snow)) {
    return 'avalanche hold';
  }
  if (isReducedWindRange(wind)) {
    return 'reduced speed';
  }
  return 'fully open';
};

const formatStatus = (name, condition) => `${name}: ${condition}`;

function status(reports) {
  return reports.map((report) => {
    const telemetry = parseReport(report);
    const condition = classifyLift(telemetry);
    return formatStatus(telemetry.name, condition);
  });
}

