const parseLogEntry = (log) => {
  const match = /^\s*Day\s*(\d+)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/i.exec(String(log));
  if (!match) {
    throw new Error(`Unrecognised log entry: "${log}"`);
  }
  const day = Number(match[1]);
  const distance = Number(match[2]);
  if (distance < 0) {
    throw new Error(`Negative distance in entry: "${log}"`);
  }
  return { day, distance };
};

const roundToOneDecimal = (value) => Math.round(value * 10) / 10;

const sortEntriesByDay = (entries) => [...entries].sort((a, b) => a.day - b.day);

const computeRollingAverage = (entries, index) => {
  const window = entries.slice(Math.max(0, index - 2), index + 1);
  const sum = window.reduce((acc, entry) => acc + entry.distance, 0);
  return roundToOneDecimal(sum / window.length);
};

const isRestingDay = (distance, rollingAverage) => distance < 20 && rollingAverage < 50;

const formatRestLine = (stop) =>
  `Day ${stop.day} flagged as rest (${stop.distance} km, 3-day avg ${stop.rollingAverage} km).`;

const buildSummary = (totalDistance, restStops) => {
  const lines = [`Total distance travelled: ${totalDistance} km`];
  if (restStops.length === 0) {
    lines.push('No resting stops identified.');
    return lines;
  }
  const days = restStops.map((stop) => stop.day);
  lines.push(`Resting stops on days: ${days.join(', ')}`);
  restStops.forEach((stop) => {
    lines.push(formatRestLine(stop));
  });
  return lines;
};

function track(logs) {
  if (!Array.isArray(logs)) {
    throw new TypeError('track expects an array of log strings');
  }
  const parsed = logs.map((log) => parseLogEntry(log));
  const entries = sortEntriesByDay(parsed);
  const restStops = [];
  let total = 0;
  entries.forEach((entry, index) => {
    total += entry.distance;
    const rollingAverage = computeRollingAverage(entries, index);
    if (isRestingDay(entry.distance, rollingAverage)) {
      restStops.push({ day: entry.day, distance: entry.distance, rollingAverage });
    }
  });
  const totalDistance = roundToOneDecimal(total);
  const summary = buildSummary(totalDistance, restStops);
  return { totalDistance, restStops, summary };
}

const printReport = (logs) => {
  const report = track(logs);
  report.summary.forEach((line) => console.log(line));
  return report;
};

printReport([
  'Day 1, 120',
  'Day 2, 85',
  'Day 3, 15',
  'Day 4, 18',
  'Day 5, 12',
  'Day 6, 95',
]);

module.exports = {
  track,
  parseLogEntry,
  computeRollingAverage,
  isRestingDay,
  buildSummary,
  printReport,
};

