const normalizePriority = (raw) => {
  const token = String(raw).trim().toLowerCase();
  if (token.startsWith('express')) return 'express';
  if (token.startsWith('standard')) return 'standard';
  throw new Error(`Unknown priority: ${raw}`);
};

const extractHouseNumber = (raw) => {
  const match = String(raw).match(/-?\d+/);
  if (!match) throw new Error(`No house number found in: ${raw}`);
  const number = Number(match[0]);
  if (number < 0) throw new Error(`House number must not be negative: ${raw}`);
  return number;
};

const parsePackage = (entry) => {
  const parts = String(entry).split(',');
  if (parts.length < 2) throw new Error(`Malformed package entry: ${entry}`);
  const house = extractHouseNumber(parts[0]);
  const priority = normalizePriority(parts.slice(1).join(','));
  return { house, priority };
};

const priorityRank = (priority) => (priority === 'express' ? 0 : 1);

const comparePackages = (left, right) => {
  const leftRank = priorityRank(left.priority);
  const rightRank = priorityRank(right.priority);
  if (leftRank !== rightRank) return leftRank - rightRank;
  return left.house - right.house;
};

const computeTotalDistance = (route) => {
  let position = 0;
  let distance = 0;
  for (const stop of route) {
    distance += Math.abs(stop.house - position) * 10;
    position = stop.house;
  }
  return distance;
};

const formatDeliveryLine = (stop, index) =>
  `${index + 1}. House ${stop.house}, ${stop.priority}`;

const sequence = (packages) => {
  if (!Array.isArray(packages)) throw new Error('packages must be an array');
  const parsed = packages.map(parsePackage);
  const sorted = parsed.sort(comparePackages);
  const totalDistance = computeTotalDistance(sorted);
  return {
    deliveries: sorted,
    totalDistance,
    lines: sorted.map(formatDeliveryLine),
  };
};

const buildReport = (packages) => {
  const result = sequence(packages);
  const body = result.lines.join('\n');
  return `${body}\nDistance: ${result.totalDistance} meters`;
};

const main = () => {
  const args = process.argv.slice(2);
  const entries = args.length > 0 ? args : [
    'House 30, standard',
    'House 12, express',
    'House 4, standard',
    'House 25, express',
  ];
  console.log(buildReport(entries));
};

if (require.main === module) main();

module.exports = {
  sequence,
  buildReport,
  parsePackage,
  computeTotalDistance,
};

