const normalizeCode = (code) => String(code).trim().toUpperCase();

const isCriticalCode = (code) => /^C\d+$/.test(code);

const isMinorCode = (code) => /^M\d+$/.test(code);

const pointsForCode = (code) => (isCriticalCode(code) ? 5 : 1);

const countCriticalViolations = (codes) => codes.filter(isCriticalCode).length;

const calculatePenaltyPoints = (codes) =>
  codes.reduce((total, code) => total + pointsForCode(code), 0);

const requiresClosure = (criticalCount, points) => criticalCount > 3 || points > 20;

function parseRecord(record) {
  if (!Array.isArray(record) || record.length !== 3) {
    throw new TypeError('Each inspection must be [name, codes, daysSinceLastInspection]');
  }
  const [name, rawCodes, days] = record;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('Restaurant name must be a non-empty string');
  }
  if (!Array.isArray(rawCodes)) {
    throw new TypeError(`Violation codes for ${name} must be a list`);
  }
  if (!Number.isFinite(days) || days < 0) {
    throw new RangeError(`Days since last inspection for ${name} must be >= 0`);
  }
  const codes = rawCodes.map(normalizeCode);
  const unknown = codes.find((code) => !isCriticalCode(code) && !isMinorCode(code));
  if (unknown !== undefined) {
    throw new RangeError(`Unrecognised violation code "${unknown}" for ${name}`);
  }
  return { name: name.trim(), codes, days };
}

function inspectRestaurant(record) {
  const { name, codes, days } = parseRecord(record);
  const criticalCount = countCriticalViolations(codes);
  const points = calculatePenaltyPoints(codes);
  return { name, days, points, closed: requiresClosure(criticalCount, points) };
}

const buildSentence = (result) => {
  const verdict = result.closed
    ? 'requires immediate closure'
    : 'passed the inspection';
  return `${result.name} has ${result.points} penalty points and ${verdict}.`;
};

const sortByStaleness = (results) =>
  [...results].sort((a, b) => b.days - a.days || a.name.localeCompare(b.name));

function evaluate(inspections) {
  if (!Array.isArray(inspections)) {
    throw new TypeError('inspections must be a list of records');
  }
  const results = inspections.map(inspectRestaurant);
  return sortByStaleness(results).map(buildSentence);
}

const sampleInspections = [
  ['Blue Fork Diner', ['C12', 'M03', 'M07'], 45],
  ['Riverside Grill', ['C01', 'C02', 'C03', 'C04'], 210],
  ['Corner Bakery', [], 12],
  ['Spice Alley', ['C05', 'C06', 'M01', 'M02', 'M04', 'M08'], 98]
];

for (const sentence of evaluate(sampleInspections)) {
  console.log(sentence);
}

module.exports = { evaluate, inspectRestaurant, calculatePenaltyPoints, requiresClosure };

