  const homeScoreAt = tokens.findIndex(isNumberWord);
  const awayScoreAt = tokens.findIndex((token, index) => index > homeScoreAt && isNumberWord(token));
  if (homeScoreAt < 1 || awayScoreAt < 0) {
    throw new Error(`cannot parse match result: "${text}"`);
  }
  const homeWords = tokens.slice(0, homeScoreAt);
  const awayWords = tokens.slice(homeScoreAt + 1, awayScoreAt);
  if (awayWords.length === 0) {
