const isSilentLevel = (level) => level === 0;

const isValidLevel = (level) => Number.isFinite(level) && level >= 0;

function validateAudioInput(audio) {
  if (!Array.isArray(audio)) {
    throw new TypeError('trim() expects an array of volume levels');
  }
  const badIndex = audio.findIndex((level) => !isValidLevel(level));
  if (badIndex !== -1) {
    throw new RangeError(`invalid volume level at second ${badIndex}: ${audio[badIndex]}`);
  }
  return audio;
}

function findSilenceBlocks(audio) {
  const blocks = [];
  let start = -1;
  audio.forEach((level, index) => {
    if (isSilentLevel(level)) {
      if (start === -1) start = index;
      return;
    }
    if (start !== -1) {
      blocks.push({ start, length: index - start });
      start = -1;
    }
  });
  if (start !== -1) {
    blocks.push({ start, length: audio.length - start });
  }
  return blocks;
}

const isRemovableBlock = (block) => block.length > 3;

const computeRemovableSeconds = (block) => block.length - 2;

function sumRemovableSeconds(blocks) {
  return blocks.reduce((total, block) => total + computeRemovableSeconds(block), 0);
}

function formatClockDuration(seconds) {
  const minutes = Math.floor(seconds / 60);
  const rest = seconds % 60;
  return `${minutes}m ${String(rest).padStart(2, '0')}s`;
}

function buildSummarySentence(original, trimmed, removed) {
  const originalText = formatClockDuration(original);
  const trimmedText = formatClockDuration(trimmed);
  return `Original duration: ${originalText}; new duration: ${trimmedText}; ` +
    `${removed} second${removed === 1 ? '' : 's'} removed.`;
}

function trim(audio) {
  const levels = validateAudioInput(audio);
  const blocks = findSilenceBlocks(levels);
  const silences = blocks.filter(isRemovableBlock);
  const removed = sumRemovableSeconds(silences);
  const original = levels.length;
  return buildSummarySentence(original, original - removed, removed);
}

function parseLevelList(text) {
  return text
    .split(/[\s,]+/)
    .filter((token) => token.length > 0)
    .map(Number);
}

function runCommandLine(argv) {
  const levels = parseLevelList(argv.join(' '));
  return trim(levels);
}

if (require.main === module) {
  console.log(runCommandLine(process.argv.slice(2)));
}

module.exports = {
  trim,
  findSilenceBlocks,
  computeRemovableSeconds,
  sumRemovableSeconds,
  formatClockDuration,
  buildSummarySentence,
  validateAudioInput,
  parseLevelList,
  runCommandLine,
};

