const MAX_CAPACITY = 2000;

const parsePalletItem = (entry) => {
  const [id, weight, category] = entry;
  return { id: String(id), weight: Number(weight), category: String(category).trim().toLowerCase() };
};

const isKnownCategory = (category) => category === 'fragile' || category === 'sturdy';

const describeBadEntry = (entry, reason) => `invalid pallet entry ${JSON.stringify(entry)}: ${reason}`;

function assertValidItem(item, entry) {
  if (!item.id) {
    throw new Error(describeBadEntry(entry, 'missing identifier'));
  }
  if (!Number.isFinite(item.weight) || item.weight < 0) {
    throw new Error(describeBadEntry(entry, 'weight must be a non-negative number'));
  }
  if (!isKnownCategory(item.category)) {
    throw new Error(describeBadEntry(entry, 'category must be fragile or sturdy'));
  }
}

const crushesFragileBelow = (item, fragileSeen) => fragileSeen && item.category === 'sturdy';

const exceedsCapacity = (loadSoFar, item) => loadSoFar + item.weight > MAX_CAPACITY;

function validate(pallets) {
  const accepted = [];
  let totalWeight = 0;
  let fragileSeen = false;
  for (const entry of pallets) {
    const item = parsePalletItem(entry);
    assertValidItem(item, entry);
    if (crushesFragileBelow(item, fragileSeen)) {
      break;
    }
    if (exceedsCapacity(totalWeight, item)) {
      break;
    }
    totalWeight += item.weight;
    fragileSeen = fragileSeen || item.category === 'fragile';
    accepted.push(item.id);
  }
  return accepted;
}

const totalAcceptedWeight = (pallets, accepted) =>
  pallets
    .map(parsePalletItem)
    .filter((item) => accepted.includes(item.id))
    .reduce((sum, item) => sum + item.weight, 0);

function formatReport(label, pallets) {
  const accepted = validate(pallets);
  const load = totalAcceptedWeight(pallets, accepted);
  const status = accepted.length === pallets.length ? 'stack valid' : 'stack truncated';
  return `${label}: ${status} -> [${accepted.join(', ')}] at ${load} kg`;
}

const goodStack = [
  ['crate-a', 600, 'sturdy'],
  ['crate-b', 500, 'sturdy'],
  ['glass-c', 300, 'fragile'],
  ['glass-d', 200, 'fragile'],
];

const badOrderStack = [
  ['drum-a', 400, 'sturdy'],
  ['vase-b', 150, 'fragile'],
  ['drum-c', 700, 'sturdy'],
];

const overweightStack = [
  ['steel-a', 900, 'sturdy'],
  ['steel-b', 900, 'sturdy'],
  ['steel-c', 400, 'sturdy'],
];

console.log(formatReport('good stack', goodStack));
console.log(formatReport('bad order', badOrderStack));
console.log(formatReport('overweight', overweightStack));

module.exports = { validate, formatReport, MAX_CAPACITY };

