const STANDARD_FEATURES = new Set(['export-csv', 'basic-report', 'search']);
const PREMIUM_FEATURES = new Set(['ai-summary', 'bulk-import', 'custom-dashboard']);
const STARTING_TOKENS = 10;

function isPremiumFeature(feature) {
  return PREMIUM_FEATURES.has(feature);
}

function isStandardFeature(feature) {
  return STANDARD_FEATURES.has(feature);
}

function tokenCostFor(feature) {
  return isPremiumFeature(feature) ? 3 : 1;
}

function tierAllowsFeature(tier, feature) {
  if (isPremiumFeature(feature)) {
    return tier === 'premium';
  }
  return isStandardFeature(feature);
}

const normalizeRequest = (request) => {
  const [user, tier, feature] = request;
  return {
    user: String(user).trim(),
    tier: String(tier).trim().toLowerCase(),
    feature: String(feature).trim().toLowerCase(),
  };
};

const ensureUserQuota = (quotas, user) => {
  if (!Object.prototype.hasOwnProperty.call(quotas, user)) {
    quotas[user] = STARTING_TOKENS;
  }
  return quotas[user];
};

const hasEnoughTokens = (remaining, cost) => remaining >= cost;

const deductTokens = (quotas, user, cost) => {
  quotas[user] -= cost;
};

function access(requests) {
  const quotas = {};
  const results = [];
  for (const raw of requests) {
    const req = normalizeRequest(raw);
    if (!tierAllowsFeature(req.tier, req.feature)) {
      results.push(false);
      continue;
    }
    const cost = tokenCostFor(req.feature);
    const remaining = ensureUserQuota(quotas, req.user);
    if (!hasEnoughTokens(remaining, cost)) {
      results.push(false);
      continue;
    }
    deductTokens(quotas, req.user, cost);
    results.push(true);
  }
  return results;
}

const formatDecisionLine = (request, granted) => {
  const req = normalizeRequest(request);
  const verdict = granted ? 'GRANTED' : 'DENIED';
  return `${req.user} [${req.tier}] ${req.feature} -> ${verdict}`;
};

const summarizeGrants = (results) => {
  const granted = results.filter(Boolean).length;
  return `${granted}/${results.length} requests granted`;
};

const sample = [
  ['ana', 'premium', 'ai-summary'],
  ['ana', 'premium', 'bulk-import'],
  ['ana', 'premium', 'custom-dashboard'],
  ['ana', 'premium', 'ai-summary'],
  ['bob', 'basic', 'ai-summary'],
  ['bob', 'basic', 'search'],
  ['bob', 'BASIC', ' export-csv '],
  ['cleo', 'basic', 'time-travel'],
];

const decisions = access(sample);
sample.forEach((request, index) => {
  console.log(formatDecisionLine(request, decisions[index]));
});
console.log(summarizeGrants(decisions));

module.exports = { access, tokenCostFor, tierAllowsFeature, summarizeGrants };

