const BRIGHTNESS_THRESHOLD = 3;

const isValidStar = (star) =>
  Array.isArray(star) && star.length === 3 && star.every((value) => Number.isFinite(value));

const isBrightEnough = (star) => star[2] >= BRIGHTNESS_THRESHOLD;

function filterBrightStars(stars) {
  const bright = [];
  for (const star of stars) {
    if (!isValidStar(star)) {
      throw new TypeError(`Malformed star record: ${JSON.stringify(star)}`);
    }
    if (isBrightEnough(star)) {
      bright.push(star);
    }
  }
  return bright;
}

const euclideanDistance = (a, b) => {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  return Math.sqrt(dx * dx + dy * dy);
};

function findMaxPairDistance(stars) {
  let widest = 0;
  for (let i = 0; i < stars.length - 1; i += 1) {
    for (let j = i + 1; j < stars.length; j += 1) {
      const span = euclideanDistance(stars[i], stars[j]);
      if (span > widest) {
        widest = span;
      }
    }
  }
  return widest;
}

function identify(stars) {
  const bright = filterBrightStars(stars);
  return [bright.length, findMaxPairDistance(bright)];
}

const roundToTenths = (value) => Math.round(value * 10) / 10;

const describeBrightest = (stars) => {
  const bright = filterBrightStars(stars);
  if (bright.length === 0) {
    return "no bright stars";
  }
  const leader = bright.reduce((best, star) => (star[2] > best[2] ? star : best));
  return `magnitude ${roundToTenths(leader[2])} at (${leader[0]}, ${leader[1]})`;
};

function formatSegmentReport(name, stars) {
  const [count, spread] = identify(stars);
  const headline = `${name}: ${count} bright star(s), max separation ${roundToTenths(spread)}`;
  return `${headline} — brightest ${describeBrightest(stars)}`;
