const isNumericDigit = (character) => character >= '0' && character <= '9';

const trimField = (field) => field.trim();

function extractSurname(scan) {
  return trimField(scan.slice(0, 10)).toLowerCase();
}

function extractFlightNumber(scan) {
  return trimField(scan.slice(10, 16));
}

function extractSignature(scan) {
  return trimField(scan.slice(16));
}

function countNumericDigits(text) {
  let total = 0;
  for (const character of text) {
    if (isNumericDigit(character)) {
      total += 1;
    }
  }
  return total;
}

function hasValidSignature(scan) {
  const signature = extractSignature(scan);
  return countNumericDigits(signature) === 2;
}

const digitToWord = (digit) => DIGIT_WORDS[Number(digit)];

function spellFlightNumber(flight) {
  const digits = [];
  for (const character of flight) {
    if (isNumericDigit(character)) {
      digits.push(digitToWord(character));
    }
  }
  return digits.join(' ');
}

