const MAX_CONTAMINATION = 15;

const getMaterialCategory = (barcode) => {
  const leadingDigit = String(barcode).trim().charAt(0);
  if (leadingDigit === '1') return 'plastic';
  if (leadingDigit === '2') return 'glass';
  if (leadingDigit === '3') return 'paper';
  return null;
};

const isTooContaminated = (contamination) => Number(contamination) > MAX_CONTAMINATION;

const hasValidShape = (item) => Array.isArray(item) && item.length === 3;

const isScannableItem = (item) => {
  if (!hasValidShape(item)) return false;
  const [barcode, contamination, weight] = item;
  if (getMaterialCategory(barcode) === null) return false;
  return Number.isFinite(Number(contamination)) && Number.isFinite(Number(weight));
};

const buildBins = () => ({ plastic: [], glass: [], paper: [] });

function sort(items) {
  const bins = buildBins();
  for (const item of items) {
    if (!isScannableItem(item)) continue;
    const [barcode, contamination] = item;
    if (isTooContaminated(contamination)) continue;
    bins[getMaterialCategory(barcode)].push(item);
  }
  return [bins.plastic, bins.glass, bins.paper];
}

const totalWeightOf = (bin) => bin.reduce((sum, [, , weight]) => sum + Number(weight), 0);

const countRejected = (items, sorted) => {
  const accepted = sorted.reduce((sum, bin) => sum + bin.length, 0);
  return items.length - accepted;
};

const describeBin = (label, bin) =>
  `${label}: ${bin.length} item(s), ${totalWeightOf(bin).toFixed(2)} kg`;

const formatReport = (items, sorted) => {
  const [plastic, glass, paper] = sorted;
  const lines = [
    describeBin('Plastic', plastic),
    describeBin('Glass', glass),
    describeBin('Paper', paper),
    `Rejected: ${countRejected(items, sorted)} item(s)`
  ];
  return lines.join('\n');
};

function main() {
  const scanned = [
    ['10045', 3, 0.25],
    ['10992', 22.5, 0.4],
    ['20871', 0, 1.1],
    ['21133', 15, 0.75],
    ['30004', 8.2, 2.0],
    ['39999', 60, 1.5],
    ['48821', 1, 0.9],
    ['3001', 'n/a', 0.3]
  ];
  const sorted = sort(scanned);
  console.log(formatReport(scanned, sorted));
}

main();

module.exports = { sort, getMaterialCategory, isTooContaminated, formatReport };

