const GRAVITATIONAL_CONSTANT = 6.674e-11;
const EARTH_MASS_KG = 5.972e24;
const EARTH_RADIUS_M = 6.371e6;

const isPositiveNumber = (value) =>
  typeof value === 'number' && Number.isFinite(value) && value > 0;

function parsePlanetRecord(record) {
  if (!Array.isArray(record) || record.length < 3) {
    throw new TypeError('Each planet must be [name, relativeMass, relativeRadius]');
  }
  const [name, relativeMass, relativeRadius] = record;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('Planet name must be a non-empty string');
  }
  if (!isPositiveNumber(relativeMass)) {
    throw new RangeError(`Invalid mass for ${name}`);
  }
  if (!isPositiveNumber(relativeRadius)) {
    throw new RangeError(`Invalid radius for ${name}`);
  }
  return { name: name.trim(), relativeMass, relativeRadius };
}

const toAbsoluteMass = (relativeMass) => relativeMass * EARTH_MASS_KG;

const toAbsoluteRadius = (relativeRadius) => relativeRadius * EARTH_RADIUS_M;

function computeGravitationalParameter(relativeMass) {
  return GRAVITATIONAL_CONSTANT * toAbsoluteMass(relativeMass);
}

function computeEscapeVelocity(relativeMass, relativeRadius) {
  const mu = computeGravitationalParameter(relativeMass);
  return Math.sqrt((2 * mu) / toAbsoluteRadius(relativeRadius));
}

const roundToTwoDecimals = (value) => Math.round(value * 100) / 100;

function formatEscapeSentence(name, velocity) {
  return `The escape velocity of ${name} is ${roundToTwoDecimals(velocity).toFixed(2)} m/s.`;
}

function compute(planets) {
  if (!Array.isArray(planets)) {
    throw new TypeError('planets must be an array');
  }
  return planets.map((record) => {
    const planet = parsePlanetRecord(record);
    const velocity = computeEscapeVelocity(planet.relativeMass, planet.relativeRadius);
    return formatEscapeSentence(planet.name, velocity);
  });
}

function describeHeaviest(planets) {
  const parsed = planets.map(parsePlanetRecord);
  const heaviest = parsed.reduce((best, planet) =>
    planet.relativeMass > best.relativeMass ? planet : best
  );
  const mu = computeGravitationalParameter(heaviest.relativeMass);
  return `${heaviest.name} is the most massive, with mu = ${mu.toExponential(3)} m^3/s^2.`;
}

const discoveries = [
  ['Kepler-22b', 6.36, 2.38],
  ['Gliese 581g', 3.1, 1.5],
  ['Proxima b', 1.27, 1.08],
  ['TRAPPIST-1e', 0.62, 0.92],
];

compute(discoveries).forEach((sentence) => console.log(sentence));
console.log(describeHeaviest(discoveries));

module.exports = { compute, computeEscapeVelocity, computeGravitationalParameter, describeHeaviest };

