const PENALTY_TABLE = {
  'tab switched': 3,
  'out of frame': 2,
};

const PENALTY_LIMIT = 10;

const normalizeAction = (raw) =>
  String(raw).trim().toLowerCase().replace(/[_-]+/g, ' ').replace(/\s+/g, ' ');

const penaltyForAction = (action) => {
  const key = normalizeAction(action);
  return PENALTY_TABLE[key] ?? 0;
};

const isValidEvent = (event) => {
  if (!Array.isArray(event) || event.length < 3) return false;
  const [timestamp, name, action] = event;
  if (typeof timestamp !== 'number' || !Number.isFinite(timestamp)) return false;
  if (typeof name !== 'string' || name.trim() === '') return false;
  return typeof action === 'string' && action.trim() !== '';
};

const sortChronologically = (events) =>
  events.filter(isValidEvent).slice().sort((a, b) => a[0] - b[0]);

const accumulatePenalties = (events) => {
  const tally = new Map();
  for (const [, name, action] of sortChronologically(events)) {
    const points = penaltyForAction(action);
    if (points === 0) continue;
    const student = name.trim();
    tally.set(student, (tally.get(student) ?? 0) + points);
  }
  return tally;
};

const hasExceededLimit = (points) => points > PENALTY_LIMIT;

const collectFlagged = (tally) => {
  const flagged = [];
  for (const [student, points] of tally) {
    if (hasExceededLimit(points)) flagged.push(student);
  }
  return flagged;
};

function monitor(events) {
  const tally = accumulatePenalties(events ?? []);
  return collectFlagged(tally);
}

const describeStudent = (student, points) =>
  `${student}: ${points} pts${hasExceededLimit(points) ? ' -> FLAGGED' : ''}`;

const formatSummary = (events) => {
  const tally = accumulatePenalties(events);
  const lines = [...tally.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([student, points]) => describeStudent(student, points));
  return lines.join('\n');
};

const sessionLog = [
  [12, 'Ana', 'tab switched'],
  [30, 'Ben', 'out of frame'],
  [45, 'Ana', 'out of frame'],
  [61, 'Ana', 'tab_switched'],
  [78, 'Ben', 'question answered'],
  [90, 'Ana', 'TAB SWITCHED'],
  [104, 'Cleo', 'out of frame'],
  [119, 'Ana', 'out of frame'],
  [133, 'Ben', 'out of frame'],
];

console.log(formatSummary(sessionLog));
console.log('Flagged for review:', monitor(sessionLog).join(', ') || '(none)');

module.exports = {
  monitor,
  penaltyForAction,
  accumulatePenalties,
  formatSummary,
};

