const normalizeRockType = (rockType) => String(rockType).trim().toLowerCase();

const isTopsoilLayer = (layer) => {
  const kind = normalizeRockType(layer.rockType);
  return kind === 'topsoil';
};

const parseDepth = (value, index) => {
  const depth = Number(value);
  if (!Number.isFinite(depth)) {
    throw new TypeError(`Layer ${index} has non-numeric depths.`);
  }
  return depth;
};

const validateLayer = (layer, index) => {
  const isTriple = Array.isArray(layer) && layer.length >= 3;
  if (!isTriple) {
    throw new TypeError(`Layer ${index} must be [rockType, startDepth, endDepth].`);
  }
  const kind = normalizeRockType(layer[0]);
  if (kind.length === 0) {
    throw new TypeError(`Layer ${index} is missing a rock type.`);
  }
  const start = parseDepth(layer[1], index);
  const end = parseDepth(layer[2], index);
  return { rockType: String(layer[0]).trim(), start, end };
};

const computeThickness = (layer) => {
  const span = layer.end - layer.start;
  return Math.abs(span);
};

const toMeasuredLayer = (layer) => {
  const thickness = computeThickness(layer);
  return { rockType: layer.rockType, thickness };
};

const dropLeadingTopsoil = (layers) => {
  const [first] = layers;
  if (first && isTopsoilLayer(first)) {
    return layers.slice(1);
  }
  return layers;
};

const findThickestLayer = (measured) => {
  return measured.reduce((best, current) => (current.thickness > best.thickness ? current : best));
};

const formatThickness = (thickness) => {
  const rounded = Number(thickness.toFixed(3));
  return String(rounded);
};

const describeThickest = (layer) => {
  const thickness = formatThickness(layer.thickness);
  return `The thickest layer is ${layer.rockType}, measuring ${thickness} meters.`;
};

const describeLayerLine = (entry) => {
  const thickness = formatThickness(entry.thickness);
  return `${entry.rockType}: ${thickness} m`;
};

const measure = (layers) => {
  if (!Array.isArray(layers)) {
    throw new TypeError('layers must be an array of [rockType, startDepth, endDepth].');
  }
