const VALID_STYLES = ['aggressive', 'smooth'];

const normalizeStyle = (style) => String(style).trim().toLowerCase();

const isKnownStyle = (style) => VALID_STYLES.includes(style);

const parseWeight = (weight) => {
  const pounds = Number(weight);
  if (!Number.isFinite(pounds) || pounds <= 0) {
    throw new RangeError(`invalid body weight: ${weight}`);
  }
  return pounds;
};

const validateRider = (rider) => {
  if (!Array.isArray(rider) || rider.length < 3) {
    throw new TypeError('each rider needs a name, a weight and a riding style');
  }
  const [name, weight, style] = rider;
  const cleanStyle = normalizeStyle(style);
  if (!isKnownStyle(cleanStyle)) {
    throw new RangeError(`unsupported riding style: ${style}`);
  }
  return {
    name: String(name).trim(),
    pounds: parseWeight(weight),
    style: cleanStyle,
  };
};

const calculateAirPressure = (pounds) => pounds / 2;

const baseReboundClicks = (pounds) => Math.round(pounds / 25);

const styleAdjustment = (style) => (style === 'aggressive' ? 2 : -1);

const calculateReboundClicks = (pounds, style) => {
  const base = baseReboundClicks(pounds);
  const clicks = base + styleAdjustment(style);
  return Math.max(clicks, 0);
};

const formatPressure = (psi) => {
  const rounded = Math.round(psi * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
};

const buildSentence = (setup) => {
  const pressure = formatPressure(setup.psi);
  const clickWord = setup.clicks === 1 ? 'click' : 'clicks';
  return `${setup.name}: set the shock to ${pressure} psi with ${setup.clicks} rebound ${clickWord}.`;
};

const buildSetup = (rider) => {
  const { name, pounds, style } = validateRider(rider);
  return {
    name,
    psi: calculateAirPressure(pounds),
    clicks: calculateReboundClicks(pounds, style),
  };
};

function tune(riders) {
  if (!Array.isArray(riders)) {
    throw new TypeError('riders must be a list');
  }
  const setups = riders.map(buildSetup);
  return setups.map(buildSentence);
}

function main() {
  const riders = [
    ['Dana', 150, 'aggressive'],
    ['Miguel', 205, 'smooth'],
    ['Ines', 128, 'Smooth'],
    ['Ravi', 175, 'AGGRESSIVE'],
  ];
  tune(riders).forEach((line) => console.log(line));
}

main();

module.exports = { tune, calculateAirPressure, calculateReboundClicks };

