const OBSTACLE_AREA = 20;
const PANEL_AREA = 15;
const PANEL_OUTPUT_KWH = 1.5;

const parseRoofSpec = (roof) => {
  if (!Array.isArray(roof) || roof.length < 3) {
    throw new TypeError(`Each roof needs [footage, chimneys, shade]: got ${JSON.stringify(roof)}`);
  }
  const [footage, chimneys, shade] = roof.map(Number);
  if ([footage, chimneys, shade].some((value) => !Number.isFinite(value))) {
    throw new TypeError(`Roof values must be numeric: ${JSON.stringify(roof)}`);
  }
  return { footage, chimneys, shade };
};

const clampPercentage = (shade) => Math.min(100, Math.max(0, shade));

const usableRoofArea = (footage, chimneys) => {
  const blocked = Math.max(0, chimneys) * OBSTACLE_AREA;
  return Math.max(0, footage - blocked);
};

const countPanelsThatFit = (area) => Math.floor(area / PANEL_AREA);

const applyShadeFactor = (rawOutput, shade) => {
  const efficiency = (100 - clampPercentage(shade)) / 100;
  return rawOutput * efficiency;
};

const roundToTwo = (value) => Math.round(value * 100) / 100;

const panelCountFor = (roof) => {
  const { footage, chimneys, shade } = parseRoofSpec(roof);
  const area = usableRoofArea(footage, chimneys);
  return { panels: countPanelsThatFit(area), shade };
};

const expectedOutputFor = (roof) => {
  const { panels, shade } = panelCountFor(roof);
  const shaded = applyShadeFactor(panels * PANEL_OUTPUT_KWH, shade);
  return roundToTwo(shaded);
};

function optimize(roofs) {
  if (!Array.isArray(roofs)) {
    throw new TypeError('optimize expects a list of roofs');
  }
  return roofs.map(expectedOutputFor);
}

const describeRoof = (roof, index) => {
  const { footage, chimneys, shade } = parseRoofSpec(roof);
  const { panels } = panelCountFor(roof);
  const label = `Roof ${index + 1}`.padEnd(8);
  return `${label} ${footage} sqft, ${chimneys} chimney(s), ${shade}% shade -> ${panels} panels`;
};

const buildReport = (roofs) => {
  const outputs = optimize(roofs);
  const lines = roofs.map((roof, index) => `${describeRoof(roof, index)}, ${outputs[index]} kWh`);
  const total = outputs.reduce((sum, kwh) => sum + kwh, 0);
  lines.push(`Neighborhood total: ${roundToTwo(total)} kWh`);
  return lines.join('\n');
};

const neighborhood = [
  [1200, 2, 10],
  [800, 0, 25],
  [450, 3, 0],
  [100, 5, 50],
  [2000, 1, 100],
];

console.log(buildReport(neighborhood));

module.exports = { optimize, buildReport, usableRoofArea, countPanelsThatFit, applyShadeFactor };

