'use strict';

const isFinitePair = (point) =>
  Array.isArray(point) && point.length >= 2 &&
  Number.isFinite(point[0]) && Number.isFinite(point[1]);

const validateStroke = (stroke, index) => {
  if (!Array.isArray(stroke) || stroke.length === 0) {
    throw new TypeError(`stroke ${index} must be a non-empty array of points`);
  }
  const bad = stroke.findIndex((point) => !isFinitePair(point));
  if (bad !== -1) {
    throw new TypeError(`stroke ${index}, point ${bad} is not a numeric pair`);
  }
  return stroke;
};

const computeBoundingBox = (stroke) => {
  const box = { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity };
  for (const [x, y] of stroke) {
    box.minX = Math.min(box.minX, x);
    box.maxX = Math.max(box.maxX, x);
    box.minY = Math.min(box.minY, y);
    box.maxY = Math.max(box.maxY, y);
  }
  return box;
};

const boxDimensions = (box) => ({
  width: box.maxX - box.minX,
  height: box.maxY - box.minY,
});

const classifyDirection = (width, height) => {
  const span = Math.max(width, height);
  if (span === 0) return 'point';
  const shorter = Math.min(width, height);
  if (shorter / span > 0.5) return 'diagonal';
  return width > height ? 'horizontal' : 'vertical';
};

const computePathLength = (stroke) => {
  let total = 0;
  for (let i = 1; i < stroke.length; i += 1) {
    const dx = stroke[i][0] - stroke[i - 1][0];
    const dy = stroke[i][1] - stroke[i - 1][1];
    total += Math.hypot(dx, dy);
  }
  return total;
};

const strokeExtent = (stroke) => {
  const box = computeBoundingBox(stroke);
  return boxDimensions(box);
};

function analyze(strokes) {
  if (!Array.isArray(strokes)) {
    throw new TypeError('strokes must be an array of strokes');
  }
  return strokes.map((stroke, index) => {
    const points = validateStroke(stroke, index);
    const { width, height } = strokeExtent(points);
    return classifyDirection(width, height);
  });
}

const formatStrokeReport = (stroke, label, index) => {
  const { width, height } = strokeExtent(stroke);
  const length = computePathLength(stroke).toFixed(2);
  return `#${index}: ${label} (${width}x${height}, path ${length}, ${stroke.length} pts)`;
};

const sampleStrokes = [
  [[0, 0], [10, 1], [22, 0], [35, 2]],
  [[5, 0], [6, 9], [5, 18], [7, 30]],
  [[0, 0], [8, 7], [16, 15], [24, 22]],
  [[3, 3]],
];

const labels = analyze(sampleStrokes);
sampleStrokes.forEach((stroke, index) => {
  console.log(formatStrokeReport(stroke, labels[index], index));
});

module.exports = { analyze, classifyDirection, computeBoundingBox, computePathLength };

