const AMBIENT_PER_TEN_METERS = 1;
const HULL_SAFETY_FACTOR = 0.8;
const OXYGEN_RESERVE_HOURS = 1;

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

const validateDive = (dive, index) => {
  if (!Array.isArray(dive) || dive.length !== 3) {
    throw new TypeError(`Dive ${index} must be [depth, hullRating, oxygenHours]`);
  }
  const [depth, hullRating, oxygenHours] = dive;
  if (![depth, hullRating, oxygenHours].every(isFiniteNumber)) {
    throw new TypeError(`Dive ${index} contains a non-numeric field`);
  }
  if (depth < 0 || hullRating <= 0 || oxygenHours < 0) {
    throw new RangeError(`Dive ${index} has out-of-range values`);
  }
  return { depth, hullRating, oxygenHours };
};

const ambientPressure = (depth) => 1 + (depth / 10) * AMBIENT_PER_TEN_METERS;

const hullPressureLimit = (hullRating) => hullRating * HULL_SAFETY_FACTOR;

const isHullCompliant = (depth, hullRating) =>
  ambientPressure(depth) <= hullPressureLimit(hullRating);

const safeDiveHours = (oxygenHours) =>
  Math.max(0, oxygenHours - OXYGEN_RESERVE_HOURS);

function check(dives) {
  if (!Array.isArray(dives)) {
    throw new TypeError('dives must be an array of dive descriptors');
  }
  const approved = [];
  dives.forEach((dive, index) => {
    const { depth, hullRating, oxygenHours } = validateDive(dive, index);
    if (isHullCompliant(depth, hullRating)) {
      approved.push(safeDiveHours(oxygenHours));
    }
  });
  return approved;
}

const describeDive = (dive, index) => {
  const { depth, hullRating, oxygenHours } = validateDive(dive, index);
  const pressure = ambientPressure(depth);
  const limit = hullPressureLimit(hullRating);
  const verdict = isHullCompliant(depth, hullRating)
    ? `approved for ${safeDiveHours(oxygenHours)} h`
    : 'rejected: hull margin exceeded';
  return `#${index} ${depth} m | ambient ${pressure.toFixed(1)} atm of ${limit.toFixed(1)} atm | ${verdict}`;
};

const buildMissionReport = (dives) => {
  const lines = dives.map(describeDive);
  const approved = check(dives);
  const totalHours = approved.reduce((sum, hours) => sum + hours, 0);
  lines.push(`Approved dives: ${approved.length}, total safe time: ${totalHours} h`);
  return lines.join('\n');
};

const runMissionLog = () => {
  const missions = [
    [30, 6, 5],
    [100, 12, 8],
    [50, 10, 1],
    [20, 4, 3.5],
  ];
  console.log(buildMissionReport(missions));
  console.log('check() =>', check(missions));
};

runMissionLog();

module.exports = { check, ambientPressure, hullPressureLimit, safeDiveHours, buildMissionReport };

