const MARATHON_MILES = 26;
const HALF_WAY_MILE = 13;
const HILL_ADJUSTMENT_SECONDS = 30;

const isHillyProfile = (profile) => String(profile).toLowerCase() === 'hilly';

const validateRunner = (runner) => {
  if (!Array.isArray(runner) || runner.length < 3) {
    throw new TypeError('Each runner must be [name, targetMinutes, profile]');
  }
  const [name, targetMinutes, profile] = runner;
  const normalized = String(profile).toLowerCase();
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('Runner name must be a non-empty string');
  }
  if (typeof targetMinutes !== 'number' || !(targetMinutes > 0)) {
    throw new RangeError(`Target finish time for ${name} must be a positive number of minutes`);
  }
  if (normalized !== 'flat' && normalized !== 'hilly') {
    throw new RangeError(`Elevation profile for ${name} must be flat or hilly`);
  }
  return { name: name.trim(), targetMinutes, profile: normalized };
};

const computeEvenSplitSeconds = (targetMinutes) => (targetMinutes * 60) / MARATHON_MILES;

const adjustSplitSeconds = (evenSeconds, profile) => {
  const hilly = isHillyProfile(profile);
  const splits = [];
  for (let mile = 1; mile <= MARATHON_MILES; mile += 1) {
    if (!hilly) {
      splits.push(evenSeconds);
    } else if (mile <= HALF_WAY_MILE) {
      splits.push(evenSeconds + HILL_ADJUSTMENT_SECONDS);
    } else {
      splits.push(evenSeconds - HILL_ADJUSTMENT_SECONDS);
    }
  }
  return splits;
};

const formatSplitTime = (totalSeconds) => {
  const rounded = Math.round(totalSeconds);
  const minutes = Math.floor(rounded / 60);
  const seconds = String(rounded % 60).padStart(2, '0');
