};

const buildStrategySentence = (name, firstMileSeconds) =>
  `${name} should run the first mile in ${formatSplitTime(firstMileSeconds)} per mile.`;

const buildRunnerPlan = (runner) => {
  const { name, targetMinutes, profile } = validateRunner(runner);
  const evenSeconds = computeEvenSplitSeconds(targetMinutes);
  return { name, profile, splits: adjustSplitSeconds(evenSeconds, profile) };
};

