  const opening = formatSplitTime(plan.splits[0]);
  const closing = formatSplitTime(plan.splits[MARATHON_MILES - 1]);
  const terrain = isHillyProfile(plan.profile) ? 'hilly course' : 'flat course';
  return `${plan.name} (${terrain}): miles 1-13 at ${opening}, miles 14-26 at ${closing}`;
