const BASE_DURATIONS = { lawn: 20, shrub: 10 };

const normalizePlantType = (plantType) => String(plantType).trim().toLowerCase();

const getBaseDuration = (plantType) => {
  const key = normalizePlantType(plantType);
  if (!Object.prototype.hasOwnProperty.call(BASE_DURATIONS, key)) {
    throw new Error(`Unknown plant type: ${plantType}`);
  }
  return BASE_DURATIONS[key];
};

const adjustForRain = (duration, rainedYesterday) =>
  rainedYesterday ? duration / 2 : duration;

const validateZone = (zone, index) => {
  if (!Array.isArray(zone) || zone.length !== 3) {
    throw new Error(`Zone ${index} must be [plantType, flowRate, rainedYesterday]`);
  }
  const flowRate = Number(zone[1]);
  if (!Number.isFinite(flowRate) || flowRate < 0) {
    throw new Error(`Zone ${index} has an invalid flow rate: ${zone[1]}`);
  }
  return { plantType: zone[0], flowRate, rainedYesterday: Boolean(zone[2]) };
};

const computeZoneUsage = (zone, index) => {
  const { plantType, flowRate, rainedYesterday } = validateZone(zone, index);
  const baseDuration = getBaseDuration(plantType);
  const duration = adjustForRain(baseDuration, rainedYesterday);
  return {
    plantType: normalizePlantType(plantType),
    minutes: duration,
    gallons: duration * flowRate,
  };
};

function calculate(zones) {
  if (!Array.isArray(zones)) {
    throw new Error('zones must be an array of zone descriptions');
  }
  return zones.reduce((total, zone, index) => {
    const usage = computeZoneUsage(zone, index);
    return total + usage.gallons;
  }, 0);
}

const formatGallons = (gallons) => `${gallons.toFixed(1)} gal`;

const describeZone = (usage, index) =>
  `Zone ${index + 1} (${usage.plantType}): ${usage.minutes} min -> ${formatGallons(usage.gallons)}`;

const buildReport = (zones) => {
  const usages = zones.map((zone, index) => computeZoneUsage(zone, index));
  const lines = usages.map((usage, index) => describeZone(usage, index));
  const total = calculate(zones);
  lines.push(`Total: ${formatGallons(total)}`);
  return lines.join('\n');
};

const main = () => {
  const zones = [
    ['lawn', 2.5, false],
    ['shrub', 1.2, true],
    ['Lawn', 3, true],
    ['SHRUB', 0.8, false],
  ];
  console.log(buildReport(zones));
  const dryZones = zones.map(([plantType, flowRate]) => [plantType, flowRate, false]);
  const dryTotal = calculate(dryZones);
  console.log(`Dry-week total: ${formatGallons(dryTotal)}`);
};

main();

module.exports = { calculate, getBaseDuration, adjustForRain, computeZoneUsage, buildReport };

