const SAFETY_RADIUS = 5;

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

const parseDrone = (entry) => {
  if (!Array.isArray(entry) || entry.length !== 4) {
    throw new TypeError('each drone must be [id, x, y, z]');
  }
  const [id, x, y, z] = entry;
  if (![x, y, z].every(isFiniteNumber)) {
    throw new TypeError(`drone ${id} has non numeric coordinates`);
  }
  return { id, position: [x, y, z] };
};

const parseFleet = (drones) => {
  if (!Array.isArray(drones)) {
    throw new TypeError('fleet must be an array of drones');
  }
  return drones.map(parseDrone);
};

const swarmCenter = (fleet) => {
  if (fleet.length === 0) {
    return [0, 0, 0];
  }
  const totals = fleet.reduce(
    (acc, drone) => acc.map((sum, axis) => sum + drone.position[axis]),
    [0, 0, 0]
  );
  return totals.map((sum) => sum / fleet.length);
};

const euclideanDistance = (a, b) =>
  Math.sqrt(a.reduce((acc, value, axis) => acc + (value - b[axis]) ** 2, 0));

const findConflicts = (fleet) => {
  const offenders = new Set();
  for (let i = 0; i < fleet.length; i += 1) {
    for (let j = i + 1; j < fleet.length; j += 1) {
      const gap = euclideanDistance(fleet[i].position, fleet[j].position);
      if (gap < SAFETY_RADIUS) {
        offenders.add(fleet[i].id);
        offenders.add(fleet[j].id);
      }
    }
  }
  return [...offenders];
};

const validate = (drones) => {
  const fleet = parseFleet(drones);
  swarmCenter(fleet);
  return findConflicts(fleet);
};

const formatPoint = (point) => `(${point.map((v) => v.toFixed(2)).join(', ')})`;

const describeFleet = (drones) => {
  const fleet = parseFleet(drones);
  const center = swarmCenter(fleet);
  const offenders = findConflicts(fleet);
  const spread = fleet.map((drone) => euclideanDistance(drone.position, center));
  const widest = spread.length ? Math.max(...spread).toFixed(2) : '0.00';
  const status = offenders.length ? `unsafe: ${offenders.join(', ')}` : 'safe';
  return `center ${formatPoint(center)} | radius ${widest} m | ${status}`;
};

const safeFormation = [
  ['A1', 0, 0, 0],
  ['B2', 10, 0, 0],
  ['C3', 0, 12, 0],
];

const tightFormation = [
  ['D4', 0, 0, 0],
  ['E5', 2, 1, 0],
  ['F6', 30, 30, 30],
];

console.log(describeFleet(safeFormation));
console.log(validate(safeFormation));
console.log(describeFleet(tightFormation));
console.log(validate(tightFormation));

