const CONDITION_LADDER = ['mint', 'good', 'poor'];

const isNonEmptyString = (value) => typeof value === 'string' && value.trim().length > 0;

const toScratchCount = (value) => {
  const count = Number(value);
  if (!Number.isFinite(count) || count < 0) {
    throw new TypeError(`invalid scratch count: ${String(value)}`);
  }
  return Math.trunc(count);
};

function parseRecord(record) {
  if (!Array.isArray(record) || record.length < 3) {
    throw new TypeError('each record must be [name, scratches, fadedLabel]');
  }
  const [name, scratches, faded] = record;
  if (!isNonEmptyString(name)) {
    throw new TypeError(`invalid album name: ${String(name)}`);
  }
  return {
    name: name.trim(),
    scratches: toScratchCount(scratches),
    faded: Boolean(faded)
  };
}

function classifyScratches(scratches) {
  if (scratches === 0) {
    return 'mint';
  }
  return scratches <= 3 ? 'good' : 'poor';
}

const downgradeCondition = (condition) => {
  const index = CONDITION_LADDER.indexOf(condition);
  const next = Math.min(index + 1, CONDITION_LADDER.length - 1);
  return CONDITION_LADDER[next];
};

const adjustForLabel = (condition, faded) =>
  faded ? downgradeCondition(condition) : condition;

function appraiseAlbum(record) {
  const album = parseRecord(record);
  const base = classifyScratches(album.scratches);
  return { name: album.name, condition: adjustForLabel(base, album.faded) };
}

const formatSentence = ({ name, condition }) =>
  `${name} is in ${condition} condition.`;

function grade(records) {
  if (!Array.isArray(records)) {
    throw new TypeError('records must be an array');
  }
  const appraisals = records.map(appraiseAlbum);
  return appraisals.map(formatSentence);
}

const summarizeGrades = (records) => {
  const tally = new Map(CONDITION_LADDER.map((name) => [name, 0]));
  for (const record of records) {
    const { condition } = appraiseAlbum(record);
    tally.set(condition, tally.get(condition) + 1);
  }
  return CONDITION_LADDER.map((name) => `${name}: ${tally.get(name)}`).join(', ');
};

const collection = [
  ['Rumours', 0, false],
  ['Kind of Blue', 0, true],
  ['Abbey Road', 2, false],
  ['Blue Train', 3, true],
  ['Pet Sounds', 9, false],
  ['Sgt. Pepper', 7, true]
];

for (const sentence of grade(collection)) {
  console.log(sentence);
}
console.log(`Collection tally -> ${summarizeGrades(collection)}`);

module.exports = {
  grade,
  appraiseAlbum,
  classifyScratches,
  summarizeGrades
};

