const validateMatchRecord = (record, index) => {
  if (!Array.isArray(record) || record.length !== 4) {
    throw new TypeError(`match ${index}: expected [name, hits, received, captures]`);
  }
  const [name, hits, received, captures] = record;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError(`match ${index}: player name must be a non-empty string`);
  }
  for (const count of [hits, received, captures]) {
    if (!isFiniteCount(count)) {
      throw new TypeError(`match ${index}: counts must be non-negative integers`);
    }
  }
};

const parseMatchRecord = (record, index) => {
  validateMatchRecord(record, index);
  const [name, hits, received, captures] = record;
  return { name: name.trim(), hits, received, captures };
};

const calculateBaseScore = (match) => match.hits * 10 - match.received * 5;

const computeCaptureBonus = (match) => match.captures * 50;

const computeTotalScore = (match) => {
  const base = calculateBaseScore(match);
  const bonus = computeCaptureBonus(match);
  return base + bonus;
};

const determinePlayerTitle = (total) => {
  if (total < 100) {
    return 'novice';
  }
  if (total > 1000) {
    return 'expert';
  }
  return 'veteran';
};

const formatResultLine = (name, total, title) => `${name}: ${total} (${title})`;

