const PAR = 3;
const HOLE_COUNT = 18;

const validateScorecard = (name, strokes) => {
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('Every scorecard must start with a player name.');
  }
  if (strokes.length !== HOLE_COUNT) {
    throw new RangeError(`${name} reported ${strokes.length} holes, expected ${HOLE_COUNT}.`);
  }
  if (strokes.some((s) => !Number.isInteger(s) || s < 1)) {
    throw new RangeError(`${name} has an invalid stroke count.`);
  }
};

const parseScorecard = (card) => {
  const [name, ...strokes] = card;
  validateScorecard(name, strokes);
  return { name, strokes };
};

const strokesOverPar = (strokes) => strokes.map((s) => s - PAR);

const sumValues = (numbers) => numbers.reduce((total, n) => total + n, 0);

const countHolesAbove = (strokes, limit) => strokes.filter((s) => s > limit).length;

const penaltyPoints = (strokes) => {
  const slowHoles = countHolesAbove(strokes, 6);
  return slowHoles * 2;
};

const consistencyBonus = (strokes) => {
  const looseHoles = countHolesAbove(strokes, 4);
  return looseHoles === 0 ? -5 : 0;
};

const adjustedScore = (strokes) => {
  const overPar = strokesOverPar(strokes);
  const baseline = sumValues(overPar);
  const penalty = penaltyPoints(strokes);
  const bonus = consistencyBonus(strokes);
  return baseline + penalty + bonus;
};

const formatSentence = (name, score) =>
  `${name} finished with an adjusted final score of ${score}.`;

function analyze(scorecards) {
  return scorecards.map((card) => {
    const { name, strokes } = parseScorecard(card);
    const score = adjustedScore(strokes);
    return formatSentence(name, score);
  });
}

