  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) {
    throw new TypeError(`${label} must be a non-negative number, got: ${value}`);
  }
  return Math.trunc(parsed);
};

const normalizeRecord = (record) => {
  if (!Array.isArray(record) || record.length < 4) {
    throw new TypeError('each roster entry must be [name, eliminations, deaths, flags]');
  }
  const [name, eliminations, deaths, flags] = record;
  return {
    name: String(name).trim(),
    eliminations: toWholeNumber(eliminations, 'eliminations'),
    deaths: toWholeNumber(deaths, 'times eliminated'),
    flags: toWholeNumber(flags, 'flags grabbed'),
  };
};

