const INFLOW_PER_MM = 5000;
const SPILLWAY_THRESHOLD_LEVEL = 50;
const EXTRA_RELEASE = 10000;
const ENERGY_DIVISOR = 500;
const CRITICAL_RELEASE = 50000;

const parseDayEntry = (day, index) => {
  if (!Array.isArray(day) || day.length < 2) {
    throw new TypeError(`day ${index} must be a [rainfall, level] pair`);
  }
  const [rainfall, level] = day;
  if (!Number.isFinite(rainfall) || !Number.isFinite(level)) {
    throw new TypeError(`day ${index} must contain finite numbers`);
  }
  return { rainfall, level };
};

const computeInflowVolume = (rainfall) => rainfall * INFLOW_PER_MM;

const computeReleaseRate = (inflow, level) =>
  level > SPILLWAY_THRESHOLD_LEVEL ? inflow + EXTRA_RELEASE : inflow;

const computeEnergyOutput = (releaseRate) => releaseRate / ENERGY_DIVISOR;

const classifySafetyStatus = (releaseRate) =>
  releaseRate > CRITICAL_RELEASE ? 'critical' : 'normal';

const releaseRateForDay = (day, index) => {
  const { rainfall, level } = parseDayEntry(day, index);
  const inflow = computeInflowVolume(rainfall);
  return computeReleaseRate(inflow, level);
};

const formatEnergyValue = (energy) =>
  Number.isInteger(energy) ? String(energy) : energy.toFixed(2);

const formatDailyReport = (energy, status) =>
  `${formatEnergyValue(energy)} MWh - ${status}`;

function regulate(days) {
  if (!Array.isArray(days)) {
    throw new TypeError('days must be an array');
  }
  return days.map((day, index) => {
    const releaseRate = releaseRateForDay(day, index);
    const energy = computeEnergyOutput(releaseRate);
    const status = classifySafetyStatus(releaseRate);
    return formatDailyReport(energy, status);
  });
}

const countCriticalDays = (days) =>
  days.filter((day, index) => {
    const releaseRate = releaseRateForDay(day, index);
    return classifySafetyStatus(releaseRate) === 'critical';
  }).length;

const totalEnergyProduced = (days) =>
  days.reduce((sum, day, index) => {
    const releaseRate = releaseRateForDay(day, index);
    return sum + computeEnergyOutput(releaseRate);
  }, 0);

const buildSeasonSummary = (days) => {
  const reports = regulate(days);
  const lines = reports.map((report, index) => `Day ${index + 1}: ${report}`);
  lines.push(`Critical days: ${countCriticalDays(days)}`);
  const total = totalEnergyProduced(days);
  lines.push(`Total energy: ${formatEnergyValue(total)} MWh`);
  return lines.join('\n');
};

const season = [[2, 48.5], [12, 51.2], [0, 30], [9.5, 62], [4, 50]];
console.log(buildSeasonSummary(season));

module.exports = { regulate, buildSeasonSummary, countCriticalDays, totalEnergyProduced };

