const toWholeNumber = (value, label) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) {
    throw new RangeError(`${label} must be a non-negative number`);
  }
  return Math.trunc(parsed);
};

const parseRun = (run) => {
  if (!Array.isArray(run) || run.length !== 4) {
    throw new TypeError('each run needs [name, difficulty, grindMeters, footTouches]');
  }
  const [name, difficulty, grind, touches] = run;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('skater name must be a non-empty string');
  }
  return {
    name: name.trim(),
    difficulty: toWholeNumber(difficulty, 'difficulty points'),
    grindMeters: toWholeNumber(grind, 'grind distance'),
    footTouches: toWholeNumber(touches, 'foot touches'),
  };
};

const trickScoreBase = (difficulty) => difficulty * 2;

const railBonus = (grindMeters) => Math.max(0, grindMeters - 3) * 5;

const landingDeduction = (footTouches) => footTouches * -10;

const flawlessBonus = (footTouches) => (footTouches === 0 ? 20 : 0);

const scoreRun = (run) => {
  const parsed = parseRun(run);
  const base = trickScoreBase(parsed.difficulty);
  const rail = railBonus(parsed.grindMeters);
  const deduction = landingDeduction(parsed.footTouches);
  const flawless = flawlessBonus(parsed.footTouches);
  return { name: parsed.name, total: base + rail + deduction + flawless };
};

