  if (!Array.isArray(runs)) {
    throw new TypeError('judge expects a list of runs');
  }
  const scored = runs.map(scoreRun);
  return scored.map(formatScoreLine);
}

const rankRuns = (runs) => {
  const scored = runs.map(scoreRun);
  scored.sort((a, b) => b.total - a.total || a.name.localeCompare(b.name));
  return scored;
};

