const clampAtZero = (value) => (value < 0 ? 0 : value);

const steepnessModifier = (angle) => clampAtZero((angle - 90) * 2);

const holdDifficulty = (holdSize) => clampAtZero((50 - holdSize) * 2);

const fatigueReduction = (restPoints) => restPoints * 5;

const endurancePenalty = (angle, restPoints) =>
  angle > 100 && restPoints === 0 ? 10 : 0;

function validateRoute(route) {
  if (!Array.isArray(route) || route.length !== 4) {
    throw new TypeError('each route needs a name, angle, hold size and rest count');
  }
  const [name, angle, holdSize, restPoints] = route;
  if (typeof name !== 'string' || name.length === 0) {
    throw new TypeError('route name must be a non-empty string');
  }
  const numbers = [angle, holdSize, restPoints];
  if (numbers.some((value) => typeof value !== 'number' || Number.isNaN(value))) {
    throw new TypeError(`route "${name}" has non-numeric measurements`);
  }
  return { name, angle, holdSize, restPoints };
}

function difficultyScore(angle, holdSize, restPoints) {
  const steepness = steepnessModifier(angle);
  const holds = holdDifficulty(holdSize);
  const rests = fatigueReduction(restPoints);
  const penalty = endurancePenalty(angle, restPoints);
  return steepness + holds - rests + penalty;
}

function grade(routes) {
  return routes.map((route) => {
    const { name, angle, holdSize, restPoints } = validateRoute(route);
    return [name, difficultyScore(angle, holdSize, restPoints)];
  });
}

const formatScoreLine = ([name, score]) => `${name.padEnd(18, '.')} ${score}`;

function hardestRoute(results) {
  return results.reduce(
    (best, entry) => (entry[1] > best[1] ? entry : best),
    results[0]
  );
}

function buildReport(results) {
  const lines = results.map(formatScoreLine);
  const hardest = hardestRoute(results);
  lines.push(`hardest: ${formatScoreLine(hardest)}`);
  return lines.join('\n');
}

const overhangs = [
  ['Roof Rat', 135, 18, 0],
  ['Slab Shuffle', 82, 60, 3],
  ['Tendon Test', 104, 22, 2],
];

const vertWall = [
  ['Crimp Ladder', 91, 12, 1],
  ['Jug Haul', 95, 55, 4],
];

console.log(buildReport(grade(overhangs)));
console.log('---');
console.log(buildReport(grade(vertWall)));

module.exports = { grade, difficultyScore, buildReport, hardestRoute };

