const sumAllScores = (scores) => scores.reduce((total, value) => total + value, 0);

const dropHighAndLow = (scores) => {
  const sorted = [...scores].sort((a, b) => a - b);
  return sorted.slice(1, sorted.length - 1);
};

const averageAfterDrops = (scores) => {
  const kept = dropHighAndLow(scores);
  const total = sumAllScores(kept);
  return total / 3;
};

const syncPenaltyFor = (errorCount) => errorCount * 0.5;

const perfectionBonusFor = (errorCount) => (errorCount === 0 ? 1 : 0);

const validateJudgeScores = (scores, panel, team) => {
  if (!Array.isArray(scores) || scores.length !== 5) {
    throw new Error(`${team}: the ${panel} panel must supply exactly five scores`);
  }
  if (scores.some((value) => typeof value !== 'number' || Number.isNaN(value))) {
    throw new Error(`${team}: the ${panel} panel reported a non-numeric score`);
  }
};

const validateErrorCount = (errorCount, team) => {
  if (!Number.isInteger(errorCount) || errorCount < 0) {
    throw new Error(`${team}: synchronization errors must be a non-negative integer`);
  }
};

const computeTotalScore = (technical, artistic, errorCount) => {
  const technicalAverage = averageAfterDrops(technical);
  const artisticAverage = averageAfterDrops(artistic);
  const penalty = syncPenaltyFor(errorCount);
