const SHELL_FIELDS = ['size', 'color', 'effect'];

const parseShellEntry = (shell, index) => {
  if (!Array.isArray(shell) || shell.length < SHELL_FIELDS.length) {
    throw new TypeError(`Shell #${index + 1} must be [size, color, effect]`);
  }
  const [size, color, effect] = shell;
  if (typeof size !== 'number' || !Number.isFinite(size) || size <= 0) {
    throw new RangeError(`Shell #${index + 1} has an invalid size: ${size}`);
  }
  return { size, color: String(color), effect: String(effect) };
};

const computeLaunchDelay = (size) => size * 1.5;

const computeBurstAltitude = (size) => size * 100;

const computeSafetyRadius = (size) => size * 70;

const needsCrowdWarning = (radius) => radius > 300;

const trimNumber = (value) => {
  const rounded = Math.round(value * 100) / 100;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(2).replace(/0$/, '');
};

const formatLaunchInstruction = (shell) => {
  const altitude = computeBurstAltitude(shell.size);
  const delay = computeLaunchDelay(shell.size);
  const radius = computeSafetyRadius(shell.size);
  const warning = needsCrowdWarning(radius);
  return `Launch ${shell.color} ${shell.effect} to ${trimNumber(altitude)} ft ` +
    `after ${trimNumber(delay)} s delay; crowd warning: ${warning}`;
};

function choreograph(shells) {
  if (!Array.isArray(shells)) {
    throw new TypeError('choreograph expects an array of shells');
  }
  return shells.map((shell, index) => {
    const parsed = parseShellEntry(shell, index);
    return formatLaunchInstruction(parsed);
  });
}

const summarizeShow = (shells) => {
  const parsed = shells.map(parseShellEntry);
  const totalRuntime = parsed.reduce((sum, shell) => sum + computeLaunchDelay(shell.size), 0);
  const widestPerimeter = parsed.reduce((max, shell) => Math.max(max, computeSafetyRadius(shell.size)), 0);
  const highestBurst = parsed.reduce((max, shell) => Math.max(max, computeBurstAltitude(shell.size)), 0);
  return {
    shellCount: parsed.length,
    runtimeSeconds: trimNumber(totalRuntime),
    perimeterFeet: trimNumber(widestPerimeter),
    ceilingFeet: trimNumber(highestBurst),
    warningRequired: needsCrowdWarning(widestPerimeter),
  };
};

const runShowPlanner = (shells) => {
  const instructions = choreograph(shells);
  const summary = summarizeShow(shells);
  instructions.forEach((line, index) => console.log(`${index + 1}. ${line}`));
  console.log(`-- ${summary.shellCount} shells, ${summary.runtimeSeconds} s of cued delays`);
  console.log(`-- ceiling ${summary.ceilingFeet} ft, perimeter ${summary.perimeterFeet} ft`);
  console.log(`-- announcer warning required: ${summary.warningRequired}`);
  return instructions;
};

const showPlan = [
  [3, 'red', 'peony'],
  [5, 'gold', 'willow'],
  [8, 'blue', 'chrysanthemum'],
  [12, 'silver', 'crossette'],
];

runShowPlanner(showPlan);

module.exports = { choreograph, summarizeShow, runShowPlanner };

