const TotalDrops = (topDrops, heartDrops, baseDrops) => topDrops + heartDrops + baseDrops;

const ValidateRecipe = (recipe) => {
  if (!Array.isArray(recipe) || recipe.length !== 4) {
    throw new Error('each recipe needs a name and three drop counts');
  }
  const [name, ...drops] = recipe;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new Error('scent name must be a non-empty string');
  }
  drops.forEach((count) => {
    if (!Number.isFinite(count) || count < 0) {
      throw new Error(`invalid drop count for ${name}: ${count}`);
    }
  });
  return { name: name.trim(), top: drops[0], heart: drops[1], base: drops[2] };
};

const ComputeOilVolume = (drops) => drops / 20;

const ComputeAlcoholVolume = (oilVolume) => oilVolume * 4;

const ComputeWaterVolume = (alcoholVolume) => alcoholVolume * 0.1;

const IsBaseDominant = (baseDrops, drops) => baseDrops > drops - baseDrops;

function MaturationWeeks(baseDrops, drops) {
  if (IsBaseDominant(baseDrops, drops)) {
    return 2;
  }
  return 1;
}

const FormatVolume = (millilitres) => `${millilitres.toFixed(2)}ml`;

const DescribeBatch = (scent) => {
  const drops = TotalDrops(scent.top, scent.heart, scent.base);
  const oilVolume = ComputeOilVolume(drops);
  const alcoholVolume = ComputeAlcoholVolume(oilVolume);
  const waterVolume = ComputeWaterVolume(alcoholVolume);
  const weeks = MaturationWeeks(scent.base, drops);
  const weekLabel = weeks === 1 ? 'week' : 'weeks';
  const oilText = FormatVolume(oilVolume);
  const alcoholText = FormatVolume(alcoholVolume);
  const waterText = FormatVolume(waterVolume);
  return `${scent.name}: ${oilText} oil, ${alcoholText} alcohol, `
    + `${waterText} water, mature ${weeks} ${weekLabel}`;
};

function Formulate(recipes) {
  if (!Array.isArray(recipes)) {
    throw new Error('recipes must be a list');
  }
