  const waterText = FormatVolume(waterVolume);
  const bottleText = FormatVolume(bottleVolume);
  return `Workshop total: ${oilText} oil, ${alcoholText} alcohol, `
    + `${waterText} water, ${bottleText} bottled`;
};

