const computeAirTime = (height) => 2 * Math.sqrt(height / 5);

const computeHandSpeed = (props, airTime) => props / airTime;

const applyComplexityPenalty = (handSpeed, props) =>
  props > 5 ? handSpeed - 2 : handSpeed;

const estimateCatchCount = (skill, adjustedSpeed) =>
  skill * 20 - adjustedSpeed * adjustedSpeed;

function validateRoutine(routine) {
  if (!Array.isArray(routine) || routine.length !== 4) {
    throw new TypeError('each routine needs name, props, height and skill');
  }
  const [name, props, height, skill] = routine;
  if (typeof name !== 'string' || name.length === 0) {
    throw new TypeError('juggler name must be a non-empty string');
  }
  if (!Number.isInteger(props) || props < 1) {
    throw new RangeError(`${name}: prop count must be a positive integer`);
  }
  if (typeof height !== 'number' || height <= 0) {
    throw new RangeError(`${name}: throw height must be above zero metres`);
  }
  if (typeof skill !== 'number' || skill < 1 || skill > 10) {
    throw new RangeError(`${name}: skill rating must lie between 1 and 10`);
  }
  return { name, props, height, skill };
}

function evaluateRoutine(routine) {
  const { name, props, height, skill } = validateRoutine(routine);
  const airTime = computeAirTime(height);
  const handSpeed = computeHandSpeed(props, airTime);
  const adjustedSpeed = applyComplexityPenalty(handSpeed, props);
  return [name, estimateCatchCount(skill, adjustedSpeed)];
}

function simulate(patterns) {
  if (!Array.isArray(patterns)) {
    throw new TypeError('patterns must be a list of routines');
  }
  return patterns.map(evaluateRoutine);
}

const findBestJuggler = (results) =>
  results.reduce((best, current) => (current[1] > best[1] ? current : best));

const formatResultLine = ([name, catches]) =>
  `${name.padEnd(10)} ${catches.toFixed(2).padStart(9)} catches`;

function buildReport(results) {
  const lines = results.map(formatResultLine);
  const [bestName, bestCatches] = findBestJuggler(results);
  lines.push(`best: ${bestName} with ${bestCatches.toFixed(2)} catches`);
  return lines.join('\n');
}

function main() {
  const patterns = [
    ['Anya', 3, 2.5, 8],
    ['Boris', 7, 3.2, 9],
    ['Clara', 5, 1.8, 6],
    ['Dmitri', 9, 4.0, 10],
  ];
  const results = simulate(patterns);
  console.log(buildReport(results));

  const soloAirTime = computeAirTime(2.5);
  const soloSpeed = computeHandSpeed(3, soloAirTime);
  console.log(`Anya hand speed: ${soloSpeed.toFixed(3)} throws/second`);
  console.log(`Anya adjusted: ${applyComplexityPenalty(soloSpeed, 3).toFixed(3)}`);
}

main();

module.exports = { simulate, evaluateRoutine, buildReport };

