const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function parseLocation(entry) {
  if (!Array.isArray(entry) || entry.length < 4) {
    throw new TypeError('each location needs a street, pedestrians, competitors and fee');
  }
  const [street, pedestrians, competitors, fee] = entry;
  if (typeof street !== 'string' || street.trim() === '') {
    throw new TypeError('street name must be a non-empty string');
  }
  if (![pedestrians, competitors, fee].every(isFiniteNumber)) {
    throw new TypeError(`numeric fields expected for "${street}"`);
  }
  return { street: street.trim(), pedestrians, competitors, fee };
}

const computeTrafficScore = (pedestrians) => pedestrians / 10;

const computeCompetitorPenalty = (competitors) => -(competitors * 15);

const computeParkingAdjustment = (fee) => 50 - fee;

const computeHighVolumeBonus = (pedestrians) => (pedestrians > 1000 ? 20 : 0);

function computeViabilityScore(spot) {
  return computeTrafficScore(spot.pedestrians)
    + computeCompetitorPenalty(spot.competitors)
    + computeParkingAdjustment(spot.fee)
    + computeHighVolumeBonus(spot.pedestrians);
}

function scoreLocation(entry) {
  const spot = parseLocation(entry);
  return { street: spot.street, score: computeViabilityScore(spot) };
}

const compareByScoreDesc = (a, b) => b.score - a.score;

function rankLocations(locations) {
  if (!Array.isArray(locations)) {
    throw new TypeError('locations must be an array');
  }
  return locations.map(scoreLocation).sort(compareByScoreDesc);
}

function select(locations) {
  return rankLocations(locations).map((ranked) => ranked.street);
}

const formatScoreLine = (ranked, index) =>
  `${index + 1}. ${ranked.street} — ${ranked.score.toFixed(1)} pts`;

function buildRankingReport(locations) {
  const ranked = rankLocations(locations);
  return ranked.map(formatScoreLine).join('\n');
}

function main() {
  const candidates = [
    ['Maple Street', 1200, 3, 40],
    ['Harbor Road', 800, 1, 25],
    ['Union Plaza', 1500, 6, 75],
    ['Cedar Lane', 400, 0, 10],
  ];
  console.log(buildRankingReport(candidates));
  console.log(select(candidates));
}

main();

module.exports = { select, computeViabilityScore, buildRankingReport };

