const BLADE_WEIGHTS = { carbon: 85, 'all-wood': 75 };

const normalizeWoodType = (wood) => String(wood).trim().toLowerCase();

const getBladeWeight = (wood) => {
  const key = normalizeWoodType(wood);
  return BLADE_WEIGHTS[key];
};

const isValidThickness = (mm) => Number.isFinite(mm) && mm > 0 && mm <= 5;

const computeSpeedRating = (forehandMm) => forehandMm * 40;

const computeSpinRating = (backhandMm) => backhandMm * 35;

const computeRubberWeight = (forehandMm, backhandMm) => (forehandMm + backhandMm) * 10;

const computeTotalWeight = (wood, forehandMm, backhandMm) => {
  const blade = getBladeWeight(wood);
  const rubber = computeRubberWeight(forehandMm, backhandMm);
  return blade + rubber;
};

const determineBalance = (speed, spin) => {
  if (speed - spin > 20) return 'offensive';
  if (spin > speed) return 'defensive';
  return 'all-around';
};

const validateOrder = (order) => {
  if (!Array.isArray(order) || order.length !== 4) {
    throw new TypeError('each order must be [name, wood, forehandMm, backhandMm]');
  }
  const [name, wood, forehandMm, backhandMm] = order;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('customer name must be a non-empty string');
  }
  if (!(normalizeWoodType(wood) in BLADE_WEIGHTS)) {
    throw new RangeError(`unknown blade wood: ${wood}`);
  }
  if (!isValidThickness(forehandMm)) {
    throw new RangeError(`bad forehand thickness: ${forehandMm}`);
  }
  if (!isValidThickness(backhandMm)) {
    throw new RangeError(`bad backhand thickness: ${backhandMm}`);
  }
  return { name: name.trim(), wood, forehandMm, backhandMm };
};

const formatWeight = (grams) => `${Number(grams.toFixed(1))}g`;

const buildPaddleSummary = (order) => {
  const spec = validateOrder(order);
  const speed = computeSpeedRating(spec.forehandMm);
  const spin = computeSpinRating(spec.backhandMm);
  const total = computeTotalWeight(spec.wood, spec.forehandMm, spec.backhandMm);
  const balance = determineBalance(speed, spin);
  return `${spec.name}: ${formatWeight(total)}, ${balance}`;
};

function assemble(orders) {
  if (!Array.isArray(orders)) {
    throw new TypeError('orders must be an array');
  }
  return orders.map(buildPaddleSummary);
}

const printWorkshopReport = (orders) => {
  const summaries = assemble(orders);
  summaries.forEach((line) => console.log(line));
  const heaviest = orders.reduce(
    (max, [, wood, fh, bh]) => Math.max(max, computeTotalWeight(wood, fh, bh)),
    0
  );
  console.log(`heaviest paddle in batch: ${formatWeight(heaviest)}`);
};

printWorkshopReport([
  ['Ada', 'carbon', 2.1, 1.8],
  ['Kenji', 'all-wood', 1.5, 2.0],
  ['Mira', 'CARBON', 2.0, 2.0],
]);

module.exports = { assemble };

