const isValidJudgeScore = (value) =>
  Number.isInteger(value) && value >= 0 && value <= 10;

const validateVault = (vault) => {
  if (!Array.isArray(vault) || vault.length !== 3) {
    throw new TypeError('each vault must be [name, judgeScores, difficulty]');
  }
  const [name, judgeScores, difficulty] = vault;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('gymnast name must be a non-empty string');
  }
  if (!Array.isArray(judgeScores) || judgeScores.length !== 5) {
    throw new TypeError(`${name}: exactly five judge scores are required`);
  }
  const scoresAreValid = judgeScores.every(isValidJudgeScore);
  if (!scoresAreValid) {
    throw new RangeError(`${name}: judge scores must be integers from 0 to 10`);
  }
  if (typeof difficulty !== 'number' || !Number.isFinite(difficulty)) {
    throw new TypeError(`${name}: base difficulty must be a finite number`);
  }
  return { name: name.trim(), judgeScores, difficulty };
};

const dropExtremeScores = (judgeScores) =>
  [...judgeScores].sort((a, b) => a - b).slice(1, -1);

const averageExecution = (judgeScores) => {
  const retained = dropExtremeScores(judgeScores);
  const sum = retained.reduce((acc, value) => acc + value, 0);
  return sum / retained.length;
};

const computeRawTotal = (judgeScores, difficulty) =>
  difficulty + averageExecution(judgeScores);

const hasLowJudgeScore = (judgeScores) => judgeScores.some((value) => value < 7);

const isPerfectLanding = (judgeScores) =>
  dropExtremeScores(judgeScores).every((value) => value === 10);

const neutralDeduction = (judgeScores) =>
  (hasLowJudgeScore(judgeScores) ? 0.5 : 0);

const landingBonus = (judgeScores) =>
  (isPerfectLanding(judgeScores) ? 0.3 : 0);

const roundToThousandths = (value) => Math.round(value * 1000) / 1000;

const finalScore = (judgeScores, difficulty) => {
  const raw = computeRawTotal(judgeScores, difficulty);
  const penalty = neutralDeduction(judgeScores);
  const bonus = landingBonus(judgeScores);
  return roundToThousandths(raw - penalty + bonus);
};

const formatScoreLine = (name, total) => `${name}: ${total.toFixed(3)}`;

function score(vaults) {
  if (!Array.isArray(vaults)) {
    throw new TypeError('vaults must be a list of competitors');
  }
  return vaults.map((vault) => {
    const { name, judgeScores, difficulty } = validateVault(vault);
    const total = finalScore(judgeScores, difficulty);
    return formatScoreLine(name, total);
  });
}

const parseLineTotal = (line) => parseFloat(line.split(': ')[1]);

const rankByTotal = (lines) =>
  lines
    .map((line) => ({ line, total: parseLineTotal(line) }))
    .sort((a, b) => b.total - a.total)
    .map((entry) => entry.line);

function main() {
  const roster = [
    ['Simone', [10, 10, 10, 10, 9], 6.4],
    ['Kohei', [9, 8, 9, 9, 8], 6.0],
    ['Alex', [6, 8, 7, 7, 8], 5.6],
    ['Nadia', [10, 10, 10, 9, 10], 5.8],
  ];
  const lines = score(roster);
  const ranked = rankByTotal(lines);
  ranked.forEach((line, index) => {
    console.log(`${index + 1}. ${line}`);
  });
}

main();

module.exports = {
  score,
  averageExecution,
  finalScore,
  rankByTotal,
};

