  }
  return n;
}

const touchIndicator = (scored, received) => scored - received;

const penaltyPoints = (yellow, red) => -(yellow * 0) - red;

const defenseBonus = (received) => (received < 3 ? 2 : 0);

const effectiveScore = (record) => {
  const indicator = touchIndicator(record.scored, record.received);
  const penalties = penaltyPoints(record.yellow, record.red);
