const toFiniteNumber = (value) => {
  const parsed = typeof value === 'string' ? Number(value.trim()) : Number(value);
  if (!Number.isFinite(parsed)) {
    throw new TypeError(`expected a numeric value, received ${JSON.stringify(value)}`);
  }
  return parsed;
};

const normalizeRoute = (route) => {
  if (!Array.isArray(route) || route.length < 4) {
    throw new TypeError('each route needs [id, distanceKm, weightKg, windKnots]');
  }
  const [id, distance, weight, wind] = route;
  return {
    id: String(id),
    distanceKm: toFiniteNumber(distance),
    weightKg: toFiniteNumber(weight),
    windKnots: toFiniteNumber(wind),
  };
};

const computeBaselineDrag = ({ distanceKm, weightKg }) => distanceKm * 2 + weightKg * 3;

const computeWindMultiplier = ({ windKnots }) => 1 + windKnots / 15;

const computeLineTension = (route) => {
  const baselineDrag = computeBaselineDrag(route);
  return baselineDrag * computeWindMultiplier(route);
};

const classifyRiskLevel = (tension) => {
  if (tension > 500) return 'high';
  if (tension > 300) return 'medium';
  return 'low';
};

const formatTension = (tension) => tension.toFixed(2);

const formatRouteReport = (route) => {
  const tension = computeLineTension(route);
  const risk = classifyRiskLevel(tension);
  return `${route.id}: tension ${formatTension(tension)} N, risk ${risk}`;
};

function analyze(routes) {
  if (!Array.isArray(routes)) {
    throw new TypeError('analyze expects a list of routes');
  }
  return routes.map((route) => formatRouteReport(normalizeRoute(route)));
}

const summarizeRiskCounts = (routes) => {
  const counts = { high: 0, medium: 0, low: 0 };
  routes.forEach((route) => {
    const tension = computeLineTension(normalizeRoute(route));
    counts[classifyRiskLevel(tension)] += 1;
  });
  return counts;
};

