const MIXING_TIMES = { silica: 15, feldspar: 12, kaolin: 10 };
const DEFAULT_MIXING_TIME = 10;
const STANDARD_REST_HOURS = 24;
const COMFORT_TEMPERATURE = 20;
const EVAPORATION_THRESHOLD = 25;
const EVAPORATION_BONUS_ML = 50;

const normalizeMineralName = (mineral) => String(mineral).trim().toLowerCase();

function parseNumericField(value, label) {
  const parsed = typeof value === 'number' ? value : Number(String(value).trim());
  if (!Number.isFinite(parsed)) {
    throw new TypeError(`${label} must be a finite number, got "${value}"`);
  }
  return parsed;
}

function validateBatch(batch) {
  if (!Array.isArray(batch) || batch.length !== 4) {
    throw new TypeError('each batch must be [mineral, waterPercent, dryWeight, temperature]');
  }
  const [mineral, waterPercent, dryWeight, temperature] = batch;
  if (typeof mineral !== 'string' || mineral.trim() === '') {
    throw new TypeError('the base mineral must be a non-empty string');
  }
  return {
    mineral: normalizeMineralName(mineral),
    waterPercent: parseNumericField(waterPercent, 'water percentage'),
    dryWeight: parseNumericField(dryWeight, 'dry weight'),
    temperature: parseNumericField(temperature, 'temperature'),
  };
}

const computeWaterVolume = (dryWeight, waterPercent) => dryWeight * (waterPercent / 100);

function determineMixingTime(mineral) {
  const key = normalizeMineralName(mineral);
  return Object.prototype.hasOwnProperty.call(MIXING_TIMES, key) ? MIXING_TIMES[key] : DEFAULT_MIXING_TIME;
}

function computeRestingHours(temperature) {
  const excess = Math.max(0, temperature - COMFORT_TEMPERATURE);
  return STANDARD_REST_HOURS - excess;
}

const applyEvaporationCompensation = (volume, temperature) =>
  temperature > EVAPORATION_THRESHOLD ? volume + EVAPORATION_BONUS_ML : volume;

const formatVolumeLabel = (milliliters) => `${Math.round(milliliters * 100) / 100} ml`;

function formatBatchReport(spec) {
  const rawVolume = computeWaterVolume(spec.dryWeight, spec.waterPercent);
  const volume = applyEvaporationCompensation(rawVolume, spec.temperature);
  const mixingTime = determineMixingTime(spec.mineral);
  const restingHours = computeRestingHours(spec.temperature);
  return `${spec.mineral}: add ${formatVolumeLabel(volume)} water, mix for ${mixingTime} minutes, rest for ${restingHours} hours`;
}

function mix(batches) {
  if (!Array.isArray(batches)) {
    throw new TypeError('batches must be an array of batch definitions');
  }
  return batches.map((batch) => {
    const spec = validateBatch(batch);
    return formatBatchReport(spec);
  });
}

function parseBatchSpec(text) {
  const parts = String(text).split(':');
  if (parts.length !== 4) {
    throw new TypeError(`expected mineral:water%:dryWeight:temperature, got "${text}"`);
  }
  return [parts[0], parts[1], parts[2], parts[3]];
}

function main(argv) {
  if (argv.length === 0) {
    console.error('usage: node glaze.js mineral:water%:dryWeight:temperature ...');
    return 1;
  }
  const batches = argv.map((arg) => parseBatchSpec(arg));
  mix(batches).forEach((line) => console.log(line));
  return 0;
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

module.exports = { mix, determineMixingTime, computeRestingHours, computeWaterVolume };

