const MAJOR_CARDS = new Set(['sun', 'moon', 'star', 'world', 'tower', 'fool', 'death']);
const MINOR_SUITS = new Set(['cups', 'swords', 'wands', 'pentacles']);

const normalizeToken = (token) => String(token).trim().toLowerCase();

const isKnownOrientation = (orientation) => orientation === 'upright' || orientation === 'reversed';

const isUprightOrientation = (orientation) => orientation === 'upright';

const getCardSuit = (name) => name.split(' ').pop();

const isMajorCard = (name) => {
  const suit = getCardSuit(name);
  return MAJOR_CARDS.has(suit);
};

const splitCardEntry = (entry) => {
  const parts = normalizeToken(entry).split(/\s+/);
  const orientation = parts.pop();
  const name = parts.join(' ');
  if (!isKnownOrientation(orientation)) {
    throw new Error(`missing or unknown orientation in "${entry}"`);
  }
  if (name.length === 0) {
    throw new Error(`missing card name in "${entry}"`);
  }
  return { name, orientation };
};

const getBasePower = (name) => {
  if (isMajorCard(name)) {
    return 10;
  }
  const suit = getCardSuit(name);
  if (MINOR_SUITS.has(suit)) {
    return 5;
  }
  throw new Error(`unrecognised card "${name}"`);
};

const applyOrientation = (power, orientation) =>
  isUprightOrientation(orientation) ? power * 2 : power / 2;

const scoreSingleCard = (entry) => {
  const { name, orientation } = splitCardEntry(entry);
  const base = getBasePower(name);
  return applyOrientation(base, orientation);
};

const categorizeTotal = (total) => {
  if (total >= 20) {
    return 'favorable';
  }
  return total >= 10 ? 'neutral' : 'ominous';
};

function predict(spread) {
  if (!Array.isArray(spread)) {
    throw new TypeError('spread must be an array of card strings');
  }
  const total = spread.reduce((sum, entry) => sum + scoreSingleCard(entry), 0);
  const rounded = Math.round(total * 100) / 100;
  return [rounded, categorizeTotal(rounded)];
}

const formatPowerValue = (power) => (Number.isInteger(power) ? String(power) : power.toFixed(1));

const formatReading = (spread) => {
  const [total, category] = predict(spread);
  const lines = spread.map((entry) => {
    const { name, orientation } = splitCardEntry(entry);
    const kind = isMajorCard(name) ? 'major' : 'minor';
    const power = scoreSingleCard(entry);
    return `  ${name} (${orientation}, ${kind}): ${formatPowerValue(power)}`;
  });
  lines.push(`  total ${formatPowerValue(total)} -> ${category}`);
  return lines.join('\n');
};

const readings = [
  ['sun upright', 'cups reversed'],
  ['moon reversed', 'swords reversed'],
  ['star upright', 'tower upright', 'wands upright'],
];

readings.forEach((spread) => {
  console.log(spread.join(', '));
  console.log(formatReading(spread));
});

module.exports = {
  predict,
  formatReading,
  scoreSingleCard,
  categorizeTotal,
};

