const TRACK_LENGTH = 1000;
const PENALTY_THRESHOLD = 200;
const PENALTY_STEP_POUNDS = 50;
const PENALTY_RATE = 0.1;

const toPositiveNumber = (text, label) => {
  const value = Number(text.trim());
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`${label} must be a positive number, got "${text.trim()}"`);
  }
  return value;
};

const parseChariotSpec = (spec) => {
  const parts = String(spec).split(",");
  if (parts.length !== 3) {
    throw new Error(`expected "team, speed, weight" but got "${spec}"`);
  }
  const team = parts[0].trim();
  const speed = toPositiveNumber(parts[1], "horse speed");
  const weight = toPositiveNumber(parts[2], "chariot weight");
  return { team, speed, weight };
};

const countPenaltySteps = (weight) => {
  const excess = weight - PENALTY_THRESHOLD;
  if (excess <= 0) {
    return 0;
  }
  return Math.floor(excess / PENALTY_STEP_POUNDS);
};

const computePenaltyFactor = (weight) => {
  const steps = countPenaltySteps(weight);
  return Math.max(0, 1 - steps * PENALTY_RATE);
};

const computeBaseAcceleration = (speed, weight) => speed / weight;

const computeAdjustedAcceleration = (speed, weight) => {
  const base = computeBaseAcceleration(speed, weight);
  return base * computePenaltyFactor(weight);
};

const roundToHundredths = (value) => Math.round(value * 100) / 100;

const computeLapTime = (speed, weight) => {
  const acceleration = computeAdjustedAcceleration(speed, weight);
  // acceleration is measured per pound, so scale it back up by the chariot weight
  const groundSpeed = acceleration * weight;
  return roundToHundredths(TRACK_LENGTH / groundSpeed);
};

