const isValidHexString = (text) =>
  typeof text === 'string' && /^[0-9a-fA-F]+$/.test(text.trim());

const decodeHexNode = (text) => {
  if (!isValidHexString(text)) {
    throw new TypeError(`not a hexadecimal node: ${String(text)}`);
  }
  return parseInt(text.trim(), 16);
};

const isPrimeNumber = (value) => {
  if (value < 2) return false;
  if (value % 2 === 0) return value === 2;
  for (let divisor = 3; divisor * divisor <= value; divisor += 2) {
    if (value % divisor === 0) return false;
  }
  return true;
};

const sumDigitValues = (value) => {
  let total = 0;
  let remaining = value;
  do {
    total += remaining % 10;
    remaining = Math.floor(remaining / 10);
  } while (remaining > 0);
  return total;
};

const inspectNode = (text) => {
  const decimal = decodeHexNode(text);
  const firewall = isPrimeNumber(decimal);
  return {
    hex: text.trim().toUpperCase(),
    decimal,
    firewall,
    vulnerability: firewall ? 0 : sumDigitValues(decimal),
  };
};

const totalVulnerability = (reports) =>
  reports.reduce((sum, report) => sum + report.vulnerability, 0);

const countFirewallNodes = (reports) =>
  reports.filter((report) => report.firewall).length;

function hack(nodes) {
  if (!Array.isArray(nodes)) {
    throw new TypeError('hack expects an array of hexadecimal strings');
  }
  const reports = nodes.map(inspectNode);
  const firewalls = countFirewallNodes(reports);
  const vulnerabilities = totalVulnerability(reports);
  return [vulnerabilities > 50, firewalls];
}

const formatNodeLine = (report) =>
  `${report.hex} -> ${report.decimal} ` +
  (report.firewall ? '[firewall]' : `[vuln ${report.vulnerability}]`);

const describeAttack = (nodes) => {
  const reports = nodes.map(inspectNode);
  const [success, firewalls] = hack(nodes);
  const lines = reports.map(formatNodeLine);
  lines.push(`total vulnerability: ${totalVulnerability(reports)}`);
  lines.push(`firewall nodes: ${firewalls}`);
  lines.push(`intrusion ${success ? 'successful' : 'failed'}`);
  return lines.join('\n');
};

const runDriver = () => {
  const targets = [
    ['0A', '1F', '07'],
    ['FF', 'AB', '2C', '90', '3D'],
  ];
  for (const batch of targets) {
    console.log(describeAttack(batch));
    console.log('');
  }
};

runDriver();

module.exports = {
  hack,
  isPrimeNumber,
  sumDigitValues,
  decodeHexNode,
  describeAttack,
};

