const RURAL_LIMIT = 100;
const COMMERCIAL_LIMIT = 500;

const isValidDensity = (value) =>
  typeof value === "number" && Number.isFinite(value) && value >= 0;

const validateBlocks = (blocks) => {
  if (!Array.isArray(blocks)) {
    throw new TypeError("zone expects an array of densities");
  }
  blocks.forEach((density, index) => {
    if (!isValidDensity(density)) {
      throw new RangeError(`block ${index} has an invalid density: ${density}`);
    }
  });
  return blocks;
};

const classifyDensity = (density) => {
  if (density < RURAL_LIMIT) {
    return "rural";
  }
  if (density <= COMMERCIAL_LIMIT) {
    return "residential";
  }
  return "commercial";
};

const taxForCategory = (category) => {
  switch (category) {
    case "rural":
      return 10;
    case "residential":
      return 20;
    default:
      return 50;
  }
};

const sumRevenue = (categories) =>
  categories.reduce((total, category) => total + taxForCategory(category), 0);

const averageRevenue = (categories) => {
  if (categories.length === 0) {
    return 0;
  }
  return sumRevenue(categories) / categories.length;
};

function zone(blocks) {
  const densities = validateBlocks(blocks);
  const categories = densities.map((density) => classifyDensity(density));
  return [categories, averageRevenue(categories)];
}

const countByCategory = (categories) =>
  categories.reduce((tally, category) => {
    tally[category] = (tally[category] || 0) + 1;
    return tally;
  }, {});

const formatAverage = (average) =>
  Number.isInteger(average) ? String(average) : average.toFixed(2);

const describeZoning = (blocks) => {
  const [categories, average] = zone(blocks);
  const tally = countByCategory(categories);
  const breakdown = Object.keys(tally)
    .sort()
    .map((category) => `${category}: ${tally[category]}`)
    .join(", ");
  return `${categories.length} blocks (${breakdown}) -> avg revenue ${formatAverage(average)}`;
};

const main = () => {
  const samples = [
    [50, 600],
    [99, 100, 500, 501],
    [120, 340, 80, 900, 450],
  ];
  samples.forEach((sample) => {
    console.log(describeZoning(sample));
  });
};

main();

module.exports = { zone, classifyDensity, taxForCategory, describeZoning };

