const VOWELS = new Set(['a', 'e', 'i', 'o', 'u']);

const normalizeWord = (word) => String(word).toLowerCase().replace(/[^a-z]/g, '');

const isVowelLetter = (letter) => VOWELS.has(letter);

const countVowels = (word) => {
  let total = 0;
  for (const letter of word) {
    if (isVowelLetter(letter)) {
      total += 1;
    }
  }
  return total;
};

const countConsonants = (word) => {
  const vowels = countVowels(word);
  return word.length - vowels;
};

const estimateSyllables = (word) => {
  return countVowels(word);
};

const consonantVowelRatio = (word) => {
  const vowels = countVowels(word);
  const consonants = countConsonants(word);
  if (vowels === 0) {
    return consonants === 0 ? 0 : Infinity;
  }
  return consonants / vowels;
};

const isComplexWord = (word) => {
  const ratio = consonantVowelRatio(word);
  return ratio > 3;
};

const describeWord = (word) => {
  const cleaned = normalizeWord(word);
  return {
    cleaned,
    syllables: estimateSyllables(cleaned),
    ratio: consonantVowelRatio(cleaned),
    complex: isComplexWord(cleaned),
  };
};

function analyze(words) {
  const simple = [];
  const complex = [];
  for (const word of words) {
    const info = describeWord(word);
    if (info.complex) {
      complex.push(info.cleaned);
    } else {
      simple.push(info.cleaned);
    }
  }
  return [simple, complex];
}

const formatRatio = (ratio) => (Number.isFinite(ratio) ? ratio.toFixed(2) : 'inf');

const formatWordLine = (word) => {
  const info = describeWord(word);
  const label = info.complex ? 'complex' : 'simple';
  const ratio = formatRatio(info.ratio);
  return `${info.cleaned || '(empty)'}: syllables=${info.syllables} ratio=${ratio} -> ${label}`;
};

const buildReport = (words) => {
  const [simple, complex] = analyze(words);
  const lines = words.map(formatWordLine);
  lines.push(`simple (${simple.length}): ${simple.join(', ')}`);
  lines.push(`complex (${complex.length}): ${complex.join(', ')}`);
  return lines.join('\n');
};

if (require.main === module) {
  console.log(buildReport(process.argv.slice(2)));
}

module.exports = { analyze };

