const splitBatchFields = (batch) => String(batch).trim().split(/\s+/);

const parseBatchRecord = (batch) => {
  const fields = splitBatchFields(batch);
  if (fields.length !== 3) {
    throw new Error(`malformed batch entry: "${batch}"`);
  }
  const [cheeseType, rawMoisture, rawTemperature] = fields;
  const moisture = Number(rawMoisture);
  const temperature = Number(rawTemperature);
  if (!Number.isFinite(moisture) || !Number.isFinite(temperature)) {
    throw new Error(`non-numeric moisture or temperature in "${batch}"`);
  }
  return { cheeseType, moisture, temperature };
};

const classifyCheeseCategory = (moisture) => (moisture < 40 ? 'hard' : 'soft');

const computeAgingDays = (moisture, temperature) => {
  const baseAging = moisture * temperature;
  const category = classifyCheeseCategory(moisture);
  return category === 'soft' ? baseAging / 2 : baseAging;
};

const determineFlavorProfile = (agingDays) => (agingDays > 100 ? 'sharp' : 'mild');

function predict(batches) {
  return batches.map((batch) => {
    const record = parseBatchRecord(batch);
    const agingDays = computeAgingDays(record.moisture, record.temperature);
    return determineFlavorProfile(agingDays);
  });
}

const buildBatchSummary = (batch) => {
  const record = parseBatchRecord(batch);
  const category = classifyCheeseCategory(record.moisture);
  const agingDays = computeAgingDays(record.moisture, record.temperature);
  const flavor = determineFlavorProfile(agingDays);
  return {
    cheeseType: record.cheeseType,
    category,
    agingDays,
    flavor,
  };
};

const formatSummaryLine = (summary) => {
  const days = Number.isInteger(summary.agingDays)
    ? String(summary.agingDays)
    : summary.agingDays.toFixed(1);
  return `${summary.cheeseType} (${summary.category}): ages ${days} days -> ${summary.flavor}`;
};

const reportAllBatches = (batches) => batches
  .map(buildBatchSummary)
  .map(formatSummaryLine)
  .join('\n');

const main = () => {
  const batches = ['cheddar 30 5', 'brie 52 4', 'gouda 41 3', 'mozzarella 60 6'];
  console.log(reportAllBatches(batches));
  console.log(predict(batches).join(', '));
};

if (require.main === module) {
  main();
}

module.exports = { predict, buildBatchSummary, reportAllBatches };

