const validateShifts = (shifts) => {
  if (!Array.isArray(shifts)) {
    throw new TypeError("shifts must be an array of durations in seconds");
  }
  return shifts.map((raw, index) => {
    const seconds = Number(raw);
    if (!Number.isFinite(seconds) || seconds < 0) {
      throw new RangeError(`shift ${index} is not a valid duration: ${raw}`);
    }
    return seconds;
  });
};

const computeFatiguePoints = (seconds) => {
  const overtime = seconds - 40;
  if (overtime < 0) {
    return 0;
  }
  return Math.floor(overtime / 10);
};

const classifyInjuryRisk = (fatiguePoints) => (fatiguePoints > 5 ? "high" : "low");

const assessShift = (seconds) => {
  const points = computeFatiguePoints(seconds);
  return classifyInjuryRisk(points);
};

const countLowRisk = (risks) => risks.filter((risk) => risk === "low").length;

const computeEfficiency = (risks) => {
  if (risks.length === 0) {
    return 0;
  }
  const lowRisk = countLowRisk(risks);
  return (lowRisk / risks.length) * 100;
};

function evaluate(shifts) {
  const durations = validateShifts(shifts);
  const risks = durations.map(assessShift);
  return [risks, computeEfficiency(risks)];
}

const formatEfficiency = (efficiency) => {
  const rounded = Math.round(efficiency * 100) / 100;
  return `${rounded}%`;
};

const describeShift = (seconds) => {
  const points = computeFatiguePoints(seconds);
  const risk = classifyInjuryRisk(points);
  return `${seconds}s -> fatigue ${points}, risk ${risk}`;
};

const buildReport = (shifts) => {
  const durations = validateShifts(shifts);
  const [risks, efficiency] = evaluate(durations);
  const lines = durations.map(describeShift);
  const lowCount = countLowRisk(risks);
  lines.push(`low-risk shifts: ${lowCount} of ${risks.length}`);
  const summary = formatEfficiency(efficiency);
  lines.push(`penalty kill efficiency: ${summary}`);
  return lines.join("\n");
};

const main = (argv) => {
  const args = argv.slice(2);
  if (args.length === 0) {
    console.error("usage: node penalty-kill.js <shift-seconds>...");
    process.exitCode = 1;
    return;
  }
  console.log(buildReport(args));
};

main(process.argv);

module.exports = {
  evaluate,
  computeFatiguePoints,
  classifyInjuryRisk,
  buildReport,
};

