const KNOWN_ACTIONS = new Set(['heat', 'strike', 'quench']);
const COLD_THRESHOLD = 20;

const normalizeAction = (action) => String(action).trim().toLowerCase();

const isKnownAction = (action) => KNOWN_ACTIONS.has(action);

const validateActions = (actions) => {
  if (!Array.isArray(actions)) {
    throw new TypeError('forge expects an array of action strings');
  }
  const cleaned = actions.map((action) => normalizeAction(action));
  const unknown = cleaned.filter((action) => !isKnownAction(action));
  if (unknown.length > 0) {
    throw new Error(`unknown forge actions: ${unknown.join(', ')}`);
  }
  return cleaned;
};

const isTooCold = (state) => state.temperature < COLD_THRESHOLD;

const applyHeat = (state) => ({
  temperature: state.temperature + 50,
  quality: state.quality,
  quenched: state.quenched,
});

const applyStrike = (state) => {
  const penalty = isTooCold(state) ? 5 : 0;
  return {
    temperature: state.temperature - 5,
    quality: state.quality + 10 - penalty,
    quenched: state.quenched,
  };
};

const applyQuench = (state) => ({
  temperature: state.temperature,
  quality: state.quality,
  quenched: true,
});

const applyAction = (state, action) => {
  if (action === 'heat') {
    return applyHeat(state);
  }
  if (action === 'strike') {
    return applyStrike(state);
  }
  return applyQuench(state);
};

const classifyTier = (quality) => (quality > 50 ? 'masterwork' : 'standard');

function forge(actions) {
  const steps = validateActions(actions);
  let state = { temperature: 0, quality: 0, quenched: false };
  for (const action of steps) {
    if (state.quenched) {
      break;
    }
    state = applyAction(state, action);
  }
  return [classifyTier(state.quality), state.quality];
}

const formatForgeReport = (actions) => {
  const [tier, quality] = forge(actions);
  return `${actions.join(' > ')} => ${tier} (quality ${quality})`;
};

const runForgeBatch = (batches) => batches.map(
  (batch) => formatForgeReport(batch),
);

const orders = [
  ['heat', 'strike', 'quench'],
  ['strike', 'strike', 'quench'],
  ['heat', 'heat', 'strike', 'strike', 'strike', 'strike', 'strike', 'strike', 'quench'],
  ['heat', 'strike', 'quench', 'strike'],
];

for (const line of runForgeBatch(orders)) {
  console.log(line);
}

module.exports = {
  forge,
  classifyTier,
  formatForgeReport,
  runForgeBatch,
};

