const NUMBER_WORDS = {
  zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7,
  eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12, fifteen: 15, twenty: 20
};

const AXIS_STEPS = {
  north: [0, 1],
  south: [0, -1],
  east: [1, 0],
  west: [-1, 0]
};

const SOIL_DENSITY = 3;

const splitTokens = (instruction) => String(instruction).trim().toLowerCase().split(/\s+/);

const wordToNumber = (token) => {
  if (/^-?\d+(\.\d+)?$/.test(token)) return Number(token);
  if (Object.prototype.hasOwnProperty.call(NUMBER_WORDS, token)) return NUMBER_WORDS[token];
  throw new Error(`unknown distance: ${token}`);
};

const parseInstruction = (instruction) => {
  const tokens = splitTokens(instruction);
  if (tokens.length !== 2) throw new Error(`malformed instruction: ${instruction}`);
  const [heading, amount] = tokens;
  if (!Object.prototype.hasOwnProperty.call(AXIS_STEPS, heading)) {
    throw new Error(`unknown direction: ${heading}`);
  }
  return { heading, distance: wordToNumber(amount) };
};

const applyStep = (position, step) => {
  const [dx, dy] = AXIS_STEPS[step.heading];
  return {
    x: position.x + dx * step.distance,
    y: position.y + dy * step.distance
  };
};

const walkInstructions = (instructions) => {
  const steps = instructions.map(parseInstruction);
  return steps.reduce(applyStep, { x: 0, y: 0 });
};

const straightLineDistance = (position) => Math.hypot(position.x, position.y);

const diggingEffort = (distance) => distance * SOIL_DENSITY;

function decode(instructions) {
  if (!Array.isArray(instructions)) throw new TypeError('instructions must be an array');
  const finish = walkInstructions(instructions);
  const distance = straightLineDistance(finish);
  return [finish.x, finish.y, diggingEffort(distance)];
}

const formatReport = (instructions) => {
  const [x, y, effort] = decode(instructions);
  const rounded = Math.round(effort * 100) / 100;
  return `(${x}, ${y}) -> effort ${rounded}`;
};

const routes = [
  ['north 3', 'east 4'],
  ['north five', 'west twelve'],
  ['south 6', 'east 8', 'north 6']
];

routes.forEach((route) => {
  console.log(`${route.join(', ')} => ${formatReport(route)}`);
});

exports.decode = decode;
exports.parseInstruction = parseInstruction;
exports.wordToNumber = wordToNumber;
exports.diggingEffort = diggingEffort;
exports.formatReport = formatReport;

