const SCRATCH = "scratch";
const MIN_ANGLE = 0;
const MAX_ANGLE = 90;

const parseShotValue = (raw) => (typeof raw === "string" ? Number(raw.trim()) : raw);

const isNumericAngle = (value) => typeof value === "number" && Number.isFinite(value);

const reflectAngle = (angle) => Math.abs(angle);

const applySpinDeviation = (angle) => (angle > 45 ? angle + 2 : angle - 1);

const isWithinBounds = (angle) => angle >= MIN_ANGLE && angle <= MAX_ANGLE;

const isScratch = (value) => value === SCRATCH;

function adjustShot(raw) {
  const incoming = parseShotValue(raw);
  if (!isNumericAngle(incoming)) {
    return SCRATCH;
  }
  const deviated = applySpinDeviation(reflectAngle(incoming));
  return isWithinBounds(deviated) ? deviated : SCRATCH;
}

function analyze(shots) {
  if (!Array.isArray(shots)) {
    throw new TypeError("analyze expects an array of incoming angles");
  }
  return shots.map(adjustShot);
}

const formatAngle = (value) => (isScratch(value) ? SCRATCH : `${value}\u00b0`);

const countScratches = (results) => results.filter(isScratch).length;

const formatShotList = (shots) => shots.map((shot) => String(shot)).join(", ");

function buildReport(shots) {
  const results = analyze(shots);
  const rendered = results.map(formatAngle).join(", ");
  const scratches = countScratches(results);
  return `[${formatShotList(shots)}] -> [${rendered}] | scratches: ${scratches}`;
}

const summarizeRuns = (runs) => {
  const total = runs.reduce((sum, run) => sum + countScratches(analyze(run)), 0);
  const shotCount = runs.reduce((sum, run) => sum + run.length, 0);
  return `${shotCount} shots played, ${total} scratched`;
};

function main() {
  const runs = [
    [30, 100],
    [45, 46, 0, 90, 89],
    ["12", " 70 ", "wide", -30, 0.5],
  ];
  runs.forEach((run) => console.log(buildReport(run)));
  console.log(summarizeRuns(runs));
}

main();

module.exports = { analyze, adjustShot, buildReport, summarizeRuns };

