const CARBON_MATERIALS = ["leaves", "twigs"];
const NITROGEN_MATERIALS = ["grass", "scraps"];

function normalizeMaterial(material) {
    return String(material).trim().toLowerCase();
}

function isCarbonRich(material) {
    const name = normalizeMaterial(material);
    return CARBON_MATERIALS.includes(name);
}

function isNitrogenRich(material) {
    const name = normalizeMaterial(material);
    return NITROGEN_MATERIALS.includes(name);
}

function isKnownMaterial(material) {
    if (isCarbonRich(material)) {
        return true;
    }
    return isNitrogenRich(material);
}

function countCarbon(materials) {
    let total = 0;
    for (const material of materials) {
        if (isCarbonRich(material)) {
            total += 1;
        }
    }
    return total;
}

function countNitrogen(materials) {
    let total = 0;
    for (const material of materials) {
        if (isNitrogenRich(material)) {
            total += 1;
        }
    }
    return total;
}

function collectUnknown(materials) {
    const unknown = [];
    for (const material of materials) {
        if (!isKnownMaterial(material)) {
            unknown.push(String(material).trim());
        }
    }
    return unknown;
}

function roundRatio(value) {
    return Math.round(value * 100) / 100;
}

function computeRatio(carbonCount, nitrogenCount) {
    if (nitrogenCount === 0) {
        return carbonCount === 0 ? 0 : Infinity;
    }
    return roundRatio(carbonCount / nitrogenCount);
}

function evaluateHealth(ratio) {
    if (ratio === 2) {
        return "optimal";
    }
    return ratio < 2 ? "too wet" : "too dry";
}

function balance(materials) {
    if (!Array.isArray(materials)) {
        throw new TypeError("balance expects an array of material names");
    }
    const unknown = collectUnknown(materials);
    if (unknown.length > 0) {
        throw new Error(`unrecognized material(s): ${unknown.join(", ")}`);
    }
    const carbonCount = countCarbon(materials);
    const nitrogenCount = countNitrogen(materials);
    const ratio = computeRatio(carbonCount, nitrogenCount);
    const health = evaluateHealth(ratio);
    return [ratio, health];
}

function describeRatio(ratio) {
    return Number.isFinite(ratio) ? ratio.toFixed(1) : "infinite";
}

function formatReport(materials) {
    const [ratio, health] = balance(materials);
    const carbonCount = countCarbon(materials);
    const nitrogenCount = countNitrogen(materials);
    const summary = `${carbonCount}C : ${nitrogenCount}N`;
    return `${summary} -> ratio ${describeRatio(ratio)} (${health})`;
}

const piles = [
    ["leaves", "leaves", "grass"],
    ["leaves", "grass", "scraps"],
    ["twigs", "leaves", "Leaves", "grass"],
    ["twigs", "twigs"],
];

for (const pile of piles) {
    console.log(formatReport(pile));
}

module.exports = {
    balance,
    formatReport,
    computeRatio,
    evaluateHealth,
};

