const TRANSITION_TABLE = { fade: FADE_SECONDS, snap: SNAP_SECONDS };

const normalizeCue = (cue) => String(cue).trim().toLowerCase().replace(/\s+/g, " ");

const parseCue = (cue) => {
  const [color, transition] = normalizeCue(cue).split(" ");
  return { color, transition };
};

const isKnownColor = (color) => Object.prototype.hasOwnProperty.call(POWER_TABLE, color);

const isKnownTransition = (transition) =>
  Object.prototype.hasOwnProperty.call(TRANSITION_TABLE, transition);

const validateCue = (cue) => {
  const parsed = parseCue(cue);
  if (!isKnownColor(parsed.color)) {
    throw new Error(`unknown color in cue: "${cue}"`);
  }
  if (!isKnownTransition(parsed.transition)) {
    throw new Error(`unknown transition in cue: "${cue}"`);
  }
  return parsed;
};

const transitionDuration = (transition) => TRANSITION_TABLE[transition];

const powerLoad = (color) => POWER_TABLE[color];

function sequence(cues) {
  if (!Array.isArray(cues)) {
    throw new TypeError("sequence expects an array of cue strings");
  }
  let totalDuration = 0;
  let totalPower = 0;
  for (const cue of cues) {
    const { color, transition } = validateCue(cue);
    totalDuration += transitionDuration(transition);
    totalPower += powerLoad(color);
  }
  return [totalDuration, totalPower];
}

