const roundToMillimetre = (value) => Math.round(value * 10) / 10;

function formatCentimetres(value) {
  const rounded = roundToMillimetre(value);
  return `${rounded.toFixed(1)} cm`;
}

function validateBranchLengths(branches) {
  if (!Array.isArray(branches)) {
    throw new TypeError('prune expects an array of branch lengths');
  }
  branches.forEach((length, index) => {
    if (typeof length !== 'number' || !Number.isFinite(length) || length < 0) {
      throw new RangeError(`branch ${index} is not a valid length: ${length}`);
    }
  });
  return branches;
}

function computeAverageLength(branches) {
  const total = branches.reduce((sum, length) => sum + length, 0);
  return total / branches.length;
}

const isOvergrown = (length, average) => length > average * 1.5;

function suggestedCutLength(length, average) {
  return roundToMillimetre(length - average);
}

function prune(branches) {
  validateBranchLengths(branches);
  if (branches.length === 0) {
    return [[], 0];
  }
  const average = computeAverageLength(branches);
  const cuts = [];
  let untouched = 0;
  branches.forEach((length) => {
    if (isOvergrown(length, average)) {
      cuts.push(suggestedCutLength(length, average));
    } else {
      untouched += 1;
    }
  });
  return [cuts, untouched];
}

function describeCutList(cuts) {
  if (cuts.length === 0) {
    return 'no cuts needed';
  }
  const trims = cuts.map((cut) => `trim ${formatCentimetres(cut)}`);
  return trims.join(', ');
}

function formatPruningReport(branches, result) {
  const [cuts, untouched] = result;
  const measured = branches.map((length) => formatCentimetres(length));
  const lines = [`branches: ${measured.join(' | ')}`];
  if (branches.length > 0) {
    const average = computeAverageLength(branches);
    lines.push(`average: ${formatCentimetres(average)}`);
  }
  const plan = describeCutList(cuts);
  lines.push(`plan: ${plan}`);
  lines.push(`untouched branches: ${untouched}`);
  return lines.join('\n');
}

function parseBranchLengths(text) {
  const parts = text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  const numbers = parts.map(Number);
  return validateBranchLengths(numbers);
}

const trees = ['10, 10, 25', '12, 12, 12, 12', '5, 8, 40, 9, 6'];
trees.forEach((description) => {
  const branches = parseBranchLengths(description);
  const result = prune(branches);
  const report = formatPruningReport(branches, result);
  console.log(report);
  console.log('---');
});

module.exports = {
  prune,
  parseBranchLengths,
  formatPruningReport,
};

