const SAFETY_MARGIN_FEET = 10;
const FEET_PER_BOLT = 20;

const isValidDepth = (value) =>
  typeof value === 'number' && Number.isFinite(value) && value > 0;

function validateDepths(depths) {
  if (!Array.isArray(depths)) {
    throw new TypeError('plan() expects an array of drop depths');
  }
  const bad = depths.findIndex((depth) => !isValidDepth(depth));
  if (bad !== -1) {
    throw new RangeError(`depth at index ${bad} is not a positive number`);
  }
  return depths;
}

function ropeLengthFor(depth) {
  return depth + SAFETY_MARGIN_FEET;
}

function boltsFor(ropeLength) {
  return Math.ceil(ropeLength / FEET_PER_BOLT);
}

function describeDrop(depth) {
  const rope = ropeLengthFor(depth);
  return { depth, rope, bolts: boltsFor(rope) };
}

function buildDropTable(depths) {
  return depths.map(describeDrop);
}

function sumTotals(drops) {
  return drops.reduce(
    (totals, drop) => [totals[0] + drop.rope, totals[1] + drop.bolts],
    [0, 0]
  );
}

function plan(depths) {
  const clean = validateDepths(depths);
  const drops = buildDropTable(clean);
  return sumTotals(drops);
}

function formatDropLine(drop, index) {
  const label = `Drop ${index + 1}`.padEnd(8);
  return `${label} ${String(drop.depth).padStart(4)} ft deep -> ` +
    `${String(drop.rope).padStart(4)} ft rope, ${drop.bolts} bolt(s)`;
}

function formatPlanReport(depths) {
  const clean = validateDepths(depths);
  const drops = buildDropTable(clean);
  const lines = drops.map(formatDropLine);
  const [totalRope, totalBolts] = sumTotals(drops);
  lines.push(`Total:   ${totalRope} ft of rope, ${totalBolts} bolts`);
  return lines.join('\n');
}

function main() {
  const expeditions = [[30, 55], [9.5, 100, 61], [15]];
  expeditions.forEach((depths) => {
    console.log(formatPlanReport(depths));
    const totals = plan(depths);
    console.log(`plan(${JSON.stringify(depths)}) = ${JSON.stringify(totals)}\n`);
  });
}

if (typeof require !== 'undefined' && require.main === module) {
  main();
}

module.exports = { plan, formatPlanReport, ropeLengthFor, boltsFor };

