const isValidEncounter = (value) =>
  typeof value === "number" && Number.isInteger(value) && value > 0;

const validateEncounters = (encounters) => {
  if (!Array.isArray(encounters)) {
    throw new TypeError("encounters must be an array of difficulty levels");
  }
  const bad = encounters.filter((value) => !isValidEncounter(value));
  if (bad.length > 0) {
    throw new RangeError(`invalid encounter levels: ${bad.join(", ")}`);
  }
  return encounters;
};

const computeBaseGold = (level) => level * 50;

const hasMagicDrop = (level) => level % 2 === 0;

const determineRarityTier = (level) => (level < 5 ? "uncommon" : "rare");

function loot(encounters) {
  const levels = validateEncounters(encounters);
  let totalGold = 0;
  const rarities = [];
  for (const level of levels) {
    totalGold += computeBaseGold(level);
    if (hasMagicDrop(level)) {
      rarities.push(determineRarityTier(level));
    }
  }
  return [totalGold, rarities];
}

const countByRarity = (rarities) =>
  rarities.reduce((tally, tier) => {
    tally[tier] = (tally[tier] || 0) + 1;
    return tally;
  }, {});

const describeHaul = (rarities) => {
  const tally = countByRarity(rarities);
  const tiers = Object.keys(tally).sort();
  if (tiers.length === 0) {
    return "no magic items";
  }
  return tiers.map((tier) => `${tally[tier]} ${tier}`).join(", ");
};

const formatLootReport = (encounters) => {
  const [gold, rarities] = loot(encounters);
  const haul = describeHaul(rarities);
  return `[${encounters.join(", ")}] -> ${gold} gp, ${haul}`;
};

function main() {
  const sessions = [
    [3, 6],
    [1, 2, 4, 10],
    [5, 7, 9],
    [8],
