    .map((session) => loot(session)[0])
    .reduce((sum, gold) => sum + gold, 0);
  console.log(`campaign total: ${campaignTotal} gp`);
}

main();

module.exports = {
  loot,
  computeBaseGold,
  hasMagicDrop,
  determineRarityTier,
  formatLootReport,
};

