const SHAPE_AREAS = { square: 10, triangle: 5 };
const COLOR_RATES = { blue: 2, red: 3 };

const normalizeSpec = (spec) => String(spec).trim().toLowerCase().replace(/\s+/g, ' ');

const parsePanelSpec = (spec) => {
  const parts = normalizeSpec(spec).split(' ');
  if (parts.length !== 2) {
    throw new Error(`panel spec must be "<shape> <color>": got "${spec}"`);
  }
  return { shape: parts[0], color: parts[1] };
};

const getShapeArea = (shape) => {
  const area = SHAPE_AREAS[shape];
  if (area === undefined) {
    throw new Error(`unknown shape: ${shape}`);
  }
  return area;
};

const getColorRate = (color) => {
  const rate = COLOR_RATES[color];
  if (rate === undefined) {
    throw new Error(`unknown color: ${color}`);
  }
  return rate;
};

const measurePanel = (spec) => {
  const { shape, color } = parsePanelSpec(spec);
  const area = getShapeArea(shape);
  return { shape, color, area, cost: area * getColorRate(color) };
};

function design(panels) {
  if (!Array.isArray(panels)) {
    throw new TypeError('design expects an array of panel specs');
  }
  return panels.reduce(
    (totals, spec) => {
      const panel = measurePanel(spec);
      return [totals[0] + panel.area, totals[1] + panel.cost];
    },
    [0, 0]
  );
}

const describePanel = (spec) => {
  const panel = measurePanel(spec);
  return `${panel.shape} (${panel.color}): ${panel.area} sq in, $${panel.cost}`;
};

const formatDesignReport = (panels) => {
  const [totalArea, totalCost] = design(panels);
  const lines = panels.map((spec) => `  - ${describePanel(spec)}`);
  lines.push(`  total: ${totalArea} sq in for $${totalCost}`);
  return lines.join('\n');
};

const runLayouts = (layouts) => {
  Object.keys(layouts).forEach((name) => {
    console.log(`${name}:`);
    console.log(formatDesignReport(layouts[name]));
  });
};

runLayouts({
  'simple window': ['square blue', 'triangle red'],
  'rose accent': ['triangle red', 'triangle blue', 'square red', 'square blue'],
});

module.exports = design;

