const VALID_DIRECTIONS = ["mountain", "valley"];
const VALID_MULTIPLICITIES = ["single", "double"];

const normalizeInstruction = (raw) => String(raw).trim().toLowerCase().split(/\s+/);

const parseCrease = (raw) => {
  const [direction, multiplicity] = normalizeInstruction(raw);
  if (!VALID_DIRECTIONS.includes(direction)) {
    throw new Error(`unknown crease direction: ${direction}`);
  }
  if (!VALID_MULTIPLICITIES.includes(multiplicity)) {
    throw new Error(`unknown crease multiplicity: ${multiplicity}`);
  }
  return { direction, multiplicity };
};

const isDoubleFold = (crease) => crease.multiplicity === "double";

const isMountainFold = (crease) => crease.direction === "mountain";

const stepValueOf = (crease) => {
  return isDoubleFold(crease) ? 2 : 1;
};

const stressValueOf = (crease) => {
  return isMountainFold(crease) ? 5 : 0;
};

const sumStepCount = (creases) => {
  return creases.reduce((total, crease) => total + stepValueOf(crease), 0);
};

const sumStressLevel = (creases) => {
  return creases.reduce((total, crease) => total + stressValueOf(crease), 0);
};

const classifyDifficulty = (steps, stress) => (steps > 10 || stress > 20 ? "expert" : "beginner");

function fold(patterns) {
  if (!Array.isArray(patterns)) {
    throw new TypeError("fold expects an array of crease instructions");
  }
  const creases = patterns.map(parseCrease);
  const steps = sumStepCount(creases);
  const stress = sumStressLevel(creases);
  return [steps, classifyDifficulty(steps, stress)];
}

const describePattern = (patterns) => {
  const creases = patterns.map(parseCrease);
  const mountains = creases.filter(isMountainFold).length;
  const doubles = creases.filter(isDoubleFold).length;
  return `${creases.length} creases (${mountains} mountain, ${doubles} double)`;
};

const formatReport = (patterns) => {
  const [steps, difficulty] = fold(patterns);
  return `${describePattern(patterns)} -> ${steps} steps, ${difficulty}`;
};

function main() {
  const samples = [
    ["mountain double", "valley single"],
    ["valley single", "valley single", "mountain double", "mountain double"],
    [
      "mountain double",
      "mountain double",
      "mountain double",
      "mountain single",
      "valley double",
      "valley double",
    ],
  ];
  samples.forEach((sample) => console.log(formatReport(sample)));
  try {
    fold(["mountain triple"]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = {
  fold,
  parseCrease,
  classifyDifficulty,
  formatReport,
};

