const KNOWN_TOXICITY = { root: 10, leaf: 5 };
const PREPARATION_FACTORS = { crushed: 0.5, diced: 2 };

const parseIngredient = (entry) => {
  const parts = String(entry).trim().toLowerCase().split(/\s+/);
  return { name: parts[0], action: parts[1] };
};

const baseToxicityOf = (name) => {
  if (!Object.prototype.hasOwnProperty.call(KNOWN_TOXICITY, name)) {
    throw new Error(`unknown ingredient: ${name}`);
  }
  return KNOWN_TOXICITY[name];
};

const preparationFactorOf = (action) => {
  if (!Object.prototype.hasOwnProperty.call(PREPARATION_FACTORS, action)) {
    throw new Error(`unknown preparation: ${action}`);
  }
  return PREPARATION_FACTORS[action];
};

const itemToxicity = (entry) => {
  const { name, action } = parseIngredient(entry);
  const base = baseToxicityOf(name);
  return base * preparationFactorOf(action);
};

const classifySafety = (total) => (total > 20 ? "lethal" : "safe");

const validateIngredientList = (ingredients) => {
  if (!Array.isArray(ingredients)) {
    throw new TypeError("ingredients must be an array of strings");
  }
  const bad = ingredients.filter((entry) => typeof entry !== "string");
  if (bad.length > 0) {
    throw new TypeError(`non-string ingredient entries: ${bad.length}`);
  }
};

function brew(ingredients) {
  validateIngredientList(ingredients);
  const total = ingredients.reduce((sum, entry) => sum + itemToxicity(entry), 0);
  return [total, classifySafety(total)];
}

const describeIngredient = (entry) => {
  const { name, action } = parseIngredient(entry);
  return `${name} (${action}) -> ${itemToxicity(entry)}`;
};

const formatBrewReport = (ingredients) => {
  const [total, flag] = brew(ingredients);
  const lines = ingredients.map((entry) => `  ${describeIngredient(entry)}`);
  lines.push(`  total: ${total} [${flag}]`);
  return lines.join("\n");
};

const readBatchFromArgv = (argv) => argv.slice(2);

const batch = readBatchFromArgv(process.argv);
if (batch.length > 0) {
  console.log(formatBrewReport(batch));
}

module.exports = { brew };

