const splitFields = (line) => String(line).split(',').map((part) => part.trim());

const parsePriorityValue = (raw) => {
  const value = Number.parseFloat(raw);
  return Number.isFinite(value) ? value : 0;
};

const parseDurationValue = (raw) => {
  const value = Number.parseFloat(raw);
  if (!Number.isFinite(value)) {
    return 0;
  }
  return value > 0 ? value : 0;
};

function parseProposal(line) {
  const [priority, duration, target] = splitFields(line);
  return {
    priority: parsePriorityValue(priority),
    duration: parseDurationValue(duration),
    target: target === undefined ? '' : target
  };
}

const isClassifiedTarget = (target) => /classified/i.test(target);

const isUsableProposal = (proposal) => {
  if (isClassifiedTarget(proposal.target)) {
    return false;
  }
  return proposal.target.length > 0 && proposal.duration > 0;
};

const comparePriorityDesc = (a, b) => {
  if (b.priority !== a.priority) {
    return b.priority - a.priority;
  }
  return a.duration - b.duration;
};

const sortByPriority = (proposals) => {
  const ordered = proposals.slice();
  ordered.sort(comparePriorityDesc);
  return ordered;
};

function allocate(proposals, capacity) {
  const parsed = proposals.map(parseProposal);
  const usable = parsed.filter(isUsableProposal);
  const ordered = sortByPriority(usable);
  const accepted = [];
  let used = 0;
  for (const proposal of ordered) {
    if (used + proposal.duration > capacity) {
      break;
    }
    used += proposal.duration;
    accepted.push(proposal.target);
  }
  return accepted;
}

const formatDuration = (minutes) => `${minutes.toFixed(1)} min`;

const buildScheduleReport = (proposals, capacity) => {
  const targets = allocate(proposals, capacity);
  const lookup = new Map();
  for (const line of proposals) {
    const proposal = parseProposal(line);
    lookup.set(proposal.target, proposal.duration);
  }
  const total = targets.reduce((sum, target) => sum + lookup.get(target), 0);
  const lines = targets.map((target, index) => `${index + 1}. ${target} (${lookup.get(target)} min)`);
  const spent = formatDuration(total);
  lines.push(`used ${spent} of ${formatDuration(capacity)}`);
  return lines.join('\n');
};

const requests = [
  '3, 45, Andromeda Core',
  '9, 30, Vega Transit',
  '5, 20.5, CLASSIFIED site 4',
  '7, 60, Orion Nebula',
  '5, 15, Kepler 22b',
  '1, 90, Deep Field South'
];

console.log(allocate(requests, 110).join(', '));
console.log(buildScheduleReport(requests, 110));

module.exports = {
  allocate,
  parseProposal,
  isClassifiedTarget,
  buildScheduleReport
};

