const parseIsoDate = (text) => {
  const parts = text.trim().split("-").map(Number);
  if (parts.length !== 3 || parts.some((n) => !Number.isInteger(n))) {
    throw new Error(`invalid date: ${text}`);
  }
  const [year, month, day] = parts;
  return Date.UTC(year, month - 1, day);
};

const addDaysTo = (timestamp, days) => timestamp + days * 86400000;

const daysBetween = (from, to) => Math.round((to - from) / 86400000);

const parseBatch = (line) => {
  const fields = line.split(",").map((field) => field.trim());
  if (fields.length !== 3) {
    throw new Error(`malformed batch record: ${line}`);
  }
  const [flavor, produced, shelfLife] = fields;
  const days = Number(shelfLife);
  if (!Number.isInteger(days) || days < 0) {
    throw new Error(`invalid shelf life for ${flavor}: ${shelfLife}`);
  }
  const stamp = parseIsoDate(produced);
  return { flavor, produced: stamp, shelfLife: days };
};

const expirationOf = (batch) => {
  return addDaysTo(batch.produced, batch.shelfLife);
};

const daysLeftFor = (batch, today) => {
  const expires = expirationOf(batch);
  return daysBetween(today, expires);
};

function manage(batches, date) {
  const today = parseIsoDate(date);
  const rows = [];
  for (const line of batches) {
    const batch = parseBatch(line);
    const remaining = daysLeftFor(batch, today);
    if (remaining < 0) continue;
    rows.push([batch.flavor, remaining <= 3 ? "discount" : "keep"]);
  }
  return rows;
}

const formatReport = (rows) =>
  rows.map(([flavor, status]) => `${flavor.padEnd(14, ".")} ${status}`).join("\n");

const summarizeStatuses = (rows) =>
  rows.reduce((counts, [, status]) => {
    counts[status] = (counts[status] || 0) + 1;
    return counts;
  }, {});

function main() {
  const today = "2024-06-10";
  const inventory = [
    "vanilla, 2024-05-01, 60",
    "strawberry, 2024-06-01, 7",
    "pistachio, 2024-04-20, 30",
    "mint chip, 2024-06-08, 5",
    "mango sorbet, 2024-03-15, 90",
  ];
  const rows = manage(inventory, today);
  console.log(formatReport(rows));
  const counts = summarizeStatuses(rows);
  const summary = ["keep", "discount"]
    .filter((status) => counts[status])
    .map((status) => `${status}: ${counts[status]}`)
    .join(", ");
  console.log(`\nAs of ${today} — ${summary}`);
  const shortlist = rows
    .filter(([, status]) => status === "discount")
    .map(([flavor]) => flavor);
  if (shortlist.length) {
    console.log(`Discount now: ${shortlist.join(", ")}`);
  }
}

main();

module.exports = { manage, parseBatch, daysLeftFor, formatReport, summarizeStatuses };

