const WEAR_LIMIT = 1000;
const HOT_TRACK_THRESHOLD = 40;

const splitLapFields = (lap) => String(lap).trim().split(/\s+/);

const parseNumericField = (field, label, lapNumber) => {
  const value = Number(field);
  if (!Number.isFinite(value)) {
    throw new Error(`Lap ${lapNumber}: ${label} is not a number ("${field}")`);
  }
  return value;
};

const parseLapRecord = (lap, lapNumber) => {
  const fields = splitLapFields(lap);
  if (fields.length !== 3) {
    throw new Error(`Lap ${lapNumber}: expected 3 values, got ${fields.length}`);
  }
  const speed = parseNumericField(fields[0], "speed", lapNumber);
  const cornering = parseNumericField(fields[1], "cornering force", lapNumber);
  const temperature = parseNumericField(fields[2], "track temperature", lapNumber);
  return { speed, cornering, temperature };
};

const isHotTrack = (temperature) => temperature > HOT_TRACK_THRESHOLD;

const computeLapWear = ({ speed, cornering, temperature }) => {
  const baseWear = speed * cornering;
  return isHotTrack(temperature) ? baseWear * 1.1 : baseWear;
};

function analyze(laps) {
  let totalWear = 0;
  for (let index = 0; index < laps.length; index += 1) {
    const lapNumber = index + 1;
    const record = parseLapRecord(laps[index], lapNumber);
    totalWear += computeLapWear(record);
    if (totalWear > WEAR_LIMIT) {
      return lapNumber;
    }
  }
  return -1;
}

const buildWearTable = (laps) =>
  laps.map((lap, index) => {
    const record = parseLapRecord(lap, index + 1);
    return { lapNumber: index + 1, wear: computeLapWear(record) };
  });

const formatWearRow = ({ lapNumber, wear }, runningTotal) =>
  `lap ${String(lapNumber).padStart(2)}: wear ${wear.toFixed(1).padStart(8)}` +
  `  total ${runningTotal.toFixed(1).padStart(9)}`;

const reportStint = (laps) => {
  const lines = [];
  let runningTotal = 0;
  for (const row of buildWearTable(laps)) {
    runningTotal += row.wear;
    lines.push(formatWearRow(row, runningTotal));
  }
  const limitLap = analyze(laps);
  lines.push(
    limitLap === -1
      ? `tyre limit never exceeded (final total ${runningTotal.toFixed(1)})`
      : `tyre limit exceeded on lap ${limitLap}`
  );
  return lines.join("\n");
};

const stint = [
  "120 3.2 38",
  "135 3.5 41",
  "140 3.6 44",
  "118 2.9 39",
];

console.log(reportStint(stint));
console.log(analyze(["10 2 20", "11 2 25"]));

module.exports = { analyze, parseLapRecord, computeLapWear, reportStint };

