const IDEAL_LEVELS = [50, 30, 20];
const STANDARD_MIX = [5, 3, 2];

const parseLevel = (part, test) => {
  const value = Number(part.trim());
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`reading "${test}" contains an invalid level: "${part}"`);
  }
  return value;
};

const parseReading = (test) => {
  const parts = String(test).trim().split('-');
  if (parts.length !== IDEAL_LEVELS.length) {
    throw new Error(`reading "${test}" must have ${IDEAL_LEVELS.length} values`);
  }
  return parts.map((part) => parseLevel(part, test));
};

const deficiencyOf = (ideal, actual) => Math.max(0, ideal - actual);

const computeDeficiencies = (levels) =>
  IDEAL_LEVELS.map((ideal, index) => deficiencyOf(ideal, levels[index]));

const largestDeficiency = (values) => Math.max(...values);

const roundAmount = (amount) => Math.round(amount * 100) / 100;

const scaleStandardMix = (peak) => {
  const reference = largestDeficiency(STANDARD_MIX);
  const factor = peak / reference;
  return STANDARD_MIX.map((portion) => roundAmount(portion * factor));
};

const formatMix = (amounts) => amounts.join('-');

const blendFor = (test) => {
  const levels = parseReading(test);
  const deficiencies = computeDeficiencies(levels);
  const peak = largestDeficiency(deficiencies);
  const amounts = scaleStandardMix(peak);
  return formatMix(amounts);
};

function blend(tests) {
  if (!Array.isArray(tests)) {
    throw new TypeError('blend expects a list of strings');
  }
  return tests.map(blendFor);
}

const buildReportLine = (test, mix) => {
  const levels = parseReading(test);
  const deficiencies = computeDeficiencies(levels);
  const peak = largestDeficiency(deficiencies);
  const deficits = formatMix(deficiencies);
  return `${test} -> ${mix} (deficits ${deficits}, peak ${peak})`;
};

const runReport = (tests) => {
  const mixes = blend(tests);
  return tests.map((test, index) => buildReportLine(test, mixes[index]));
};

if (require.main === module) {
  const tests = process.argv.slice(2);
  const lines = runReport(tests);
  lines.forEach((line) => console.log(line));
}

module.exports = {
  blend,
  parseReading,
  computeDeficiencies,
  scaleStandardMix,
  runReport,
};

