const POSITIVE_EVENTS = ['rally', 'endorsement', 'debate-win', 'fundraiser', 'ad-blitz'];
const SCANDAL_EVENTS = ['scandal', 'gaffe', 'leak', 'indictment'];

const normalizeToken = (token) => String(token).trim().toLowerCase();

const isPositiveEvent = (event) => POSITIVE_EVENTS.includes(normalizeToken(event));

const isScandalEvent = (event) => SCANDAL_EVENTS.includes(normalizeToken(event));

function parseEventList(fields) {
  return fields
    .map((field) => field.trim())
    .filter((field) => field.length > 0);
}

function parseBaseVotes(raw) {
  const votes = Number.parseInt(String(raw).trim(), 10);
  if (!Number.isFinite(votes) || votes < 0) {
    throw new Error(`invalid base vote count: ${raw}`);
  }
  return votes;
}

function parseCandidateRecord(line) {
  const fields = String(line).split(':');
  if (fields.length < 2) {
    throw new Error(`malformed candidate record: ${line}`);
  }
  const name = fields[0].trim();
  if (name.length === 0) {
    throw new Error(`missing candidate name: ${line}`);
  }
  return {
    name,
    baseVotes: parseBaseVotes(fields[1]),
    events: parseEventList(fields.slice(2)),
  };
}

function computeModifier(events) {
  return events.reduce((modifier, event) => {
    if (isPositiveEvent(event)) {
      return modifier + 0.05;
    }
    if (isScandalEvent(event)) {
      return modifier - 0.10;
    }
    return modifier;
  }, 1);
}

const applyModifier = (baseVotes, modifier) => Math.max(0, Math.round(baseVotes * modifier));

function buildCandidateReport(line) {
  const record = parseCandidateRecord(line);
  const modifier = computeModifier(record.events);
  return {
    name: record.name,
    baseVotes: record.baseVotes,
    modifier,
    finalVotes: applyModifier(record.baseVotes, modifier),
  };
}

function findLeadingCandidate(reports) {
  return reports.reduce((leader, report) => (report.finalVotes > leader.finalVotes ? report : leader));
}

function formatReportLine(report) {
  const percent = `${(report.modifier * 100).toFixed(1)}%`;
  return `${report.name}: ${report.baseVotes} base x ${percent} => ${report.finalVotes}`;
}

function simulate(data) {
  if (!Array.isArray(data) || data.length === 0) {
    throw new Error('no candidate data supplied');
  }
  const reports = data.map(buildCandidateReport);
  return findLeadingCandidate(reports).name;
}

const electionData = [
  'Alice Warren:12000:rally:endorsement:debate-win',
  'Bob Keeler:15000:scandal:rally:gaffe',
  'Cora Diaz:11500:fundraiser:ad-blitz:rally:endorsement',
];

electionData
  .map(buildCandidateReport)
  .forEach((report) => console.log(formatReportLine(report)));
console.log(`Winner: ${simulate(electionData)}`);

module.exports = { simulate, buildCandidateReport, computeModifier, formatReportLine };

