const GAP = 2;

const parseWidthValue = (text) => {
  const value = Number(String(text).trim());
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`invalid width: ${text}`);
  }
  return value;
};

const parsePainting = (entry) => {
  const parts = String(entry).split(',');
  if (parts.length !== 2) {
    throw new Error(`expected "width,style" but got: ${entry}`);
  }
  const style = parts[1].trim();
  if (style === '') {
    throw new Error(`missing style in: ${entry}`);
  }
  return { width: parseWidthValue(parts[0]), style };
};

const groupPaintingsByStyle = (paintings) => {
  const groups = new Map();
  for (const entry of paintings) {
    const painting = parsePainting(entry);
    const widths = groups.get(painting.style);
    if (widths) {
      widths.push(painting.width);
    } else {
      groups.set(painting.style, [painting.width]);
    }
  }
  return groups;
};

const computeGroupWidth = (widths) =>
  widths.reduce((sum, w) => sum + w, 0) + GAP * (widths.length - 1);

const centerStartCoordinate = (groupWidth, wallWidth) => (wallWidth - groupWidth) / 2;

const formatCoordinate = (value) => {
  const rounded = Math.round(value * 100) / 100;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(2);
};

function arrange(paintings, width) {
  const wallWidth = parseWidthValue(width);
  const groups = groupPaintingsByStyle(paintings);
  const starts = [];
  for (const widths of groups.values()) {
    starts.push(centerStartCoordinate(computeGroupWidth(widths), wallWidth));
  }
  return starts;
}

const describeArrangement = (paintings, width) => {
  const starts = arrange(paintings, width);
  const styles = [...groupPaintingsByStyle(paintings).entries()];
  return styles.map(([style, widths], index) => {
    const span = computeGroupWidth(widths);
    const from = formatCoordinate(starts[index]);
    const to = formatCoordinate(starts[index] + span);
    return `${style}: ${widths.length} painting(s), span ${formatCoordinate(span)}, ${from} -> ${to}`;
  });
};

const samples = ['30,impressionist', '18,cubist', '22,impressionist', '40,surreal', '16,cubist'];
for (const line of describeArrangement(samples, 120)) {
  console.log(line);
}
console.log(arrange(samples, 120).map(formatCoordinate).join(' '));

module.exports = { arrange, describeArrangement };

