const parseSighting = (line) => {
  const parts = String(line).split(',').map((piece) => piece.trim());
  if (parts.length !== 3) return null;
  const [animal, zone, rawProbability] = parts;
  const probability = Number(rawProbability);
  if (!animal || !zone || !Number.isFinite(probability)) return null;
  return { animal, zone, probability };
};

const isHighProbability = (sighting) => sighting.probability >= 50;

const parseSightings = (sightings) => {
  if (!Array.isArray(sightings)) return [];
  return sightings
    .map(parseSighting)
    .filter((entry) => entry !== null);
};

const groupByZone = (entries) => {
  const zones = new Map();
  entries.forEach((entry) => {
    const animals = zones.get(entry.zone) || [];
    animals.push(entry.animal);
    zones.set(entry.zone, animals);
  });
  return zones;
};

const compareZones = (left, right) => {
  if (right[1].length !== left[1].length) return right[1].length - left[1].length;
  return left[0].localeCompare(right[0]);
};

const sortZonesByCount = (zones) => {
  const ranking = [...zones.entries()];
  return ranking.sort(compareZones);
};

const normalizeDays = (days) => {
  const count = Math.floor(Number(days));
  return Number.isFinite(count) && count > 0 ? count : 0;
};

const allocateDays = (rankedZones, days) => {
  const schedule = [];
  for (let index = 0; index < rankedZones.length && schedule.length < days; index += 1) {
    schedule.push(rankedZones[index][0]);
  }
  return schedule;
};

function plan(sightings, days) {
  const parsed = parseSightings(sightings);
  const promising = parsed.filter(isHighProbability);
  const zones = groupByZone(promising);
  const ranked = sortZonesByCount(zones);
  const budget = normalizeDays(days);
  return allocateDays(ranked, budget);
}

const describeZone = (zone, zones) => {
  const animals = zones.get(zone) || [];
  return `${zone}: ${animals.join(', ')}`;
};

const formatItinerary = (sightings, days) => {
  const itinerary = plan(sightings, days);
  if (itinerary.length === 0) return 'No zones worth visiting.';
  const parsed = parseSightings(sightings);
  const promising = parsed.filter(isHighProbability);
  const zones = groupByZone(promising);
  return itinerary
    .map((zone, index) => `Day ${index + 1} - ${describeZone(zone, zones)}`)
    .join('\n');
};

const field = [
  'elephant, savanna, 80',
  'lion, savanna, 65',
  'pangolin, savanna, 12',
  'tapir, wetland, 55',
  'heron, wetland, 90',
  'jaguar, rainforest, 51',
  'harpy eagle, rainforest, 30',
  'ibex, cliffs, 74',
];

console.log(formatItinerary(field, 3));

module.exports = {
  plan,
  parseSighting,
  parseSightings,
  groupByZone,
  formatItinerary,
};

