const LOW_AMPLITUDE_LIMIT = 0.5;
const BIOLOGICAL_FREQUENCY_LIMIT = 200;
const MECHANICAL_FREQUENCY_LIMIT = 500;
const CATEGORY_NAMES = ['biological', 'mechanical', 'geological'];

const splitPingFields = (ping) => String(ping).split(',').map((field) => field.trim());

const parseNumericField = (field, label, index) => {
  const value = Number(field);
  if (field === '' || !Number.isFinite(value)) {
    throw new Error(`ping ${index}: ${label} "${field}" is not a number`);
  }
  return value;
};

const parsePing = (ping, index) => {
  if (typeof ping !== 'string') {
    throw new TypeError(`ping ${index}: expected a string, got ${typeof ping}`);
  }
  const fields = splitPingFields(ping);
  if (fields.length !== 2) {
    throw new Error(`ping ${index}: expected "frequency,amplitude", got "${ping}"`);
  }
  const frequency = parseNumericField(fields[0], 'frequency', index);
  const amplitude = parseNumericField(fields[1], 'amplitude', index);
  return { frequency, amplitude };
};

const isLowAmplitude = (amplitude) => amplitude < LOW_AMPLITUDE_LIMIT;

const isBiologicalPing = (reading) =>
  reading.frequency < BIOLOGICAL_FREQUENCY_LIMIT && isLowAmplitude(reading.amplitude);

const isMechanicalPing = (reading) => reading.frequency > MECHANICAL_FREQUENCY_LIMIT;

const classifyReading = (reading) => {
  if (isBiologicalPing(reading)) {
    return 'biological';
  }
  if (isMechanicalPing(reading)) {
    return 'mechanical';
  }
  return 'geological';
};

function classify(pings) {
  if (!Array.isArray(pings)) {
    throw new TypeError('pings must be an array of strings');
  }
  const counts = { biological: 0, mechanical: 0, geological: 0 };
  pings.forEach((ping, index) => {
    const reading = parsePing(ping, index);
    const category = classifyReading(reading);
    counts[category] += 1;
  });
  return [counts.biological, counts.mechanical, counts.geological];
}

const formatPercentage = (count, total) => {
  if (total === 0) {
    return '0.0%';
  }
  return `${((count / total) * 100).toFixed(1)}%`;
};

const buildReportLines = (counts) => {
  const total = counts.reduce((sum, count) => sum + count, 0);
  const lines = CATEGORY_NAMES.map(
    (name, index) => `${name}: ${counts[index]} (${formatPercentage(counts[index], total)})`
  );
  lines.push(`total pings: ${total}`);
  return lines;
};

const counts = classify(process.argv.slice(2));
console.log(counts.join(' '));
buildReportLines(counts).forEach((line) => console.log(line));

