const parseFlowerRecord = (record) => {
  const parts = record.split(',').map((part) => part.trim());
  return { name: parts[0], season: parts[1], zone: parts[2] };
};

const normalizeSeason = (season) => String(season || '').trim().toLowerCase();

const buildInterestSet = (interests) => {
  const wanted = new Set();
  for (const interest of interests) {
    wanted.add(normalizeSeason(interest));
  }
  return wanted;
};

const isValidRecord = (flower) => {
  const parsed = parseFlowerRecord(flower);
  return Boolean(parsed.name && parsed.season && parsed.zone);
};

const matchesInterest = (flower, wanted) => wanted.has(normalizeSeason(flower.season));

const collectUniqueZones = (flowers) => {
  const zones = new Set();
  for (const flower of flowers) {
    zones.add(flower.zone);
  }
  return [...zones];
};

const sortZonesAlphabetically = (zones) => [...zones].sort((a, b) => a.localeCompare(b));

function guide(flowers, interests) {
  const wanted = buildInterestSet(interests);
  const matched = flowers
    .filter(isValidRecord)
    .map(parseFlowerRecord)
    .filter((flower) => matchesInterest(flower, wanted));
  const zones = collectUniqueZones(matched);
  return sortZonesAlphabetically(zones);
}

const describeRoute = (zones) => {
  if (zones.length === 0) {
    return 'No zones match the selected seasons.';
  }
  return `Walking route: ${zones.join(' -> ')}`;
};

const countFlowersPerZone = (flowers, interests) => {
  const wanted = buildInterestSet(interests);
  const tally = new Map();
  for (const record of flowers.filter(isValidRecord)) {
    const flower = parseFlowerRecord(record);
    if (matchesInterest(flower, wanted)) {
      tally.set(flower.zone, (tally.get(flower.zone) || 0) + 1);
    }
  }
  return tally;
};

const formatZoneReport = (flowers, interests) => {
  const tally = countFlowersPerZone(flowers, interests);
  const zones = guide(flowers, interests);
  return zones.map((zone) => `${zone}: ${tally.get(zone)} bloom(s)`).join('\n');
};

const garden = [
  'Tulip, Spring, Zone B',
  'Sunflower, Summer, Zone C',
  'Crocus, Spring, Zone A',
  'Aster, Autumn, Zone D',
  'Daffodil, Spring, Zone A',
  'Lavender, Summer, Zone B',
];

const route = guide(garden, ['Spring', 'Summer']);
console.log(describeRoute(route));
console.log(formatZoneReport(garden, ['Spring', 'Summer']));

