const BASE_SPEED = 60;
const REST_PENALTY_MINUTES = 15;
const LONG_SEGMENT_MINUTES = 120;

const normalizeTerrain = (terrain) => String(terrain).trim().toLowerCase();

function speedForTerrain(terrain) {
  const name = normalizeTerrain(terrain);
  if (name === 'gravel') return 40;
  if (name === 'dirt') return 30;
  return BASE_SPEED;
}

function parseCheckpoint(entry) {
  const parts = String(entry).trim().split(/\s+/);
  if (parts.length < 2) {
    throw new Error(`Malformed checkpoint: "${entry}"`);
  }
  const distance = Number(parts[0]);
  if (!Number.isFinite(distance) || distance < 0) {
    throw new Error(`Invalid distance in checkpoint: "${entry}"`);
  }
  return { distance, terrain: normalizeTerrain(parts.slice(1).join(' ')) };
}

function segmentMinutes(segment) {
  const speed = speedForTerrain(segment.terrain);
  return (segment.distance / speed) * 60;
}

function collectSegments(checkpoints) {
  if (!Array.isArray(checkpoints)) {
    throw new TypeError('checkpoints must be an array of strings');
  }
  return checkpoints.map(parseCheckpoint);
}

const hasLongSegment = (minutesList) => minutesList.some((m) => m > LONG_SEGMENT_MINUTES);

function route(checkpoints) {
  const segments = collectSegments(checkpoints);
  const minutesList = segments.map(segmentMinutes);
  const driving = minutesList.reduce((sum, m) => sum + m, 0);
  return hasLongSegment(minutesList) ? driving + REST_PENALTY_MINUTES : driving;
}

function formatDuration(minutes) {
  const whole = Math.round(minutes);
  const hours = Math.floor(whole / 60);
  return `${hours}h ${String(whole % 60).padStart(2, '0')}m`;
}

function describeSegment(segment) {
  const minutes = segmentMinutes(segment);
  const speed = speedForTerrain(segment.terrain);
  const pretty = formatDuration(minutes);
  return `${segment.distance} km of ${segment.terrain} @ ${speed} km/h -> ${pretty}`;
}

function reportRoute(checkpoints) {
  const segments = collectSegments(checkpoints);
  const lines = segments.map(describeSegment);
  const total = route(checkpoints);
  lines.push(`total: ${formatDuration(total)} (${total.toFixed(2)} minutes)`);
  return lines.join('\n');
}

const trip = ['30 paved', '20 gravel', '15 dirt'];
const hardTrip = ['150 paved', '90 dirt'];

console.log(reportRoute(trip));
console.log(reportRoute(hardTrip));

module.exports = {
  route,
  reportRoute,
  parseCheckpoint,
  speedForTerrain,
  formatDuration,
};

