const TEN_MINUTES_MS = 10 * 60 * 1000;
const MAGNITUDE_THRESHOLD = 3;

const toFiniteNumber = (raw, label) => {
  const value = Number(raw);
  if (!Number.isFinite(value)) {
    throw new Error(`invalid ${label}: "${raw}"`);
  }
  return value;
};

const toEpochMillis = (timestamp) => {
  const millis = Date.parse(timestamp);
  if (Number.isNaN(millis)) {
    throw new Error(`unreadable timestamp: "${timestamp}"`);
  }
  return millis;
};

const parseLogEntry = (line) => {
  const parts = line.split(',').map((field) => field.trim());
  if (parts.length !== 3) {
    throw new Error(`malformed log entry: "${line}"`);
  }
  const [stamp, magnitude, depth] = parts;
  return {
    timestamp: stamp,
    time: toEpochMillis(stamp),
    magnitude: toFiniteNumber(magnitude, 'magnitude'),
    depth: toFiniteNumber(depth, 'depth'),
  };
};

const isSignificantTremor = (tremor) => tremor.magnitude >= MAGNITUDE_THRESHOLD;

const sortByTime = (tremors) => [...tremors].sort((a, b) => a.time - b.time);

const groupIntoClusters = (tremors) => {
  const clusters = [];
  for (const tremor of sortByTime(tremors)) {
    const current = clusters[clusters.length - 1];
    const previous = current && current[current.length - 1];
    if (previous && tremor.time - previous.time <= TEN_MINUTES_MS) {
      current.push(tremor);
    } else {
      clusters.push([tremor]);
    }
  }
  return clusters;
};

const maxMagnitudeOf = (cluster) => cluster.reduce((peak, t) => Math.max(peak, t.magnitude), -Infinity);

const buildClusters = (logs) => {
  const parsed = logs.map(parseLogEntry);
  const significant = parsed.filter(isSignificantTremor);
  return groupIntoClusters(significant);
};

function monitor(logs) {
  if (!Array.isArray(logs)) {
    throw new TypeError('logs must be an array of strings');
  }
  const clusters = buildClusters(logs);
  return clusters.map(maxMagnitudeOf);
}

const describeCluster = (cluster) => {
  const first = cluster[0].timestamp;
  const last = cluster[cluster.length - 1].timestamp;
  const peak = maxMagnitudeOf(cluster).toFixed(1);
  return `${first} -> ${last}: ${cluster.length} tremor(s), peak M${peak}`;
};

const buildReport = (logs) => {
  const clusters = buildClusters(logs);
  return clusters.map(describeCluster).join('\n');
};

const readLogLines = (text) => text.split('\n').map((line) => line.trim()).filter(Boolean);

if (require.main === module) {
  const raw = require('fs').readFileSync(0, 'utf8');
  const lines = readLogLines(raw);
  console.log(buildReport(lines));
}

module.exports = {
  monitor,
  buildReport,
  parseLogEntry,
  groupIntoClusters,
};

