const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function validateNumberList(values, label) {
  if (!Array.isArray(values)) {
    throw new TypeError(`${label} must be an array of numbers`);
  }
  const badIndex = values.findIndex((value) => !isFiniteNumber(value));
  if (badIndex !== -1) {
    throw new TypeError(`${label}[${badIndex}] is not a finite number`);
  }
  return values;
}

const skillDistance = (skill, energy) => Math.abs(skill - energy);

function rankCandidates(musicians, energy) {
  return musicians
    .map((skill, index) => ({ index, gap: skillDistance(skill, energy) }))
    .sort((a, b) => a.gap - b.gap || a.index - b.index)
    .map((entry) => entry.index);
}

function pickBestCandidate(ranked, previousIndex) {
  const eligible = ranked.filter((index) => index !== previousIndex);
  return eligible.length > 0 ? eligible[0] : ranked[0];
}

function allocate(musicians, sections) {
  validateNumberList(musicians, 'musicians');
  validateNumberList(sections, 'sections');
  if (musicians.length === 0) {
