const parseCoordinate = (text) => {
  const parts = String(text).split(',');
  if (parts.length !== 2) {
    throw new Error(`malformed coordinate: "${text}"`);
  }
  const x = Number(parts[0].trim());
  const y = Number(parts[1].trim());
  if (!Number.isFinite(x) || !Number.isFinite(y)) {
    throw new Error(`non-numeric coordinate: "${text}"`);
  }
  return { x, y };
};

const parseCoordinateList = (items) => {
  if (!Array.isArray(items)) {
    throw new Error('expected a list of coordinate strings');
  }
  return items.map(parseCoordinate);
};

const manhattanDistance = (from, to) => Math.abs(to.x - from.x) + Math.abs(to.y - from.y);

const findNearestCourier = (destination, couriers) => {
  let bestIndex = 0;
  let bestDistance = manhattanDistance(couriers[0], destination);
  for (let i = 1; i < couriers.length; i += 1) {
    const distance = manhattanDistance(couriers[i], destination);
    if (distance < bestDistance) {
      bestDistance = distance;
      bestIndex = i;
    }
  }
  return { index: bestIndex, distance: bestDistance };
};

const moveCourierTo = (couriers, index, destination) => {
  couriers[index] = { x: destination.x, y: destination.y };
};

function dispatch(deliveries, couriers) {
  const stops = parseCoordinateList(deliveries);
  const fleet = parseCoordinateList(couriers);
  if (fleet.length === 0) {
    throw new Error('at least one courier is required');
  }
  return stops.map((stop) => {
    const nearest = findNearestCourier(stop, fleet);
    moveCourierTo(fleet, nearest.index, stop);
    return nearest.distance;
  });
}

const formatCoordinate = (point) => `(${point.x}, ${point.y})`;

const formatDispatchReport = (deliveries, distances) => {
  const lines = deliveries.map((raw, i) => {
    const stop = parseCoordinate(raw);
    return `delivery ${i + 1} -> ${formatCoordinate(stop)}: ${distances[i]}`;
  });
  const total = distances.reduce((sum, d) => sum + d, 0);
  lines.push(`total distance travelled: ${total}`);
  return lines.join('\n');
};

function main() {
  const deliveries = ['3,4', '-1,2', '10,10', '0,0'];
  const couriers = ['0,0', '5,5', '-4,-4'];
  const distances = dispatch(deliveries, couriers);
  console.log(formatDispatchReport(deliveries, distances));
}

main();

module.exports.dispatch = dispatch;
module.exports.parseCoordinate = parseCoordinate;
module.exports.manhattanDistance = manhattanDistance;
module.exports.formatDispatchReport = formatDispatchReport;

