const splitTeethCounts = (pair) => pair.split('/').map((part) => part.trim());

const parseToothCount = (text) => {
  const count = Number(text);
  if (!Number.isInteger(count) || count <= 0) {
    throw new RangeError(`invalid tooth count: "${text}"`);
  }
  return count;
};

const parseGearPair = (pair) => {
  if (typeof pair !== 'string') {
    throw new TypeError('each gear pair must be a string like "driving/driven"');
  }
  const parts = splitTeethCounts(pair);
  if (parts.length !== 2) {
    throw new SyntaxError(`gear pair must look like "driving/driven": "${pair}"`);
  }
  const [driving, driven] = parts.map(parseToothCount);
  return { driving, driven };
};

const computeGearRatio = ({ driving, driven }) => driving / driven;

const parseGearTrain = (gears) => {
  if (!Array.isArray(gears)) {
    throw new TypeError('gears must be an array of strings');
  }
  return gears.map(parseGearPair);
};

const computeTrainRatio = (pairs) =>
  pairs.reduce((total, pair) => total * computeGearRatio(pair), 1);

const computeRotationalSpeed = (ratio) => Math.round(ratio * 60);

function tune(gears) {
  const pairs = parseGearTrain(gears);
  const totalRatio = computeTrainRatio(pairs);
  return computeRotationalSpeed(totalRatio);
}

