const normalizeVariety = (raw) => {
  const trimmed = String(raw).trim();
  if (trimmed.length === 0) {
    throw new Error('tree record is missing a variety name');
  }
  return trimmed[0].toUpperCase() + trimmed.slice(1).toLowerCase();
};

const toFiniteNumber = (raw, label) => {
  const value = Number(String(raw).trim());
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`invalid ${label}: ${String(raw).trim()}`);
  }
  return value;
};

const roundTo = (value, places) => {
  const scale = 10 ** places;
  return Math.round(value * scale) / scale;
};

function parseTreeRecord(entry) {
  const fields = String(entry).split(':');
  if (fields.length !== 3) {
    throw new Error(`expected "variety:age:yield" but got "${entry}"`);
  }
  return {
    variety: normalizeVariety(fields[0]),
    age: toFiniteNumber(fields[1], 'age'),
    historicalYield: toFiniteNumber(fields[2], 'yield'),
  };
}

const yieldMultiplier = (age) => {
  if (age < 10) return 1.05;
  if (age > 20) return 0.9;
  return 1;
};

function computeExpectedYield(record) {
  const multiplier = yieldMultiplier(record.age);
  return roundTo(record.historicalYield * multiplier, 4);
}

function aggregateByVariety(records) {
  const totals = new Map();
  for (const record of records) {
    const running = totals.get(record.variety) || 0;
    totals.set(record.variety, running + computeExpectedYield(record));
  }
  return totals;
}

const selectTopVariety = (totals) => {
  let best = null;
  for (const [variety, total] of totals) {
    if (best === null || total > best.total) {
      best = { variety, total };
    }
  }
  return best;
};

function forecast(trees) {
  if (!Array.isArray(trees) || trees.length === 0) {
    throw new Error('forecast requires a non-empty list of tree records');
  }
  const records = trees.map(parseTreeRecord);
  const totals = aggregateByVariety(records);
  const best = selectTopVariety(totals);
  return best.variety;
}

const formatReport = (trees) => {
  const records = trees.map(parseTreeRecord);
  const totals = aggregateByVariety(records);
  const lines = [...totals.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([variety, total]) => `${variety}: ${roundTo(total, 2)}`);
  return lines.join('\n');
};

const orchard = [
  'gala:8:120',
  'Gala:25:200',
  'fuji:15:180',
  'FUJI:9:160',
  'braeburn:30:400',
];

console.log(formatReport(orchard));
console.log(`Top variety: ${forecast(orchard)}`);

