  };
};

const IsValidChocolate = (choc) => {
  if (choc.flavor.length === 0) {
    return false;
  }
  return Number.isFinite(choc.weight) && choc.weight > 0;
};

const ParseChocolateList = (entries) => {
  const parsed = entries.map(ParseChocolate);
  return parsed.filter(IsValidChocolate);
};

const IsUnderWeightLimit = (choc) => choc.weight < 20;

const FilterLightChocolates = (chocolates) => {
  return chocolates.filter(IsUnderWeightLimit);
};

const QueueByFlavor = (chocolates, flavor) =>
  chocolates.filter((choc) => choc.flavor === flavor);

const OppositeFlavor = (flavor) => (flavor === 'sweet' ? 'bitter' : 'sweet');

const Assort = (chocolates, capacity) => {
  const parsed = ParseChocolateList(chocolates);
  const light = FilterLightChocolates(parsed);
  const queues = {
    sweet: QueueByFlavor(light, 'sweet'),
    bitter: QueueByFlavor(light, 'bitter'),
  };
  let wanted = 'sweet';
  let total = 0;
  let count = 0;
  while (queues[wanted].length > 0) {
    const picked = queues[wanted].shift();
    total += picked.weight;
    if (total > capacity) {
      break;
    }
    count += 1;
    wanted = OppositeFlavor(wanted);
  }
  return count;
};

const DescribeCapacity = (capacity) => `capacity ${capacity}g`;

const FormatReport = (chocolates, capacity) => {
  const packed = Assort(chocolates, capacity);
  const label = DescribeCapacity(capacity);
  return `${label}: packed ${packed} of ${chocolates.length}`;
};

const boxA = ['Sweet, 12', 'Bitter, 15', 'Sweet, 8', 'Bitter, 25', 'Bitter, 6'];
const boxB = ['bitter, 19', 'SWEET, 4', 'sweet, 21', 'bitter, 3', 'sweet, 9'];

console.log(FormatReport(boxA, 40));
console.log(FormatReport(boxB, 20));
console.log(FormatReport(boxB, 5));

module.exports = {
  Assort,
  ParseChocolateList,
  FilterLightChocolates,
  FormatReport,
};

