const SAFE_RANGES = {
  oxygen: { min: 19.5, max: 23.5, ideal: 21.0 },
  temperature: { min: 18.0, max: 24.0, ideal: 21.0 },
  pressure: { min: 99.0, max: 102.0, ideal: 101.3 }
};

const METRIC_NAMES = ['oxygen', 'temperature', 'pressure'];

const validateReadings = (readings) => {
  if (!Array.isArray(readings) || readings.length === 0) {
    throw new Error('diagnose requires at least one reading');
  }
  readings.forEach((reading, index) => {
    if (!Array.isArray(reading) || reading.length !== 3) {
      throw new Error(`reading ${index} must hold three numbers`);
    }
    if (reading.some((value) => typeof value !== 'number' || Number.isNaN(value))) {
      throw new Error(`reading ${index} contains a non-numeric value`);
    }
  });
  return readings;
};

const averageOfColumn = (readings, column) =>
  readings.reduce((sum, reading) => sum + reading[column], 0) / readings.length;

const computeAverages = (readings) => {
  const averages = {};
  METRIC_NAMES.forEach((name, column) => {
    averages[name] = averageOfColumn(readings, column);
  });
  return averages;
};

const isWithinRange = (value, range) => value >= range.min && value <= range.max;

const findUnsafeMetrics = (averages) =>
  METRIC_NAMES.filter((name) => !isWithinRange(averages[name], SAFE_RANGES[name]));

const scoreSingleMetric = (value, range) => {
  const span = Math.max(range.ideal - range.min, range.max - range.ideal);
  const deviation = Math.abs(value - range.ideal);
  const closeness = 1 - deviation / span;
  return closeness > 0 ? closeness : 0;
};

const computeHealthScore = (averages) => {
  const total = METRIC_NAMES.reduce(
    (sum, name) => sum + scoreSingleMetric(averages[name], SAFE_RANGES[name]),
    0
  );
  return Math.round((total / METRIC_NAMES.length) * 1000) / 10;
};

function diagnose(readings) {
  const valid = validateReadings(readings);
  const averages = computeAverages(valid);
  const unsafe = findUnsafeMetrics(averages);
  const score = computeHealthScore(averages);
  return [score, unsafe.length === 0 ? 'safe' : 'critical'];
}

const describeDiagnosis = (label, readings) => {
  const [score, status] = diagnose(readings);
  const averages = computeAverages(readings);
  const detail = METRIC_NAMES.map((name) => `${name}=${averages[name].toFixed(2)}`).join(' ');
  return `${label}: ${status.toUpperCase()} score=${score.toFixed(1)} [${detail}]`;
};

const nominalLog = [
  [21.0, 21.2, 101.3],
  [20.8, 20.9, 101.4],
  [21.2, 21.1, 101.2]
];

const failingLog = [
  [18.4, 26.5, 97.2],
  [19.1, 25.8, 98.0]
];

console.log(describeDiagnosis('Module A', nominalLog));
console.log(describeDiagnosis('Module B', failingLog));

module.exports.diagnose = diagnose;
module.exports.computeAverages = computeAverages;
module.exports.isWithinRange = isWithinRange;
module.exports.computeHealthScore = computeHealthScore;
module.exports.describeDiagnosis = describeDiagnosis;

