const POWER_THRESHOLD = 100;
const NEURAL_BASELINE = 50;
const CURVE_FACTOR = 6;

const isValidImplant = (implant) =>
  Array.isArray(implant) &&
  implant.length === 3 &&
  implant.every((value) => typeof value === 'number' && Number.isFinite(value));

function validateImplants(implants) {
  if (!Array.isArray(implants)) {
    throw new TypeError('implants must be an array of [power, load, rejection] triples');
  }
  implants.forEach((implant, index) => {
    if (!isValidImplant(implant)) {
      throw new TypeError(`implant at index ${index} is not a triple of finite numbers`);
    }
  });
  return implants;
}

const sumField = (implants, index) =>
  implants.reduce((total, implant) => total + implant[index], 0);

function applyReductionCurve(power) {
  if (power <= POWER_THRESHOLD) {
    return power;
  }
  const excess = power - POWER_THRESHOLD;
  return POWER_THRESHOLD + CURVE_FACTOR * Math.sqrt(excess);
}

const clampProbability = (value) => Math.min(Math.max(value, 0), 1);

function combinedRejectionRisk(implants) {
  return implants.reduce((risk, implant) => risk * clampProbability(implant[2]), 1);
}

const roundTo = (value, digits) => {
  const scale = 10 ** digits;
  return Math.round(value * scale) / scale;
};

function evaluate(implants) {
  validateImplants(implants);
  const rawPower = sumField(implants, 0);
  const curvedPower = applyReductionCurve(rawPower);
  const adjustedPower = roundTo(curvedPower, 2);
  const neuralLoad = sumField(implants, 1);
  const loadIsSafe = neuralLoad <= NEURAL_BASELINE;
  const risk = combinedRejectionRisk(implants);
  const riskPercent = roundTo(risk * 100, 4);
  return [adjustedPower, loadIsSafe, riskPercent];
}

const describeLoadStatus = (safe) => (safe ? 'within baseline' : 'OVER BASELINE');

function formatReport(label, implants) {
  const [power, safe, risk] = evaluate(implants);
  const rawLoad = sumField(implants, 1);
  const load = roundTo(rawLoad, 2);
  const status = describeLoadStatus(safe);
  return `${label}: power ${power}W, neural load ${load} (${status}), rejection risk ${risk}%`;
}

function main() {
  const patients = [
    ['Arm + optic', [[40, 12, 0.05], [30, 9, 0.1]]],
    ['Full chassis', [[90, 25, 0.2], [80, 20, 0.15], [60, 18, 0.3]]],
    ['Spinal brace', [[120, 41, 0.02]]],
  ];
  patients.forEach(([label, implants]) => {
    console.log(formatReport(label, implants));
  });
}

main();

module.exports = { evaluate, applyReductionCurve, combinedRejectionRisk, formatReport };

