const DIET_THRESHOLD = 0.18;
const BLUEPRINT = { predator: 24, herbivore: 30 };

function parseBoneRecord(entry) {
  if (!Array.isArray(entry) || entry.length < 3) return null;
  const [length, density, curvature] = entry.map(Number);
  if ([length, density, curvature].some(Number.isNaN)) return null;
  return { length, density, curvature };
}

const isUsableBone = (bone) => bone.length > 0 && bone.density > 0;

const prepareBoneSet = (bones) => {
  const source = Array.isArray(bones) ? bones : [];
  return source
    .map(parseBoneRecord)
    .filter((bone) => bone !== null && isUsableBone(bone));
};

const estimateBoneAge = (bone) =>
  Math.round(bone.density * 8200 + bone.length * 140);

const computeCurvatureRatio = (bone) => bone.curvature / bone.length;

function classifyBoneType(bone) {
  return computeCurvatureRatio(bone) > DIET_THRESHOLD ? 'predator' : 'herbivore';
}

function tallyBoneTypes(boneSet) {
  const tally = { predator: 0, herbivore: 0 };
  for (const bone of boneSet) {
    tally[classifyBoneType(bone)] += 1;
  }
  return tally;
}

const pickDominantType = (tally) =>
  tally.predator >= tally.herbivore ? 'predator' : 'herbivore';

function scoreSkeletonCompletion(tally, dominant) {
  const required = BLUEPRINT[dominant];
  const matched = Math.min(tally[dominant], required);
  return Math.round((matched / required) * 1000) / 10;
}

function averageBoneAge(boneSet) {
  if (boneSet.length === 0) return 0;
  const total = boneSet.reduce((sum, bone) => sum + estimateBoneAge(bone), 0);
  return Math.round(total / boneSet.length);
}

function reconstruct(bones) {
  const boneSet = prepareBoneSet(bones);
  if (boneSet.length === 0) return 0;
  const tally = tallyBoneTypes(boneSet);
  const dominant = pickDominantType(tally);
  return scoreSkeletonCompletion(tally, dominant);
}

function formatCompletionReport(label, bones) {
  const boneSet = prepareBoneSet(bones);
  const tally = tallyBoneTypes(boneSet);
  const dominant = pickDominantType(tally);
  const oldest = boneSet.length ? Math.max(...boneSet.map(estimateBoneAge)) : 0;
  return [
    `${label}: ${boneSet.length} usable bones of ${bones.length} found`,
    `  predator bones: ${tally.predator}, herbivore bones: ${tally.herbivore}`,
    `  species guess: ${dominant} (blueprint needs ${BLUEPRINT[dominant]} bones)`,
    `  mean age: ${averageBoneAge(boneSet)} years, oldest: ${oldest} years`,
    `  skeleton completed: ${reconstruct(bones)}%`,
  ].join('\n');
}

const trenchA = [
  [120, 2.4, 30], [95, 2.1, 25], [140, 2.6, 12], [88, 1.9, 4],
  [77, 2.2, 20], [130, 2.5, 35], [0, 2.0, 5], [64, 2.3, 14],
];
const trenchB = [
  [210, 3.1, 8], [198, 3.0, 6], [175, 2.8, 5], [160, 2.9, 40],
  [182, 3.2, 9], ['x', 1.0, 1], [205, 3.3, 7],
];

console.log(formatCompletionReport('Trench A', trenchA));
console.log(formatCompletionReport('Trench B', trenchB));
console.log(`Combined completion: ${reconstruct(trenchA.concat(trenchB))}%`);

