const LIFT_COEFFICIENT = 0.35;
const DRAG_COEFFICIENT = 0.08;
const BASE_LIFT_CAPACITY = 500;
const GROUND_LEVEL = 0;

const toFiniteNumber = (value, label) => {
  const parsed = typeof value === 'string' ? Number(value.trim()) : value;
  if (typeof parsed !== 'number' || !Number.isFinite(parsed)) {
    throw new TypeError(`${label} must be a finite number, got: ${String(value)}`);
  }
  return parsed;
};

function readEnvironment(reading) {
  if (!Array.isArray(reading) || reading.length < 3) {
    throw new TypeError('each condition must be an array of [wind, altitude, ballast]');
  }
  return {
    windSpeed: toFiniteNumber(reading[0], 'wind speed'),
    altitude: toFiniteNumber(reading[1], 'altitude'),
    ballast: toFiniteNumber(reading[2], 'ballast'),
  };
}

function computeBuoyancyLift(ballast) {
  const spareCapacity = BASE_LIFT_CAPACITY - Math.max(ballast, 0);
  return spareCapacity * LIFT_COEFFICIENT;
}

function computeWindPenalty(windSpeed) {
  const magnitude = Math.abs(windSpeed);
  return magnitude * magnitude * DRAG_COEFFICIENT;
}

function computeNewAltitude(reading) {
  const { windSpeed, altitude, ballast } = readEnvironment(reading);
  const lift = computeBuoyancyLift(ballast);
  const drag = computeWindPenalty(windSpeed);
  return Math.max(altitude + lift - drag, GROUND_LEVEL);
}

function navigate(conditions) {
  if (!Array.isArray(conditions)) {
    throw new TypeError('conditions must be an array of readings');
  }
  return conditions.map(computeNewAltitude);
}

const formatFlightLine = (reading, newAltitude) => {
  const { windSpeed, altitude, ballast } = readEnvironment(reading);
  const lift = computeBuoyancyLift(ballast).toFixed(2);
  const drag = computeWindPenalty(windSpeed).toFixed(2);
  return `wind ${windSpeed} | alt ${altitude} -> ${newAltitude.toFixed(2)} (lift ${lift}, drag ${drag})`;
};

function buildFlightReport(conditions) {
  const altitudes = navigate(conditions);
  return conditions
    .map((reading, index) => formatFlightLine(reading, altitudes[index]))
    .join('\n');
}

const flightPlan = [
  [12, 1000, 420],
  [45, 800, 150],
  [0, 50, 495],
  [80, 120, 300],
];

console.log(buildFlightReport(flightPlan));
console.log('final altitudes:', navigate(flightPlan));

module.exports = {
  navigate,
  computeBuoyancyLift,
  computeWindPenalty,
  buildFlightReport,
};

