const NORMAL_PACKET_SIZE = 512;
const BLOCK_THRESHOLD = 75;
const FAILURE_LIMIT = 3;
const FAILURE_MULTIPLIER = 2.5;

const extractOctets = (ipInteger) => [
  (ipInteger >>> 24) & 255,
  (ipInteger >>> 16) & 255,
  (ipInteger >>> 8) & 255,
  ipInteger & 255,
];

const formatIpAddress = (ipInteger) => extractOctets(ipInteger).join('.');

function validateEntry(entry) {
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError('each log entry must be [ip, packetSize, failures]');
  }
  const [ip, size, failures] = entry;
  if (!Number.isInteger(ip) || ip < 0 || ip > 0xffffffff) {
    throw new RangeError(`invalid IP integer: ${ip}`);
  }
  if (!Number.isFinite(size) || size < 0) {
    throw new RangeError(`invalid packet size: ${size}`);
  }
  if (!Number.isInteger(failures) || failures < 0) {
    throw new RangeError(`invalid failure count: ${failures}`);
  }
  return { ip, size, failures };
}

function computeBaselineRisk(packetSize) {
  const deviation = Math.abs(packetSize - NORMAL_PACKET_SIZE);
  return Math.min(100, (deviation / NORMAL_PACKET_SIZE) * 100);
}

function applyFailureMultiplier(risk, failures) {
  return failures > FAILURE_LIMIT ? risk * FAILURE_MULTIPLIER : risk;
}

function matchesBotnetPattern(ipInteger) {
  const [a, b, c, d] = extractOctets(ipInteger);
  return (a === c && b === d) || (a + d === b + c && b !== c);
}

const scoreConnection = (entry) => {
  const { ip, size, failures } = validateEntry(entry);
  const baseline = computeBaselineRisk(size);
  const risk = applyFailureMultiplier(baseline, failures);
  return { ip, risk, botnet: matchesBotnetPattern(ip) };
};

const shouldBlockConnection = (scored) => scored.botnet || scored.risk >= BLOCK_THRESHOLD;

function analyze(logs) {
  if (!Array.isArray(logs)) {
    throw new TypeError('logs must be an array');
  }
  return logs.map((entry) => shouldBlockConnection(scoreConnection(entry)));
}

const formatReportLine = (scored, blocked) => {
  const address = formatIpAddress(scored.ip);
  const flag = scored.botnet ? 'botnet-pattern' : 'clean-pattern';
  const verdict = blocked ? 'BLOCK' : 'allow';
  return `${address.padEnd(15)} risk=${scored.risk.toFixed(1).padStart(6)} ${flag} -> ${verdict}`;
};

function buildReport(logs) {
  return logs.map((entry) => {
    const scored = scoreConnection(entry);
    return formatReportLine(scored, shouldBlockConnection(scored));
  });
}

function main() {
  const traffic = [
    [3232235777, 500, 1],
    [3232235777, 1500, 0],
    [167772161, 520, 7],
    [2886729729, 2048, 5],
    [1347440721, 512, 0],
  ];
  const decisions = analyze(traffic);
  buildReport(traffic).forEach((line) => console.log(line));
  console.log(`blocked ${decisions.filter(Boolean).length} of ${decisions.length} connections`);
}

main();

module.exports = { analyze, buildReport, formatIpAddress };

