const FADE_STEPS = 3;
const MAX_FRAMES = 4096;
const MAX_TIMELINE_MS = 60000;

const validateDurations = (config) => {
  if (!Array.isArray(config)) {
    throw new TypeError('config must be an array of durations');
  }
  return config.map((value, index) => {
    if (!Number.isInteger(value) || value <= 0) {
      throw new RangeError(`duration at index ${index} must be a positive integer`);
    }
    return value;
  });
};

const createFrameState = (brightness, duration) => ({ brightness, duration });

const buildPhaseFrames = (durations) =>
  durations.map((duration, index) => {
    const brightness = index % 2 === 0 ? 255 : 0;
    return createFrameState(brightness, duration);
  });

const interpolateBrightness = (from, to, step, steps) =>
  Math.round(from + ((to - from) * step) / (steps + 1));

const applyFadeTransitions = (frames, steps) => {
  const faded = [];
  frames.forEach((frame, index) => {
    const next = frames[index + 1];
    if (!next) {
      faded.push(createFrameState(frame.brightness, frame.duration));
      return;
    }
    const slice = Math.max(1, Math.floor((frame.duration * 0.2) / steps));
    const held = frame.duration - slice * steps;
    faded.push(createFrameState(frame.brightness, Math.max(1, held)));
    for (let step = 1; step <= steps; step += 1) {
      const level = interpolateBrightness(frame.brightness, next.brightness, step, steps);
      faded.push(createFrameState(level, slice));
    }
  });
  return faded;
};

const mergeAdjacentFrames = (frames) =>
  frames.reduce((acc, frame) => {
    const last = acc[acc.length - 1];
    if (last && last.brightness === frame.brightness) {
      last.duration += frame.duration;
      return acc;
    }
    acc.push(createFrameState(frame.brightness, frame.duration));
    return acc;
  }, []);

const compileTimeline = (frames) => {
  const visible = frames.filter((frame) => frame.duration > 0);
  return mergeAdjacentFrames(visible);
};

const sumTotalDuration = (frames) => frames.reduce((total, frame) => total + frame.duration, 0);

const fitsMemoryLimit = (frames, totalMs) =>
  frames.length <= MAX_FRAMES && totalMs <= MAX_TIMELINE_MS;

function animate(config) {
  const durations = validateDurations(config);
  const phases = buildPhaseFrames(durations);
  const faded = applyFadeTransitions(phases, FADE_STEPS);
  const timeline = compileTimeline(faded);
  const totalMs = sumTotalDuration(timeline);
  if (!fitsMemoryLimit(timeline, totalMs)) {
    throw new Error(`sequence of ${timeline.length} frames / ${totalMs}ms exceeds hardware limits`);
  }
  return timeline.length;
}

const formatSignReport = (label, config) => {
  const frameCount = animate(config);
  return `${label}: ${config.join('/')}ms -> ${frameCount} frames`;
};

