  ['slow blink', [1000, 1000]],
  ['marquee', [400, 200, 400, 200, 800]],
  ['strobe', [60, 60, 60, 60]],
];

signPrograms.forEach(([label, config]) => {
  console.log(formatSignReport(label, config));
});

module.exports = { animate, buildPhaseFrames, applyFadeTransitions, compileTimeline };

