const LIGHT_FLOOR = 400;

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function validateReading(reading, index) {
  if (!Array.isArray(reading) || reading.length !== 3) {
    throw new TypeError(`sensor ${index} must be an array of three numbers`);
  }
  reading.forEach((value, slot) => {
    if (!isFiniteNumber(value)) {
      throw new TypeError(`sensor ${index} value ${slot} is not a finite number`);
    }
  });
  return reading;
}

function needsCooling(temperature) {
  return temperature > TEMP_LIMIT;
}

function needsWatering(moisture) {
  return moisture < MOISTURE_FLOOR;
}

function needsLighting(sunlight) {
  return sunlight < LIGHT_FLOOR;
}

