  if (!Array.isArray(sensors)) {
    throw new TypeError('sensors must be an array of readings');
  }
  return sensors.map((reading, index) => {
    const [temperature, moisture, sunlight] = validateReading(reading, index);
    const fan = needsCooling(temperature);
    const water = needsWatering(moisture);
    const light = needsLighting(sunlight);
