const isWholeNumber = (value) => typeof value === 'number' && Number.isInteger(value);

const validateHits = (hits) => {
  if (!Array.isArray(hits)) {
    throw new TypeError('hits must be an array of integers');
  }
  const offender = hits.findIndex((hit) => !isWholeNumber(hit));
  if (offender !== -1) {
    throw new TypeError(`hit at index ${offender} is not an integer`);
  }
  return hits;
};

const sumBaseScore = (hits) => hits.reduce((total, hit) => total + hit, 0);

const collectIncreasingRuns = (hits) => {
  const runs = [];
  let current = hits.length > 0 ? [hits[0]] : [];
  for (let i = 1; i < hits.length; i += 1) {
    if (hits[i] > hits[i - 1]) {
      current.push(hits[i]);
    } else {
      if (current.length > 1) {
        runs.push(current);
      }
      current = [hits[i]];
    }
  }
  if (current.length > 1) {
    runs.push(current);
  }
  return runs;
};

const comboBonusForRun = (run) => {
  const runTotal = sumBaseScore(run);
  return runTotal * (run.length - 1);
};

const computeComboBonus = (hits) => {
  const runs = collectIncreasingRuns(hits);
  return runs.reduce((total, run) => total + comboBonusForRun(run), 0);
};

const computeMultiplier = (hits) => 1 + Math.floor(hits.length / 10);

function score(hits) {
  validateHits(hits);
  const base = sumBaseScore(hits);
  const combo = computeComboBonus(hits);
  const multiplier = computeMultiplier(hits);
  return (base + combo) * multiplier;
}

const describeRuns = (hits) => {
  const runs = collectIncreasingRuns(hits);
  if (runs.length === 0) {
    return 'no combos';
  }
  return runs.map((run) => run.join('>')).join(', ');
};

const formatScoreReport = (label, hits) => {
  const parts = [
    `base=${sumBaseScore(hits)}`,
    `combo=${computeComboBonus(hits)}`,
    `x${computeMultiplier(hits)}`,
    `combos: ${describeRuns(hits)}`,
  ];
  return `${label}: ${score(hits)} (${parts.join(' ')})`;
};

const sessions = [
  ['warmup', [5, 10, 20]],
  ['flat run', [7, 7, 7, 7]],
  ['long game', [1, 2, 3, 2, 4, 6, 8, 1, 1, 9, 12, 3]],
  ['empty', []],
];

sessions.forEach(([label, hits]) => {
  console.log(formatScoreReport(label, hits));
});

module.exports = { score, sumBaseScore, computeComboBonus, computeMultiplier, formatScoreReport };

