const ORE_PRICE_PER_PERCENT = 120;
const COST_PER_HOUR = 45;
const DEPTH_SCALE = 800;

const RoundToCents = (value) => Math.round(value * 100) / 100;

function ParseSiteEntry(entry, index) {
  if (!Array.isArray(entry) || entry.length < 2) {
    throw new TypeError(`Site ${index} must be an array of [depth, concentration]`);
  }
  const [depth, concentration] = entry;
  if (typeof depth !== 'number' || Number.isNaN(depth) || depth < 0) {
    throw new RangeError(`Site ${index} has an invalid depth: ${depth}`);
  }
  if (typeof concentration !== 'number' || Number.isNaN(concentration) || concentration < 0) {
    throw new RangeError(`Site ${index} has an invalid concentration: ${concentration}`);
  }
  return { depth, concentration };
}

const CalculatePressurePenalty = (depth) => Math.exp(depth / DEPTH_SCALE);

const EstimateExtractionTime = (concentration, penalty) => concentration / penalty;

const ComputeRawOreValue = (concentration) => concentration * ORE_PRICE_PER_PERCENT;

const ComputeOperatingCost = (hours) => hours * COST_PER_HOUR;

function ComputeNetYield(site) {
  const penalty = CalculatePressurePenalty(site.depth);
  const hours = EstimateExtractionTime(site.concentration, penalty);
  const rawValue = ComputeRawOreValue(site.concentration);
  const cost = ComputeOperatingCost(hours);
  return RoundToCents(rawValue - cost);
}

function Prospect(map) {
  if (!Array.isArray(map)) {
    throw new TypeError('prospect expects a list of [depth, concentration] arrays');
  }
  return map.map((entry, index) => {
    const site = ParseSiteEntry(entry, index);
    return ComputeNetYield(site);
  });
}

function FormatSiteReport(entry, netYield, index) {
  const site = ParseSiteEntry(entry, index);
  const penalty = CalculatePressurePenalty(site.depth);
  const hours = EstimateExtractionTime(site.concentration, penalty);
  const depthLabel = `${site.depth} m`.padStart(8);
  const oreLabel = `${site.concentration}%`.padStart(6);
  return `${depthLabel} ${oreLabel}  penalty=${RoundToCents(penalty)}` +
    `  time=${RoundToCents(hours)} h  net=${netYield}`;
}

const SummarizeTotalYield = (values) =>
  RoundToCents(values.reduce((total, value) => total + value, 0));

