const FULL_CIRCLE = 360;
const SHARP_TURN_LIMIT = 45;
const MAX_SHARP_TURNS = 5;
const SEGMENT_LENGTH = 10;
const MIN_BRAKING_LENGTH = 30;

const toAbsoluteAngle = (angle) => Math.abs(angle);

const isSharpTurn = (angle) => {
  return toAbsoluteAngle(angle) > SHARP_TURN_LIMIT;
};

const isStraightSegment = (angle) => {
  return toAbsoluteAngle(angle) === 0;
};

const isValidTrack = (track) => {
  if (!Array.isArray(track)) return false;
  return track.every((angle) => Number.isInteger(angle));
};

const countSharpTurns = (track) => {
  let sharp = 0;
  for (const angle of track) {
    if (isSharpTurn(angle)) sharp += 1;
  }
  return sharp;
};

const hasDangerousLoop = (track) => {
  for (let i = 1; i < track.length; i += 1) {
    const previous = toAbsoluteAngle(track[i - 1]);
    const current = toAbsoluteAngle(track[i]);
    if (previous + current > FULL_CIRCLE) return true;
  }
  return false;
};

const totalStraightLength = (track) => {
  let straights = 0;
  for (const angle of track) {
    if (isStraightSegment(angle)) straights += 1;
  }
  return straights * SEGMENT_LENGTH;
};

function validate(track) {
  if (!isValidTrack(track)) return false;
  if (countSharpTurns(track) > MAX_SHARP_TURNS) return false;
  if (hasDangerousLoop(track)) return false;
  return totalStraightLength(track) >= MIN_BRAKING_LENGTH;
}

const parseTrack = (text) => {
  return text
    .split(/[,\s]+/)
    .filter((piece) => piece.length > 0)
    .map((piece) => Number.parseInt(piece, 10));
};

const formatReport = (name, text) => {
  const track = parseTrack(text);
  const verdict = validate(track) ? 'PASSED' : 'FAILED';
  const loopNote = hasDangerousLoop(track) ? 'loop risk' : 'no loop risk';
  return [
    `${name}: ${verdict}`,
    `  sharp turns: ${countSharpTurns(track)} (limit ${MAX_SHARP_TURNS})`,
    `  straightaways: ${totalStraightLength(track)}m (need ${MIN_BRAKING_LENGTH}m)`,
    `  consecutive turns: ${loopNote}`,
  ].join('\n');
};

const courses = [
  ['Neon Spiral', '0 30 0 90 0 20 0 15'],
  ['Crater Run', '200, 190, 0, 0, 0, 0'],
  ['Blade Circuit', '60 70 80 90 100 0 0 0'],
];

for (const [name, definition] of courses) {
  console.log(formatReport(name, definition));
}

module.exports = { validate, parseTrack, countSharpTurns, totalStraightLength };

