'use strict';

const SPACE_PER_PERSON = 2;
const CANS_PER_PERSON_DAY = 3;
const LITERS_PER_PERSON_DAY = 4;
const MISSION_DAYS = 30;

const toWholeUnits = (value) => {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`Supply amounts must be finite numbers, got: ${value}`);
  }
  return Math.max(0, Math.floor(value));
};

const validateShelter = (shelter) => {
  if (!Array.isArray(shelter) || shelter.length !== 3) {
    throw new TypeError('Each shelter must be [cans, liters, squareMeters]');
  }
  const cans = toWholeUnits(shelter[0]);
  const liters = toWholeUnits(shelter[1]);
  const area = toWholeUnits(shelter[2]);
  return { cans, liters, area };
};

const computeMaxCapacity = (area) => Math.floor(area / SPACE_PER_PERSON);

const daysFromRation = (supply, capacity, rationPerDay) => {
  if (capacity === 0) {
    return Infinity;
  }
  return Math.floor(supply / (capacity * rationPerDay));
};

const determineLimitingFactor = (foodDays, waterDays) => {
  if (foodDays >= MISSION_DAYS && waterDays >= MISSION_DAYS) {
    return 'space';
  }
  return waterDays < foodDays ? 'water' : 'food';
};

function plan(supplies) {
  return supplies.map((shelter) => {
    const { cans, liters, area } = validateShelter(shelter);
    const capacity = computeMaxCapacity(area);
    const foodDays = daysFromRation(cans, capacity, CANS_PER_PERSON_DAY);
    const waterDays = daysFromRation(liters, capacity, LITERS_PER_PERSON_DAY);
    return [capacity, determineLimitingFactor(foodDays, waterDays)];
  });
}

const formatDays = (days) => (days === Infinity ? 'n/a' : `${days}d`);

const describeShelter = (shelter, result) => {
  const { cans, liters, area } = validateShelter(shelter);
  const capacity = computeMaxCapacity(area);
  const food = daysFromRation(cans, capacity, CANS_PER_PERSON_DAY);
  const water = daysFromRation(liters, capacity, LITERS_PER_PERSON_DAY);
  const foodText = formatDays(food);
  const waterText = formatDays(water);
  return `${area}m2 -> ${result[0]} people | food ${foodText} | water ${waterText} | limit: ${result[1]}`;
};

const formatReport = (supplies) => {
  const results = plan(supplies);
  return supplies
    .map((shelter, index) => describeShelter(shelter, results[index]))
    .join('\n');
};

const shelters = [
  [300, 500, 20],
  [1000, 4000, 40],
  [90, 2000, 12],
  [5000, 120, 30],
  [10, 10, 1],
];

console.log(formatReport(shelters));
console.log(JSON.stringify(plan(shelters)));

module.exports = { plan, formatReport };

