const SEED_MULTIPLIERS = { strength: 1, agility: 3, wisdom: 7 };

const CLASS_BY_STAT = { strength: 'warrior', agility: 'rogue', wisdom: 'mage' };

const toWholeNumber = (value) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    throw new TypeError(`seed must be an integer, received: ${String(value)}`);
  }
  return Math.trunc(numeric);
};

const normalizeSeed = (seed) => {
  const whole = toWholeNumber(seed);
  return Math.abs(whole);
};

const rollStat = (seed, multiplier) => ((seed * multiplier) % 18) + 3;

const computeBaseStats = (seed) => ({
  strength: rollStat(seed, SEED_MULTIPLIERS.strength),
  agility: rollStat(seed, SEED_MULTIPLIERS.agility),
  wisdom: rollStat(seed, SEED_MULTIPLIERS.wisdom),
});

const findHighestStat = (stats) => {
  const order = ['strength', 'agility', 'wisdom'];
  return order.reduce((best, name) => (stats[name] > stats[best] ? name : best), order[0]);
};

const determineClass = (stats) => {
  const highest = findHighestStat(stats);
  return CLASS_BY_STAT[highest];
};

const computeHealthPoints = (seed, stats) => stats.strength * 10 + (seed % 20);

const formatProfile = (characterClass, stats, healthPoints) =>
  `${characterClass}: HP ${healthPoints}, STR ${stats.strength}, AGI ${stats.agility}, WIS ${stats.wisdom}`;

const buildProfile = (rawSeed) => {
  const seed = normalizeSeed(rawSeed);
  const stats = computeBaseStats(seed);
  const characterClass = determineClass(stats);
  const healthPoints = computeHealthPoints(seed, stats);
  return formatProfile(characterClass, stats, healthPoints);
};

function generate(seeds) {
  if (!Array.isArray(seeds)) {
    throw new TypeError('generate expects an array of integer seeds');
  }
  return seeds.map(buildProfile);
}

const summarizeParty = (profiles) => {
  const counts = profiles.reduce((tally, profile) => {
    const characterClass = profile.slice(0, profile.indexOf(':'));
    tally[characterClass] = (tally[characterClass] || 0) + 1;
    return tally;
  }, {});
  return Object.keys(counts)
    .sort()
    .map((name) => `${name} x${counts[name]}`)
    .join(', ');
};

const main = () => {
  const seeds = [1, 4, 7, 15, 23, 42, 100, -8];
  const profiles = generate(seeds);
  profiles.forEach((profile, index) => {
    console.log(`seed ${seeds[index]} -> ${profile}`);
  });
  const summary = summarizeParty(profiles);
  console.log(`party: ${summary}`);
};

main();

module.exports = {
  generate,
  buildProfile,
  summarizeParty,
};

