const toRadians = (degrees) => (degrees * Math.PI) / 180;

const toDegrees = (radians) => (radians * 180) / Math.PI;

const clampCosine = (value) => Math.min(1, Math.max(-1, value));

function angularDistance(first, second) {
  const ra1 = toRadians(first[0]);
  const ra2 = toRadians(second[0]);
  const dec1 = toRadians(first[1]);
  const dec2 = toRadians(second[1]);
  const raw =
    Math.sin(dec1) * Math.sin(dec2) +
    Math.cos(dec1) * Math.cos(dec2) * Math.cos(ra1 - ra2);
  const cosine = clampCosine(raw);
  return toDegrees(Math.acos(cosine));
}

function buildDistanceMatrix(coordinates) {
  const matrix = coordinates.map(() => new Array(coordinates.length).fill(0));
  for (let i = 0; i < coordinates.length; i += 1) {
    for (let j = i + 1; j < coordinates.length; j += 1) {
      const separation = angularDistance(coordinates[i], coordinates[j]);
      matrix[i][j] = separation;
      matrix[j][i] = separation;
    }
  }
  return matrix;
}

const findNearestUnvisited = (matrix, current, visited) => {
  let best = -1;
  for (let candidate = 0; candidate < matrix.length; candidate += 1) {
    if (visited[candidate]) continue;
    if (best === -1 || matrix[current][candidate] < matrix[current][best]) {
      best = candidate;
    }
  }
  return best;
};

function nearestNeighborOrder(coordinates) {
  const matrix = buildDistanceMatrix(coordinates);
  const visited = coordinates.map(() => false);
  const order = [0];
  visited[0] = true;
  let current = 0;
  while (order.length < coordinates.length) {
    const next = findNearestUnvisited(matrix, current, visited);
    visited[next] = true;
    order.push(next);
    current = next;
  }
  return order;
}

const applyRefraction = ([ra, dec]) => (dec < 20 ? [ra, dec - 0.1] : [ra, dec]);

function validateCoordinates(coordinates) {
  if (!Array.isArray(coordinates)) throw new TypeError('coordinates must be an array');
  coordinates.forEach((pair) => {
    if (!Array.isArray(pair) || pair.length !== 2 || pair.some((n) => !Number.isFinite(n))) {
      throw new TypeError('each coordinate must be a pair of finite numbers');
    }
  });
}

function align(coordinates) {
  validateCoordinates(coordinates);
  if (coordinates.length === 0) return [];
  const order = nearestNeighborOrder(coordinates);
  return order.map((index) => applyRefraction(coordinates[index]));
}

const formatCoordinate = ([ra, dec]) => `RA ${ra.toFixed(3)}, Dec ${dec.toFixed(3)}`;

function describeSequence(sequence) {
  return sequence
    .map((pair, index) => {
      const label = formatCoordinate(pair);
      if (index === 0) return `1. ${label}`;
      const hop = angularDistance(sequence[index - 1], pair);
      return `${index + 1}. ${label} (+${hop.toFixed(2)}°)`;
    })
    .join('\n');
}

const targets = [
  [10.684, 41.269],
  [83.822, -5.391],
  [45.59, 12.15],
  [11.888, 40.05],
  [84.053, -1.202],
];
const plan = align(targets);
const report = describeSequence(plan);
console.log(report);

