const VOWELS = 'aeiouy';

const isVowelChar = (ch) => VOWELS.includes(ch);

const normalizeWord = (word) => word.toLowerCase().replace(/[^a-z']/g, '').replace(/'/g, '');

const splitIntoWords = (line) => {
  const raw = line.split(/\s+/);
  const cleaned = raw.map(normalizeWord);
  return cleaned.filter((word) => word.length > 0);
};

const stripSilentE = (word) => {
  const last = word.length - 1;
  if (word.length > 2 && word[last] === 'e' && !isVowelChar(word[last - 1])) {
    return word.slice(0, last);
  }
  return word;
};

const countVowelGroups = (word) => {
  let groups = 0;
  let inGroup = false;
  for (const ch of word) {
    const vowel = isVowelChar(ch);
    if (vowel && !inGroup) {
      groups += 1;
    }
    inGroup = vowel;
  }
  return groups;
};

const countSyllables = (word) => {
  const stem = stripSilentE(word);
  const groups = countVowelGroups(stem);
  return Math.max(1, groups);
};

const buildSyllableProfile = (line) => {
  const words = splitIntoWords(line);
  return words.map(countSyllables);
};

const isAllMonosyllabic = (counts) => counts.length > 0 && counts.every((n) => n === 1);

const isAlternatingPattern = (counts) => {
  if (counts.length < 2) return false;
  return counts.every((n, i) => (n === 1 || n === 2) && (i === 0 || n !== counts[i - 1]));
};

const classifyLine = (line) => {
  const counts = buildSyllableProfile(line);
  if (isAllMonosyllabic(counts)) return 'staccato';
  if (isAlternatingPattern(counts)) return 'iambic';
  return 'free';
};

function scan(lines) {
  return lines.map(classifyLine);
}

const formatReport = (poem, labels) => poem.map((line, index) => {
  const counts = buildSyllableProfile(line);
  return `${labels[index].padEnd(9)} [${counts.join(' ')}]  ${line}`;
});

const main = () => {
  const poem = [
    'The road was rough and long',
    'Behold the silent water under stone',
    'A cat sat on the mat',
    'Wandering endlessly through hollow corridors'
  ];
  const labels = scan(poem);
  const report = formatReport(poem, labels);
  report.forEach((row) => console.log(row));
};

main();

module.exports = { scan, classifyLine, countSyllables };

