const MIN_DELTA = 1;
const VOLUME_DIVISOR = 30;
const ROOM_AIRFLOW_CAP = 500;
const SYSTEM_AIRFLOW_CAP = 2000;

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function validateRoom(room, index) {
  if (!Array.isArray(room) || room.length < 3) {
    throw new TypeError(`Room ${index} must be [volume, current, target]`);
  }
  if (!room.slice(0, 3).every(isFiniteNumber)) {
    throw new TypeError(`Room ${index} contains a non-numeric value`);
  }
  if (room[0] <= 0) {
    throw new RangeError(`Room ${index} must have a positive volume`);
  }
}

const temperatureDelta = (current, target) => Math.abs(target - current);

function rawAirflow(volume, delta) {
  if (delta < MIN_DELTA) {
    return 0;
  }
  return (delta * volume) / VOLUME_DIVISOR;
}

const capRoomAirflow = (airflow) => Math.min(airflow, ROOM_AIRFLOW_CAP);

function airflowForRoom(room, index) {
  validateRoom(room, index);
  const [volume, current, target] = room;
  const delta = temperatureDelta(current, target);
  const required = rawAirflow(volume, delta);
  return capRoomAirflow(required);
}

const sumAirflow = (flows) => flows.reduce((total, flow) => total + flow, 0);

function balanceFactor(flows) {
  const total = sumAirflow(flows);
  if (total <= SYSTEM_AIRFLOW_CAP) {
    return 1;
  }
  return SYSTEM_AIRFLOW_CAP / total;
}

function balanceSystem(flows) {
  const factor = balanceFactor(flows);
  if (factor === 1) {
    return flows;
  }
  return flows.map((flow) => flow * factor);
}

function optimize(rooms) {
  if (!Array.isArray(rooms)) {
    throw new TypeError('rooms must be an array');
  }
  const flows = rooms.map(airflowForRoom);
  return balanceSystem(flows);
}

const formatFlow = (flow) => `${flow.toFixed(1)} CFM`;

function describeSystem(rooms) {
  const flows = optimize(rooms);
  const lines = flows.map((flow, i) => `Room ${i + 1} (${rooms[i][0]} ft³): ${formatFlow(flow)}`);
  const total = sumAirflow(flows);
  lines.push(`System total: ${formatFlow(total)}`);
  return lines.join('\n');
}

const sampleHouse = [
  [1200, 68, 74],
  [900, 80, 72],
  [400, 70, 70.5],
  [2500, 62, 75],
  [1800, 85, 68],
];

console.log(describeSystem(sampleHouse));

module.exports = { optimize, describeSystem, airflowForRoom, balanceSystem };

