const splitAtColon = (packet) => {
  const index = packet.indexOf(':');
  if (index === -1) {
    return null;
  }
  return { head: packet.slice(0, index), tail: packet.slice(index + 1) };
};

const isDigitsOnly = (text) => text.length > 0 && [...text].every((ch) => ch >= '0' && ch <= '9');

function parsePacket(packet) {
  if (typeof packet !== 'string') {
    return null;
  }
  const parts = splitAtColon(packet);
  if (parts === null) {
    return null;
  }
  if (!isDigitsOnly(parts.head)) {
    return null;
  }
  return { sequence: Number(parts.head), payload: parts.tail };
}

function collectValidPackets(packets) {
  const parsed = packets.map((packet) => parsePacket(packet));
  return parsed.filter((entry) => entry !== null);
}

const sortBySequence = (entries) => [...entries].sort((a, b) => a.sequence - b.sequence);

const dropDuplicateSequences = (sorted) => {
  const unique = [];
  const seen = new Set();
  for (const entry of sorted) {
    if (!seen.has(entry.sequence)) {
      seen.add(entry.sequence);
      unique.push(entry);
    }
  }
  return unique;
};

const concatPayloads = (entries) => entries.map((entry) => entry.payload).join('');

function buildRecovery(packets) {
  const valid = collectValidPackets(packets);
  const ordered = sortBySequence(valid);
  const unique = dropDuplicateSequences(ordered);
  return {
    text: concatPayloads(unique),
    received: packets.length,
    discarded: packets.length - valid.length,
    duplicates: valid.length - unique.length,
    sequences: unique.map((entry) => entry.sequence)
  };
}

function recover(packets) {
  return buildRecovery(packets).text;
}

const describeGaps = (sequences) => {
  const gaps = [];
  for (let i = 1; i < sequences.length; i += 1) {
    if (sequences[i] !== sequences[i - 1] + 1) {
      gaps.push(`${sequences[i - 1]}->${sequences[i]}`);
    }
  }
  return gaps.length === 0 ? 'none' : gaps.join(', ');
};

const formatReport = (packets) => {
  const result = buildRecovery(packets);
  const lines = [
    `message: "${result.text}"`,
    `received ${result.received}, invalid ${result.discarded}, duplicates ${result.duplicates}`,
    `gaps: ${describeGaps(result.sequences)}`
  ];
  return lines.join('\n');
};

if (require.main === module) {
  console.log(formatReport(process.argv.slice(2)));
}

module.exports = {
  recover,
  buildRecovery,
  parsePacket
};

