const FIBER_TABLE = {
  apple: 4,
  oats: 8,
  broccoli: 5
};

const HIGH_FIBER_THRESHOLD = 15;

const NormalizeFoodName = (food) => String(food).trim().toLowerCase();

const GetFiberValue = (food) => {
  const key = NormalizeFoodName(food);
  return Object.prototype.hasOwnProperty.call(FIBER_TABLE, key) ? FIBER_TABLE[key] : 0;
};

function SumMealFiber(meal) {
  let total = 0;
  for (const food of meal) {
    total += GetFiberValue(food);
  }
  return total;
}

const IsHighFiberMeal = (mealTotal) => mealTotal > HIGH_FIBER_THRESHOLD;

function ValidateMeals(meals) {
  if (!Array.isArray(meals)) {
    throw new TypeError('meals must be an array of arrays');
  }
  meals.forEach((meal, index) => {
    if (!Array.isArray(meal)) {
      throw new TypeError(`meal at index ${index} must be an array of food names`);
    }
  });
}

const ComputeMealTotals = (meals) => {
  ValidateMeals(meals);
  return meals.map(SumMealFiber);
};

function CountHighFiberMeals(mealTotals) {
  return mealTotals.filter(IsHighFiberMeal).length;
}

const SumAllFiber = (mealTotals) => mealTotals.reduce((acc, value) => acc + value, 0);

function Track(meals) {
  const mealTotals = ComputeMealTotals(meals);
