const APERTURE_SEQUENCE = [2, 4, 8];

function isValidReading(value) {
  return Number.isInteger(value) && value >= 0;
}

function validateReadings(scenes) {
  if (!Array.isArray(scenes)) {
    throw new TypeError('expose expects an array of light meter readings');
  }
  scenes.forEach((reading, index) => {
    if (!isValidReading(reading)) {
      throw new RangeError(`reading at index ${index} must be a non-negative integer`);
    }
  });
  return scenes;
}

function computeExposureValue(reading) {
  return Math.floor(reading / 10);
}

function chooseAperture(exposureValue) {
  let chosen = APERTURE_SEQUENCE[0];
  for (const aperture of APERTURE_SEQUENCE) {
    if (aperture <= exposureValue) {
      chosen = aperture;
    }
  }
  return chosen;
}

function computeShutterSpeed(exposureValue, aperture) {
  return Math.floor(exposureValue / aperture);
}

function exposeScene(reading) {
  const exposureValue = computeExposureValue(reading);
  const aperture = chooseAperture(exposureValue);
  return [aperture, computeShutterSpeed(exposureValue, aperture)];
}

function expose(scenes) {
  validateReadings(scenes);
  return scenes.map(exposeScene);
}

const formatAperture = (aperture) => `f/${aperture}`;

const formatShutterSpeed = (speed) => (speed > 0 ? `1/${speed}s` : 'bulb');

function describeScene(reading, setting) {
  const [aperture, speed] = setting;
  const lens = formatAperture(aperture);
  return `${reading} lx -> ${lens} @ ${formatShutterSpeed(speed)}`;
}

function buildReport(scenes, settings) {
  return scenes
    .map((reading, index) => describeScene(reading, settings[index]))
    .join('\n');
}

function summarizeApertures(settings) {
  const counts = new Map();
  for (const [aperture] of settings) {
    counts.set(aperture, (counts.get(aperture) || 0) + 1);
  }
  const parts = [];
  for (const aperture of APERTURE_SEQUENCE) {
    const used = counts.get(aperture) || 0;
    if (used > 0) {
      parts.push(`${formatAperture(aperture)} x${used}`);
    }
  }
  return parts.join(', ');
}

function main() {
  const readings = [5, 20, 45, 80, 130, 240];
  const settings = expose(readings);
  console.log(buildReport(readings, settings));
  console.log(`apertures used: ${summarizeApertures(settings)}`);
}

if (require.main === module) {
  main();
}

module.exports = { expose, exposeScene, buildReport, summarizeApertures };

