const SHELF_WIDTH = 200;

const isPositiveNumber = (value) => typeof value === 'number' && Number.isFinite(value) && value > 0;

const parseProduct = (entry) => {
  if (!Array.isArray(entry) || entry.length < 3) {
    throw new TypeError('each product must be [id, width, sales]');
  }
  const [id, width, sales] = entry;
  if (typeof id !== 'string' || id.length === 0) {
    throw new TypeError('product identifier must be a non-empty string');
  }
  if (!isPositiveNumber(width)) {
    throw new RangeError(`width of ${id} must be a positive number`);
  }
  if (typeof sales !== 'number' || !Number.isFinite(sales) || sales < 0) {
    throw new RangeError(`sales of ${id} must be a non-negative number`);
  }
  return { id, width, sales };
};

const computeScore = (product) => product.sales / product.width;

const sortByScore = (parsed) => {
  const scored = parsed.map((product) => ({ product, score: computeScore(product) }));
  scored.sort((left, right) => right.score - left.score);
  return scored.map((entry) => entry.product);
};

const canFit = (remaining, width) => width <= remaining;

function allocate(products) {
  if (!Array.isArray(products)) {
    throw new TypeError('products must be an array');
  }
  const parsed = products.map(parseProduct);
  const ordered = sortByScore(parsed);
  const shelf = [];
  let remaining = SHELF_WIDTH;
  let placedAnything = true;
  while (placedAnything) {
    placedAnything = false;
    for (const product of ordered) {
      if (canFit(remaining, product.width)) {
        shelf.push(product.id);
        remaining -= product.width;
        placedAnything = true;
      }
    }
  }
  return shelf;
}

const countCopies = (shelf) => {
  const counts = new Map();
  for (const id of shelf) {
    counts.set(id, (counts.get(id) || 0) + 1);
  }
  return counts;
};

const usedWidth = (shelf, products) => {
  const parsed = products.map(parseProduct);
  const widths = new Map(parsed.map((p) => [p.id, p.width]));
  return shelf.reduce((total, id) => total + widths.get(id), 0);
};

const formatReport = (products) => {
  const shelf = allocate(products);
  const lines = [];
  for (const [id, copies] of countCopies(shelf)) {
    lines.push(`${id.padEnd(12)} x${copies}`);
  }
  const used = usedWidth(shelf, products);
  lines.push(`used ${used} cm of ${SHELF_WIDTH} cm, ${SHELF_WIDTH - used} cm free`);
  return lines.join('\n');
};

const catalogue = [
  ['cornflakes', 30, 900],
  ['oat-rings', 25, 500],
  ['honey-pops', 18, 540],
  ['bran-bricks', 40, 400],
];

console.log(formatReport(catalogue));

