const isValidBox = (box) =>
  Array.isArray(box) &&
  box.length === 4 &&
  box.every((n) => Number.isInteger(n));

function normalizeBox(box) {
  const [left, top, right, bottom] = box;
  return [
    Math.min(left, right),
    Math.min(top, bottom),
    Math.max(left, right),
    Math.max(top, bottom),
  ];
}

function validateBoxes(boxes) {
  if (!Array.isArray(boxes)) {
    throw new TypeError("merge expects an array of boxes");
  }
  return boxes.map((box, index) => {
    if (!isValidBox(box)) {
      throw new TypeError(`box at index ${index} is not four integers`);
    }
    return normalizeBox(box);
  });
}

const overlapsHorizontally = (a, b) => a[0] <= b[2] && b[0] <= a[2];

const overlapsVertically = (a, b) => a[1] <= b[3] && b[1] <= a[3];

function boxesIntersect(a, b) {
  if (!overlapsHorizontally(a, b)) {
    return false;
  }
  return overlapsVertically(a, b);
}

const unionBoxes = (a, b) => [
  Math.min(a[0], b[0]),
  Math.min(a[1], b[1]),
  Math.max(a[2], b[2]),
  Math.max(a[3], b[3]),
];

function mergeOnce(boxes) {
  for (let i = 0; i < boxes.length; i += 1) {
    for (let j = i + 1; j < boxes.length; j += 1) {
      if (boxesIntersect(boxes[i], boxes[j])) {
        const rest = boxes.filter((_, index) => index !== i && index !== j);
        rest.push(unionBoxes(boxes[i], boxes[j]));
        return rest;
      }
    }
  }
  return null;
}

function merge(boxes) {
  let current = validateBoxes(boxes);
  let reduced = mergeOnce(current);
  while (reduced !== null) {
    current = reduced;
    reduced = mergeOnce(current);
  }
  return current.sort((a, b) => a[1] - b[1] || a[0] - b[0]);
}

const formatBox = (box) => `(${box.join(", ")})`;

function describeResult(input) {
  const merged = merge(input);
  const lines = merged.map((box) => `  ${formatBox(box)}`);
  return `${input.length} boxes -> ${merged.length} words\n${lines.join("\n")}`;
}

function runCli(argv) {
  const payload = argv[2];
  if (payload !== undefined) {
    console.log(describeResult(JSON.parse(payload)));
  }
}

runCli(process.argv);

module.exports = {
  merge,
  boxesIntersect,
  unionBoxes,
  formatBox,
  describeResult,
};

