const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

const normalizeReading = (value) => {
  if (!isFiniteNumber(value)) {
    throw new TypeError(`step reading is not a finite number: ${value}`);
  }
  return Math.max(0, value);
};

const validateStepData = (data) => {
  if (!Array.isArray(data)) {
    throw new TypeError('step data must be an array of per-minute counts');
  }
  return data.map(normalizeReading);
};

const collectWindow = (readings, index) => {
  const window = [];
  for (let offset = -1; offset <= 1; offset += 1) {
    const neighbour = index + offset;
    if (neighbour >= 0 && neighbour < readings.length) {
      window.push(readings[neighbour]);
    }
  }
  return window;
};

const averageOf = (values) => values.reduce((sum, value) => sum + value, 0) / values.length;

const snapNoiseToZero = (value) => (value < 5 ? 0 : value);

function smooth(data) {
  const readings = validateStepData(data);
  const smoothed = [];
  for (let minute = 0; minute < readings.length; minute += 1) {
    const window = collectWindow(readings, minute);
    const mean = averageOf(window);
    const rounded = Math.round(mean);
    smoothed.push(snapNoiseToZero(rounded));
  }
  return smoothed;
}

const totalSteps = (readings) => readings.reduce((sum, value) => sum + value, 0);

const countQuietMinutes = (readings) => readings.filter((value) => value === 0).length;

const formatSummary = (raw, smoothed) => {
  const rawTotal = totalSteps(raw);
  const cleanTotal = totalSteps(smoothed);
  const quiet = countQuietMinutes(smoothed);
  return [
    `minutes: ${smoothed.length}`,
    `raw total: ${rawTotal}`,
    `smoothed total: ${cleanTotal}`,
    `noise removed: ${rawTotal - cleanTotal}`,
    `quiet minutes: ${quiet}`,
  ].join(' | ');
};

const reportSession = (label, data) => {
  const readings = validateStepData(data);
  const smoothed = smooth(readings);
  const summary = formatSummary(readings, smoothed);
  console.log(`${label}: ${smoothed.join(', ')}`);
  console.log(`  ${summary}`);
};

reportSession('morning walk', [0, 3, 1, 40, 62, 58, 61, 2, 0, 1]);
reportSession('desk work', [1, 0, 2, 1, 0, 0, 7, 3, 0]);
reportSession('sprint', [80, 95, 120, 110, 4, 0, 0, 90, 100]);

module.exports = { smooth, totalSteps, countQuietMinutes, formatSummary };

