const DREAM_REALMS = ['lucid', 'nightmare', 'limbo'];

const isValidRealm = (realm) => DREAM_REALMS.includes(realm);

const toFiniteNumber = (value, label, index) => {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    throw new TypeError(`layer ${index}: ${label} must be a finite number`);
  }
  return number;
};

const normalizeLayer = (layer, index) => {
  if (layer === null || typeof layer !== 'object') {
    throw new TypeError(`layer ${index}: expected an object`);
  }
  if (!isValidRealm(layer.realm)) {
    throw new RangeError(`layer ${index}: unknown realm "${layer.realm}"`);
  }
  return {
    realm: layer.realm,
    depth: toFiniteNumber(layer.depth, 'depth', index),
    resonance: toFiniteNumber(layer.resonance, 'resonance', index),
  };
};

const applyLucidShift = (lucidity, layer) => lucidity + layer.resonance;

const applyNightmareShift = (lucidity, layer) => {
  const loss = layer.depth * 2;
  return lucidity - (layer.resonance > 0 ? loss / 2 : loss);
};

const applyLimboShift = (lucidity) => lucidity - 10;

const resolveRealm = (lucidity, layer) => {
  if (layer.realm === 'lucid') return applyLucidShift(lucidity, layer);
  if (layer.realm === 'nightmare') return applyNightmareShift(lucidity, layer);
  return applyLimboShift(lucidity);
};

const hasAcquiredFear = (lucidity, layer) => layer.realm === 'nightmare' && lucidity < 50;

const hasWokenUp = (lucidity) => lucidity <= 0;

function project(layers) {
  if (!Array.isArray(layers)) {
    throw new TypeError('layers must be an array');
  }
  let lucidity = 100;
  let fearTokens = 0;
  for (let i = 0; i < layers.length; i += 1) {
    const layer = normalizeLayer(layers[i], i);
    lucidity = resolveRealm(lucidity, layer);
    if (hasAcquiredFear(lucidity, layer)) {
      fearTokens += 1;
    }
    if (hasWokenUp(lucidity)) {
      return [0, fearTokens];
    }
  }
  return [lucidity, fearTokens];
}

const formatReport = ([lucidity, fearTokens]) =>
  `lucidity: ${lucidity} | fear tokens: ${fearTokens}`;

const describeDescent = (layers) => layers.map((l) => `${l.realm}@${l.depth}`).join(' -> ');

const runProjection = (name, layers) => {
  const outcome = project(layers);
  console.log(`${name}: ${describeDescent(layers)}`);
  console.log(`  ${formatReport(outcome)}`);
  return outcome;
};

runProjection('calm descent', [
  { realm: 'lucid', depth: 1, resonance: 12 },
  { realm: 'nightmare', depth: 4, resonance: 3 },
  { realm: 'limbo', depth: 9, resonance: -5 },
]);

runProjection('collapse', [
  { realm: 'nightmare', depth: 20, resonance: -8 },
  { realm: 'nightmare', depth: 25, resonance: -2 },
  { realm: 'lucid', depth: 1, resonance: 40 },
]);

module.exports = { project, formatReport, describeDescent };

