const NIGHTLY_COST = { stone: 10, obsidian: 15, marble: 20 };
const RAIN_RESTORE = { stone: 5, obsidian: 0, marble: 5 };
const STORM_RESTORE = { stone: 0, obsidian: 10, marble: 0 };

const normalizeLabel = (value) => String(value).trim().toLowerCase();

const getNightlyCost = (material) => {
  const cost = NIGHTLY_COST[normalizeLabel(material)];
  if (cost === undefined) {
    throw new Error(`unknown gargoyle material: ${material}`);
  }
  return cost;
};

const getWeatherRestore = (material, weather) => {
  const sky = normalizeLabel(weather);
  const kind = normalizeLabel(material);
  if (sky === 'rain') {
    return RAIN_RESTORE[kind];
  }
  if (sky === 'storm') {
    return STORM_RESTORE[kind];
  }
  if (sky !== 'clear') {
    throw new Error(`unknown weather condition: ${weather}`);
  }
  return 0;
};

const isFullyPetrified = (magic) => magic <= 0;

const resolveNight = (material, magic, weather) => {
  const spent = magic - getNightlyCost(material);
  if (isFullyPetrified(spent)) {
    return 0;
  }
  return spent + getWeatherRestore(material, weather);
};

const runWeek = (gargoyle) => {
  let magic = Number(gargoyle.magic);
  for (const weather of gargoyle.weather || []) {
    if (isFullyPetrified(magic)) {
      break;
    }
    magic = resolveNight(gargoyle.material, magic, weather);
  }
  return isFullyPetrified(magic) ? 0 : magic;
};

const track = (gargoyles) => gargoyles.map(runWeek);

const describeGargoyle = (gargoyle, reserve) => {
  const material = normalizeLabel(gargoyle.material);
  const state = isFullyPetrified(reserve) ? 'fully petrified' : `${reserve} magic left`;
  return `${gargoyle.name} (${material}): ${state}`;
};

const buildReport = (gargoyles, reserves) =>
  gargoyles.map((gargoyle, index) => describeGargoyle(gargoyle, reserves[index]));

const weekWeather = ['clear', 'rain', 'storm', 'clear', 'rain', 'storm', 'clear'];
const roster = [
  { name: 'Grimsby', material: 'Stone', magic: 70, weather: weekWeather },
  { name: 'Vex', material: 'obsidian', magic: 60, weather: weekWeather },
  { name: 'Alabast', material: 'marble', magic: 90, weather: weekWeather }
];

const finalReserves = track(roster);
console.log(buildReport(roster, finalReserves).join('\n'));
console.log(`final reserves: [${finalReserves.join(', ')}]`);

