const REGION_MULTIPLIERS = { urban: 0.9, rural: 1.15 };
const LUXURY_TAX_VIALS = 20;
const VIALS_PER_MEMBER = 10;
const ENDANGERED_THRESHOLD = 5;

const normalizeRegion = (region) => String(region).trim().toLowerCase();

function validateCoven(coven, index) {
  if (!coven || typeof coven !== 'object') {
    throw new TypeError(`Coven at index ${index} is not a record`);
  }
  const region = normalizeRegion(coven.region);
  if (!Object.prototype.hasOwnProperty.call(REGION_MULTIPLIERS, region)) {
    throw new RangeError(`Coven at index ${index} has unknown region "${coven.region}"`);
  }
  const members = Number(coven.members ?? coven.memberCount);
  if (!Number.isFinite(members) || members < 0) {
    throw new RangeError(`Coven at index ${index} has an invalid member count`);
  }
  const wealth = Number(coven.wealth ?? coven.wealthRating);
  if (!Number.isInteger(wealth) || wealth < 1 || wealth > 5) {
    throw new RangeError(`Coven at index ${index} has a wealth rating outside 1-5`);
  }
  return { region, members, wealth };
}

const computeBaseTithe = (members) => members * VIALS_PER_MEMBER;

const applyRegionalRule = (baseTithe, region) => baseTithe * REGION_MULTIPLIERS[region];

const levyWealthTax = (tithe, wealth) => (wealth >= 4 ? tithe + LUXURY_TAX_VIALS : tithe);

const applyViabilityRelief = (tithe, members) =>
  members < ENDANGERED_THRESHOLD ? tithe / 2 : tithe;

function assessSingleCoven(coven, index) {
  const { region, members, wealth } = validateCoven(coven, index);
  const base = computeBaseTithe(members);
  const regional = applyRegionalRule(base, region);
  const taxed = levyWealthTax(regional, wealth);
  const relieved = applyViabilityRelief(taxed, members);
  return Math.round(relieved);
}

function assess(covens) {
  if (!Array.isArray(covens)) {
    throw new TypeError('assess expects an array of covens');
  }
  return covens.map(assessSingleCoven);
}

function describeCoven(coven, index) {
  const { region, members, wealth } = validateCoven(coven, index);
  return `${members} members, ${region}, wealth ${wealth}`;
}

function formatTitheLine(coven, index, vials) {
  const description = describeCoven(coven, index);
  return `${description} -> ${vials} vials`;
}

function buildCouncilLedger(covens) {
  const totals = assess(covens);
  const lines = covens.map((coven, i) => formatTitheLine(coven, i, totals[i]));
  const grandTotal = totals.reduce((sum, vials) => sum + vials, 0);
  lines.push(`Total owed to the high council: ${grandTotal} vials`);
  return lines.join('\n');
}

module.exports = {
  assess,
  assessSingleCoven,
  buildCouncilLedger,
};

