const HEAT_PER_UNIT = { machineGun: 2, plasmaCannon: 10 };
const MISSILE_FLAT_HEAT = 50;
const OVERHEAT_THRESHOLD = 100;
const RECOVERY_THRESHOLD = 50;

const NormalizeWeaponName = (weapon) =>
  String(weapon).trim().toLowerCase().replace(/[\s_-]+(.)/g, (_m, c) => c.toUpperCase());

const ParseBurstDuration = (duration) => {
  const value = Number(duration);
  return Number.isFinite(value) && value > 0 ? value : 0;
};

const ReadAction = (action) => {
  if (Array.isArray(action)) {
    return { weapon: NormalizeWeaponName(action[0]), burst: ParseBurstDuration(action[1]) };
  }
  const weapon = NormalizeWeaponName(action.weapon ?? action.type ?? action.name);
  return { weapon, burst: ParseBurstDuration(action.burst ?? action.duration ?? action.time) };
};

const ComputeHeatGain = ({ weapon, burst }, overheated) => {
  if (weapon === 'missileLauncher') return MISSILE_FLAT_HEAT;
  if (weapon === 'plasmaCannon' && overheated) return 0;
  const rate = HEAT_PER_UNIT[weapon];
  return rate === undefined ? 0 : rate * burst;
};

const ApplyCoolingCycle = (heat, overheated) => Math.max(0, heat - (overheated ? 10 : 20));

const HasEnteredOverheat = (heat, overheated) => !overheated && heat > OVERHEAT_THRESHOLD;

const HasClearedOverheat = (heat, overheated) => overheated && heat < RECOVERY_THRESHOLD;

function Manage(actions) {
  const queue = Array.isArray(actions) ? actions : [];
  let heat = 0;
  let overheated = false;
  let overheatCount = 0;

  for (const raw of queue) {
    const action = ReadAction(raw);
    heat += ComputeHeatGain(action, overheated);
    if (HasEnteredOverheat(heat, overheated)) {
      overheated = true;
      overheatCount += 1;
    }
    heat = ApplyCoolingCycle(heat, overheated);
    if (HasClearedOverheat(heat, overheated)) {
      overheated = false;
    }
  }

  return [heat, overheatCount];
}

const DescribeAction = (raw) => {
  const { weapon, burst } = ReadAction(raw);
  return weapon === 'missileLauncher' ? `${weapon} (salvo)` : `${weapon} x${burst}`;
};

const FormatReport = (actions) => {
  const [heat, overheats] = Manage(actions);
  const log = actions.map(DescribeAction).join(', ');
  return `[${log}] -> heat ${heat}, overheats ${overheats}`;
};

const Main = () => {
  const runs = [
    [{ weapon: 'machine gun', burst: 5 }, { weapon: 'plasma cannon', burst: 3 }],
    [['missile launcher', 1], ['plasma cannon', 8], ['plasma cannon', 8], ['machine gun', 2]],
    [['plasma cannon', 12], ['missile launcher', 4], ['machine gun', 1], ['machine gun', 1]]
  ];
  runs.forEach((run) => console.log(FormatReport(run)));
};

Main();

module.exports = { Manage, ComputeHeatGain, ApplyCoolingCycle, FormatReport };

