const BASE_REACTION_MS = 200;
const INTIMIDATION_PENALTY_MS = 50;
const RAIN_PENALTY_MS = 20;
const SUN_PENALTY_MS = 40;
const HIGH_INTIMIDATION_THRESHOLD = 7;

const normalizeLabel = (value) => String(value ?? '').trim().toLowerCase();

const parseDrawSpeed = (speed) => {
  const milliseconds = Number(speed);
  if (!Number.isFinite(milliseconds) || milliseconds <= 0) {
    throw new TypeError(`Invalid opponent draw speed: ${speed}`);
  }
  return milliseconds;
};

const isHighIntimidation = (factor) => {
  if (typeof factor === 'number') {
    return factor >= HIGH_INTIMIDATION_THRESHOLD;
  }
  return normalizeLabel(factor) === 'high';
};

const adjustGunslingerTime = (factor) => {
  if (isHighIntimidation(factor)) {
    return BASE_REACTION_MS + INTIMIDATION_PENALTY_MS;
  }
  return BASE_REACTION_MS;
};

const applyWeatherPenalty = (weather, gunslingerTime, opponentTime) => {
  const condition = normalizeLabel(weather);
  if (condition === 'raining') {
    return { gunslinger: gunslingerTime + RAIN_PENALTY_MS, opponent: opponentTime + RAIN_PENALTY_MS };
  }
  if (condition === 'blinding sun') {
    return { gunslinger: gunslingerTime, opponent: opponentTime + SUN_PENALTY_MS };
  }
  if (condition !== 'clear') {
    throw new RangeError(`Unknown weather condition: ${weather}`);
  }
  return { gunslinger: gunslingerTime, opponent: opponentTime };
};

const resolveEncounter = (encounter) => {
  const opponentSpeed = parseDrawSpeed(encounter.drawSpeed ?? encounter.speed);
  const reaction = adjustGunslingerTime(encounter.intimidation ?? encounter.intimidationFactor);
  const finalTimes = applyWeatherPenalty(encounter.weather, reaction, opponentSpeed);
  return finalTimes.gunslinger < finalTimes.opponent;
};

const summarizeVerdict = (injuries) => (injuries === 0 ? 'legend' : 'mortal');

function duel(encounters) {
  if (!Array.isArray(encounters)) {
    throw new TypeError('duel() expects an array of encounters');
  }
  let wins = 0;
  let injuries = 0;
  for (const encounter of encounters) {
    if (resolveEncounter(encounter)) {
      wins += 1;
    } else {
      injuries += 1;
    }
  }
  return [wins, injuries, summarizeVerdict(injuries)];
}

const formatReport = (town, [wins, injuries, verdict]) =>
  `${town}: ${wins} won, ${injuries} injured -> ${verdict}`;

const tombstone = [
  { drawSpeed: 260, intimidation: 3, weather: 'clear' },
  { drawSpeed: 300, intimidation: 9, weather: 'raining' },
  { drawSpeed: 255, intimidation: 2, weather: 'blinding sun' },
];

const deadwood = [
  { drawSpeed: 240, intimidation: 'high', weather: 'clear' },
  { drawSpeed: 210, intimidation: 'low', weather: 'raining' },
];

console.log(formatReport('Tombstone', duel(tombstone)));
console.log(formatReport('Deadwood', duel(deadwood)));

module.exports = { duel, resolveEncounter, applyWeatherPenalty, isHighIntimidation };

