const START_INTEGRITY = 1000;
const SNAP_THRESHOLD = 200;
const SNAP_DAMAGE = 50;
const MATERIAL_MULTIPLIERS = { brass: 1, iron: 1, copper: 2 };

const toPositiveNumber = (value, label) => {
  const amount = Number(value);
  if (!Number.isFinite(amount) || amount < 0) {
    throw new TypeError(`${label} must be a non-negative finite number`);
  }
  return amount;
};

const normalizeMaterial = (material) => {
  const key = String(material).trim().toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(MATERIAL_MULTIPLIERS, key)) {
    throw new RangeError(`unknown gear material: ${material}`);
  }
  return key;
};

function validateGear(gear, index) {
  if (!gear || typeof gear !== 'object') {
    throw new TypeError(`gear at index ${index} is not an object`);
  }
  const size = toPositiveNumber(gear.size, `gear ${index} size`);
  const teeth = toPositiveNumber(gear.teeth ?? gear.toothCount, `gear ${index} tooth count`);
  const material = normalizeMaterial(gear.material);
  return { size, teeth, material };
}

const calculateTorque = (gear) => gear.size * gear.teeth;

const isSnapped = (torque) => torque > SNAP_THRESHOLD;

const materialStressDamage = (material, torque) => torque * MATERIAL_MULTIPLIERS[material];

const grantsShield = (material) => material === 'iron';

const applyShield = (damage, shielded) => (shielded ? damage / 2 : damage);

const clampIntegrity = (integrity) => (integrity < 0 ? 0 : integrity);

function test(gears) {
  if (!Array.isArray(gears)) {
    throw new TypeError('gears must be an array');
  }
  let integrity = START_INTEGRITY;
  let shielded = false;
  gears.forEach((raw, index) => {
    const gear = validateGear(raw, index);
    const torque = calculateTorque(gear);
    const snapped = isSnapped(torque);
    let baseDamage = SNAP_DAMAGE;
    let nextShield = false;
    if (!snapped) {
      baseDamage = materialStressDamage(gear.material, torque);
      nextShield = grantsShield(gear.material);
    }
    const damage = applyShield(baseDamage, shielded);
    integrity = clampIntegrity(integrity - damage);
    shielded = nextShield;
  });
  return integrity;
}

function describeRun(gears) {
  return gears.map((raw, index) => {
    const gear = validateGear(raw, index);
    const torque = calculateTorque(gear);
    const state = isSnapped(torque) ? 'SNAPPED' : 'holding';
    return `#${index} ${gear.material} torque=${torque} (${state})`;
  });
}

const workbench = [
  { size: 4, teeth: 10, material: 'brass' },
  { size: 5, teeth: 8, material: 'iron' },
  { size: 6, teeth: 9, material: 'copper' },
  { size: 15, teeth: 20, material: 'brass' }
];

describeRun(workbench).forEach((line) => console.log(line));
console.log(`workbench integrity: ${test(workbench)}`);

module.exports = {
  test,
  describeRun,
  calculateTorque
};

