const MINUTES_PER_BLOCK = 10;
const COST_PER_BLOCK = 2;
const SOCK_FEE = 3;
const MINIMUM_AGE = 5;

const isValidBooking = (booking) =>
  Array.isArray(booking) &&
  booking.length === 3 &&
  Number.isFinite(booking[0]) &&
  Number.isFinite(booking[1]) &&
  typeof booking[2] === 'boolean';

const isEligibleAge = (age) => age >= MINIMUM_AGE;

function countJumpBlocks(minutes) {
  return Math.ceil(minutes / MINUTES_PER_BLOCK);
}

function calculateBaseCost(minutes) {
  const blocks = countJumpBlocks(minutes);
  return blocks * COST_PER_BLOCK;
}

const applySockFee = (cost, needsSocks) => (needsSocks ? cost + SOCK_FEE : cost);

function computeBookingCost(booking) {
  const [, minutes, needsSocks] = booking;
  const base = calculateBaseCost(minutes);
  return applySockFee(base, needsSocks);
}

function process(bookings) {
  if (!Array.isArray(bookings)) {
    throw new TypeError('bookings must be an array of [age, minutes, socks] entries');
  }
  const costs = [];
  for (const booking of bookings) {
    if (!isValidBooking(booking)) {
      throw new TypeError(`invalid booking entry: ${JSON.stringify(booking)}`);
    }
    if (isEligibleAge(booking[0])) {
      const cost = computeBookingCost(booking);
      costs.push(cost);
    }
  }
  return costs;
}

const formatDollars = (amount) => `$${amount.toFixed(2)}`;

function describeBooking(booking) {
  const [age, minutes, needsSocks] = booking;
  const socksLabel = needsSocks ? 'with socks' : 'no socks';
  return `age ${age}, ${minutes} min, ${socksLabel}`;
}

function buildReport(bookings) {
  const lines = bookings.map((booking) => {
    const description = describeBooking(booking);
    if (!isEligibleAge(booking[0])) {
      return `${description} -> rejected (under ${MINIMUM_AGE})`;
    }
    const cost = computeBookingCost(booking);
    return `${description} -> ${formatDollars(cost)}`;
  });
  const costs = process(bookings);
  const total = costs.reduce((sum, cost) => sum + cost, 0);
  lines.push(`TOTAL: ${formatDollars(total)}`);
  return lines.join('\n');
}

function main() {
  const bookings = [
    [12, 60, true],
    [4, 30, false],
    [20, 120, false],
    [7, 45, true],
  ];
  const report = buildReport(bookings);
  console.log(report);
}

main();

module.exports = { process, computeBookingCost, buildReport };

