const isIntegerScore = (value) => Number.isInteger(value);

const validateScoreSet = (scores, index) => {
  if (!Array.isArray(scores)) {
    throw new TypeError(`Entry ${index} must be an array of scores`);
  }
  if (scores.length !== 5) {
    throw new RangeError(`Entry ${index} must hold exactly five scores`);
  }
  if (!scores.every(isIntegerScore)) {
    throw new TypeError(`Entry ${index} must contain integer scores only`);
  }
  return scores;
};

const sortAscending = (scores) => [...scores].sort((a, b) => a - b);

const trimExtremes = (scores) => {
  const ordered = sortAscending(scores);
  return ordered.slice(1, -1);
};

const averageOf = (scores) =>
  scores.reduce((sum, value) => sum + value, 0) / scores.length;

const medalForAverage = (average) => {
  if (average > 9) return 'gold';
  if (average > 7) return 'silver';
  return 'bronze';
};

function score(results) {
  if (!Array.isArray(results)) {
    throw new TypeError('results must be an array of score arrays');
  }
  return results.map((scores, index) => {
    const checked = validateScoreSet(scores, index);
    const counted = trimExtremes(checked);
    const average = averageOf(counted);
    return medalForAverage(average);
  });
}

const tallyMedals = (medals) =>
  medals.reduce((tally, medal) => {
    tally[medal] = (tally[medal] || 0) + 1;
    return tally;
  }, {});

const formatBakerLine = (scores, medal, index) => {
  const kept = trimExtremes(scores);
  const average = averageOf(kept).toFixed(2);
  return `Baker ${index + 1}: kept ${kept.join(', ')} -> avg ${average} -> ${medal}`;
};

const formatTally = (tally) =>
  ['gold', 'silver', 'bronze']
    .map((medal) => `${medal}: ${tally[medal] || 0}`)
    .join(' | ');

const buildReport = (results) => {
  const medals = score(results);
  const lines = results.map((scores, index) =>
    formatBakerLine(scores, medals[index], index)
  );
  const tally = tallyMedals(medals);
  lines.push(formatTally(tally));
  return lines.join('\n');
};

const competition = [
  [8, 9, 9, 10, 7],
  [5, 6, 6, 7, 5],
  [10, 10, 9, 10, 8],
  [7, 8, 7, 8, 9],
];

console.log(score(competition).join(', '));
console.log(buildReport(competition));

module.exports = { score, trimExtremes, averageOf, medalForAverage, buildReport };

