const removeDigits = (text) => Array.from(text)
  .filter((character) => !isDigitChar(character))
  .join('');

const reverseCharacters = (text) => Array.from(text).reverse().join('');

const swapAToE = (text) => text.replace(/a/g, 'e');

const countDigitsRemoved = (text) => text.length - removeDigits(text).length;

const assertTextEntry = (value, index) => {
  if (typeof value !== 'string') {
    throw new TypeError(`transmission at index ${index} is not a string: ${String(value)}`);
  }
};

const translateMessage = (text) => {
  const stripped = removeDigits(text);
  const reversed = reverseCharacters(stripped);
  return swapAToE(reversed);
};

function translate(messages) {
  if (!Array.isArray(messages)) {
    throw new TypeError('translate expects an array of transmission strings');
  }
  messages.forEach(assertTextEntry);
  return messages.map((message) => translateMessage(message));
}

const formatReportLine = (original, translated) => {
  const removed = countDigitsRemoved(original);
  const from = JSON.stringify(original);
  const to = JSON.stringify(translated);
  return `${from} -> ${to}  [${removed} digit(s) stripped]`;
};

