const MAX_TOKENS = 50;
const POINTS_PER_TOKEN = 1000;
const TOKENS_PER_COMBO = 2;
const PENALTY_PER_CONTINUE = 5;

const isNonNegativeInteger = (value) =>
  Number.isInteger(value) && value >= 0;

function validateSession(session, index) {
  if (!Array.isArray(session) || session.length !== 3) {
    throw new TypeError(`session ${index} must be an array of three numbers`);
  }
  const labels = ['points', 'combos', 'continues'];
  session.forEach((value, position) => {
    if (!isNonNegativeInteger(value)) {
      throw new RangeError(
        `session ${index}: ${labels[position]} must be a non-negative integer`
      );
    }
  });
  return session;
}

const baseTokensFor = (points) => Math.floor(points / POINTS_PER_TOKEN);

const comboBonusFor = (combos) => combos * TOKENS_PER_COMBO;

const continuePenaltyFor = (continues) => continues * PENALTY_PER_CONTINUE;

function clampTokenCount(tokens) {
  if (tokens < 0) {
    return 0;
  }
  return Math.min(tokens, MAX_TOKENS);
}

function tokensForSession(session, index) {
  const [points, combos, continues] = validateSession(session, index);
  let tokens = baseTokensFor(points);
  tokens += comboBonusFor(combos);
  tokens -= continuePenaltyFor(continues);
  return clampTokenCount(tokens);
}

function payout(sessions) {
  if (!Array.isArray(sessions)) {
    throw new TypeError('sessions must be an array');
  }
  return sessions.map(tokensForSession);
}

const describeSession = (session, tokens, index) => {
  const [points, combos, continues] = session;
  const parts = [
    `player ${index + 1}`,
    `${points} pts`,
    `${combos} combo(s)`,
    `${continues} continue(s)`,
  ];
  return `${parts.join(' | ')} -> ${tokens} token(s)`;
};

function buildPayoutReport(sessions) {
  const tokens = payout(sessions);
  const lines = sessions.map((session, index) =>
    describeSession(session, tokens[index], index)
  );
  const total = tokens.reduce((sum, value) => sum + value, 0);
  lines.push(`total tokens awarded: ${total}`);
  return lines.join('\n');
}

const arcadeLog = [
  [5000, 3, 0],
  [2000, 0, 1],
  [99000, 12, 2],
  [750, 1, 0],
];

console.log(buildPayoutReport(arcadeLog));

module.exports.payout = payout;
module.exports.buildPayoutReport = buildPayoutReport;

