const LOYALTY_THRESHOLD = 500;

const isValidProfile = (profile) =>
  Array.isArray(profile) &&
  profile.length === 3 &&
  Number.isFinite(profile[0]) &&
  typeof profile[1] === 'boolean' &&
  Number.isFinite(profile[2]);

const readProfile = (profile, index) => {
  if (!isValidProfile(profile)) {
    throw new TypeError(`passenger ${index} must be [age, mobilityNeeds, points]`);
  }
  return { age: profile[0], mobilityNeeds: profile[1], points: profile[2] };
};

const hasMobilityNeeds = (passenger) => passenger.mobilityNeeds === true;

const hasEliteLoyalty = (passenger) => passenger.points > LOYALTY_THRESHOLD;

const deckForPassenger = (passenger) => {
  if (hasMobilityNeeds(passenger)) {
    return 1;
  }
  if (hasEliteLoyalty(passenger)) {
    return 3;
  }
  return 2;
};

function allocate(passengers) {
  if (!Array.isArray(passengers)) {
    throw new TypeError('passengers must be an array of profiles');
  }
  return passengers.map((profile, index) => {
    const passenger = readProfile(profile, index);
    return deckForPassenger(passenger);
  });
}

const countPerDeck = (decks) => {
  const totals = { 1: 0, 2: 0, 3: 0 };
  decks.forEach((deck) => {
    totals[deck] += 1;
  });
  return totals;
};

const describeDeck = (deck) => {
  if (deck === 1) {
    return 'deck 1 (assisted boarding)';
  }
  if (deck === 3) {
    return 'deck 3 (loyalty lounge)';
  }
  return 'deck 2 (standard)';
};

const formatAllocationLine = (profile, index, deck) => {
  const passenger = readProfile(profile, index);
  const flags = hasMobilityNeeds(passenger) ? 'mobility support' : `${passenger.points} pts`;
  return `age ${passenger.age}, ${flags} -> ${describeDeck(deck)}`;
};

const buildReport = (passengers) => {
  const decks = allocate(passengers);
  const lines = passengers.map((profile, i) => formatAllocationLine(profile, i, decks[i]));
  const totals = countPerDeck(decks);
  const summary = [1, 2, 3]
    .map((deck) => `${describeDeck(deck)}: ${totals[deck]}`)
    .join(' | ');
  return lines.concat(summary).join('\n');
};

const manifest = [
  [65, true, 100],
  [30, false, 600],
  [25, false, 50],
  [41, false, 501],
  [8, true, 0],
];

console.log(allocate(manifest).join(', '));
console.log(buildReport(manifest));

