const TACO_PRICE = 3;
const GUACAMOLE_FEE = 2;
const SPICY_PENALTY = 1;
const TAX_RATE = 0.1;

const isValidCount = (value) =>
  Number.isInteger(value) && value >= 0;

const isBooleanFlag = (value) => typeof value === 'boolean';

function validateOrder(order, index) {
  if (!Array.isArray(order) || order.length !== 3) {
    throw new TypeError(`Order ${index} must be an array of three elements`);
  }
  const [count, guacamole, spicy] = order;
  if (!isValidCount(count)) {
    throw new RangeError(`Order ${index} has an invalid taco count: ${count}`);
  }
  if (!isBooleanFlag(guacamole)) {
    throw new TypeError(`Order ${index} has a non-boolean guacamole flag`);
  }
  if (!isBooleanFlag(spicy)) {
    throw new TypeError(`Order ${index} has a non-boolean spicy sauce flag`);
  }
  return { count, guacamole, spicy };
}

const tacoSubtotal = (count) => count * TACO_PRICE;

function orderSubtotal({ count, guacamole, spicy }) {
  let subtotal = tacoSubtotal(count);
  if (guacamole) {
    subtotal += GUACAMOLE_FEE;
  }
  if (spicy) {
    subtotal += SPICY_PENALTY;
  }
  return subtotal;
}

const applyTaxRate = (subtotal) => subtotal * (1 + TAX_RATE);

const roundUpDollars = (amount) => Math.ceil(amount);

function priceSingleOrder(order, index) {
  const parsed = validateOrder(order, index);
  const subtotal = orderSubtotal(parsed);
  const taxed = applyTaxRate(subtotal);
  return roundUpDollars(taxed);
}

function compile(orders) {
  if (!Array.isArray(orders)) {
    throw new TypeError('orders must be an array');
  }
  return orders.map(priceSingleOrder);
}

function describeOrder([count, guacamole, spicy]) {
  const extras = [];
  if (guacamole) {
    extras.push('guacamole');
  }
  if (spicy) {
    extras.push('extra spicy sauce');
  }
  const tail = extras.length ? ` with ${extras.join(' and ')}` : '';
  return `${count} taco${count === 1 ? '' : 's'}${tail}`;
}

function formatReceiptLine(order, price) {
  const label = describeOrder(order);
  return `${label.padEnd(46, '.')} $${price}`;
}

function buildReceipt(orders) {
  const prices = compile(orders);
  const lines = orders.map((order, i) => formatReceiptLine(order, prices[i]));
  const total = prices.reduce((sum, price) => sum + price, 0);
  lines.push(`${'TOTAL'.padEnd(46, '.')} $${total}`);
  return lines.join('\n');
}

console.log(buildReceipt([[3, true, true], [2, false, false], [1, true, false]]));

module.exports = {
  compile,
  buildReceipt,
  priceSingleOrder,
};

