    throw new TypeError(`show ${index + 1} must be an array of durations`);
  }
  for (const duration of durations) {
    if (!IsPositiveInteger(duration)) {
      throw new RangeError(`show ${index + 1} has an invalid duration: ${duration}`);
    }
  }
  return durations;
};

const ComputeBaseTime = (durations) => durations.reduce((sum, minutes) => sum + minutes, 0);

const NeedsIntermission = (baseTime) => baseTime > MAX_BASE_MINUTES;

const ComputeTotalTime = (durations) => {
  const baseTime = ComputeBaseTime(durations);
  return NeedsIntermission(baseTime) ? baseTime + INTERMISSION_MINUTES : baseTime;
};

const EvaluateRunningTime = (durations) => (
  ComputeTotalTime(durations) > MAX_TOTAL_MINUTES ? 'too long' : 'valid'
);

function Sequence(shows) {
  if (!Array.isArray(shows)) {
    throw new TypeError('shows must be an array of duration arrays');
  }
  return shows.map((durations, index) => {
    ValidateDurations(durations, index);
    return EvaluateRunningTime(durations);
  });
}

const FormatDuration = (minutes) => `${minutes} min`;

const FormatShowReport = (durations, index) => {
  const baseTime = ComputeBaseTime(durations);
  const totalTime = ComputeTotalTime(durations);
  const label = `Show ${index + 1}`;
  const base = FormatDuration(baseTime);
  const total = FormatDuration(totalTime);
  const pause = NeedsIntermission(baseTime) ? ` + ${INTERMISSION_MINUTES} min intermission` : ' (no intermission)';
  const verdict = EvaluateRunningTime(durations);
  return `${label}: ${base}${pause} => ${total} [${verdict}]`;
};

const BuildScheduleReport = (shows) => shows.map((durations, index) => {
  ValidateDurations(durations, index);
  return FormatShowReport(durations, index);
});

const CountTooLongShows = (verdicts) => verdicts.filter((verdict) => verdict === 'too long').length;

function Main() {
  const shows = [[10, 15, 25], [10, 10], [30, 30, 30], [20, 30, 25], [50]];
  const verdicts = Sequence(shows);
  for (const line of BuildScheduleReport(shows)) {
    console.log(line);
  }
  console.log(`Verdicts: ${verdicts.join(', ')}`);
  console.log(`Shows needing a shorter program: ${CountTooLongShows(verdicts)}`);
}

Main();

module.exports = { Sequence, ComputeBaseTime, ComputeTotalTime, EvaluateRunningTime, BuildScheduleReport };

