const LEVEL_EXPERT = 'expert';
const LEVEL_INTERMEDIATE = 'intermediate';
const LEVEL_BEGINNER = 'beginner';

const isValidCount = (value) => Number.isInteger(value) && value >= 0;

function validatePark(park, index) {
  if (!Array.isArray(park) || park.length !== 3) {
    throw new TypeError(`park ${index} must be [jumps, rails, halfpipe]`);
  }
  const [jumps, rails, halfpipe] = park;
  if (!isValidCount(jumps)) {
    throw new TypeError(`park ${index}: jumps must be a non-negative integer`);
  }
  if (!isValidCount(rails)) {
    throw new TypeError(`park ${index}: rails must be a non-negative integer`);
  }
  if (typeof halfpipe !== 'boolean') {
    throw new TypeError(`park ${index}: halfpipe must be a boolean`);
  }
  return { jumps, rails, halfpipe };
}

const halfpipeBonus = (halfpipe) => (halfpipe ? 5 : 0);

function scorePark(park, index) {
  const { jumps, rails, halfpipe } = validatePark(park, index);
  return jumps * 2 + rails + halfpipeBonus(halfpipe);
}

function classifyScore(score) {
  if (score > 20) {
    return LEVEL_EXPERT;
  }
  if (score > 10) {
    return LEVEL_INTERMEDIATE;
  }
  return LEVEL_BEGINNER;
}

function evaluate(parks) {
  if (!Array.isArray(parks)) {
    throw new TypeError('parks must be an array');
  }
  return parks.map((park, index) => {
    const score = scorePark(park, index);
    return classifyScore(score);
  });
}

function formatParkLine(park, index) {
  const [jumps, rails, halfpipe] = park;
  const score = scorePark(park, index);
  const features = `${jumps} jumps, ${rails} rails, halfpipe: ${halfpipe ? 'yes' : 'no'}`;
  return `Park ${index + 1}: ${features} -> ${score} pts (${classifyScore(score)})`;
}

function summarizeLevels(levels) {
  const tally = { [LEVEL_BEGINNER]: 0, [LEVEL_INTERMEDIATE]: 0, [LEVEL_EXPERT]: 0 };
  levels.forEach((level) => { tally[level] += 1; });
  return [LEVEL_BEGINNER, LEVEL_INTERMEDIATE, LEVEL_EXPERT]
    .map((level) => `${level}: ${tally[level]}`)
    .join(', ');
}

