const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function parseRocketSpec(rocket) {
  if (!Array.isArray(rocket) || rocket.length < 3) {
    throw new TypeError('each rocket must be [fuelVolume, engineEfficiency, windSpeed]');
  }
  const [fuelVolume, engineEfficiency, windSpeed] = rocket;
  if (!isFiniteNumber(fuelVolume) || fuelVolume < 0) {
    throw new RangeError(`fuel volume must be a non-negative number, got ${fuelVolume}`);
  }
  if (!isFiniteNumber(engineEfficiency) || engineEfficiency < 0) {
    throw new RangeError(`engine efficiency must be a non-negative number, got ${engineEfficiency}`);
  }
  if (!isFiniteNumber(windSpeed)) {
    throw new RangeError(`wind speed must be a number, got ${windSpeed}`);
  }
  return { fuelVolume, engineEfficiency, windSpeed };
}

const computeBaseAltitude = (spec) => spec.fuelVolume * spec.engineEfficiency;

const applyWindDrag = (altitude, windSpeed) => altitude - 2 * windSpeed;

const clampToGround = (altitude) => (altitude < 0 ? 0 : altitude);

const toWholeKilometers = (meters) => Math.floor(meters / 1000);

function peakAltitudeKm(spec) {
  const base = computeBaseAltitude(spec);
  const afterWeather = applyWindDrag(base, spec.windSpeed);
  const reached = clampToGround(afterWeather);
  return toWholeKilometers(reached);
}

function launch(rockets) {
  if (!Array.isArray(rockets)) {
    throw new TypeError('rockets must be an array of rocket specs');
  }
  return rockets.map((rocket) => {
    const spec = parseRocketSpec(rocket);
    return peakAltitudeKm(spec);
  });
}

const highestFlight = (altitudes) => altitudes.reduce((best, km) => Math.max(best, km), 0);

const groundedCount = (altitudes) => altitudes.filter((km) => km === 0).length;

function formatRocketLine(index, spec, km) {
  const fuel = `${spec.fuelVolume} mL`;
  const wind = `${spec.windSpeed} km/h wind`;
  return `#${index + 1}: ${fuel} x${spec.engineEfficiency}, ${wind} -> ${km} km`;
}

function formatLaunchReport(rockets) {
  const altitudes = launch(rockets);
  const lines = rockets.map((rocket, index) => {
    const spec = parseRocketSpec(rocket);
    return formatRocketLine(index, spec, altitudes[index]);
  });
  lines.push(`best: ${highestFlight(altitudes)} km`);
  lines.push(`grounded: ${groundedCount(altitudes)} of ${altitudes.length}`);
  return lines.join('\n');
}

function main() {
  const sample = [[1000, 5, 20], [500, 2, 600]];
  console.log(launch(sample).join(', '));
  const fleet = [[2400, 3.5, 150], [750, 1, 400], [12000, 0.9, 25], [100, 12, 0]];
  console.log(formatLaunchReport(fleet));
  const fleetAltitudes = launch(fleet);
  console.log(`fleet ceiling: ${highestFlight(fleetAltitudes)} km`);
}

main();

module.exports = { launch, formatLaunchReport, parseRocketSpec, toWholeKilometers };

