const READY_THRESHOLD_PERCENT = 20;
const MIN_AGE_DAYS = 30;

const validateBatch = (batch, index) => {
  if (!Array.isArray(batch) || batch.length !== 3) {
    throw new TypeError(`Batch ${index} must be an array of three numbers`);
  }
  batch.forEach((value) => {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`Batch ${index} contains a non-numeric value`);
    }
  });
  const [initial, current] = batch;
  if (initial <= 0) {
    throw new RangeError(`Batch ${index} has a non-positive initial weight`);
  }
  if (current > initial) {
    throw new RangeError(`Batch ${index} gained weight, which is impossible`);
  }
  return batch;
};

const computeWaterLost = (initialWeight, currentWeight) => initialWeight - currentWeight;

const waterLossPercent = (initialWeight, currentWeight) => {
  const lost = computeWaterLost(initialWeight, currentWeight);
  return (lost / initialWeight) * 100;
};

const isReadyForSale = (percentLost, daysAged) =>
  percentLost > READY_THRESHOLD_PERCENT && daysAged > MIN_AGE_DAYS;

const determineStatus = (batch, index) => {
  const [initial, current, days] = validateBatch(batch, index);
  const percent = waterLossPercent(initial, current);
  return isReadyForSale(percent, days) ? 'ready' : 'curing';
};

function track(batches) {
  if (!Array.isArray(batches)) {
    throw new TypeError('track expects a list of batches');
  }
  return batches.map(determineStatus);
}

const describeBatch = (batch, index) => {
  const [initial, current, days] = batch;
  const percent = waterLossPercent(initial, current);
  const lost = computeWaterLost(initial, current);
  const status = determineStatus(batch, index);
  return `#${index + 1}: ${lost}g lost (${percent.toFixed(1)}%), ${days} days -> ${status}`;
};

const countReadyBatches = (statuses) => statuses.filter((s) => s === 'ready').length;

const buildReport = (batches) => {
  const statuses = track(batches);
  const lines = batches.map(describeBatch);
  lines.push(`${countReadyBatches(statuses)} of ${statuses.length} batches ready for sale`);
  return lines.join('\n');
};

const inventory = [
  [100, 75, 35],
  [100, 90, 10],
  [850, 660, 45],
  [500, 380, 28],
  [1200, 1150, 60],
];

console.log(track(inventory).join(', '));
console.log(buildReport(inventory));

module.exports = {
  track,
  buildReport,
  determineStatus,
  waterLossPercent,
};

