const SECONDS_PER_OBSTACLE = 5;
const SECONDS_PER_TUNNEL_METER = 2;
const SECONDS_PER_PENALTY_POINT = 3;

const isNonNegativeInteger = (value) => Number.isInteger(value) && value >= 0;

function validateCourse(course, index) {
  if (!Array.isArray(course) || course.length !== 3) {
    throw new TypeError(`Course ${index} must be an array of three numbers`);
  }
  const [obstacles, tunnelLength, penalties] = course;
  if (!isNonNegativeInteger(obstacles)) {
    throw new RangeError(`Course ${index}: obstacle count must be a non-negative integer`);
  }
  if (!isNonNegativeInteger(tunnelLength)) {
    throw new RangeError(`Course ${index}: tunnel length must be a non-negative integer`);
  }
  if (!isNonNegativeInteger(penalties)) {
    throw new RangeError(`Course ${index}: penalty points must be a non-negative integer`);
  }
  return { obstacles, tunnelLength, penalties };
}

const computeObstacleTime = (obstacles) => obstacles * SECONDS_PER_OBSTACLE;

const computeTunnelTime = (tunnelLength) => tunnelLength * SECONDS_PER_TUNNEL_METER;

const computePenaltyTime = (penalties) => penalties * SECONDS_PER_PENALTY_POINT;

function rateSingleCourse(course, index) {
  const { obstacles, tunnelLength, penalties } = validateCourse(course, index);
  let total = computeObstacleTime(obstacles);
  total += computeTunnelTime(tunnelLength);
  total += computePenaltyTime(penalties);
  return total;
}

function rate(courses) {
  if (!Array.isArray(courses)) {
    throw new TypeError('courses must be an array of course descriptions');
  }
  return courses.map(rateSingleCourse);
}

const padTwoDigits = (value) => String(value).padStart(2, '0');

function formatSeconds(totalSeconds) {
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}m ${padTwoDigits(seconds)}s`;
}

function buildReportLine(course, seconds, index) {
  const [obstacles, tunnelLength, penalties] = course;
  const details = `${obstacles} obstacles, ${tunnelLength}m tunnel, ${penalties} penalties`;
  return `Course ${index + 1}: ${details} -> ${seconds}s (${formatSeconds(seconds)})`;
}

function findFastestIndex(times) {
  return times.reduce((best, time, index) => (time < times[best] ? index : best), 0);
}

const courses = [[10, 5, 2], [15, 10, 0], [20, 12, 4]];
const times = rate(courses);
courses.forEach((course, index) => {
  console.log(buildReportLine(course, times[index], index));
});
const fastest = findFastestIndex(times);
console.log(`Fastest expected run: course ${fastest + 1} at ${formatSeconds(times[fastest])}`);

module.exports = {
  rate,
  rateSingleCourse,
  formatSeconds,
  buildReportLine,
  findFastestIndex,
};

