    throw new TypeError(`design ${index} must be [length, density, isMetal]`);
  }
  const [pathLength, density, isMetal] = design;
  if (!isFiniteNumber(pathLength) || pathLength < 0) {
    throw new RangeError(`design ${index} has an invalid path length`);
  }
  if (!isFiniteNumber(density) || density <= 0) {
    throw new RangeError(`design ${index} has an invalid density factor`);
  }
  if (typeof isMetal !== 'boolean') {
    throw new TypeError(`design ${index} must flag metal with a boolean`);
  }
  return { pathLength, density, isMetal };
};

const computeBaseTime = (pathLength, density) => pathLength * density;

const applyMetalDoubling = (minutes, isMetal) => (isMetal ? minutes * 2 : minutes);

const needsCooling = (minutes) => minutes > 60;

const addCoolingTime = (minutes) => {
  if (needsCooling(minutes)) {
    return minutes + 10;
  }
  return minutes;
};

function estimate(designs) {
  if (!Array.isArray(designs)) {
    throw new TypeError('designs must be an array');
  }
  return designs.map((design, index) => {
    const { pathLength, density, isMetal } = validateDesign(design, index);
    const base = computeBaseTime(pathLength, density);
    const engraved = applyMetalDoubling(base, isMetal);
    const cooled = addCoolingTime(engraved);
    return Math.round(cooled);
  });
}

const formatDuration = (minutes) => {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours === 0) {
    return `${rest}m`;
  }
  return rest === 0 ? `${hours}h` : `${hours}h ${rest}m`;
};

const describeJob = (design, minutes, index) => {
  const label = design[2] ? 'metal' : 'non-metal';
  const cooling = needsCooling(minutes - 10) ? ' (incl. cooling)' : '';
  return `#${index + 1} ${design[0]}cm ${label}: ${formatDuration(minutes)}${cooling}`;
};

const buildReport = (designs) => {
  const times = estimate(designs);
  const lines = designs.map((design, index) => describeJob(design, times[index], index));
  const total = times.reduce((sum, minutes) => sum + minutes, 0);
  lines.push(`Total queue time: ${formatDuration(total)}`);
  return lines.join('\n');
};

const main = () => {
  const queue = [[10, 3, false], [20, 2, true], [45, 1.5, false], [7.5, 4, true]];
  console.log(estimate(queue).join(', '));
  console.log(buildReport(queue));
};

main();

module.exports = { estimate, buildReport, formatDuration };

