const MILEAGE_LIMIT = 10000;
const PAD_WEAR_LIMIT = 80;

function validateTrain(train, index) {
  if (!Array.isArray(train) || train.length < 3) {
    throw new TypeError(`Train ${index} must be an array of [mileage, wear, rattling]`);
  }
  const [mileage, wear, rattling] = train;
  if (!Number.isFinite(mileage) || mileage < 0) {
    throw new RangeError(`Train ${index} has an invalid mileage: ${mileage}`);
  }
  if (!Number.isFinite(wear) || wear < 0 || wear > 100) {
    throw new RangeError(`Train ${index} has an invalid brake pad wear: ${wear}`);
  }
  return { mileage, wear, rattling: Boolean(rattling) };
}

const exceedsMileageLimit = (record) => record.mileage > MILEAGE_LIMIT;

const exceedsPadWear = (record) => record.wear > PAD_WEAR_LIMIT;

const hasRattlingDoors = (record) => record.rattling;

function collectReasons(record) {
  const reasons = [];
  if (exceedsMileageLimit(record)) {
    reasons.push(`mileage ${record.mileage} km over ${MILEAGE_LIMIT} km`);
  }
  if (exceedsPadWear(record)) {
    reasons.push(`brake pad wear ${record.wear}% over ${PAD_WEAR_LIMIT}%`);
  }
  if (hasRattlingDoors(record)) {
    reasons.push('passenger doors rattling');
  }
  return reasons;
}

function needsService(record) {
  const reasons = collectReasons(record);
  return reasons.length > 0;
}

function schedule(trains) {
  if (!Array.isArray(trains)) {
    throw new TypeError('schedule expects a list of train readings');
  }
  return trains.map((train, index) => {
    const record = validateTrain(train, index);
    return needsService(record) ? 'service' : 'operational';
  });
}

function formatTrainLine(train, index) {
  const record = validateTrain(train, index);
  const reasons = collectReasons(record);
  const detail = reasons.length > 0 ? reasons.join('; ') : 'all readings within limits';
  const verdict = needsService(record) ? 'SERVICE' : 'OPERATIONAL';
  return `Train #${index + 1}: ${verdict} (${detail})`;
}

const countServiceFlags = (verdicts) => verdicts.filter((v) => v === 'service').length;

function summarizeFleet(trains) {
  const verdicts = schedule(trains);
  const flagged = countServiceFlags(verdicts);
  const lines = trains.map(formatTrainLine);
  lines.push(`${flagged} of ${verdicts.length} unit(s) require preventative repair.`);
  return lines.join('\n');
}

function main() {
  const fleet = [[12000, 50, false], [5000, 30, false], [8000, 85, true]];
  const report = summarizeFleet(fleet);
  console.log(report);
}

if (require.main === module) {
  main();
}

module.exports = {
  schedule,
  summarizeFleet,
};

