const assertNumber = (value, label) => {
  if (typeof value !== 'number' || Number.isNaN(value)) {
    throw new TypeError(`${label} must be a number, got ${String(value)}`);
  }
  return value;
};

const validateEntry = (entry, index) => {
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError(`donation ${index} must be an array of three values`);
  }
  const weight = assertNumber(entry[0], `donation ${index} weight`);
  const days = assertNumber(entry[1], `donation ${index} expiration`);
  if (typeof entry[2] !== 'boolean') {
    throw new TypeError(`donation ${index} damage flag must be a boolean`);
  }
  return { weight, days, damaged: entry[2] };
};

const isExpired = (can) => can.days < 0;

const isAcceptable = (can) => {
  if (isExpired(can)) {
    return false;
  }
  return can.damaged === false;
};

const countMeals = (weight) => Math.floor(weight / 200);

function sort(donations) {
  if (!Array.isArray(donations)) {
    throw new TypeError('donations must be an array');
  }
  return donations
    .map((entry, index) => validateEntry(entry, index))
    .filter(isAcceptable)
    .map((can) => countMeals(can.weight));
}

const sumMeals = (counts) => counts.reduce((total, meals) => total + meals, 0);

const pluralizeMeals = (count) => (count === 1 ? '1 meal' : `${count} meals`);

const summarizeDonations = (donations) => {
  const meals = sort(donations);
  return {
    accepted: meals.length,
    discarded: donations.length - meals.length,
    total: sumMeals(meals),
    largest: meals.length === 0 ? 0 : Math.max(...meals),
    counts: meals,
  };
};

const formatSummary = (label, donations) => {
  const summary = summarizeDonations(donations);
  const lines = [`${label}: ${summary.accepted} cans kept, ${summary.discarded} discarded`];
  lines.push(`  total ${pluralizeMeals(summary.total)}`);
  lines.push(`  best can provides ${pluralizeMeals(summary.largest)}`);
  lines.push(`  per-can meals: [${summary.counts.join(', ')}]`);
  return lines.join('\n');
};

const morningDelivery = [[1000, 30, false], [500, -5, false], [600, 10, true]];
const eveningDelivery = [[199, 3, false], [800, 0, false], [450, 12, false], [2000, -1, true]];

console.log(formatSummary('Morning delivery', morningDelivery));
console.log(formatSummary('Evening delivery', eveningDelivery));

module.exports.sort = sort;
module.exports.countMeals = countMeals;
module.exports.summarizeDonations = summarizeDonations;
module.exports.formatSummary = formatSummary;

