const POINTS_BULLSEYE = 10;
const POINTS_MIDDLE = 5;
const POINTS_OUTER = 0;

const isValidDistance = (value) =>
  typeof value === 'number' && Number.isFinite(value) && value >= 0;

const assertValidVolley = (volley, index) => {
  if (!Array.isArray(volley) || volley.length !== 3) {
    throw new TypeError(`archer ${index} must supply exactly three arrows`);
  }
  const bad = volley.findIndex((distance) => !isValidDistance(distance));
  if (bad !== -1) {
    throw new TypeError(`archer ${index}, arrow ${bad} has an invalid distance`);
  }
};

const pointsForDistance = (distance) => {
  if (distance < 2) {
    return POINTS_BULLSEYE;
  }
  if (distance < 5) {
    return POINTS_MIDDLE;
  }
  return POINTS_OUTER;
};

const sumNumbers = (numbers) => numbers.reduce((acc, n) => acc + n, 0);

const scoreVolley = (volley) => {
  const arrowPoints = volley.map(pointsForDistance);
  return sumNumbers(arrowPoints);
};

function score(archers) {
  if (!Array.isArray(archers)) {
    throw new TypeError('archers must be an array of volleys');
  }
  return archers.map((volley, index) => {
    assertValidVolley(volley, index);
    return scoreVolley(volley);
  });
}

const formatScoreLine = (index, total) =>
  `Archer ${index + 1}: ${total} point${total === 1 ? '' : 's'}`;

const rankArchers = (totals) =>
  totals
    .map((total, index) => ({ index, total }))
    .sort((a, b) => b.total - a.total || a.index - b.index);

const buildScoreReport = (archers) => {
  const totals = score(archers);
  const lines = rankArchers(totals).map((entry) =>
    formatScoreLine(entry.index, entry.total)
  );
  lines.push(`Team total: ${sumNumbers(totals)}`);
  return lines.join('\n');
};

const volleys = [
  [1, 4, 10],
  [0, 1, 3],
  [5, 6, 7],
  [1.9, 2, 4.99],
];

console.log(score(volleys).join(', '));
console.log(buildScoreReport(volleys));

module.exports = { score, scoreVolley, pointsForDistance, buildScoreReport };

