const TRACK_LIMIT_PENALTY = 3;
const PIT_SPEED_LIMIT = 60;
const DRIVE_THROUGH_PENALTY = 50;
const DISQUALIFICATION_PENALTY = 999;

const validateLapEntry = (lap, index) => {
  if (!Array.isArray(lap) || lap.length !== 3) {
    throw new TypeError(`lap ${index} must be [violations, pitSpeed, severity]`);
  }
  const [violations, pitSpeed] = lap;
  if (!Number.isInteger(violations) || violations < 0) {
    throw new RangeError(`lap ${index} has an invalid violation count`);
  }
  if (typeof pitSpeed !== 'number' || Number.isNaN(pitSpeed)) {
    throw new TypeError(`lap ${index} has an invalid pit lane speed`);
  }
};

const normalizeSeverity = (severity) => String(severity).trim().toLowerCase();

const isDisqualifyingCollision = (severity) => {
  const tag = normalizeSeverity(severity);
  return tag === 'high';
};

const trackLimitPenalty = (violations) => violations * TRACK_LIMIT_PENALTY;

const pitLanePenalty = (pitSpeed) => (pitSpeed > PIT_SPEED_LIMIT ? DRIVE_THROUGH_PENALTY : 0);

const lapPenalty = (lap, index) => {
  validateLapEntry(lap, index);
  const [violations, pitSpeed] = lap;
  let total = trackLimitPenalty(violations);
  total += pitLanePenalty(pitSpeed);
  return total;
};

function adjudicate(laps) {
  if (!Array.isArray(laps)) {
    throw new TypeError('laps must be an array of lap records');
  }
  const penalties = [];
  for (let i = 0; i < laps.length; i += 1) {
    const lap = laps[i];
    validateLapEntry(lap, i);
    if (isDisqualifyingCollision(lap[2])) {
      return DISQUALIFICATION_PENALTY;
    }
    penalties.push(lapPenalty(lap, i));
  }
  return penalties;
}

const sumPenalties = (penalties) => penalties.reduce((acc, p) => acc + p, 0);

const formatPenaltyLine = (penalty, index) => `  lap ${index + 1}: +${penalty}s`;

const buildRaceReport = (sessionName, laps) => {
  const outcome = adjudicate(laps);
  if (!Array.isArray(outcome)) {
    return `${sessionName}: DISQUALIFIED (${outcome}s)`;
  }
  const body = outcome.map(formatPenaltyLine).join('\n');
  const total = sumPenalties(outcome);
  const header = `${sessionName}: total ${total}s over ${outcome.length} lap(s)`;
  return body ? `${header}\n${body}` : header;
};

const sessions = [
  ['Practice', [[2, 55, 'low'], [0, 65, 'none']]],
  ['Qualifying', [[1, 58, 'none'], [3, 72, 'medium']]],
  ['Race', [[0, 59, 'low'], [2, 61, 'High']]],
];

for (const [name, laps] of sessions) {
  console.log(buildRaceReport(name, laps));
}

module.exports = {
  adjudicate,
  buildRaceReport,
  lapPenalty,
  isDisqualifyingCollision,
};

