const isFiniteNumber = (value) => typeof value === "number" && Number.isFinite(value);

function validateObservation(observation, index) {
  if (!Array.isArray(observation) || observation.length < 3) {
    throw new TypeError(`observation ${index} must be [start, peak, temperature]`);
  }
  const [start, peak, temperature] = observation;
  if (!isFiniteNumber(start) || start <= 0) {
    throw new RangeError(`observation ${index} has a non-positive starting volume`);
  }
  if (!isFiniteNumber(peak) || peak < 0) {
    throw new RangeError(`observation ${index} has an invalid peak volume`);
  }
  if (!isFiniteNumber(temperature)) {
    throw new TypeError(`observation ${index} has a non-numeric temperature`);
  }
  const measured = observation.length > 3 ? observation[3] : null;
  if (measured !== null && (!isFiniteNumber(measured) || measured <= 0)) {
    throw new RangeError(`observation ${index} has an invalid rise time`);
  }
  return { start, peak, temperature, measured };
}

const computeExpansionRatio = (start, peak) => peak / start;

const computeAdjustedBaseline = (temperature) => 6 + Math.max(0, 25 - temperature);

// Without a logged rise time, a culture is assumed to need one hour per fold of growth.
const estimateRiseTime = (record, ratio) => (record.measured === null ? ratio : record.measured);

const isHighVitality = (ratio, riseTime, baseline) => ratio > 2 && riseTime < baseline;

function score(observations) {
  if (!Array.isArray(observations)) {
    throw new TypeError("observations must be an array");
  }
  return observations.map((observation, index) => {
    const record = validateObservation(observation, index);
    const ratio = computeExpansionRatio(record.start, record.peak);
    const riseTime = estimateRiseTime(record, ratio);
    const baseline = computeAdjustedBaseline(record.temperature);
    const high = isHighVitality(ratio, riseTime, baseline);
    return high ? "high" : "low";
  });
}

function formatReport(observations, labels) {
  return observations.map((observation, index) => {
    const record = validateObservation(observation, index);
    const ratio = computeExpansionRatio(record.start, record.peak);
    const riseTime = estimateRiseTime(record, ratio);
    const baseline = computeAdjustedBaseline(record.temperature);
    const head = `culture ${index + 1}: x${ratio.toFixed(2)} at ${record.temperature}C`;
    return `${head}, rise ${riseTime.toFixed(1)}h vs ${baseline.toFixed(1)}h -> ${labels[index]}`;
  });
}

function summarizeLabels(labels) {
  const high = labels.filter((label) => label === "high").length;
  return `${high} high / ${labels.length - high} low`;
}

function main() {
  const cultures = [[100, 250, 25], [100, 150, 20], [50, 200, 18, 9], [80, 400, 21, 3]];
  const labels = score(cultures);
  console.log(labels);
  const report = formatReport(cultures, labels);
  report.forEach((line) => console.log(line));
  console.log(summarizeLabels(labels));
  const cold = [[10, 90, 12, 14], [10, 15, 12, 2]];
  const coldLabels = score(cold);
  console.log(summarizeLabels(coldLabels));
}

if (require.main === module) {
  main();
}

module.exports = { score, formatReport, summarizeLabels, computeAdjustedBaseline };

