  const splitIntoWords = (str) => str.split(/[\s-]+/);
  const isAlphaChar = (char) => /[a-zA-Z]/.test(char);
  const getFirstAlphaChar = (word) => {
    for (let i = 0; i < word.length; i++) {
      if (isAlphaChar(word[i])) {
        return word[i];
      }
    }
    return '';
  };
  const convertToUpper = (char) => char.toUpperCase();
  const filterEmptyStrings = (arr) => arr.filter(str => str.length > 0);
  const joinChars = (arr) => arr.join('');

  const words = splitIntoWords(phrase);
  const filteredWords = filterEmptyStrings(words);
  const firstLetters = filteredWords.map(word => getFirstAlphaChar(word));
  const validLetters = filterEmptyStrings(firstLetters);
  const capitalizedLetters = validLetters.map(char => convertToUpper(char));
  return joinChars(capitalizedLetters);
};

