const countSetBits = (n) => {
  let count = 0;
  let numberToProcess = n;

  const isNotZero = (val) => val !== 0;
  const getLeastSignificantBit = (val) => val & 1;
  const rightShiftByOne = (val) => val >>> 1;
  const incrementCount = (currentCount) => currentCount + 1;
  const checkBitAndIncrement = (currentNum, currentCount) => {
    if (getLeastSignificantBit(currentNum) === 1) {
      return incrementCount(currentCount);
    }
    return currentCount;
  };
  const updateNumber = (currentNum) => rightShiftByOne(currentNum);

  while (isNotZero(numberToProcess)) {
    count = checkBitAndIncrement(numberToProcess, count);
    numberToProcess = updateNumber(numberToProcess);
  }
  return count;
};

