const isUpperCase = (char) => char >= 'A' && char <= 'Z';
const isLowerCase = (char) => char >= 'a' && char <= 'z';
const getCharCode = (char) => char.charCodeAt(0);
const getShiftedCharCode = (charCode, base, shift) => base + (charCode - base + shift) % 26;
const convertCharCodeToString = (charCode) => String.fromCharCode(charCode);

const processCharacter = (char, shift) => {
  const charCode = getCharCode(char);
  if (isUpperCase(char)) {
    const shiftedCode = getShiftedCharCode(charCode, getCharCode('A'), shift);
    return convertCharCodeToString(shiftedCode);
  }
  if (isLowerCase(char)) {
    const shiftedCode = getShiftedCharCode(charCode, getCharCode('a'), shift);
    return convertCharCodeToString(shiftedCode);
  }
  return char;
};

const caesarCipher = (text, shift) => {
  let result = '';
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    result += processCharacter(char, shift);
  }
  return result;
};

