const multiplyStrings = (num1, num2) => {
  if (num1 === '0' || num2 === '0') return '0';
  const n1 = num1.split('').reverse().map(Number);
  const n2 = num2.split('').reverse().map(Number);
  const product = Array(n1.length + n2.length).fill(0);

  for (let i = 0; i < n1.length; i++) {
    for (let j = 0; j < n2.length; j++) {
      product[i + j] += n1[i] * n2[j];
    }
  }

  return formatProductResult(product);
};

const formatProductResult = (productArray) => {
  let carry = 0;
  for (let i = 0; i < productArray.length; i++) {
    const sum = productArray[i] + carry;
    productArray[i] = sum % 10;
    carry = Math.floor(sum / 10);
  }

  while (productArray.length > 1 && productArray[productArray.length - 1] === 0) {
    productArray.pop();
  }
  return productArray.reverse().join('');
};

const convertNumberToString = (num) => String(num);
const isNumberNegative = (num) => num < 0;
const isNumberZero = (num) => num === 0;
const isNumberOne = (num) => num === 1;

const largeFactorial = (n) => {
  if (isNumberNegative(n)) return 'Error: Factorial of negative numbers is undefined.';
  if (isNumberZero(n) || isNumberOne(n)) return '1';

  let result = '1';
  for (let i = 2; i <= n; i++) {
    const currentNumberAsString = convertNumberToString(i);
    result = multiplyStrings(result, currentNumberAsString);
  }
  return result;
};

