const isAnArray = item => Array.isArray(item);
const createEmptyArray = () => [];
const addElementToArray = (arr, element) => { arr.push(element); return arr; };
const processNonArrayItem = (result, item) => addElementToArray(result, item);
const combineArrays = (arr1, arr2) => arr1.concat(arr2);
const iterateOverItems = (arr, callback) => arr.forEach(callback);

const flattenArray = arr => {
  let flattenedResult = createEmptyArray();
  iterateOverItems(arr, item => {
    if (isAnArray(item)) {
      flattenedResult = combineArrays(flattenedResult, flattenArray(item));
    } else {
      processNonArrayItem(flattenedResult, item);
    }
  });
  return flattenedResult;
};

