const getRemainder = (number, divisor) => number % divisor;
const divideByTwo = (number) => Math.floor(number / 2);
const convertToString = (value) => value.toString();
const prependDigit = (digit, binaryString) => digit + binaryString;
const isGreaterThanZero = (number) => number > 0;
const initializeBinaryString = () => '';

const decimalToBinary = (decimalNum) => {
  if (decimalNum === 0) return '0';

  let binary = initializeBinaryString();
  let currentNum = decimalNum;

  while (isGreaterThanZero(currentNum)) {
    const remainder = getRemainder(currentNum, 2);
    binary = prependDigit(convertToString(remainder), binary);
    currentNum = divideByTwo(currentNum);
  }

  return binary;
};

