class Queue {
  constructor() {
    this.items = [];
  }

  getQueueLength() {
    return this.items.length;
  }

  checkIsEmpty() {
    return this.getQueueLength() === 0;
  }

  addToBack(element) {
    this.items.push(element);
  }

  removeFromFront() {
    return this.items.shift();
  }

  enqueue(element) {
    this.addToBack(element);
  }

  dequeue() {
    if (this.checkIsEmpty()) {
      return null;
    }
    return this.removeFromFront();
  }

  peekFront() {
    if (this.checkIsEmpty()) {
      return null;
    }
    return this.items[0];
  }
}

