const calculateWindowSum = (window) => window.reduce((acc, val) => acc + val, 0);
const calculateAverage = (sum, count) => sum / count;
const getWindowStart = (index, windowSize) => index - windowSize + 1;
const isWindowValid = (index, windowSize) => index >= windowSize - 1;
const extractWindow = (data, start, end) => data.slice(start, end + 1);
const addResultToArray = (results, value) => { results.push(value); return results; };

const simpleMovingAverage = (data, windowSize) => {
  const averages = [];
  for (let i = 0; i < data.length; i++) {
    if (isWindowValid(i, windowSize)) {
      const windowStartIndex = getWindowStart(i, windowSize);
      const currentWindow = extractWindow(data, windowStartIndex, i);
      const windowSum = calculateWindowSum(currentWindow);
      const average = calculateAverage(windowSum, windowSize);
      addResultToArray(averages, average);
    }
  }
  return averages;
};

