const majorityElement = (nums) => {
  const getCountsMap = (arr) => arr.reduce((acc, num) => {
    acc.set(num, (acc.get(num) || 0) + 1);
    return acc;
  }, new Map());

  const getHalfLength = (arr) => Math.floor(arr.length / 2);

  const checkIsMajority = (count, halfLen) => count > halfLen;

  const getFirstElement = (map) => map.keys().next().value;

  const findMajorityInMap = (countsMap, halfLen) => {
    for (const [num, count] of countsMap.entries()) {
      if (checkIsMajority(count, halfLen)) {
        return num;
      }
    }
    return getFirstElement(countsMap); // Should not be reached given problem constraints
  };

  const counts = getCountsMap(nums);
  const halfLength = getHalfLength(nums);
  const result = findMajorityInMap(counts, halfLength);
  return result;
};

const majorityElementBoyerMoore = (nums) => {
  let candidate = nums[0];
  let count = 0;

  const incrementCount = () => count++;
  const decrementCount = () => count--;
  const updateCandidate = (num) => candidate = num;
  const resetCount = () => count = 1;

  for (const num of nums) {
    if (count === 0) {
      updateCandidate(num);
      resetCount();
    } else if (num === candidate) {
      incrementCount();
    } else {
      decrementCount();
    }
  }
  return candidate;
};

