      AddPermutationToSet(currentArr.join(''), uniquePermutations);
      return;
    }

    const processedChars = new Set();
    for (let i = 0; i < remainingArr.length; i++) {
      const charToMove = remainingArr[i];
      if (HasBeenProcessed(processedChars, charToMove)) {
        continue;
      }
      AddCharToProcessed(processedChars, charToMove);

      const newRemaining = CreateNewRemainingArray(remainingArr, i);
      const newCurrent = AppendCharToArray(currentArr, charToMove);

      GeneratePermsRecursive(newCurrent, newRemaining);
    }
  };

  const AddPermutationToSet = (perm, set) => {
    set.add(perm);
  };

  const HasBeenProcessed = (set, char) => {
    return set.has(char);
  };

  const AddCharToProcessed = (set, char) => {
    set.add(char);
  };

  const CreateNewRemainingArray = (arr, indexToRemove) => {
    return [...arr.slice(0, indexToRemove), ...arr.slice(indexToRemove + 1)];
  };

  const AppendCharToArray = (arr, char) => {
    return [...arr, char];
  };

  GeneratePermsRecursive([], charArray);
  return Array.from(uniquePermutations);
};

