const calculateArraySum = (arr) => arr.reduce((acc, val) => acc + val, 0);

const calculateArrayMean = (arr) => calculateArraySum(arr) / arr.length;

const calculateSquaredDifference = (num, mean) => Math.pow(num - mean, 2);

const calculateSumOfSquaredDifferences = (arr, mean) => {
  return arr.reduce((acc, num) => acc + calculateSquaredDifference(num, mean), 0);
};

const calculateVariance = (arr, mean) => {
  const sumOfSquares = calculateSumOfSquaredDifferences(arr, mean);
  return sumOfSquares / (arr.length - 1);
};

