const calculateStandardDeviation = (numbers) => {
  if (numbers.length < 2) return 0;

  const arrayMean = calculateArrayMean(numbers);
  const dataVariance = calculateVariance(numbers, arrayMean);
  return calculateSquareRoot(dataVariance);
};

