  const isFirstIndexSmaller = (i, j) => i < j;
  const isFirstElementGreater = (nums, i, j) => nums[i] > nums[j];
  const incrementInversionCount = () => { inversionCount++; };
  const getOuterLoopLimit = (len) => len - 1;
  const getInnerLoopStart = (i) => i + 1;

  for (let i = 0; i < getOuterLoopLimit(getArrayLength(nums)); i++) {
    for (let j = getInnerLoopStart(i); j < getArrayLength(nums); j++) {
      if (isFirstIndexSmaller(i, j) && isFirstElementGreater(nums, i, j)) {
        incrementInversionCount();
      }
    }
  }
