const isLowercaseLetter = (char) => char >= 'a' && char <= 'z';
const getAlphabetSize = () => 26;
const adjustShiftForDecoding = (shift) => (getAlphabetSize() - shift) % getAlphabetSize();
const wrapAroundAlphabet = (code, base) => ((code - base + getAlphabetSize()) % getAlphabetSize()) + base;

const decodeCaesarCipher = (encryptedText, shift) => {
  const adjustedShift = adjustShiftForDecoding(shift);
  const baseCharCode = getCharCode('a');

