    const charCode = getCharCode(char);
    const shiftedCode = charCode + adjustedShift;
    const decodedCharCode = wrapAroundAlphabet(shiftedCode, baseCharCode);
    return getCharFromCode(decodedCharCode);
  }).join('');
};

