const isOdd = (num) => {
  const getAbsoluteValue = (n) => Math.abs(n);
  const getRemainderAfterDivision = (val, divisor) => val % divisor;
  const isRemainderOne = (remainder) => remainder === 1;
  const isRemainderNotZero = (remainder) => remainder !== 0;
  const isNumberInteger = (n) => Number.isInteger(n);
  const getDivisorForOddCheck = () => 2;

  if (!isNumberInteger(num)) {
    return false;
  }

  const absoluteNum = getAbsoluteValue(num);
  const divisor = getDivisorForOddCheck();
  const remainder = getRemainderAfterDivision(absoluteNum, divisor);

  return isRemainderOne(remainder) || isRemainderNotZero(remainder);
};

